  (1, 3, 'mrforayeji', 'mrforayeji@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মোস্তাফিজ ফরায়েজী', 'mrforayeji', 'admin', '/uploads/avatars/mrforayeji.jpg', '', '2019-01-13 18:37:05', '2026-09-12 18:23:43'),
  (2, 4, 'pintupothik', 'pintupothik@yahoo.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'পিন্টু রহমান', 'pintupothik', 'author', '/uploads/avatars/pintupothik.jpg', 'গল্পকার। গল্পের ছলে ভাষার আঞ্চলিকাতায় চিত্রায়ণ করেন বাঙাল জনপদের বহুমাত্রিক জীবনাচার। ১৩ অক্টোবর চুয়াডাঙ্গা জেলার কুমারী গ্রামে, পৈত্রিক ঘর-বসতি কুষ্টিয়ার বাজিতপুরে। মাতা: জিন্নাতুন নেছা ও পিতা: আজিবর রহমান (বীর মুক্তিযোদ্ধা)। প্রকাশিত গ্রস্থ: গল্প- পাললিক ঘ্রাণ, পরানপাখি, হাওরপাড়ের কইন্যা, উপন্যাস- কমরেড। সম্পাদদিক কাগজ: জয়ত্রি।', '2019-01-13 18:38:56', '2026-09-12 18:23:43'),
  (3, 5, 'rafiqurrashid', 'rafiqurrashid@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রফিকুর রশীদ', 'rafiqurrashid', 'author', '/uploads/avatars/rafiqurrashid.jpg', 'রফিকুর রশীদ (জন্ম: ২৭ সেপ্টেম্বর ১৯৫৭) একজন বাংলাদেশী ঔপন্যাসিক ও ছোট গল্পকার। তিনি বাংলা ভাষার অন্যতম কথাসাহিত্যক হিসেবে পরিচিত। তিনি অগ্রণী ব্যাংক শিশু একাডেমী শিশুসাহিত্য পুরস্কার, আলাওল সাহিত্য পুরস্কার, বাংলা একাডেমী সাহিত্য পুরস্কার সহ নানা পুরস্কার পেয়েছেন।', '2019-01-13 18:42:57', '2026-09-12 18:23:43'),
