  (8, 10, 'sokalriy', 'sokalroy@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সকাল রয়', 'sokalriy', 'author', '/uploads/avatars/sokalriy.jpg', '', '2019-01-16 06:10:16', '2026-09-12 18:23:43'),
  (9, 11, 'azajkhanrocky20', 'azajkhanrocky20@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'এজাজ আহাম্মেদ।', 'azajkhanrocky20', 'author', '/uploads/avatars/azajkhanrocky20.jpg', '', '2019-01-16 09:23:03', '2026-09-12 18:23:43'),
  (10, 12, 'tribhubanjit', 'tribhubanjit@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ত্রিভুবন জিৎ মুখার্জী', 'tribhubanjit', 'author', '/uploads/avatars/tribhubanjit.jpg', 'ত্রিভুবন জিৎ মুখার্জী পশ্চিম বঙ্গের ৭৭,রামকান্ত বোস ষ্ট্রীট বাগবাজার কলকাতা ৭০০ ০০৩ তে বসবাস করেন। তিন মূলত একজন গল্পকার। তিনি বিভিন্ন অনলাইন ম্যাগাজিনসহ লিটলম্যাগে লেখালেখি করেন।', '2019-01-16 10:04:33', '2026-09-12 18:23:43'),
  (11, 13, 'imrulyousuf', 'imrulyousuf@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইমরুল ইউসুফ', 'imrulyousuf', 'author', '/uploads/avatars/imrulyousuf.jpg', '', '2019-01-16 10:21:54', '2026-09-12 18:23:43'),
  (12, 14, 'kabirctg1985', 'kabirctg1985@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'কবির কাঞ্চন', 'kabirctg1985', 'author', '/uploads/avatars/kabirctg1985.jpg', '', '2019-01-17 07:55:47', '2026-09-12 18:23:43'),
  (13, 15, 'baulmozno123', 'baulmozno123@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মজনু মিয়া', 'baulmozno123', 'author', '/uploads/avatars/baulmozno123.png', '', '2019-01-17 11:56:20', '2026-09-12 18:23:43'),
  (14, 16, 'tasifislam', 'tasifislam@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মাহির তাজওয়ার', 'tasifislam', 'author', '/uploads/avatars/tasifislam.jpg', 'মাহির তাজওয়ার ছোটবেলা থেকেই চাইতেন অভিনয় শিল্পী হবেন। প্রাথমিকে পড়ার সময়েই নাটক করতেন । আর এসমস্ত নাটকের স্ক্রিপ্ট সেই সময়ে নিজেই লিখতেন তিনি। পরবর্তিতে এই চাওয়ারও পরিবর্তন আসে। লেখক হতে চান্ তিনি। ছড়া, কবিতা, গল্প তিন শাখাতেই বিচরণ তার। মাহির তাজওয়ার আবৃত্তি করেন ভালোলাগা থেকে। গল্প লিখে চলেছেন এক দশক থেকে। যৎসামান্য কবিতাও লেখেন। বাবার চাকরির সুবাদে বিভিন্ন সময়ে বিভিন্ন স্কুল ও কলেজে পড়তে হয়েছে তাকে। করেছেন ইংরেজি সাহিত্যে অনার্স ও মাস্টার্স। এ লেখকের জন্ম ১৯৯০ সালের ৩ জানুয়ারি, চুয়াডাঙ্গায়।', '2019-01-19 08:19:27', '2026-09-12 18:23:43'),
  (15, 17, 'jahangir33', 'jahangir33-345@diu.edu.bd', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শাহরিয়ার জাহাঙ্গীর', 'jahangir33', 'author', '/uploads/avatars/jahangir33.jpg', '', '2019-01-20 14:36:09', '2026-09-12 18:23:43'),
  (16, 18, 'sudev', 'email.sudev@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সুদেব চক্রবর্তী', 'sudev', 'author', '/uploads/avatars/sudev.jpg', '', '2019-01-22 09:52:19', '2026-09-12 18:23:43'),
  (17, 19, 'bantideb827', 'bantideb827@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'বান্টি দেব', 'bantideb827', 'author', '/uploads/avatars/bantideb827.jpg', '', '2019-01-23 07:22:56', '2026-09-12 18:23:43'),
  (18, 20, 'enamraju1', 'enamraju1@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'এনাম রাজু', 'enamraju1', 'author', '/uploads/avatars/enamraju1.jpg', 'এনাম রাজুর জন্ম- ২০ ফেব্রুয়ারি ১৯৯১ সালে কুড়িগ্রাম জেলার সদর থানার কাঁঠালবাড়ি ইউনিয়নে। পিতা- মো. আবু বক্র সিদ্দিক, মাতা- রাশেদা বেগম। তিন সন্তানের এনাম রাজু দ্বিতীয়। বাংলা সাহিত্যে স্নাতকোত্তর এবং বর্তমানে চাইনিজ ভাষার ডিপ্লোমা করছেন।', '2019-01-23 09:33:38', '2026-09-12 18:23:43'),
  (19, 21, 'sabina', 'sabina@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সাবিনা পারভীন লিনা', 'sabina', 'author', '/uploads/avatars/sabina.jpg', '', '2019-01-24 10:47:12', '2026-09-12 18:23:43'),
  (20, 22, 'eyasinajij', 'eyasinajij@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইয়াছিন আযীয', 'eyasinajij', 'author', '', '', '2019-01-26 06:05:57', '2026-09-12 18:23:43'),
  (21, 23, 'chaitydas256', 'chaitydas256@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'চৈতি দাস অদিতি', 'chaitydas256', 'author', '/uploads/avatars/chaitydas256.jpg', '', '2019-01-26 07:41:30', '2026-09-12 18:23:43'),
  (22, 24, 'raqibul096', 'raqibul096@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রাকিবুল ইসলাম', 'raqibul096', 'author', '/uploads/avatars/raqibul096.jpg', '', '2019-01-29 03:45:46', '2026-09-12 18:23:43'),
  (23, 26, 'tamanna', 'tamanna@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'তামান্না স্নিগ্ধা', 'tamanna', 'author', '/uploads/avatars/tamanna.jpg', '', '2019-01-30 08:01:28', '2026-09-12 18:23:43'),
  (24, 27, 'ahmedshiplu17', 'ahmedshiplu17@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আহমেদ শিপলু', 'ahmedshiplu17', 'author', '/uploads/avatars/ahmedshiplu17.jpg', 'পিতা: জাহাঙ্গীর আলম খান, মাতা: সুফিয়া বেগম। জন্ম: ১৭ জুন ১৯৭৬, কোলাপাড়া, শ্রীনগর, মুন্সীগঞ্জ। শৈশব যাপন: আলমডাঙ্গা, চুয়াডাঙ্গা। ১৯৯২ খ্রিঃ থেকে ঢাকায় স্থায়ী বসবাস। প্রকাশিত কাব্যগ্রন্থ: বসন্তের অপেক্ষায় (১৯৯৯), কোথাও তুমি নেই (২০০১), ক্রাচে ভর দেওয়া যৌবন (২০০৫), মন পাখিটার ডানা কাটা উড়তে মানা (২০০৯), নির্বাচিত কবিতা (২০১৩), বালিকার আকাশ (২০১৫), প্রজাপতিরা ফিরে গিয়েছিলো (২০১৭), বিষণ্ন ইস্পাত (২০১৮) বিষ বৃক্ষের উল্লাস (২০১৮) কোনো প্রচ্ছদ নেই (২০১৯)।', '2019-01-31 07:17:32', '2026-09-12 18:23:43'),
  (25, 28, 'parthomallik0418', 'parthomallik0418@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'পার্থ মল্লিক', 'parthomallik0418', 'author', '/uploads/avatars/parthomallik0418.jpeg', '', '2019-02-04 05:22:15', '2026-09-12 18:23:43'),
  (26, 29, 'payasti', 'payastimag@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'পয়স্তি ম্যাগাজিন', 'payasti', 'admin', '/uploads/avatars/payasti.png', 'পয়স্তি বাংলা তরুণ সাহিত্যিকদের লেখা প্রকাশে গুরুত্ব দিয়ে থাকে। পয়স্তি মনে করে আজকের তরুণ লেখকরাই আগামি দিনের প্রাজ্ঞ সাহিত্যিক হয়ে উঠবেন। আর এই বিশ্বাসের ‍উপরেই পয়স্তি নতুন লেখকদের সব থেকে বড় প্লাটফর্ম হিসেবে কাজ করতে চায়।', '2019-02-05 03:02:11', '2026-09-12 18:23:43'),
  (27, 30, 'sohelsobuj', 'sihelsobuj@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সোহেল সবুজ', 'sohelsobuj', 'author', '/uploads/avatars/sohelsobuj.jpg', '', '2019-02-05 06:00:43', '2026-09-12 18:23:43'),
  (28, 31, 'mizan.haris', 'mizan_haris@yahoo.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'হারিস মিজান', 'mizan-haris', 'author', '/uploads/avatars/mizan_haris.jpg', '', '2019-02-05 06:58:16', '2026-09-12 18:23:43'),
  (29, 32, 'shuvo.sharif', 'shuvo.sharif@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আহমেদ শরীফ শুভ', 'shuvo-sharif', 'author', '/uploads/avatars/shuvo_sharif.jpg', 'বাবাঃ আজগার আহমেদ। মাঃ শরীফুন্নেসা আহমেদ। জন্মঃ ২৭শে ফেব্রুয়ারি, ১৯৬২। শেকড় এবং শৈশবঃ কুমিল্লা। পেশায় চিকিৎসক। অষ্ট্রেলিয়ার মেলবোর্ণে কর্মরত। একাধারে কবি, গল্পকার, কলামিষ্ট ও সমাজকর্মী। প্রকাশিত গ্রন্থঃ কবিতা:\\r\\nবিহঙ্গ উড়িয়ে দাও (২০১০) , স্বপ্নে দেখি তোমার মুখ (২০১৩), ছোটগল্প: তৃষ্ণা ও জলে (২০১৩) , রাজকন্যার আহ্নিক (২০১৯), রাজনৈতিক নিবন্ধের সংকলন: বাংলাদেশে রাজনৈতিক সংস্কারের প্রস্তাবনা (২০০৫), মৃত্যুবার্ষিকী মৃত্যুবার্ষিকী খেলা (২০১১)।', '2019-02-07 07:41:02', '2026-09-12 18:23:43'),
  (30, 33, 'jimhamzah', 'jimhamzah@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জীম হামযাহ', 'jimhamzah', 'author', '/uploads/avatars/jimhamzah.jpg', '', '2019-02-11 09:06:42', '2026-09-12 18:23:43'),
  (31, 34, 'rashed.kiron', 'rashed.kiron@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রাশেদ কিরণ', 'rashed-kiron', 'author', '/uploads/avatars/rashed_kiron.jpg', '১৯৭২ সালের ২০ মে আলমডাঙ্গার অনতিদুরে আনন্দধামে জন্মগ্রহন করেন। পিতা সাইয়েদুল ইসলাম ও মাতা সালেহা খাতুন। শৈশব থেকেই সাহিত্য সংস্কৃতির প্রতি অনুরক্ত। কবিতার পাশাপাশি গল্প ও নাট্যচর্চার সাথে সংশ্লিষ্ট', '2019-02-13 11:14:09', '2026-09-12 18:23:43'),
  (32, 35, 'emam.mehedi', 'emam.mehedi@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইমাম মেহেদী', 'emam-mehedi', 'author', '/uploads/avatars/emam_mehedi.jpg', '', '2019-02-18 04:16:15', '2026-09-12 18:23:43'),
