  (34, 37, 'Minhaz.foysol', 'minhazfoysolbd@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মিনহাজ ফয়সল', 'minhaz-foysol', 'author', '/uploads/avatars/Minhaz_foysol.jpg', '', '2019-02-20 08:51:11', '2026-09-12 18:23:43'),
  (35, 38, 'amina.shelly', 'editor.dolok@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আমিনা শেলী', 'amina-shelly', 'author', '/uploads/avatars/amina_shelly.jpg', 'কবি ও গবেষক। পৃথিবীর প্রাচীন সাহিত্য নিয়ে গবেষণা করেন। বর্তমানে ইংল্যান্ডে বসবাস করছেন। দোলক নামে একটি ম্যাগাজিনের সম্পাদনা করেন।', '2019-02-26 04:52:45', '2026-09-12 18:23:43'),
  (36, 39, 'ahforayeji', 'ahforayeji@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আহসান হাবীব ফরায়েজী', 'ahforayeji', 'editor', '', '', '2019-03-02 06:25:39', '2026-09-12 18:23:43'),
  (37, 40, 'shahin', 'shahinacademy@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শাহীন আলম', 'shahin', 'author', '/uploads/avatars/shahin.jpg', 'পিতা: মোশারফ হোসেন, গ্রাম: বন্দরভিটা, পোস্ট: আসমানখালী, উপজেলা: আলমডাঙ্গা, জেলা: চুয়াডাঙ্গা।', '2019-03-03 07:24:03', '2026-09-12 18:23:43'),
  (38, 41, 'tithiafroj', 'tithiafroj@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'তিথি আফরোজ', 'tithiafroj', 'author', '/uploads/avatars/tithiafroj.jpg', 'জন্মঃ  নওগাঁ জেলার তুলসীগঙ্গার তীরে বোয়ালিয়া গ্রামে ৬ অক্টোবর ১৯৮৭। পিতাঃ  মরহুম আমির আলী সরদার। মাতাঃ আলতাফুন নেসা। শিক্ষাঃ রাষ্ট্রবিজ্ঞানে এম. এস. এস। শিক্ষকতা দিয়ে কর্মজীবনের সূচনা (ব্রাক প্রি-প্রাইমারী ও ক্যামব্রিয়ান স্কুল অ্যান্ড কলেজ) বর্তমানে বাংলাদেশ বিদুৎ উন্নয়ন বোর্ডের বিদ্যুৎ উৎপাদন কোম্পানিতে কর্মরত ( ঢাকা কর্পোরেট অফিস) । প্রকাশিত কবিতার বইঃ ছন্দপতনের শব্দ, ওড়ার কৌশল, তিথির তিরিশ। সম্পাদনাঃ পুনশ্চ (যৌথ),  ধূলিপথ। সম্মাননাঃ কবি জসীমউদ্দিন স্মৃতি পুরস্কার (চব্বিশ পরগনা, ভারত)', '2019-03-05 05:59:44', '2026-09-12 18:23:43'),
  (39, 42, 'bananubhab14', 'bananubhab14@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'অহি বন্দ্যোপাধ্যায়', 'bananubhab14', 'author', '/uploads/avatars/bananubhab14.jpg', 'অহি বন্দ্যোপাধ্যায় চন্দননগর নিবাসী এবং বাংলা সাহিত্যে স্নাতক স্তরের ছাত্র। নিজের আবেগগুলোকে প্রকাশ করার জন্য এবং সাহিত্যকে ভালোবেসেই লেখালিখি শুরু করেছে পরিবার এবং গৃ্হ শিক্ষক হারাধন বন্দোপধ্যায়ের অনুপ্রেরণায়।', '2019-03-07 04:01:15', '2026-09-12 18:23:43'),
  (40, 43, 'yaj3033', 'yaj3033@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সহন রুদ্র', 'yaj3033', 'author', '/uploads/avatars/yaj3033.jpg', '', '2019-03-09 04:16:34', '2026-09-12 18:23:43'),
  (41, 44, 'jamal', 'jamal.itsme@yahoo.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জামাল হোসেন', 'jamal', 'author', '/uploads/avatars/jamal.jpg', '', '2019-03-12 04:39:24', '2026-09-12 18:23:43'),
  (42, 45, 'emamabdullahhossain', 'emamabdullahhossain@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইমাম আব্দুল্লাহ হোসাইন', 'emamabdullahhossain', 'author', '/uploads/avatars/emamabdullahhossain.png', 'ইমাম আবদুল্লাহ হোসাইন\\r\\n\\r\\nইমাম আবদুল্লাহ হোসাইন একজন তরুণ কবি, লেখক, গবেষক, মুটার ও আইন শিক্ষার্থী। সমাজ, দর্শন, মুক্তচিন্তা, মানবাধিকার, মানবিক মর্যাদা ও সংবিধান তাঁর লেখালেখি ও গবেষণার প্রধান বিষয়।\\r\\n\\r\\nশিক্ষাজীবন থেকেই তিনি বিতর্ক, সৃজনশীলতা ও জ্ঞানচর্চায় যুক্ত। ২০১৫ সাল থেকে বিভিন্ন বিতর্ক প্রতিযোগিতায় অংশ নেন। ২০১৭–২০১৯ সালে জাতীয় শিক্ষা সপ্তাহে উপজেলা পর্যায়ে শ্রেষ্ঠ শিক্ষার্থী নির্বাচিত হন এবং গণিত অলিম্পিয়াডেও অংশগ্রহণ করেন।\\r\\n\\r\\n২০২০ সালে তিনি নটর ডেম কলেজে ভর্তি হন। ২০২১ সালে বেকম্যান আয়োজিত জাতীয় লেখালেখি প্রতিযোগিতায় বাংলা ছোটগল্পে প্রথম এবং ইংরেজি ছোটগল্পে তৃতীয় স্থান অর্জন করেন।\\r\\n\\r\\nবর্তমানে তিনি জাতীয় বিশ্ববিদ্যালয়ের গাজীপুর মূল ক্যাম্পাসের আইন বিভাগে অধ্যয়নরত। আইন শিক্ষার পাশাপাশি মুট কোর্ট, গবেষণা, বিতর্ক ও সাহিত্যচর্চায় সক্রিয়।\\r\\n\\r\\n২০২৬ সালে তিনি ‘সাবম্যাকস-সিএসডব্লিউসি লেক্সএআই ন্যাশনাল মুট কোর্ট কম্পিটিশন ২০২৬’-এ মুটার হিসেবে অংশ নেন। তাঁর দল ‘Best Emerging Team Award’ অর্জন করে।\\r\\n\\r\\nগবেষণায় তিনি আইন, মানবাধিকার, মানবিক মর্যাদা ও ফৌজদারি বিচারব্যবস্থা নিয়ে কাজ করেন। জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের একটি আন্তর্জাতিক গবেষণা সম্মেলনে প্রধান গবেষক হিসেবে গবেষণাপত্র উপস্থাপন করেন।\\r\\n\\r\\nতাঁর উল্লেখযোগ্য গবেষণা “Human Dignity Beyond Death: Necrophilia, Human Rights, and Criminal Law Reform in Bangladesh”। এতে মৃত্যুর পর মানব মর্যাদার আইনগত সুরক্ষা ও বাংলাদেশের ফৌজদারি আইন সংস্কারের প্রয়োজনীয়তা বিশ্লেষণ করা হয়েছে।\\r\\n\\r\\nসাহিত্যে তাঁর লেখার মূল বিষয় মানুষের অন্তর্জগৎ ও সমাজবাস্তবতা। প্রেম, বিষাদ, অস্তিত্ব, স্বাধীন চিন্তা ও মানবিক প্রশ্ন তাঁর কবিতায় প্রতিফলিত হয়। \\r\\n\\r\\nআইন, গবেষণা ও সাহিত্যের সমান্তরাল চর্চায় তিনি নিজস্ব বৌদ্ধিক ও সৃজনশীল পরিসর নির্মাণ করে চলেছেন।', '2019-03-14 07:01:11', '2026-09-12 18:23:43'),
  (43, 46, 'ahmedfaruque', 'ahmedrafuque@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আহমেদ ফারুক', 'ahmedfaruque', 'author', '/uploads/avatars/ahmedfaruque.jpg', '', '2019-03-16 04:54:20', '2026-09-12 18:23:43'),
  (44, 47, 'oadulislam', 'oadulislam3@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ওবাইদুল ইসলাম', 'oadulislam', 'author', '/uploads/avatars/oadulislam.jpg', '', '2019-03-18 09:44:59', '2026-09-12 18:23:43'),
  (45, 48, 'arforayeji', 'atiqur.shahitto@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আতিকুর ফরায়েজী', 'arforayeji', 'admin', '', 'আতিকুর ফরায়েজী। জন্ম ১৯৯১ খ্রিস্টাব্দে। চুয়াডাঙ্গা জেলার আলমডাঙ্গা উপজেলার নওদাবন্ডবিল গ্রামে তার জন্ম। তিনি একজন তরুণ কথাসাহিত্যিক, কবি এবং গীতিকার। তার প্রকাশিত বই: অতল জলের গভীরতা (কবিতা, ২০২৫ বইমেলা, পয়স্তি প্রকাশন)', '2019-03-19 08:49:50', '2026-09-12 18:23:43'),
  (46, 49, 'nazmulislamsheikh', 'n01864118764@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মোঃ নাজমুল শেখ', 'nazmulislamsheikh', 'author', '/uploads/avatars/nazmulislamsheikh.jpeg', '', '2019-03-23 10:17:33', '2026-09-12 18:23:43'),
  (47, 50, 'mahadihasantitu', 'mahadi16.hasan@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মেহেদী হাসান টিটু', 'mahadihasantitu', 'author', '/uploads/avatars/mahadihasantitu.jpg', '', '2019-03-24 10:19:26', '2026-09-12 18:23:43'),
  (48, 51, 'idrismondol', 'idrismondol018@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইদ্রিস মণ্ডল', 'idrismondol', 'author', '/uploads/avatars/idrismondol.jpeg', 'ইদ্রিস মণ্ডল একজন ছড়াকার। তিনি ১৯৬৫ সালের ২০ জুন চুয়াডাঙ্গা জেলার দামুড়হুদা উপজেলার বিষ্ণুপুর গ্রামে নানার বাড়ি জন্মগ্রহণ করেন। ইদ্রিস মণ্ডল দীর্ঘদিন যাবৎ ছড়া লিখে আসছেন। তিনি একজন সরকারি চাকুরিজীবি। স্বাস্থ্য বিভাগে কর্মরত আছেন।', '2019-03-30 02:26:04', '2026-09-12 18:23:43'),
  (49, 52, 'manjurulislam', 'shikkha.protity@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মনজুরুল ইসলাম', 'manjurulislam', 'author', '/uploads/avatars/manjurulislam.jpg', '', '2019-03-31 04:13:10', '2026-09-12 18:23:43'),
  (50, 53, 'jewelmiajee', 'jewelmiajee777@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জুয়েল মিয়াজি', 'jewelmiajee', 'author', '/uploads/avatars/jewelmiajee.jpg', 'জুয়েল মিয়াজি একজন ছাত্র। ফোকলোর জাতীয় কবি কাজী নজরুল ইসলাম বিশ্ববিদ্যালয়।\\r\\nত্রিশাল ময়মনসিংহ।', '2019-04-01 09:53:51', '2026-09-12 18:23:43');
REPLACE INTO `users` (`id`, `wp_id`, `username`, `email`, `password`, `display_name`, `nicename`, `role`, `avatar`, `bio`, `registered_at`, `created_at`) VALUES
  (51, 54, 'praggamousumi', 'pragga1000@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'প্রজ্ঞা মৌসুমী', 'praggamousumi', 'author', '/uploads/avatars/praggamousumi.jpg', 'প্রজ্ঞা মৌসুমী। জন্ম কুমিল্লায়, বেড়ে উঠা সুনামগঞ্জে। বৰ্তমানে প্ৰবাসে অৰ্বস্থানৱত। \'দৃশ্য-পোষা উঠোন\' লেখকেৱ প্ৰকাশিত প্ৰথম গল্পগ্ৰন্থ।', '2019-04-04 05:22:28', '2026-09-12 18:23:43'),
  (52, 55, 'fakirabubakka', 'fakirabubakka@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ফকির আবু বাক্কা শাহ্', 'fakirabubakka', 'author', '/uploads/avatars/fakirabubakka.jpg', 'বাউল কবি ফকির আবু বাক্কা শাহ্। জন্ম: বৃহত্তর কুষ্টিয়া জেলার আলমডাঙ্গা উপজেলার বাদেমাজু গ্রামে। গুরুর নাম: দিদার শাহ্। দিদার শাহ ছিলেন বেহাল শাহ্-এর যোগ্য শিষ্য। ধরা হয়, মরমী কবি লালন শাহ্-এর পরে বাউল তরিকায় সব থেকে প্রাজ্ঞ ছিলেন বেহাল শাহ্। ফকির আবু বাক্কা শাহ্ তার জীবনের অর্ধেক বাংলাদেশের বৃহত্তর কুষ্টিয়া জেলার আলমডাঙ্গা উপজেলার বাদেমাজু গ্রামে বসবাস করেন। পরে ভারতের সরিষাডাঙ্গায় বসবাস করতেন।', '2019-04-16 03:14:44', '2026-09-12 18:23:43'),
  (53, 56, 'dalanjahan', 'dalanjahan001@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'দালান জাহান', 'dalanjahan', 'author', '/uploads/avatars/dalanjahan.jpg', '', '2019-05-04 03:40:59', '2026-09-12 18:23:43'),
  (54, 57, 'omitavmir', 'omitavmir@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'অমিতাভ মীর', 'omitavmir', 'author', '/uploads/avatars/omitavmir.jpg', 'অমিতাভ মীর। প্রকৃত নাম: মীর মোমিন-উল হক। পিতা: মীর আবুল হোসেন, মাতা: সালেহা খাতুন। জন্ম ১৪ আগস্ট\'৬২ খ্রি. প্রাণের শহর ঢাকার মতিঝিলে। বর্তমানে পৈতৃক নিবাস চুয়াডাঙ্গা শহরে বসবাসরত।  জন্মসূত্রে বাংলাদেশী হলেও নিজেকে বিশ্বসংস্কৃতির মানুষ ও বিশ্বনাগরিক ভাবতে পছন্দ করেন। ধর্ম, বর্ণ, ভাষাগত সকল বিভেদের উর্ধ্বে গিয়ে এই প্রগতিশীল কবি নিজেকে একজন মানুষ ভাবতেই ভালোবাসেন। কবির বিশ্বাসে মনুষ্যত্বই মানুষের একমাত্র পরিচয়।', '2019-05-21 08:04:04', '2026-09-12 18:23:43'),
  (55, 58, 'jakirulhaque', 'jh_manna@hotmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জাকিরুল হক', 'jakirulhaque', 'author', '/uploads/avatars/jakirulhaque.jpg', 'জাকিরুল হক\\r\\nজেন্ম: ২২ সেপ্টেম্বর ২০০০\\r\\nবাসস্থান: সুনামগঞ্জ', '2019-05-22 04:13:50', '2026-09-12 18:23:43'),
  (56, 59, 'mostafamohsinadv', 'mostafamohsinadv@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মোস্তফা মহসীন', 'mostafamohsinadv', 'author', '/uploads/avatars/mostafamohsinadv.jpg', '', '2019-06-01 07:02:22', '2026-09-12 18:23:43'),
  (57, 60, 'chituchuadanga', 'chituchuadanga@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'চিত্তরঞ্জন সাহা চিতু', 'chituchuadanga', 'author', '', 'বড় বাজার,  চুয়াডাঙ্গা,  বাংলাদেশ।', '2019-06-04 03:12:02', '2026-09-12 18:23:43'),
  (58, 62, 'sibsongkar pal', 'sibsongkarpal@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শীবশঙ্কর পাল', 'sibsongkar-pal', 'author', '', '', '2019-06-04 04:02:17', '2026-09-12 18:23:43'),
  (59, 63, 'sarkarpallab', 'sarkarpallab007@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সরকার পল্লব', 'sarkarpallab', 'author', '/uploads/avatars/sarkarpallab.jpg', 'জন্ম তারি: ২৫ মার্চ, জন্মস্থানঃ:গোবিন্দগঞ্জ, গাইবান্ধা, বর্তমান নিবাস	ঢাকা , বাংলাদেশ, পেশা:	ব্যবসা, শিক্ষাগত: যোগ্যতা ঢাকা কলেজ থেকে বিএসএস অনার্স, এমএসএস (রাজনীতি বিজ্ঞান)। বঙ্গীয় সাহিত্য ও সংস্কৃতি সংসদের প্রতিষ্ঠাকালীন কেন্দ্রীয় সমন্বয়ক । প্রগতিশীল রাজনৈতিক কর্মী, সম্মিলিত সাংস্কৃতিক আন্দোলন ও সামাজিক কার্যকমে নিয়োজিত। নিজ এলাকায় শিক্ষা প্রতিষ্ঠানসহ ক্লাব ও পাঠাগার প্রতিষ্টা করেছেন।', '2019-06-04 05:17:59', '2026-09-12 18:23:43'),
  (60, 64, 'mithilaislam', 'mithilaislam@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শেখ মিথিলা ইসলাম রিয়া', 'mithilaislam', 'author', '/uploads/avatars/mithilaislam.jpg', '', '2019-06-04 05:32:10', '2026-09-12 18:23:43'),
  (61, 66, 'raisuddinshah', 'raisuddinshah@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রইছ উদ্দীন শাহ্', 'raisuddinshah', 'author', '/uploads/avatars/raisuddinshah.jpg', '', '2019-06-10 10:15:31', '2026-09-12 18:23:43'),
  (62, 67, 'didaralishah', 'didaralishah@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'দিদার আলী শাহ্', 'didaralishah', 'author', '/uploads/avatars/didaralishah.jpg', '', '2019-06-11 08:31:17', '2026-09-12 18:23:43'),
  (63, 68, 'skakmjakaria', 'skakmjakaria@none.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শেখ একেএম জাকারিয়া', 'skakmjakaria', 'author', '/uploads/avatars/skakmjakaria.jpg', 'শেখ একেএম জাকারিয়া, জন্ম : ১৭ ফেব্রুয়ারি, ১৯৭৯, শিক্ষা : এমএসসি ( উদ্ভিদবিজ্ঞান, ২০০৩) মুরারিচাঁদ কলেজ, সিলেট। \\r\\n\\r\\nসম্পাদনা : ত্রৈমাসিক সাহিত্যপত্রিকা সুরমার ঢেউ ও অনলাইন সাহিত্যপত্রিকা সুরমার ঢেউ ডটকম। \\r\\n\\r\\nপ্রকাশিত গ্রন্থ : অর্থহীন ফুল ( ২০১৯),  বাংলা কবিতায় ছন্দের গুরুত্ব ( প্রবন্ধ ২০১৭), শব্দফুলের মালা ( ২০১২), ভালোবাসার নীল রং (২০১১), প্রার্থনা ( ২০১১), গোলকধাঁধা (২০১০)\\r\\n\\r\\nযৌথ গ্রন্থ : পনেরো কবির প্রেমের কবিতা, পাখি যায় দূরে উড়ে, সংকাশ, আমার প্রথম কবিতা, ছোট্টমণির প্রশ্ন অনেক( ছড়াগ্রন্থ) লিমেরিক, নিমগ্ন ধ্যানীর ছায়াপথ প্রভৃতি।', '2019-07-13 10:35:50', '2026-09-12 18:23:43'),
  (64, 69, 'abdussalam', 'abdussalam@none.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আব্দুস সালাম দৌলতী', 'abdussalam', 'author', '/uploads/avatars/abdussalam.png', '', '2019-07-21 03:40:00', '2026-09-12 18:23:43'),
  (65, 70, 'shahedali', 'shahedali@none.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শাহেদ আলী', 'shahedali', 'author', '/uploads/avatars/shahedali.jpg', '‘জিবরাঈলের ডানা’ খ্যাত বাংলা সাহিত্যে অন্যতম পুরোধা ব্যক্তিত্ব কথাশিল্পী শাহেদ আলী। সাহিত্যে যে শাখায় তিনি হাত রেখেছেন সেখানেই ফলেছে উজ্জ্বল সাহিত্যরত্ন। তিনি ১৯৫২ সালে ভাষা আন্দোলনের অন্যতম সক্রিয় সৈনিক। একাধারে ইসলামী চিন্তাবিদ, সাংবাদিক, অনুবাদক, গবেষক ও অধ্যাপক ছিলেন। উভয় বাংলা সাহিত্যে তাকে ছোটগল্প ও অনুবাদ কর্মে অন্যতম শ্রেষ্ট ব্যক্তিদের একজন হিসেবে গন্য করা হয়। জিবরাঈলের ডানা, একই সমতলে, অতীত রাতের কাহিনী, অমর কাহিনী, নতুন জমিনদার নামক ছোটগল্পের বইগুলো শাহেদ আলীকে পৌছে দেয় পাঠকদের খুব কাছে। উপন্যাস-হৃদয়নদী, অনুবাদ কর্ম- মক্কার পথ (মূল-মুহাম্মাদ আসাদ), ইতিবৃত্ত (মূল-হিরোডাটাস) অন্যতম। এছাড়াও শিশুদের জন্য লেখা- রুহির প্রথম পাঠ, সোনার গাঁয়ের সোনার মানুষ, ছোটদের ইমাম আবু হানিফা।\\r\\nকথাশিল্পী শাহেদ আলী ছোটগল্পের জন্য ১৯৬৪ খ্রীস্টব্দে বাংলা একাডেমী এবং ১৯৮৯ খ্রীস্টাব্দে একুশে পদক লাভ করেন।\\r\\nকথাশিল্পী শাহেদ আলীর মৃত্যুর পরে তার স্ত্রী ভাষাসৈনিক, কবি ও গল্পকার অধ্যাপিকা চেমন আরা প্রবন্ধ সমগ্র এক, অপ্রকাশিত উপন্যাস কাদা মাটির সাতকাহন গ্রন্থ আকারে প্রকাশ করেন। এছাড়াও শাহেদ আলীর রচিত অপ্রকাশিত আরো কিছু গল্প, উপন্যাস, শাহেদ আলীর আত্মজীবনী, প্রবন্ধ সমগ্র দুই, চিঠি ‘কথাশিল্পী শাহেদ আলী- চেমন আরা ট্রাস্ট’ কর্তৃক প্রকাশের কাজ সম্পন্ন হওয়ার অপেক্ষায়। কথাশিল্পী শাহেদ আলী অসংখ্য কবিতাও রচনা করেছেন। যা তার জীবন দশায় প্রকাশ করতে পারেন নি।', '2019-08-27 07:20:33', '2026-09-12 18:23:43'),
  (66, 71, 'arabinda.chakraborti', 'arabinda.chakraborti@none.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'অরবিন্দ চক্রবর্তী', 'arabinda-chakraborti', 'author', '/uploads/avatars/arabinda_chakraborti.jpg', 'অরবিন্দ চক্রবর্তীর জন্ম ফরিদপুরের ভাঙ্গা উপজেলার সদরদী গ্রামে ১১ আগস্ট ১৯৮৬। শিক্ষা : স্নাতকোত্তর। একটি প্রকাশনা প্রতিষ্ঠানে সম্পাদনা বিভাগে কর্মরত। তার প্রকাশিত বই : কবিতা— ছায়া কর্মশালা (২০১৩), সারামুখে ব্যান্ডেজ (২০১৬), সম্পাদনা— দ্বিতীয় দশকের কবিতা (২০১৬), অখণ্ড বাংলার দ্বিতীয় দশকের কবিতা (২০১৬), সম্পাদিত পত্রিকা— মাদুলি।', '2019-09-02 10:36:29', '2026-09-12 18:23:43'),
  (67, 72, 'naimur.rahman', 'naimurrhoman18@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'নাইমুর রহমান', 'naimur-rahman', 'author', '/uploads/avatars/naimur_rahman.jpg', '', '2019-09-05 07:22:46', '2026-09-12 18:23:43'),
  (68, 73, 'razzaksardar', 'razzaksardar@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সরদার মোহম্মদ রাজ্জাক', 'razzaksardar', 'author', '/uploads/avatars/razzaksardar.png', '', '2019-09-06 08:58:25', '2026-09-12 18:23:43'),
  (69, 74, 'adeelparvez', 'adeelparvez35@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আদেল পারভেজ', 'adeelparvez', 'author', '/uploads/avatars/adeelparvez.jpg', 'আদেল পারভেজ। স্থায়ী ঠিকানা নারায়ণগঞ্জ, রুপগঞ্জ । বর্তমানে  সিঙ্গাপুর প্রবাসী। ছোট্ট থেকেই সখেরবসে লেখা লেখির সাথে জড়িত।', '2019-09-11 03:55:20', '2026-09-12 18:23:43'),
  (70, 75, 'alaminbrur', 'alaminbrur24@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আল-আমীন আপেল', 'alaminbrur', 'author', '', '', '2019-11-30 18:23:57', '2026-09-12 18:23:43'),
  (71, 77, 'regan.eskender', 'regan.eskender@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রিগ্যান এসকান্দার', 'regan-eskender', 'author', '/uploads/avatars/regan_eskender.jpg', '', '2024-03-27 18:40:46', '2026-09-12 18:23:43'),
  (72, 78, 'kohonkuddus', 'kohonkuddus@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'কহন কুদ্দুস', 'kohonkuddus', 'author', '/uploads/avatars/kohonkuddus.jpg', 'কবি ও গবেষক। আলমডাঙ্গার কালিদাসপুর গ্রামে তার বসবাস। ২০১৪ সালে প্রকাশিত ‘কালের সাম্পান’ তার প্রথম কবিতার বই। ২০২৩ সালে আলমডাঙ্গার লেখক এবং সাংবাদিকদের নিয়ে ‘ডাঙা’ শিরোনামে আর একটি বই প্রকাশিত হয়েছে।', '2024-05-02 07:52:27', '2026-09-12 18:23:43'),
  (73, 79, 'asforayeji', 'asforayeji@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আল শারাফার শিশির ফরায়েজী', 'asforayeji', 'author', '/uploads/avatars/asforayeji.jpg', '', '2024-05-11 18:18:56', '2026-09-12 18:23:43'),
  (74, 80, 'shirshendumukhopadhyay', 'shirshendumukhopadhyay@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শীর্ষেন্দু মুখোপাধ্যায়', 'shirshendumukhopadhyay', 'author', '/uploads/avatars/shirshendumukhopadhyay.jpg', 'শীর্ষেন্দু মুখোপাধ্যায় (জন্ম: ২ নভেম্বর ১৯৩৫) একজন বিখ্যাত ভারতীয় বাঙালি সাহিত্যিক, যিনি শিশু ও প্রাপ্তবয়স্কদের জন্য গল্প ও উপ্যনাস লিখে থাকেন। ১৯৮৮ সালে তার মানবজমিন উপ্যনাসের জন্য সাহিত্য একডেমি পুরস্কার পেয়েছেন। ছোটদের জন্য লেখা উপ্যনাসের মধ্যে মনোজদের অদ্ভুত বাড়ি, গোসাঁই-বাগানের ভূত জনপ্রিয়।', '2024-08-21 09:28:25', '2026-09-12 18:23:43'),
  (75, 81, 'masud-ahmad', 'masud-ahmad@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মাসউদ আহমাদ', 'masud-ahmad', 'author', '/uploads/avatars/masud-ahmad.jpg', 'মাসউদ আহমাদের জন্ম ৫ জুন ১৯৮৫, রাজশাহীর পুঠিয়ায়। রাজশাহী বিশ্ববিদ্যালয় থেকে স্নাতক ও স্নাতকোত্তর। লেখালেখির চেষ্টা অনেকদিনের। গল্প দিয়ে শুরু। ছোটগল্পই লেখার চেষ্টা করেন। বাংলাদেশের শীর্ষস্থানীয় প্রায় সব দৈনিকের সাহিত্য সাময়িকীতে গল্প বেরিয়েছে। ১৭ ফেব্রুয়ারি ২০১৭-তে কলকাতার ‘দেশ’পত্রিকায় প্রকাশিত হয়েছে তাঁর ‘পাণ্ডুলিপি করে আয়োজন’নামের গল্প; পরে আরো একটি গল্প ‘দূর পৃথিবীর গন্ধে’, ১৭ নভেম্বর ২০২০-এ। দেশ শারদীয় সংখ্যা ১৪২৮-এ প্রকাশিত হয়েছে গল্প ‘জনৈক কবির স্মরণসভা’। সম্প্রতি দেশ পত্রিকায় শুরু হয়েছে তাঁর দীর্ঘ ধারাবাহিক উপন্যাস ‘কাঞ্চনফুলের কবি’। জীবনানন্দ দাশের জীবন ও সময় অবলম্বনে লেখা উপন্যাসটি ইতোমধ্যে দুই বাংলায় সাড়া ফেলেছে। তিনি গল্পবিষয়ক লিটল ম্যগাজিন ‘গল্পপত্র’ সম্পাদনা করেন। দীর্ঘদিন সাংবাদিকতার সঙ্গে যুক্ত ছিলেন; সর্বশেষ কর্মস্থল দৈনিক কালের কণ্ঠের সম্পাদকীয় বিভাগ। বর্তমানে একটি বেসরকারি ব্যাংকে কর্মরত।', '2024-08-21 09:31:07', '2026-09-12 18:23:43'),
  (76, 82, 'alamjakaria', 'alamjakaria@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আলম জাকারিয়া', 'alamjakaria', 'author', '/uploads/avatars/alamjakaria.jpg', 'আলম জাকারিয়া কুষ্টিয়া জেলার ভেরামারা উপজেলায় জন্মগ্রহণ করেন এবং বর্তমানে সেখানেই বসবাস করছেন। কর্মজীবনে তিনি একজন ডেন্টিস্ট। কাজের সুবাদে দির্ঘদিন চুয়াডাঙ্গা জেলার আলমডাঙ্গা উপজেলায় বসবাস করেছেন।', '2024-10-20 10:46:47', '2026-09-12 18:23:43'),
  (77, 83, 'niamot-al--master', 'niamot-al--master@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'নিয়ামত আলী মাস্টার', 'niamot-al-master', 'author', '/uploads/avatars/niamot-al--master.jpg', 'নিভৃতচারী ও একনিষ্ঠ লালন গবেষক ছিলেন আলমডাঙ্গার নিয়ামত আলী মাস্টার। তিনি ১৯৪৮ সালে ২৭ জুলাই আলমডাঙ্গা গোবিন্দপুর গ্রামে জন্মগ্রহণ করেন। তার পিতার নাম ইসমাইল ম-ল। প্রাতিষ্ঠানিক শিক্ষা শেষে তিনি শিক্ষকতাকে পেশা হিসেবে নেন। ২০০৫ সালে তিনি প্রাথমিক বিদ্যালয়ের প্রধান শিক্ষকের পদ থেকে অবসর গ্রহণ করেন। বাংলা একাডেমির সহকারী পরিচালক সাইমুন জাকারিয়ার সাথে তার ছিলো বিশেষ হৃদ্যতা। মাঝে মধ্যেই সাইমুন জাকারিয়া ছুটে আসতেন তার নিকট। ২০২১ সালেরৈ ২৩ আগস্ট তিনি মৃত্যুবরণ করেন।', '2024-10-23 17:38:03', '2026-09-12 18:23:43'),
  (78, 84, 'shahnewazbiplob', 'shahnewazbiplob@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শাহনেওয়াজ বিপ্লব', 'shahnewazbiplob', 'author', '/uploads/avatars/shahnewazbiplob.jpg', '', '2024-11-21 04:54:18', '2026-09-12 18:23:43'),
  (79, 85, 'rokonreza', 'rokonreza1979@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'রোকন রেজা', 'rokonreza', 'author', '/uploads/avatars/rokonreza.jpg', '', '2025-02-16 10:58:59', '2026-09-12 18:23:43'),
  (80, 86, 'Sadia Sultana', 'sadiasultana8499@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সাদিয়া মুনমুন', 'sadia-sultana', 'author', '/uploads/avatars/Sadia_Sultana.jpeg', 'নাম: সাদিয়া মুনমুন। স্বামী: মরহুম মাহমুদুল হাসান। পিতা: মো: নুরুল আমিন। মাতা: নার্গিস পারভীন। থানা: সাতক্ষীরা। জেলা: সাতক্ষীরা। যে ধরনের লেখা লিখতে আগ্রহী: ছোটগল্প, প্রবন্ধ, কবিতা। যেভাবে প্রথম লেখালেখি শুরু হয়: দ্বাদশ শ্রেণীতে থাকাকালে একটা অসমাপ্ত উপন্যাস দিয়ে লেখালেখি শুরু হয়। উপন্যাসটির মূল বিষয়বস্তু ছিল সম্পূর্ণ কাল্পনিক।', '2025-04-14 04:33:45', '2026-09-12 18:23:43'),
  (81, 87, 'akibshikder', 'akibshikder333@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'আকিব শিকদার', 'akibshikder', 'author', '/uploads/avatars/akibshikder.jpg', 'আকিব শিকদার। জন্ম কিশোরগঞ্জ জেলার হোসেনপুর থানাধীন তারাপাশা গ্রামে, ০২ ডিসেম্বর ১৯৮৯ সালে। প্রফেসর আলহাজ মোঃ ইয়াকুব আলী শিকদার ও মোছাঃ নূরুন্নাহার বেগম এর জ্যেষ্ঠ সন্তান। স্নাতক পড়েছেন শান্ত-মরিয়ম ইউনিভার্সিটি থেকে ফ্যাশন ডিজাইন বিষয়ে। পাশাপাশি জাতীয় বিশ্ববিদ্যালয় থেকে ইসলামের ইতিহাস ও সংস্কৃতিতে স্নাতক ও স্নাতোকোত্তর। খন্ডকালীন শিক্ষকতা দিয়ে কর্মজীবন শুরু; বর্তমানে কর্মরত আছেন আইয়ূব-হেনা পলিটেকনিক ইন্সটিটিউটে।\\r\\nকবির বিধ্বস্ত কঙ্কাল (২০১৪), দেশদ্রোহীর অগ্নিদগ্ধ মুখ (২০১৫), কৃষ্ণপক্ষে যে দেয় উষ্ণ চুম্বন (২০১৬), জ্বালাই মশাল মানবমনে (২০১৮), দৃষ্টি মেলো জন্মান্ধ চোখ (২০২৩) তার উল্লেখযোগ্য কাব্যগ্রন্থ। দোলনা দোলার কাব্য (২০২১) তার শিশুতোষ কবিতার বই।  \\r\\nসাহিত্য চর্চায় উৎসাহ স্বরুপ পেয়েছেন “হো.সা.স. উদ্দীপনা সাহিত্য পদক”, “সমধারা সাহিত্য সম্মাননা”,  “মেঠোপথ উদ্দীপনা পদক”, “পাপড়ি-করামত আলী সেরা লেখক সম্মাননা” , “উদ্দীপন সাহিত্য-সংস্কৃতি পদক”, “স্বাধীন বাংলা সাহিত্য পরিষদ গুণীজন সম্মাননা”। লেখালেখির পাশাপাশি সঙ্গীত ও চিত্রাংকন তার নেশা।', '2025-05-06 19:35:18', '2026-09-12 18:23:43'),
  (82, 88, 'shammitultul', 'shammitultul@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শাম্মী তুলতুল', 'shammitultul', 'author', '/uploads/avatars/shammitultul.jpg', 'শাম্মী তুলতুল-এর লিখায় এক ধরনের ম্যাসেজ থাকে সব সময়।আছে সমাজ এবং সমাজ সচেতন করার এক প্রকার শক্তি।খুব অল্প বয়সেই তিনি দেশ ও দেশের বাইরে তার লেখনি দিয়ে জয় করেছেন অজস্র মানুষের ভালোবাসা।সাহিত্যিক শাম্মী তুলতুল চট্টগ্রামের একটি অভিজাত সাহিত্য, সাংস্কৃতিক, রাজনৈতিক, উচ্চশিক্ষিত , রক্ষণশীল ও মুক্তিযুদ্ধ পরিবারে জন্ম গ্রহণ করেন।সেই সুবাদে পরিবারের লোকজনকে একদিকে যেমন দেখেছেন সাহিত্য চর্চা করতে। অন্যদিকে দেখেছেন রাজনীতিতে সমানতালে অংশগ্রহণ করতে।তাই লেখালেখি তার রক্তে মুক্তিযুদ্ধ তার চেতনায়। লেখালেখির হাতে খড়ি শিশু থেকেই।স্বরচিত ছড়া পাঠ করে প্রথম পুরস্কার অর্জন করেন শিশু বয়সেই। বাবা আলহাজ আবু মোহাম্মদ খালেদ একজন শিক্ষাবিদ, সংগঠক ছিলেন|বর্তমানে একজন বিশিষ্ট ব্যবসায়ী সমাজসেবক ও সংগঠক।মা আলহাজ কাজী রওশন আখতার ছিলেন রাউজান কলেজ ছাত্র সংগঠনের নেত্রী।শীর্ষে আছেন দেশের প্রথম সারির দৈনিক পত্রিকা ও দেশের বাইরের প্রথম সারির পত্রিকাগুলোতে এক যুগ ধরে লেখালেখি করে। অধ্যায়ণ করছেন দেশ সেরা ঐতিহ্যবাহী চট্টগ্রাম সরকারী কলেজে।লেখালেখির পাশাপাশি চট্টগ্রাম বেতারে অনুষ্ঠান গ্রন্থনা ও চট্টগ্রাম টেলিভিশনে নিয়মিত আবৃত্তিও করে থাকেন।২০১৬ বইমেলায় তার রকমারি বেষ্ট সেলার দুটো বই, মুক্তিযুদ্ধ ভিত্তিক প্রথম উপন্যাস “চোরাবালির বাসিন্দা” ও শিশু-কিশোরদের বই “গণিত মামার চামচ রহস্য” তাকে নিয়ে যায় দিগুণ খ্যাতির শীর্ষে।তার আরও দুটো বই হলো কলামের বই মুক্তিযুদ্ধের চেতনা ও অন্যান্য প্রসঙ্গ, (২০১৩)।টুনটুনির পাখিস্কুল (২০১৪)। সাহিত্যে অবদানের জন্য তিনি ইতিমধ্যে জাতীয় পুরস্কারেও ভূষিত হন।', '2025-05-30 06:33:20', '2026-09-12 18:23:43'),
  (83, 89, 'prema', 'prema@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'মোহনা হাসান প্রেমা', 'prema', 'author', '/uploads/avatars/prema.jpg', 'মোহনা হাসান প্রেমা সমসাময়িক বাংলা কবিতার এক উজ্জ্বল কণ্ঠস্বর। জন্মেছেন বাংলাদেশের সীমান্তঘেঁষা জেলা চুয়াডাঙ্গায়, আর বর্তমানে বসবাস করছেন রাজধানী ঢাকা শহরে। শহরের কোলাহলের মাঝেও তার কবিতায় স্পষ্ট হয়ে ওঠে একান্ত ব্যক্তিগত অনুভব, হৃদয়ের দ্বন্দ্ব এবং সময়ের সমাজবাস্তবতা।\\r\\n\\r\\nকবিতার প্রতি তার গভীর অনুরাগ ও ভাষার প্রতি ভালোবাসা নিয়ে তিনি প্রকাশ করেছেন দুইটি কাব্যগ্রন্থ। তার দুইটি কাব্যগ্রন্থ— আমার কিছু বলার ছিল এবং আমি এখন বদলে গেছি', '2025-06-30 17:55:23', '2026-09-12 18:23:43'),
  (84, 90, 'shishirazam', 'shishir01978@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শিশির আজম', 'shishirazam', 'author', '/uploads/avatars/shishirazam.jpg', 'শিশির আজম । জন্ম : ২৭ অক্টোবর, ১৯৭৮। জন্মস্থান, বর্তমান ও স্থায়ী ঠিকানা :  এলাংগী, কোটচাঁদপুর, ঝিনাইদহ -৭৩৩০, বাংলাদেশ। কাব্যগ্রন্থসমূহ : ছাই (২০০৫), দেয়ালে লেখা কবিতা (২০০৮), রাস্তার জোনাকি (২০১৩), ইবলিস (২০১৭), চুপ (২০১৭), মারাঠা মুনমুন আগরবাতি (২০১৮), মাতাহারি (২০২০), টি পোয়েট্রি (২০২০), সরকারি কবিতা (২০২১), হংকঙের মেয়েরা (২০২২), আগুন (২০২৪), চা কফি আর জেনারেল কানেকটিভিটি (২০২৪), সন্ধ্যায় তিমিমাছ (২০২৫), প্রবন্ধ : কবির কুয়াশা (২০২৫)', '2025-07-17 07:01:22', '2026-09-12 18:23:43'),
  (85, 91, 'redoy3271', 'redoy3271@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ইসতিয়াক আহমেদ হৃদয়', 'redoy3271', 'author', '/uploads/avatars/redoy3271.png', 'ইসতিয়াক আহমেদ হৃদয় (কবি ও প্রাবন্ধিক)। জেলা : জয়পুরহাট, উপজেলা: আক্কেলপুর', '2025-08-10 05:50:40', '2026-09-12 18:23:43'),
  (86, 92, 'khairulIslam', 'khairulIslam@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'খাইরুল ইসলাম', 'khairulislam', 'author', '/uploads/avatars/khairulIslam.jpg', 'খাইরুল ইসলাম ১৯৮৮ সালের ২২ এপ্রিল চুয়াডাঙ্গা জেলার আলমডাঙ্গায় জন্মগ্রহণ করেন। তিনি ঢাকা বিশ্ববিদ্যালয় থেকে ইসলামের ইতিহাস ও সংস্কৃতি বিভাগ হতে স্নাতকোত্তর ডিগ্রি অর্জন করে কলেজ শিক্ষকতা পেশায় যুক্ত আছেন। শিক্ষকতার পাশাপাশি তিনি মুক্তিযুদ্ধ গবেষক ও মানবাধিকার কর্মী হিসেবে কাজ করছেন।  শখ করে করেন সাংবাদিকতা লেখালেখিও।', '2025-08-21 12:04:50', '2026-09-12 18:23:43'),
  (87, 93, 'drsujataghosh', 'drsujata@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ডাঃ সুজাতা ঘোষ', 'drsujataghosh', 'author', '/uploads/avatars/drsujataghosh.png', '', '2025-09-24 00:57:52', '2026-09-12 18:23:43'),
  (88, 391, 'fazlul-haque-tuhin', 'fazlul-haque-tuhin@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'ড. ফজলুল হক তুহিন', 'fazlul-haque-tuhin', 'author', '/uploads/avatars/fazlul-haque-tuhin.jpg', '', '2025-12-29 17:35:54', '2026-09-12 18:23:43'),
  (89, 711, 'sabinarahmanchoudhury', 'sabinarahmanchoudhury@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'সাবিনা রহমান চৌধুরী', 'sabinarahmanchoudhury', 'author', '/uploads/avatars/sabinarahmanchoudhury.jpg', '', '2026-01-22 10:21:52', '2026-09-12 18:23:43'),
  (90, 1157, 'sharmikadasbanhi', 'banhi2104@cseku.ac.bd', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'শর্মিকা দাস বহ্নি', 'sharmikadasbanhi', 'author', '/uploads/avatars/sharmikadasbanhi.jpeg', 'শর্মিকা দাস বহ্নি মূলত একজন স্বপ্নদ্রষ্টা, যার ভাবনার জগৎ আবর্তিত হয় শব্দ আর শিল্পের মেলবন্ধনে। তাঁর জন্ম ও বেড়ে ওঠা পলিধন্য বরিশালে। বর্তমানে তিনি খুলনা বিশ্ববিদ্যালয়ের কম্পিউটার সায়েন্স অ্যান্ড ইঞ্জিনিয়ারিং ডিসিপ্লিনে অধ্যয়নরত।\\r\\n\\r\\nশৈশব থেকেই সাহিত্যের প্রতি গভীর অনুরাগ থেকে তাঁর লেখালেখির হাতেখড়ি। কবিতার ছন্দ, ছোট গল্পের জীবনধর্মী আখ্যান আর জীবনবোধের সংক্ষিপ্ত প্রকাশ হিসেবে ‘কোটেশন’ বা উক্তি লিখতে তিনি পছন্দ করেন। বিজ্ঞানের শিক্ষার্থী হওয়া সত্ত্বেও সৃজনশীলতার আঙিনায় তাঁর বিচরণ অবাধ। লেখালেখির পাশাপাশি ছবি আঁকা এবং নান্দনিক ক্রাফটিং বা হস্তশিল্পে তাঁর রয়েছে বিশেষ দক্ষতা ও শখ। তাঁর সৃষ্টিতে একদিকে যেমন ফুটে ওঠে যান্ত্রিক জীবনের বাইরের কোমল আবেগ, অন্যদিকে তুলির আঁচড়ে প্রাণ পায় বিচিত্র সব কল্পনা।\\r\\n\\r\\nঅনাগত ভবিষ্যতে সাহিত্য ও প্রকৌশল—উভয় ক্ষেত্রেই নিজের প্রতিভার স্বাক্ষর রাখতে তিনি বদ্ধপরিকর।', '2026-04-14 10:34:20', '2026-09-12 18:23:43'),
  (91, 1205, 'jenifarjaman', 'jenifarjaman@payasti.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জেনিফা জামান', 'jenifarjaman', 'author', '/uploads/avatars/jenifarjaman.jpg', '', '2026-04-30 10:24:30', '2026-09-12 18:23:43'),
  (92, 1500, 'MichaelTrabe', 'qfftjxzm@firsthidden.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'MichaelTrabe', 'michaeltrabe', 'contributor', '', '', '2026-09-07 14:00:30', '2026-09-12 18:23:43'),
  (93, 1501, 'JONIBISWAS', 'jonibiswas1000@gmail.com', '$2b$10$q74V2POIN6SAEooVPts0kusvsXItnldg/pCQsTXoaH3Az9DhhUUvS', 'জনি বিশ্বাস', 'jonibiswas', 'contributor', '/uploads/avatars/JONIBISWAS.jpg', 'জনি বিশ্বাস ১৯৯৮ সালের ২১ জুলাই ব্রাহ্মণবাড়িয়া জেলার নাসিরনগর উপজেলায় জন্মগ্রহণ করেন। তাঁর পিতা শ্যামল বিশ্বাস এবং মাতা সবিতা বিশ্বাস।\\r\\nতিনি নাসিরনগর আশুতোষ পাইলট উচ্চ বিদ্যালয় থেকে মাধ্যমিক (এসএসসি) এবং নাসিরনগর সরকারি কলেজ থেকে উচ্চমাধ্যমিক (এইচএসসি) উত্তীর্ণ হন। পরবর্তীতে বঙ্গবন্ধু শেখ মুজিবুর রহমান বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয়ের ম্যানেজমেন্ট স্টাডিজ বিভাগ থেকে বিবিএ (BBA) ডিগ্রি অর্জন করেন।\\r\\nবর্তমানে তিনি দ্য ইনস্টিটিউট অব চার্টার্ড অ্যাকাউন্ট্যান্টস অব বাংলাদেশ (আইসিএবি)-এর অধীনে সিএ আর্টিকেলশিপ শিক্ষার্থী হিসেবে পেশাগত প্রশিক্ষণ গ্রহণ করছেন। নিরীক্ষা (Audit), হিসাববিজ্ঞান (Accounting), আর্থিক প্রতিবেদন (Financial Reporting), করব্যবস্থা (Taxation) এবং করপোরেট অর্থব্যবস্থাপনা (Corporate Finance) তাঁর আগ্রহের প্রধান ক্ষেত্র। পেশাগত দক্ষতা ও নৈতিকতার সমন্বয়ে একজন দক্ষ চার্টার্ড অ্যাকাউন্ট্যান্ট হিসেবে নিজেকে গড়ে তোলাই তাঁর লক্ষ্য।\\r\\nশিক্ষাজীবনের শুরু থেকেই বাংলা সাহিত্য, বিশেষ করে কবিতা, তাঁর আগ্রহের অন্যতম ক্ষেত্র। নিয়মিত কবিতা, ছোটগল্প ও অন্যান্য সৃজনশীল লেখা রচনার পাশাপাশি তিনি বিভিন্ন সাহিত্যভিত্তিক প্ল্যাটফর্মে লেখালেখি করে আসছেন। তাঁর প্রকাশিত কবিতা ‘কাঠগড়া’ ডিবিসি নিউজের সাহিত্য বিভাগে প্রকাশিত হয়ে পাঠকমহলে প্রশংসা অর্জন করে।\\r\\nসাহিত্যচর্চায় তিনি মানবজীবন, সমাজ, সময়, অনুভূতি এবং বাস্তব অভিজ্ঞতাকে গুরুত্ব দিয়ে লিখতে পছন্দ করেন। একই সঙ্গে পেশাগত জীবনে শৃঙ্খলা, সততা, বিশ্লেষণী চিন্তাশক্তি এবং দায়িত্ববোধকে তিনি সমানভাবে মূল্য দেন।\\r\\nসাহিত্য ও পেশাগত জীবনের মধ্যে ভারসাম্য বজায় রেখে জ্ঞানচর্চা, সৃজনশীলতা এবং আত্মোন্নয়নের মাধ্যমে সমাজে ইতিবাচক অবদান রাখার প্রত্যাশা নিয়েই তিনি এগিয়ে চলেছেন।', '2026-09-07 17:36:31', '2026-09-12 18:23:43'),
