REPLACE INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES
  (1, 1, 1, 'অন্য সাহিত্য', 'অন্য-সাহিত্য', 0, '', 16),
  (2, 2, 2, 'ধারাবাহিক', 'ধারাবাহিক', 0, '', 14),
  (3, 3, 3, 'প্রবন্ধ', 'প্রবন্ধ', 0, 'সাহিত্যে বর্ণনামূলক গদ্যকে প্রবন্ধ বলা হয়। প্রবন্ধ পয়স্তির অন্যতম একটি শাখা। এর সমার্থক শব্দগুলো হল - সংগ্রহ, রচনা, সন্দর্ভ। প্রবন্ধের বিষয়বস্তু শৈল্পিক, কাল্পনিক, জীবনমুখী, ঐতিহাসিক কিম্বা আত্মজীবনীমূলক। পয়স্তি ওয়েবম্যাগে বাংলা সাহিত্যিকদের রচিত প্রবন্ধ এই শাখায় প্রকাশিত হয়ে থাকে।\\r\\n', 14),
  (4, 4, 4, 'কবিতা', 'কবিতা', 12, 'বাংলা কবিতাকে বাংলা সাহিত্যের সব থেকে পুরাতন শাখা হিসেবে ধরা হয়। পয়স্তির ‘পদ্য’ বিভাগে ‘কবিতা’ বিভাগটি রয়েছে।  বাংলা সাহিত্যিকদের রচিত বাংলা কবিতা পয়স্তি ওয়েবম্যাগের ‘কবিতা’ বিভাগে প্রকাশ করা হয়।', 66),
  (5, 7, 7, 'অনুবাদ', 'অনুবাদ', 0, 'বাংলা সাহিত্যে অনুবাদ সাহিত্যের ধারা বিশেষভাবে উল্লেখযোগ্য। ভাষান্তরের বাঁধা পেরিয়ে, ভৌগোলিক দূরত্বকে জয় করে বিশ্বমানবের সঙ্গে সংযুক্ত হওয়ার সুযোগ এনে দেয় অনুবাদ। বাংলাদেশে অনুবাদ সাহিত্য ব্যাপকভাবে চর্চিত। পয়স্তি ওয়েবম্যাগের ‘অনুবাদ’ বিভাগে বাংলাদেশের অনুবাদকদের অনুবাদকৃত সাহিত্যগুলো প্রকাশ প্রকাশ করা হয়।', 9),
  (6, 8, 8, 'সাক্ষাৎকার', 'সাক্ষাৎকার', 0, '', 1),
  (7, 9, 9, 'গদ্য', 'গদ্য', 0, 'উনবিংশ শতাব্দীর নবজাগৃতির সার্থক রূপায়ণে সাহায্য করেছিল বাংলা গদ্য ভাষা। এর সূচনা আঠারো শতকেই হয়েছিল। পয়স্তিতে ‘গদ্য’ বিভাগের মধ্যে রয়েছে ‘ছোটগল্প’ এবং ‘অণুগল্প’। পয়স্তি ওয়েবম্যাগের ‘গদ্য’ বিভাগে বাংলা সাহিত্যিকদের রচিত ছোটগল্প এবং অণুগল্প প্রকাশ করা হবে।', 44),
  (8, 47, 47, 'অণুগল্প', 'অনুগল্প', 7, 'একবিশ্ব শতাব্দিতে বাংলা সাহিত্যের অত্যতম আলোচিত এবং চর্চিত বিভাগ হলো ‘অণুগল্প’। পয়স্তিতে ‘অণুগল্প’ বিভাগটি ‘গদ্য’ বিভাগের মধ্যে রয়েছে। পয়স্তি ওয়েবম্যাগের ‘অণুগল্প’ বিভাগে বাংলা সাহিত্যিকদের রচিত অণুগল্প প্রকাশিত হয়।', 5),
  (9, 48, 48, 'ছোটগল্প', 'ছোটগল্প', 7, 'বিংশ এবং একবিশ্ব শতাব্দিতে বাংলা সাহিত্যের অত্যতম শক্তিশালী বিভাগ হলো ‘ছোটগল্প’। পয়স্তিতে ‘ছোটগল্প’ বিভাগটি ‘গদ্য’ বিভাগের মধ্যে রয়েছে। পয়স্তি ওয়েবম্যাগের ‘ছোটগল্প’ বিভাগে বাংলা সাহিত্যিকদের রচিত ছোটগল্প প্রকাশিত হয়।', 38),
  (10, 67, 67, 'পাঠপতিক্রিয়া', 'পাঠপতিক্রিয়া', 0, '', 2),
  (11, 69, 69, 'ছড়া', 'ছড়া', 12, 'বাংলা কবিতার মতো বাংলা সাহিত্যের জনপ্রিয় শাখা হিসেবে ছড়াতে ধরা হয়। পয়স্তির ‘পদ্য’ বিভাগে ‘ছড়া’ বিভাগটি রয়েছে। বাংলা সাহিত্যিকদের রচিত বাংলা ছড়া পয়স্তি ওয়েবম্যাগের ‘ছড়া’ বিভাগে প্রকাশ করা হয়।', 10),
  (12, 71, 71, 'পদ্য', 'পদ্য', 0, 'সাহিত্যে ভাব প্রকাশের অন্যতম দু\'টি মাধ্যম হচ্ছে \'গদ্য\' ও \'পদ্য\'। পয়স্তির ‘পদ্য’ বিভাগটিতে ‘কবিতা’ এবং ‘ছড়া’ দুইটি বিভাগ অন্তর্ভূক্ত রয়েছে। পয়স্তি ওয়েবম্যাগের ‘পদ্য’ বিভাগে বাংলা সাহিত্যিকদের রচিত কবিতা ও ছড়া প্রকাশিত হয়।\\r\\n', 80),
  (13, 136, 136, 'বড় গল্প', 'বড়-গল্প', 7, '', 5),
  (14, 155, 155, 'গীতি কবিতা', 'গীতি-কবিতা', 12, 'গান সাহিত্যের একটি গুরুত্বপূর্ণ শাখা। কাথায় আছে- গদ্যে পদ্যে যা নাই, গানে তাও হয়। পয়স্তির ‘পদ্য’ বিভাগে ‘গান’ বিভাগটি রয়েছে।  বাংলা সাহিত্যিকদের রচিত বাংলা গান পয়স্তি ওয়েবম্যাগের ‘গান’ বিভাগে প্রকাশ করা হয়।', 3);
