REPLACE INTO `posts` (`id`, `wp_id`, `author_id`, `title`, `slug`, `content`, `excerpt`, `featured_image`, `category_id`, `subcategory_id`, `status`, `views`, `is_featured`, `published_at`, `created_at`, `updated_at`) VALUES
  (1, 2024, 7, 'আসতে যদি', 'আসতে-যদি', '<!-- wp:paragraph {\\"align\\":\\"left\\"} -->\n<p style=\\"text-align: left;\\">আমার গাঁয়ে ডিঙি নায়ে<br />আসতে তুমি যদি,<br />দেখতে নদী কলকলিয়ে<br />বইছে নিরবধি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেখতে তুমি নায়ের মাঝির<br />ভাটিয়ালি গানে,<br />শহুরে প্রাণে কেমন করে<br />সুখের পরশ আনে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেখতে তুমি সবুজ ভূমি<br />ডাকছে আচঁল পেতে,<br />বলছে কেউ নিমন্ত্রণে <br />মন্ঠা-মিঠাই খেতে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আসলে নাতো বন্ধু তুমি<br />আমার ছোট্ট গাঁয়ে,<br />কেমন করে মাখবে বলো<br />ভোরের শিশির পায়ে!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><!-- /wp:paragraph -->', 'আমার গাঁয়ে ডিঙি নায়ে\nআসতে তুমি যদি,\nদেখতে নদী কলকলিয়ে\nবইছে নিরবধি।\nদেখতে তুমি নায়ের মাঝির\nভাটিয়ালি গানে,\nশহুরে প্রাণে কেমন করে\nসুখের পরশ আনে।\nদেখতে তুমি সবুজ ভূমি\nডাকছে আচঁল পেতে,\nবলছে কেউ নিমন্ত...', '', 11, NULL, 'publish', 2331, 0, '2019-01-16 05:05:05', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (2, 2033, 8, 'এই তো জীবন', 'এই-তো-জীবন', '<!-- wp:paragraph -->\n<p>এরপর গেছে কেটে দিন<br> নিয়ে মন-মসলিন<br> জমে থাকা তড়িন্ময় দুপুর দিয়ে বেঁচে-<br>   &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  কিনে এনেছি তেল-নুন।<br> দেয়াল জুড়ে যতো কবিতার দল<br> তাতে ঢেলে দিয়ে কুসুমাসব<br>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  ফুটিয়েছি ভাতফল। <br> শ্লীলটুকু ফেলে দেয়া নিরস জীবন <br> কলতলায় আছে পড়ে শ্রী ভ্রষ্টা মন!<br> সর্বার্থ সাধিকা অনেক দূরের ক্যালেন্ডারে<br> হাত তুলে ডহর হাসি হাসে<br> দোহদী দিন যায় কেটে পরপর<br> অন্ধের মতো, ধর্মের বাতাসে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © সকাল রয়</p>\n<!-- /wp:paragraph -->', 'এরপর গেছে কেটে দিন\nনিয়ে মন-মসলিন\nজমে থাকা তড়িন্ময় দুপুর দিয়ে বেঁচে-\nকিনে এনেছি তেল-নুন।\nদেয়াল জুড়ে যতো কবিতার দল\nতাতে ঢেলে দিয়ে কুসুমাসব\nফুটিয়েছি ভাতফল।\nশ্লীলটুকু ফেলে দেয়া নিরস জীবন\nকলতলায় আছে পড়ে শ্...', '', 4, NULL, 'publish', 2765, 0, '2019-01-16 06:09:42', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (3, 2048, 9, 'শীতের সকাল', 'শীতের-সকাল', '<!-- wp:paragraph -->\n<p>রোঁদ কমেছে,<br>মেঘ জমেছে,&nbsp;<br>বাঁতাশ উড়ু উড়ু।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শীতের সকাল,<br>দেখলে পানি,&nbsp;<br>বুক যে দুরু দুরু।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গাছের ডালে বসছে না আর,<br>ছোট্ট পাখি চড়াই,<br>শীতের সময় বৃষ্টি নিয়ে,<br>করে না কেউ বড়াই।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শীতের দিনে চলছে তো বেশ,<br>পিঠা পুলির রেশ,<br>কাঁথা কম্বল মুরি দিয়ে,<br>হচ্ছে না দিন শেষ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শীতে কাঁপছে ছোট্ট বাবু,<br>বড়দের ও বেশ করছে কাবু,<br>অধিক শীতল রস ও মিষ্টি,&nbsp;<br>সবই মাবুদ তোমার সৃষ্টি। </p>\n<!-- /wp:paragraph -->', 'রোঁদ কমেছে,\nমেঘ জমেছে,\nবাঁতাশ উড়ু উড়ু।\nশীতের সকাল,\nদেখলে পানি,\nবুক যে দুরু দুরু।\nগাছের ডালে বসছে না আর,\nছোট্ট পাখি চড়াই,\nশীতের সময় বৃষ্টি নিয়ে,\nকরে না কেউ বড়াই।\nশীতের দিনে চলছে তো বেশ,\nপিঠা পুলি...', '', 11, NULL, 'publish', 2449, 0, '2019-01-16 09:27:57', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (4, 2053, 10, 'নয়নতারা', 'নয়নতারা', '<!-- wp:paragraph -->\n<p>পুজোর প্যান্ডেলে প্যান্ডেলে ছোট্ট মেয়েটি ঘুরে বেড়াচ্ছিল আপন মনে. সংগে একটা বড় বেলুন. সংগে কেউ&nbsp; বলে মনে হলনা. পরিচিত কেউ ওকে খুঁজছে এমন ও নয়. তবে কি মেয়েটা একা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কাছে গিয়ে বলি তোমার নাম কি?&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কোন উত্তর নেই!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটু কাছে গিয়ে কানের কাছে মুখ রেখে একই প্রশ্ন করি. তবুও কোন উত্তর নেই.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কি আশ্চর্য মেয়েটা কি তবে কালা?&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কৌতুহল হল মেয়েটির বিষয়.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমাকে কিছু বলতে দেখে মেয়েটি মুখে হাত দিয়ে তার ডান বৃদ্ধাংগুষ্ঠি নাড়ায় পরে আবার কানের কাছে নিয়ে ওই একই ইশারা করে. ফ্যাল ফ্যাল করে আমার মুখের দিকে তাকায়.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমি বুঝি মেয়েটি বোবা কালা.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভারি মুশকিল আমি কি করে ওকে বোঝাই আমার মনের কথা?&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটি আমার কাছে কি মনে করে আসে তারপর ইশারায় বোঝায় তার বাড়ি ওই দিকে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমি দু হাতে চালা করে বোঝাই তোমার বাড়ি?&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- মাথা নাড়িয়ে সম্মতি জানায়. মানে হ্যাঁ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- আহারে কত কষ্ট এই নিষ্পাপ শিশুটির মনে.কিন্তু কে তার বাবা মা?&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- মেয়েটি আমাকে কিছু বলতে চায় যা দেখে আমি বুঝি ও ওর বাড়িতে নিয়ে যেতে চায়.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- একেই বলে শিশু যে আপন পর বোঝেনা. বলি চল... হাত দেখিয়ে বলি চল.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- গুটি গুটি পায়ে এগোই ওর পিছু পিছু.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- এক পরিত্যক্ত মোটর গ্যারেজের মধ্যে এক বৃদ্ধাকে দেখি সেলাই করতে. একটা ছোট্ট আলো জ্বলছে. বৃদ্ধা ছুঁচ সুতো নিয়ে আপন মনে কি সেলাই করছেন.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- আমাদের দেখে চকিত আমার মুখপানে তাকিয়ে বলেন, কে তুমি বাবা?&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- যাক ইনি কথা বলতে পারেন তাহলে.আমি বলি মাসি আমি তোমার নাতনী কে একা একা ঘুরতে দেখে নিয়ে এলাম তোমার কাছে.ওকে এখানে ছেড়ে দিয়ে আমি ফিরে যাব আমার ঘরে.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- ও আমার নাতনী নয়. ওকে আমি এক মেলায় পেয়েছিলাম.ও এই রকম একা একা ঘুরছিল. অনেক জিজ্ঞ্যেশ করেও ওর বাড়ির ঠিকানা পাইনি. জতটুকু ঠারে ঠোরে বুঝি ওর বাবা মা কেউ নেই ও প্রায় অনাথ.কার সংগে এসেছিল তাও বুঝিনি.দিনকাল যা খারাপ ওই মেয়েকে কেউ বদ উদ্দেশ্যে চুরি করে নিয়ে যেতে পারে তাই আমার কাছে নিয়ে এলাম.প্রায় তিন&nbsp; &nbsp;মাস&nbsp; হয়ে গেল কেউ খোঁজ খবর করে নি. ভাবলাম থানায় দিয়ে আসি কিন্তু থানায় নিয়ে যাচ্ছি বুঝতে পেরে&nbsp; ও ভয়ে আমাকে জড়িয়ে ধরে. আমার মনে হয় ওর থানায় ভয় আছে.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- মেয়েটি আমার দিকে তাকিয়ে কি বলতে চায়.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>-আমি বলি কিছু খাবি?&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>-মাথা নাড়িয়ে বৃদ্ধার দিকে হাত দেখিয়ে বলে ও দেবে খেতে.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- মেয়েটিকে দেখে মনে হচ্ছিল নিশ্চই বড় ঘরের মেয়ে.অবহেলায় আছে জামা কাপড় খুব ই সাধারন, মাথার চুল উস্কো খুস্কো কিন্তু মুখের হাঁসি আর চোখ দুটোই বলছে নিশ্চই কোন সম্ভ্রান্ত বঁশের মেয়ে .হয় হারিয়ে গিয়েছে নয় অন্য কোন কিছু রহস্য আছে.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- আমি ত ফেলুদা নই কি ব্যোমকেশ বক্সি নই যে রহস্যের উৎস জেনে তার পেছনে ঘুরে কিছু সুরহা করব !</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- কি করাযায় এই নিষ্পাপ শিশুটির জন্য.চাইল্ড হেল্প লাইনে ফোন করলে হয়. নেট সার্চ করে নাম্বার পেলাম.ওর ফটো মোবাইলে তুলে হোয়াটস এপ এ পাঠালাম. রিপ্লাই এলো. আমরা পৌঁছচ্ছি.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বৃদ্ধাকে বলাতে তেলে বেগুনে জ্বলে উঠলেন. তোমাকে কে বলেছে ওই সব করতে.ও আমার কাছে আছে আমার কাছেই থাকবে.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- আমি বলি মাসি ও ওখানে অন্য ছেলে মেয়েদের সংগে ভালো থাকবে.তুমি কি চাওনা মেয়েটি ভালো থাকুগ?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- আমি একা একা এই গ্যারেজে থাকি.আমার কেউ নেই.&nbsp; ও থাকলে আমার ভালো লাগে.যা রোজগার হয় তাতে ওর আমার চলে যায়.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- কিন্তু এরকম ক দিন চলবে? তুমি কি সবদিন ওর কাছে থাকবে?&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- তা কেন বালাই সাঠ.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>- এর মধ্যে পুলিস এবং চাইল্ড লাইনের কিছু সমাজ সেবিকা এসে হাজির.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>-বৃদ্ধাকে নানা প্রশ্ন করেন. বেগতিক দেখে মেয়েটি বৃদ্ধাকে জোড়িয়ে ধরে বোঝায় ও ভালো.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটিকে চাইল্ড হেল্প লাইনের ম্যাডাম&nbsp; রা মুক বধিরদের বোঝার মত ঠারে ঠুরে কি সব জিজ্ঞাসা করলেন. মেয়েটি যা বুঝলো তার উত্তরে বলে ওর মা বাবা কেউ বেঁচে নেই ওকে পুলিস ধরে নিয়ে গিয়েছিল কিন্তু ও সেখান থেকে পালিয়ে এসেছে. পুলিসকে কেন মেয়েটি ভয় পায় বোঝা যাচ্ছেনা. বৃদ্ধাকে আঁকড়ে ধরে বলে ও ওই মাসির কাছেই থাকবে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তবুও চাইল্ড লাইনের ম্যাডাম রা নাছোড় বান্দা. ওকে অনেক বুঝিয়ে নিয়ে যান তাঁদের সংগে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমি নিশ্চিন্ত হলাম.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরের দিন আমার কাছে ফোন এল&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটু আসুন বিশেষ প্রয়োজন.&nbsp; আমি ভাবি আবার কি হল?&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গিয়ে দেখি অবাক কাণ্ড মেয়েটি না খেয়ে আছে গত কাল থেকে. তার এক জেদ মাসির কাছে যাবে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু মাসির সম্পর্কে পুলিশের তথ্য খুব একটা ভালো নয়. মাসি চুরীর দায়ে জেল খেটেছে. এখন অবশ্য ওঁর বিরুদ্ধে কোন অভিজোগ নেই.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটি কেন মাসির কাছেই থাকতে চায় ওই গ্যারেজে সকলে চিন্তা প্রকাশ করে এবং আমার সাহায্য চায়.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একে মেয়েটি প্রতিবন্ধী তার ওপর অনাথ. একটু ভূল হলে বেচারিকে আমাদের ভূলের মাসুল দিতে হবে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমি একটি প্রস্তাব দি... আচ্ছা ওকে কি&nbsp; আদ্যাপিঠের আশ্রমে রাখা যেতে পারে. ওখানে অনেক বাচ্চা পড়াশুনো করে খেয়ে পরে ভালো থাকে. আদ্যামায়ের আশ্রম খুব সুন্দর. যদি কিছু টাকার প্রয়োজন হয় আমি দিতে রাজি কিন্তু ও&nbsp; ওখানেই ভালো থাকবে আমার মনে হল. মায়ের আশ্রয়ে থাকলে মা\' ই ওকে রক্ষা করবেন.&nbsp; মা করুণাময়ী, মা রক্ষা কালী,&nbsp; মা\' র করুণা পেলে জীবন ধন্য হবে.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শেষে তাই হল. আদ্যাশ্রমে ওকে ছেড়ে আসা হল. বাচ্চাদের সংগে থেকে ও খেলা করবে কিন্তু ওর শিক্ষা?&nbsp; আরে ওটা ত চিন্তা করিনি?&nbsp; আশ্রমের পরিবেশ অত্যন্ত মনোরম. শান্তির বাতাবরন. এখানে শিক্ষা পাবে নিশ্চিৎ.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ফিরে এলাম ঘরে. মনটা ভারাক্রান্ত মেয়েটির জন্য. আমার কন্যা সন্তান নেই তাই বোধ হয় একটি কন্যার প্রয়োজন আমার. কিন্তু আমি নিজেকে বোঝাই ও আশ্রমে থাকলেই ভালো থাকবে এবং শৃঙ্খলিত জীবন ওর চলাপথ সুগম করবে. তাই ওর ভালোর জন্য সব মায়া ত্যাগ করে ওকে প্রাণভরে আশীর্বাদ করে ঘরে ফিরি...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p></p><cite> </cite></blockquote>\n<!-- /wp:quote -->', 'পুজোর প্যান্ডেলে প্যান্ডেলে ছোট্ট মেয়েটি ঘুরে বেড়াচ্ছিল আপন মনে. সংগে একটা বড় বেলুন. সংগে কেউ বলে মনে হলনা. পরিচিত কেউ ওকে খুঁজছে এমন ও নয়. তবে কি মেয়েটা একা!\nকাছে গিয়ে বলি তোমার নাম কি?\nকোন উত্...', '', 8, NULL, 'publish', 2297, 0, '2019-01-16 10:07:35', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (5, 2058, 11, 'অপ্রয়োজনীয় দিন রেখে যায় দীর্ঘশ্বাস', 'অপ্রয়োজনীয়-দিন-রেখে-যায়-দ', '<!-- wp:paragraph -->\n<p>কতো দূর চোখ গেলে নদী হয়<br />মেঘের দ্বন্দ্বে ভেঙে যায় আকাশের বালিঘর<br />অপ্রয়োজনীয় দিন<br />রেখে যায় দীর্ঘশ্বাস<br />আমাদের নগর প্রেম <br />ভুলিয়েছে দোয়েলের ঠোঁটের মিষ্টি কবিতা<br />তবু আছে ভালোবাসা-<br />সিলিংয়ে বিকেলের শেষ আলো<br />হুট করে বদলে যাওয়া মেঘ<br />তন্দ্রালু বাতাস<br />প্রেমিকার চোখে জমা সবুজ বাতিঘর<br />আলো নেই রোদ নেই<br />জানালাবন্দী আকাশ<br />টুকে রাখে নিষিদ্ধ লোবানঘাসের দীর্ঘশ্বাস।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><!-- /wp:paragraph -->', 'কতো দূর চোখ গেলে নদী হয়\nমেঘের দ্বন্দ্বে ভেঙে যায় আকাশের বালিঘর\nঅপ্রয়োজনীয় দিন\nরেখে যায় দীর্ঘশ্বাস\nআমাদের নগর প্রেম\nভুলিয়েছে দোয়েলের ঠোঁটের মিষ্টি কবিতা\nতবু আছে ভালোবাসা-\nসিলিংয়ে বিকেলের শেষ আল...', '', 4, NULL, 'publish', 2532, 0, '2019-01-16 10:39:27', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (6, 2062, 1, 'আদিম', 'আদিম', '<!-- wp:paragraph -->\n<p>কী কারণে, কী প্রক্রিয়ায়– কোন যানে করে, দোপেয়ো চারজন প্রাণী নদী তীরবর্তী বনাঞ্চলে এসেছে– তা সেখানকার চারপেয়ো প্রাণীগুলো জানে না। তাদের অতীত, বর্তমান ও ভবিষ্যৎ\nধোঁয়াশায় সমুদ্রসম।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নতুনের আগমন সবসময় শুভদৃষ্টিতে\nদেখতে হবে– কিংবা দেখা যায়, একথাটা সর্বদা সঠিক– সেকথা ভাবাটা বাঞ্ছনীয় নয়। তবু চারপেয়ো প্রাণীগুলো এই নব প্রজাতির প্রাণীদের\nসুদৃষ্টিতেই নিল। দোপেয়োগুলো এখানে পদার্পণ করেছে কয়েক দিন হলো। চারপেয়োগুলো তাদের\nনিয়ে কিঞ্চিৎ শঙ্কিত কিঞ্চিৎ দ্বিধান্বিত– তাদের আক্রমণ করে, ক্ষত-বিক্ষত করে তাড়িয়ে দেবে\nনাকি তাদের সঙ্গে মিলমিশ করে জীবনযাপন করবে। দু’ সূর্যোদয়\nপূর্বে অবশ্য তাদের মধ্যে একজন তৃণভোজী চারপেয়ো ওই নব প্রাণীদের সন্নিকটে অগ্রসর হয়েছিল– কই তেমন কিছু তো হলো না! যদিও প্রথমে দোপেয়োদের আচরণে কিছুটা আতঙ্কগ্রস্ত\nভাব লক্ষ করা গেল, কিন্তু সেটাকে চূড়ান্ত বলা যায় না। ক্ষণিকের মধ্যে তারা তাদের নিজ\nকাজে মনোনিবেশ করলো, যেন চারপেয়ো তৃণভোজীটা তাদের মাথাব্যথার কোনো কারণই নয়!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চারজন দুপেয়ো। আটটি পা। আটটি চোখ। আর আটটি কাঁধ থেকে ঝুলে থাকা বিশেষ কিছু– আজব অঙ্গ– দেখতে প্রায় পায়ের মতো হলেও তার কার্যাবলী সম্পূর্ণ ভিন্ন। চারজনের মধ্যে দুজন দেখতে আকৃতিতে বড়, বাকি দুজন ছোট। আকৃতির ভিন্নতা থাকলেও তাদের আচরণ অভিন্ন। তাদের শরীরে পশম নেই, তাই বলে তারা অনাবৃত তাও নয়– কোথা থেকে গাছের লতাপাতা দিয়ে নিজেদের কোমরের নীচের কিছু অংশ আবৃত করেছে দারুণভাবে, বড় দুজনের একজন বক্ষ আবৃত করেছে, আরেকজনের বক্ষ অনাবৃত– সে জন দেখতে বলিষ্ঠ। চারপেয়োরা তাদের আয়োজন দেখে অবাক হয়। তাদের চলাফেরার গতিবিধি, ধরণ, প্রকরণ নিয়ে তারা বিস্তর গবেষণায় বসে। কেউ কেউ হাসে। বিশেষ করে কাঁধ থেকে নেমে আসা ওই যে দুটো জিনিস– তার কার্যক্ষমতা দেখে তাদের অনেকে অবাক হয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখানে এসে দোপেয়োরা এক\nধরনের প্রশান্তি পায়, কিন্তু তাদের কপালে দৃশ্যমান বেদনার ভাজ আড়াল হয় না। এইতো কয়েকদিন\nআগেই তাদের জীবন ছিল শঙ্কায় ভরা, বর্তমানে তারা কিঞ্চিৎ শঙ্কামুক্ত হলেও দুঃখভারাক্রান্ত;\nস্বজাতির সকলকে হারিয়ে ফেলে ভালো থাকা যায় না, টিকে থাকা যায় না– এ বিশ্বাস তাদের রন্ধ্রে রন্ধ্রে। দুঃখকষ্ট তাদের ভিতরে প্রবলভাবে এখনো\nপ্রভাব ফেলে যাচ্ছে– যা কেবলি তাদের চোখের দিকে দৃষ্টিপাত করলেই বোঝা\nযায়। তাইতো মাঝে মাঝে তারা সকলে মিলে নদীর কাছে যায়, নদীর জলে নেমে আহাজারি করে, চিৎকার\nকরে বলে– বোঙ্গা…! বোঙ্গাআ…! বোঙ্গাআআআ…..!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চারপেয়োরা তাদের চিৎকার\nশুনে অবাক হয়ে হুড়োহুড়ি করে ছুটে আসে, দূর থেকে দোপেয়োদের তাকিয়ে দেখে– তারা বিস্মিত হওয়া শেখে। পাগলপনা দোপেয়োরা জলে নেমে বুক চাপড়াতে চাপড়াতে\nচিৎকার করতে থাকে অনবরত– চারপেয়োরা ভাবে, বোঙ্গা কী?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বোঙ্গা কী হতে পারে একটা\nদানব কিংবা অশরীরী শক্তি? দানব, অশরীরীতে চারপেয়োদের অবশ্য ভীতি নেই। তাদের বিশ্বাস\nদানবকে সম্মিলিত প্রচেষ্টায় হত্যা করা যায়, অশরীরী শক্তিকে তুচ্ছজ্ঞান করা যায়– তবে বোঙ্গা যদি এ দুটোর একটিও না হয়, যদি বোঙ্গা সত্যিই তাদের বিনাশকারী\nকোনোকিছু হয়; তাহলে তাদের কী হবে– তারা কী করবে? দোপেয়োদের আহাজারিতে এটা তাদের কাছে\nস্পষ্ট তারা বোঙ্গাকে চাই, তাদের বোঙ্গাকে অতীব প্রয়োজন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রয়োজনই বা হবে না কেন!\nতাদের বিশ্বাস ওই বোঙ্গাই তাদের বাঁচিয়েছে। তাদের ভাগ্য সুপ্রসন্ন যে– যখন তাদের পূর্বের আবাসস্থল উত্তপ্ত হতে লাগলো, জীবন-যাপন করা অসম্ভব\nহয়ে পড়লো, তখন তারা গাছের গুড়ির তৈরি জলযানে উঠতে পেরেছিল। তারপর তারা যাত্রা করলো\nঅজানা এক পথে। সেই দুর্গম নতুন আবাস খোঁজার যাত্রাতে তাদের সঙ্গী পঞ্চাশেক জলযান পতিত\nহলো মহাসংকটে। ঝড় তুফানে। সব শান্ত হলে তারা তাদের আবিষ্কার করে একটা অজানা নদীতে– যার তীরেই তারা এখন নতুন আবাস গড়েছে, যেখানে চারপেয়োদের আধিপত্য– তাই তাদেরকে বসবাস করতে হবে তাদের সাথে নিজেদের মানিয়ে নিয়ে। কিন্তু\nসেটা কী বাস্তবে সম্ভব– সেকথা দোপেয়ো-চারপেয়ো কেউই জানে না!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বেশ ভালোভাবেই তাদের দিন\nকাটছিল। বোঙ্গার দেখা নেই। চারপেয়োদের চিন্তা নেই। দোপেয়োরা তাদের কাঁধ থেকে বের হওয়া\nদুটো অঙ্গ দিয়ে হরহর করে গাছে উঠে গাছের ফল খায়। গাছের ডালপালা দিয়ে কৃত্রিম গুহা বানায়।\nচারপেয়োরা তাদের আশেপাশে ঘুরঘুর করে, তাদের কার্যকলাপ দেখে আর অবাক হয়। তারা বুঝতে\nপারে এই দোপেয়োদের কাছে তাদের অনেক কিছু শেখার আছে। একদিন দোপেয়োরা নদীতে গেলে নখরবিশিষ্ট\nএক চারপেয়ো তাদের কৃত্রিম গুহার রহস্য উদঘাটনে বের হয়। নখরবিশিষ্ট এই চারপেয়োকে অন্য\nচারপেয়োরা ভয় পায়, কেননা তার ভোজের উপাদান যে কেউ হতে পারে! কিন্তু দোপেয়োদের নিয়ে\nতার আগ্রহের অন্ত নেই। দোপেয়োদের আক্রমণেও তার সংশয়। কেননা তাদের মাংসের স্বাদ তার\nঅজানা। এছাড়া তাদের শরীরে কিংবা কামড়ে বিষ আছে কিনা সেটা নিয়েও রয়েছে শঙ্কা। যে বিষয়টা\nতাকে সবচেয়ে হতভম্ব করে দেয়– সেটা হলো দোপেয়োরা ভয়হীন। সে নিজেও অনেকবার দোপেয়োদের\nআশেপাশে ঘুরে বেরিয়েছে, কিন্তু দাঁত খিচিয়ে হুঙ্কার ছেড়েও তাদের দৃষ্টি আকর্ষণ করতে\nপারেনি। দোপেয়োরা শুধু হা করে তার দিকে তাকিয়ে আবার তাদের নিজের কাজে মন দিয়েছে। দোপেয়োদের\nগুহায় ঢুকে নখরবিশিষ্ট চারপেয়ো বিশেষ একটি বিষয় আবিষ্কার করে– সেটা হলো আধখাওয়া মাছ ও মাছের কাটা। এর অর্থ হচ্ছে দোপেয়োগুলো নদীর\nমাছ ধরে কাচা চিবিয়ে খায়! বিষয়টা আবিষ্কার করে নখরবিশিষ্ট চারপেয়ো আঁতকে ওঠে। তার মনে\nভীতির সঞ্চার হয়। এই দোপেয়োগুলো চারপেয়োদেরকেও ভক্ষণ শুরু করবে না তো! কৃত্রিম গুহা\nদেখে বের হতেই নখরবিশিষ্ট চারপেয়ো দেখে দোপেয়োরা শান্তশিষ্টভাবে ফিরে আসছে, কিন্তু\nতাকে লক্ষ করেই তাদের আচরণ পাল্টে গেল। তারা আজব অঙ্গের সাহায্যে গাছের ডাল তুলে তেড়ে\nআসতে লাগল। চারপেয়ো দোপেয়োদের অকস্মাৎ আক্রমণাত্মক এমন আচরণে ভড়কে যায়! সে ছুট দেয়\nসজোরে। দোপেয়োরা তার সাথে দৌড়ের পাল্লাতে পারে না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঘটনাটা পুরো চারপেয়ো সমাজে\nছড়িয়ে পড়ে। নখরবিশিষ্ট চারপেয়ো তাড়া খেয়েছে দোপেয়োদের কাছে– বিষয়টা চারপেয়োদের কাছে চরম আতঙ্কের। এমন সাহস যে বা যারা করতে পারে\nতারা কতটা ভয়ানক হতে পারে সেটা ভাবনার বিষয় হয়ে দাঁড়ায়। ওদিকে মাছের কাটার কথাও তাদের\nআশঙ্কা আরও বাড়িয়ে দেয়। তারপরেও দোপেয়ো চারপেয়োদের মিলমিশ জীবনযাপন চলতে থাকে– এক নদীতে পাশাপাশি দাঁড়িয়ে জলপান তার অনন্য উদাহরণ। তবে চারপেয়োরা ওই\nঘটনার পর থেকে দোপেয়োদের কৃত্রিম গুহার দিকে আর পা বাড়ায় না, দোপেয়োরাও আর তেড়ে আসে\nনা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এভাবে বহুক্ষণ যায়। বহুবার সূর্য অস্তমিত হয়। নখরবিশিষ্ট চারপেয়ো তাগড়া হয়। তার জীবনসঙ্গী হয়। তার দুটো বাচ্চা হয়। এরপর আসে সংকট। সূর্য তাপ বাড়াতে থাকে। নদীর জল শুকাতে থাকে। গাছের পাতা শুকাতে থাকে। গাছে ফল উৎপাদন হ্রাস পেতে থাকে। অনাবৃষ্টির কাল আসে– যেটা চারপেয়ো দোপেয়োদের জন্য মহাসংকটের শুরু করে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এমন অসময়ের এক সূর্যোদয়ের\nমূহুর্তে ঘুম থেকে হুড়মুড় করে ওঠে ছোট দোপেয়োর একজন। তার চোখদুটো যেন ঠিকরে বের হয়ে\nযেতে চাচ্ছে কোটর থেকে, শরীর ঘেমে একাকার, সাথে দীর্ঘশ্বাস। বড় দোপেয়োরা তার কাছে আসে,\nতাকে আজব অঙ্গ দিয়ে ঝাঁকি দেয়। সম্বিৎ ফিরে পায় ছোট দোপেয়ো। ইশারা ইঙ্গিতে তারা ছোট\nদোপেয়োর কাছে জানতে চায়– কী হয়েছে? ছোট দোপেয়ো আতঙ্কগ্রস্তভাবে তাদের দিকে\nতাকায়। ভীতসন্ত্রস্তভাবে ইশারায় যা ইঙ্গিত করে– তার তীর\nনখরবিশিষ্ট কোনো এক প্রাণীর দিকে যায়। নখরবিশিষ্ট কোনো প্রাণী তার দিকে এগিয়ে আসছে,\nতারপর তাকে রক্তাক্ত করছে। এমন ঘটনাই সে ঘুমের মাঝে প্রত্যক্ষ করে। কয়েকদিন আগেই ওই\nছোট দোপেয়ো দেখেছে– কীভাবে নখরবিশিষ্ট সেই চারপেয়োটি অন্য চারপেয়োদের\nছিঁড়েছুটে খায়। এজন্যই সে ভয়ঙ্কর কিছু ঘুমের মাঝে দেখেছে, সেটা বলার অপেক্ষা রাখে না– কিন্তু দোপেয়োরা তার কাছে ইশারায় বিষয়টা জেনে নিজেরাও ভীত হয়ে পড়ে।\nকৃত্রিম গুহা থেকে বেরিয়ে মাটির উপর বসে তারা বুক চাপড়াতে থাকে আর বলতে থাকে– বোঙ্গা! বোঙ্গাআ…! বোঙ্গাআআআ…..! তাদের\nচিৎকারে অন্য ছোট দোপেয়ো জেগে ওঠে। সেও দৌড়ে কৃত্রিম গুহা থেকে বের হয়ে আসে, তাদের\nসাথে চিৎকারে সামিল হয়। গগনবিদারী সেই চিৎকার!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সেই সূর্যোদয়ের পর থেকে\nদোপেয়োরা তটস্থ হয়ে ওঠে, তারা যখন তখন যেখানে সেখানে গগনবিদারী চিৎকার করতে থাকে আর\nকাঁদতে থাকে– সেটা নদীতে হোক, কৃত্রিম গুহায় হোক কিংবা বনাঞ্চলের\nমাঝখানে হোক। তাদের ঘন ঘন চিৎকার-কান্নায় চারপেয়োরা বোঙ্গা সম্পর্কে পুনরায় ভাবনায়\nপড়ে যায়। দোপেয়োদের নতুন নতুন আচরণ তারা প্রতিনিয়ত লক্ষ করতে থাকে। সেই অস্থির সময়ে\nদোপেয়োরা পুরো বনাঞ্চল চষে বেড়াতে থাকে– যেন তারা কোনো কিছু খুঁজছে। তাদের হারিয়ে যাওয়া\nকিছু। এরপর এক দুপুরে বলিষ্ট দোপেয়োটি অর্ধশুষ্ক নদীর দিক থেকে লাফাতে লাফাতে গুহার\nদিকে আসে, তার চোখেমুখে আনন্দধারা। তাকে আসতে দেখে বাকি সবাই কৃত্রিম গুহা থেকে বেরিয়ে\nআসে, তারা দেখে– বলিষ্ট দোপেয়োর হাতে দুই খণ্ড কর্দমাক্ত শক্ত বস্তু।\nতাদের মুখও উজ্জ্বল হয়ে ওঠে। কর্দমাক্ত শক্ত বস্তু দুটিকে তাদের মাঝখানে রেখে তারা\nআজব ভঙ্গিমা করতে থাকে– যে ভঙ্গিমাকে আনন্দ প্রকাশক কিছু একটা বলা যেতে\nপারে। সেই ভঙ্গিমা করতে করতেই তাদের একজন তার এক হাতের তালু দিয়ে আরেক হাতে আঘাত করে– সাথে সাথে সৃষ্টি হয় এক আনন্দদায়ক শব্দ, এরপর তার অনুকরণে অন্যরাও নিজেদের\nহাত দিয়ে সেই আনন্দসূচক শব্দ সৃষ্টি করে। মুখরিত হয় নদী তীরের আদিম এক আবাসস্থল– যেন বোঙ্গা ফিরে এসেছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তাদের এই আনন্দমাখা মূহুর্ত\nচারপেয়োদের আগোচরে থাকলো না। বিশেষ করে নখরবিশিষ্ট সেই চারপেয়োটি সবসময়ই তাদের দিকে\nতীক্ষ্ণ দৃষ্টিপাত করে চলে। সেদিন সন্ধ্যাতেই দোপেয়োদের কৃত্রিম গুহার ভিতরে আলোকরশ্মি\nদেখা গেলো। নখরবিশিষ্ট চারপেয়ো বিষয়টি সম্পর্কে বিস্তারিত জানবার জন্য সেই গুহার সম্মুখে\nআসতেই যা দেখতে পেল– তাতে তার আত্মারাম উড়াল দেবার অবস্থা! আকাশের সূর্য\nঘরে নিয়ে এসেছে দোপেয়োরা। প্রকৃতির দেবতা সূর্য কী তাহলে দোপেয়োদের দাস নাকি সূর্যদেবতার\nসন্তানকে চুরি করেছে বজ্জাতেরা– নখরবিশিষ্ট চারপেয়ো সন্ধিহান!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তার কয়েক সূর্যোদয়ের পরের ঘটনা। অনাবৃষ্টি শেষ হয়েছে। আশার আলোয় উদ্ভাসিত সবাই। দোপেয়োদের ঘরে রাত্রিবেলা সূর্যদেবতার সন্তান বসবাস করে। দোপেয়োদের \\"বোঙ্গা! বোঙ্গা!\\" আর্তনাদ কমে এসেছে। এখন শুধু তারা শক্ত বস্তু দুটোকে ঘিরেই আনন্দে মাতে– অবস্থা এমন যেন তারা বোঙ্গাকে ভুলেই গেছে। নখরবিশিষ্ট চারপেয়ো ভাবে, সূর্যদেবতাই তাদের বোঙ্গা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অথচ তার ধারণা ভুল। সেই\nছোট দোপেয়োটি হঠাৎ আরেক সূর্যোদয়ের সময় ঘুম থেকে ওঠে অস্থিরভাবে। আগের মতোই দোপেয়োরা\nগুহা থেকে বেরিয়ে আতঙ্কগ্রস্ত অবস্থায় \\"বোঙ্গা\\" রবে আর্তনাদ করে। সেই আর্তনাদের\nশব্দ শুনে নখরবিশিষ্ট চারপেয়ো দূর থেকে তাদের দিকে বিস্ময়ভরা চোখে তাকিয়ে থাকে। সেই\nসময় সে একটু দৃষ্টি সরিয়ে দেখে, তার বাড়ন্ত বাচ্চাদের একটি দোপেয়োদের কৃত্রিম গুহার\nপাশ দিয়ে নদীর দিকে যাচ্ছে– যাকে দেখে দোপেয়োরা তটস্থ হয়ে ওঠে, বলিষ্ট দোপেয়ো\n\\"বোঙ্গা\\" আর্তনাদ বন্ধ করে কৃত্রিম গুহায় প্রবেশ করে। ফিরে আসে তীক্ষ্ণ-ছুঁচালো\nএকটা গাছের ডাল নিয়ে। ফিরে এসেই দোপেয়ো নখরবিশিষ্ট চারপেয়োর বাচ্চার দিকে অগ্রসর হয়।\nচারপেয়োর বাচ্চার সেদিকে নজর নেই– তার চিন্তাতেই নেই দোপেয়োরা তাকে আক্রমণ করতে পারে,\nকিন্তু কিছুসময় পরেই রক্তাক্ত হয়ে ওঠে ছুঁচালো গাছের ডাল। মূহুর্তেই থেমে যায় বাকিদের\nআর্তনাদ, তাদের চোখ জ্বলজ্বল করে ওঠে। তারা চারপেয়োর নিথর দেহের চারপাশে অবস্থান নেয়,\nবলিষ্ট দোপেয়ো বুক চাপড়ায়, নখরবিশিষ্ট চারপেয়োর বাচ্চার গায়ে গাছের ডাল গেঁথে তার চারপাশে\nআজব ভঙ্গিমায় আনন্দ প্রকাশ করে। তারা আবার ভুলতে বসে বোঙ্গার কথা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দূরে দাঁড়িয়ে সব দেখে অনুসন্ধিৎসু নখরবিশিষ্ট সেই চারপেয়োটি– যার সন্তান কয়েকমূহুর্ত পূর্বেই দেহত্যাগ করেছে এক দোপেয়োর খোঁচায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © মোস্তাফিজ ফরায়েজী</p>\n<!-- /wp:paragraph -->', 'কী কারণে, কী প্রক্রিয়ায়– কোন যানে করে, দোপেয়ো চারজন প্রাণী নদী তীরবর্তী বনাঞ্চলে এসেছে– তা সেখানকার চারপেয়ো প্রাণীগুলো জানে না। তাদের অতীত, বর্তমান ও ভবিষ্যৎ\nধোঁয়াশায় সমুদ্রসম।\nনতুনের আগমন সবসময...', '', 9, NULL, 'publish', 2429, 0, '2019-01-16 11:04:17', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (7, 2072, 12, 'স্বপ্নভঙ্গ', 'স্বপ্নভঙ্গ', '<!-- wp:paragraph -->\n<p>একবুক জ্বালা নিয়ে মরতে মরতে বেঁচে আছেন মিলু করিম। একাত্তরের টগবগে এক যুবক&nbsp; জীবন সায়াহ্নে এসে জীবনের চরম সত্যের মুখোমুখি। <br>যে  বুকে ছিল স্বাধীন দেশে স্বাধীনতার আসল সুখকে হৃদয়াঙ্গম করার অদম্য স্পৃহা।  হিংসা হানাহানিমুক্ত স্বদেশ পাওয়ার সহজাত প্রত্যাশা। না পাওয়ার সীমাহীন  দলিলে সে বুক আজ ভারাক্রান্ত। সেই স্বপ্নিল হাতছানি স্বাধীনতার নাম করে  মিলু করিমদের পায়ে পরাধীনতার কঠিন শিকল পরিয়ে দিয়েছে। পরাধীনতার সেই শিকল  ছিন্ন করে স্বাধীন দেশের মৃত্তিকায় মুক্ত বিহঙ্গের মতো বিচরণের সেই  ব্যাকুলতা তার কাছে আজ শুধুই স্বপ্ন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্বাধীনতার এতো বছর পরও তার কপালে মুক্তজীবন জুটেনি।<br>\n অর্থনৈতিক মুক্তিসহ মাথাউঁচু করে দাঁড়ানোর শক্তি জুটেনি । যুদ্ধ বিধ্বস্ত \nদেশে রণক্ষেত্রের যে যুবক বীরের বেশে&nbsp; আপন ভিটেবাটীতে ফিরে এসেছিল। বিজয়ের \nপ্রাক্কালে সে হারিয়েছিল জীবনের অমূল্য ধন গর্ভধারিণী মাকে। <br><br> \nমা-ছেলের সংসারে ছেলেকে যুদ্ধে পাঠিয়ে একাকী জীবন কাটাচ্ছিলেন তার মা। \nকিন্তু হঠাৎ&nbsp; করে মা এক জটিল রোগে আক্রান্ত হয়ে বিছানার সঙ্গী হলেন। নিজের \nএকান্ত প্রয়োজনেও ছেলেকে কাছে ডাকেননি। জানাননি তার জটিল রোগের কথা। \nভেবেছিলেন যুদ্ধ শেষে ছেলে বীরের বেশে ঘরে ফিরে এলে তার কাছে রোগের কথা \nজানাবেন। যুদ্ধ শেষ হলে ঘরের ছেলে ঘরে ঠিকই ফিরলো। কিন্তু ততদিনে মিলু \nকরিমের কাছ থেকে তার প্রিয় মা চিরতরে বিদায় নিয়ে স্বর্গের পথে হাঁটলেন। <br><br>\n মৃত্যুর আগে আশপাশের লোকজন ছেলেকে খবর দিতে চাইলে তিনি তাদের বারণ \nকরেছিলেন। তিনি বলেছিলেন, এতে যুদ্ধে তার মনোযোগ কমে যাবে। আগে শত্রুদের \nবিষদাঁত উপড়ে ফেলুক। দেশকে ওদের কাছ থেকে উদ্ধার করুক। দেশ উদ্ধার হলে \nবাঁচবে হাজারো মা। <br> তার মায়ের এমন কথার পর কেউ তাকে মায়ের অসুস্থতার কথা জানায়নি।<br><br>\n যুদ্ধ থেকে ফিরে মায়ের বুকে মাথা রেখে বিস্তৃর্ণ খোলা আকাশ দেখার সাধ \nঅধরাই থেকে গেলো তার। শুধু বাড়ির সম্মুখে অবস্থিত মায়ের কবরের পাশে দাঁড়িয়ে\n কবর জিয়ারতের সময় বিদীর্ণ হৃদয়ের রক্তক্ষরণ আর অশ্রুজলে সিক্ত হয়েছিল সে।<br><br>\n যুদ্ধ বিধ্বস্ত দেশ। চারিদিকে পোড়া পোড়া গন্ধ। রাস্তাঘাট ভাঙা। জমিতে উঠতি\n ফসল নেই। মানুষের ঘরে ঘরে অভাব অনটন লেগেই আছে। তারওপর মিলুর ঘরে বাবা \nনেই। মা নেই। আছে শুধু মায়ের মৃত্যুকালে রেখে যাওয়া একখানা ভাঙাচোরা ছনের \nঘর। <br> সেই ঘরে রোদে পুড়ে বৃষ্টির জলে ভিজে আরো একটি বছর পার করে দিয়েছে সে। <br><br>\n এরপর বাড়ির পাশের এক প্রভাবশালী ব্যবসায়ীর চালের আড়তে সহকারীর কাজ নিয়েছে ।\n অল্প কিছুদিনের মধ্যে কাজ আর সততার মাধ্যমে আড়ৎদারের কাছে সে আস্থাভাজন \nহয়ে ওঠে। জীবন চলার পথে সে আড়ৎদারকে একজন অভিভাবকের ভূমিকায় কাছে পেয়েছে। <br>\n এরিমধ্যে আড়ৎদারের পরামর্শে সে নতুন করে সংসার জীবন শুরু করে। দেখতে দেখতে\n সংসারে নতুন মুখ আসে। নতুন করে খরচের অংক বড় হতে থাকে। তখনও<br>মোটামুটি সুন্দর জীবনের পথে এগিয়ে যাচ্ছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এরিমধ্যে\n সারাদেশে দূর্ভিক্ষ লেগে গেলো। তখন ঘরে ঘরে অভাব। কেউ কারো জন্য সাহায্যের\n হাত বাড়াতে সাহস পায়নি। মিলু করিম যে আড়ৎদারের দোকানে কাজ করতেন তার \nসংসারেও অভাব নামক দৈত্য হানা দিলে তিনি বাধ্য হয়ে ব্যবসা বন্ধ করে দেন। যে\n কারণে মিলু করিম আবার বেকার হয়ে পড়েন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> কিছুদিন যেতে না যেতেই \nতাদের সংসার জীবনে নেমে আসে ঘোর অমানিশা। স্ত্রী,&nbsp; সন্তানের মুখে দু\'মুঠো \nভাত তুলে দিতে সে কাজের সন্ধানে মরিয়া হয়ে ছুটতে থাকে। সকাল- দুপুর \n-সন্ধ্যা পেরিয়ে যায়। মিলু করিম কোথাও কোন কাজ পায় না। <br><br> রাত দশটা \nবাজে। চায়ের দোকানে অলস বসে বসে ভাবতে থাকে। ঘরে বৌ-বাচ্চা না খেয়ে আছে। \nএখন কার কাছে যাওয়া যায়।&nbsp; কথা দিয়ে কথা রাখতে পারেনি বলে কাছের লোকেরা তার \nকাছ থেকে দূরে সরে গেছে। ইতোমধ্যে বন্ধু বান্ধবের কাছ থেকেও ধার নিতে নিতে \nঅনেকে এখন তার কাছ মুখ ফিরিয়ে নিয়েছে। ধার চাইতে পারে এমন কারো নাম তার \nমাথায় আসছে না। <br> ইত্যাদি ভাবতে ভাবতে দীর্ঘ একটা শ্বাস নিয়ে মুখ দিয়ে হাওয়া বের করে দিয়ে চা বিক্রেতাকে লক্ষ্য করে বললেন,<br>- খালেক ভাই, আরেক কাপ চা দিন। সাথে একটা বিড়িও।<br>চা বিক্রেতা খালেক হাত বাড়িয়ে বিড়িটা দিতে দিতে বললেন,<br>- এই নিন, করিম ভাই। চা একটু পরে দিচ্ছি। সেই সন্ধ্যার পর থেকে একটানা বসে আছেন। কী ব্যাপার! কোন টেনশনে আছেন বলে মনে হচ্ছে?<br>দিয়াশলাইয়ের কাঠি জ্বালিয়ে বিড়িতে আগুন ধরিয়ে নিয়ে লম্বা করে এক টান দিয়ে ধোঁয়া ছাড়তে ছাড়তে বললেন,<br>- খালেক ভাই, এই জগৎ সংসারে কেউ কারো নয়। সবাই স্বার্থপরের মতো নিজের কথাই বোঝে। আর স্বার্থের সিদ্ধি হলে ভুলে যায়। <br>- আপনার কথা ঠিক বুঝতে পারলাম না। কোন বিষয় নিয়ে বলছেন?<br>-\n দেশের প্রয়োজনে নিজের সকল আরাম-আয়েশ ছেড়ে মৃত্যুকে মাথায় নিয়ে যুদ্ধের \nময়দানে গিয়েছিলাম। দেশের মুক্তির জন্য প্রিয় মায়ের শেষ বিদায়েও উপস্থিত \nথাকতে পারিনি। তবু জীবনের বাস্তবতাকে মেনে নিয়েছি। বেঁচে থাকার জন্য সবার \nদ্বারে দ্বারে গিয়েছি। কেউ একজন মুক্তিযোদ্ধাকে কাজ দেয়নি। করুণাও করেনি। \nএকজন মানুষ ভালোবেসে চালের আড়তে কাজ দিয়েছিলেন।&nbsp; কিন্তু ভাগ্যের নির্মম \nপরিহাসে সেই সুখও বেশিদিন আমার কপালে সইলো না। আজ মাস দুয়েক&nbsp; ধরে ঘরে বেকার\n বসে আছি। যে টাকা ছিল তা দিয়ে কিছুদিন চলেছি। তারপর নিকটাত্মীয়, \nবন্ধুবান্ধবদের কাছ থেকে ধার নিয়ে চলেছি। তাদের ধারদেনা সময়মতো দিতে পারিনি\n বলে অনেকেই আমার থেকে মুখ ফিরিয়ে নিয়েছে।<br>কিন্তু<br>আজ সকাল থেকে আমার \nবৌ-বাচ্চা না খেয়ে আছে। আর কারো কাছে চাওয়ার মতো মুখ নেই। অনেকের কাছে কাজ \nচেয়েছি। কেউ কোন কাজ দিলো না। তাই নিরুপায় হয়ে তোমার দোকানে এসে বসে আছি। \nএজন্যই কি এই দেশকে স্বাধীন করেছি?<br>খালেক চোখ বন্ধ করে একটু দম নিয়ে বলল,<br>-\n কি আর করবেন! দেশে দূর্ভিক্ষ লেগেছে। সবার ঘরে অভাব। সবাই নিজের জীবন নিয়ে\n চিন্তার মধ্যে আছে। এই আমার কথা ভাবেন না। সন্ধ্যার পর থেকে আপনি ছাড়া \nহাতেগোনা কয়জন কাস্টোমার এসেছে। মানুষের হাতে টাকা নেই। তাই লোকজন একান্ত \nপ্রয়োজন ছাড়া ঘর থেকে বের হয় না। দোকানের যা বিক্রি তাতে মনে হচ্ছে, না \nখেয়ে মরতে হবে। <br>- এটাই কি আমাদের স্বাধীনতার সুফল?<br>- এতো ভেঙ্গে পড়বেন না। দুঃসময় এসেছে। আবার সুসময় আসবে। আমার কাছে বিশ টাকার মতো আছে। আপনি<br>এক\n কাজ করুন। আমার কাছ থেকে পাঁচ টাকা নিয়ে কিছু চাল কিনুন। আর রাস্তার পাশের\n কচু পাতা ছিঁড়ে বাড়িতে ফিরে যান।&nbsp;&nbsp; গত কয়েক দিনে কচু পাতাও কমে গেছে। \nএকটুপরে দোকান বন্ধ করে আমিও আসছি। তাহলে আর দেরি করার দরকার নেই।<br>মিলু করিম দুঃখের মধ্যে আনন্দে কেঁদে ওঠেন। <br>এরপর\n সোয়া সের চাল কিনে বাড়ির উদ্দেশ্যে রওনা দিলেন। কিছুদূর গিয়ে কাচা রাস্তার\n পাশ থেকে খুঁজে খুঁজে কচু পাতা তুলে নিয়ে আবার হাঁটতে লাগলেন। <br>বাড়িতে পৌঁছে স্ত্রীর হাতে চাল আর কচু পাতা তুলে দিয়ে বললেন,<br>- খোকনকে দেখছি না যে। <br>-\n আস্তে বলো। ছেলেটা সকাল থেকে কিছু খায়নি। ক্ষুধার জ্বালায়&nbsp; ছটফট করেছে। \nতুমি আসবে বলে বুকে পাথর বেঁধে ওকে মিথ্যে সান্ত্বনা দিয়েছি। কাঁদতে কাঁদতে\n একসময় ঘুমিয়ে পড়েছে। <br>স্ত্রীর কথা শোনে করিম বাঁধভাঙা ঢেউয়ের মতো \nনিঃশব্দে দুচোখের জল ছেড়ে মাটিতে বসে পড়লেন। স্ত্রী কাঁদতে কাঁদতে স্বামীর \nপাশে বসে তাকে সান্ত্বনা দিলেন। <br>কিছু মুহূর্ত পর স্বাভাবিক হয়ে স্ত্রী \nউনুনে ভাতের পাতিল তুলে দিয়ে রান্নার জন্য খাবার উপযোগী কচুপাতা ছিঁড়ে নিতে\n লাগলেন। মিলু করিমও বৌয়ের সাথে বসে কচু পাতা ছিঁড়ছেন। হঠাৎ চুলোর আগুনের \nলেলিহান শিখায় চোখ পড়তেই বুকের মধ্যে দাউদাউ করে জ্বলে ওঠে। সে আনমনে ভাবে,\n <br>এই দেশ আমার, স্বাধীনতা আমার। শুধু স্বাধীনভাবে সুন্দর জীবনের স্বপ্ন দেখাটা আমার অধিকার না।<br>স্বামীর আবেগী চোখের জলে স্ত্রী আর্দ্র গলায় বললেন,<br>-\n তুমি আবার কাঁদছো কেন? যা হবার তা তো হবেই। মানুষের জীবনে অসময় আসতেই \nপারে। সেজন্য ভেঙে পড়লে তো হবে না। এতে বিপদ আরো বাড়বে। আমাদের বাঁচার উপায়\n খোঁজে বের করতে হবে। একাত্তরে শক্তিশালী পাক হানাদারদের পরাজিত করতে পারলে\n জীবনযুদ্ধের আসন্ন অভাবকেও দূর করতে পারবো। আমি ভাবছি কাল থেকে গ্রামের \nমহাজনের বাসায় গিয়ে একবেলা কাজ করে আসবো। তাতে আর কিছু দিক না দিক ভাতের \nমাড় তো দিবে। খালাম্মা খুব ভালো মানুষ। উনাকে বলে কয়ে বাবুর জন্য সামান্য \nভাত আনবো। দেখবে সব ঠিক হয়ে যাবে ইনশাল্লাহ। <br>স্ত্রীর এমন কথার পর মিলু \nকরিম বেশ কিছুসময় মাথাটা দুই হাঁটুর মধ্যে রেখে চোখ বন্ধ করে ভাবতে থাকে। \nএরপর সোজা গিয়ে মাটির বিছানায় শুয়ে বালিশে মুখটা লুকানোয়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মিলু করিম রাতের আঁধারে ঘুমের ঘোরে কষ্ট ভুলতে চায়। এ পৃথিবীকে চিরবিদায় জানাতে ইচ্ছে করে।<br>কিন্তু\n ঘড়ির কাটার ন্যায় অবিরাম ছুটে চলা সময়ের পরিক্রমায় রাত শেষে ভোর হয়।&nbsp; \nরাতের নীরবতা কাটিয়ে আবার চারিদিকের সরব প্রকৃতিতে তার ঘুম ভাঙে।&nbsp; চোখের \nপাতা খুলতেই দুশ্চিন্তাগ্রস্ত মনে প্রশান্তি ধরা দেয়। আরও বাঁচতে ইচ্ছে করে\n তার। সামনে যে তার কলিজার টুকরা একমাত্র ছেলে দাঁড়িয়ে আছে।<br>ছেলেকে কাছে\n টেনে&nbsp; বুকে জড়াতেই মনের সব কষ্ট দূর হয়ে যায়। এরপর দেশের দুর্দিনে কখনও \nখেয়ে আবার কখনও না খেয়ে দিন কাটতে থাকে মুক্তিযোদ্ধা মিলু করিমদের। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একদিন\n সন্ধ্যায় মিলু করিম খালেকের চায়ের দোকানে বসে আড্ডা দিচ্ছিলেন। এমন সময় \nদোকানের মধ্যে একজন সাহেব প্রবেশ করলেন। মিলু করিম লোকটার আপাদমস্তক দেখে \nনিলো। এক কালারের প্যান্ট শার্ট পরা। তারওপর কোর্টপরিহিত ভদ্রলোকের গলায় \nটাই বাঁধা। গালভরা দাঁড়ি। সুন্দর কালার করা। চোখে আবার রঙিন চশমা। এরপরও \nমিলু করিম তাকে দেখে চিনতে পারে। দূর গাঁয়ের কারীম মুন্সী। যুদ্ধের সময় সে \nপাকিস্তানি হানাদারদের দোসর হিসেবে কাজ করেছে। দেশ স্বাধীন হবার পর ঢাকায় \nপালিয়ে গেছে। অল্প সময়ের মধ্যে সে বেশ সম্পদশালী হয়ে গেছে। শহরে নাকি তার \nনিজের একটা কারখানাও আছে। এ নিয়ে গাঁয়ের লোকে প্রথম&nbsp; প্রথম নানান মন্তব্য \nকরলেও এখন আর কেউ কিছু বলতে সাহস পায় না। <br>কারীম মুন্সী মিলু করিমের দিকে কিছু মুহূর্ত তাকিয়ে থেকে বলল,<br>- আরে মিলু করিম না। কেমন আছো?<br>- ভালো, আ-প-নি?<br>মিলু করিমের মুখ থেকে কথা কেড়ে নিয়ে বললেন, <br>- আমি, কারীম মুন্সী। এখন ঢাকায় থাকি। তো তোমার কী খবর?<br>-\n ভাই, ভালো নেই। গ্রামের অবস্থাও ভালো নয়। এখানে কোন কাজকর্ম নাই। \nছেলেমেয়েরা না খেয়ে আছে। কী করবো কোথায় যাবো কিছু বুঝে উঠতে পারছি না।<br>- আমার কাছে একটা কাজ আছে। এখন প্রশ্ন হচ্ছে তুমি তা করবে কিনা? চাকরির সুযোগ সুবিধা ভালো পাবে।<br>- হ্যাঁ, আমি করবো। কিন্তু কাজটা কী?<br>- কাজ হচ্ছে আমার ফ্যাক্টরীতে দারোয়ানের একটি পোস্ট খালি আছে। তুমি চাইলে কালই আমার সাথে ঢাকায় যেতে পারো। <br>- আমি যাব। কিন্তু -------।<br>- আবার কিন্তু কেন? ওহ! বুঝতে পেরেছি বাড়িতে কিছু দিয়ে যেতে হবে, তাই না?<br>- জ্বি।<br>এরিমধ্যে\n কারীম মুন্সীর নির্দেশে খালেক উপস্থিত সবার সামনে চা-নাস্তা দিয়ে দেয়। \nনাস্তা খাওয়ার একফাঁকে মিলু করিমের&nbsp; হাতে নগদ পাঁচশত টাকা দিয়ে বললেন, \n\\"এইগুলো রাখ।\\"<br>এরপর<br>চা-নাস্তা খাওয়া শেষে সবার কাছ থেকে বিদায় নিয়ে কারীম মুন্সী বাড়ির উদ্দেশ্যে রওনা দেয়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরদিন মিলু করিম বৌ-বাচ্চা রেখে নতুন এক যুদ্ধে অংশ নিতে কারীম মুন্সীর সাথে ঢাকায় চলে আসে।  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © কবির কাঞ্চন</p>\n<!-- /wp:paragraph -->', 'একবুক জ্বালা নিয়ে মরতে মরতে বেঁচে আছেন মিলু করিম। একাত্তরের টগবগে এক যুবক জীবন সায়াহ্নে এসে জীবনের চরম সত্যের মুখোমুখি।\nযে বুকে ছিল স্বাধীন দেশে স্বাধীনতার আসল সুখকে হৃদয়াঙ্গম করার অদম্য স্পৃহা। হি...', '', 9, NULL, 'publish', 2168, 0, '2019-01-17 08:16:45', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (8, 2078, 13, 'হলুুদ ফুল', 'হলুুদ-ফুল', '<!-- wp:paragraph -->\n<p>যতো দূর চোখ যায় সরিষার ফুল<br>ফুটে আছে শোভা করে প্রকৃতির কোল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেখে রুপ অপরুপ মিষ্টি তার ঘ্রাণ<br>ফুরফুরে দেহ মন ভরে যায় প্রাণ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>উদাসী বাতাসে দোলে জাগে শিহরণ<br>মৌ মাছি ভ্রমর যতো মধু করে হরণ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভাবুক মনে প্রেমের টানে ধরে গান<br>ও/ আমার দেশের মাটি তোর তরে তান।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রুপে রসে গন্ধে যার নেই কোনো তূল<br>তারে চিনতে কেউ তো করে না যে ভুল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© মজনু মিয়া</p>\n<!-- /wp:paragraph -->', 'যতো দূর চোখ যায় সরিষার ফুল\nফুটে আছে শোভা করে প্রকৃতির কোল।\nদেখে রুপ অপরুপ মিষ্টি তার ঘ্রাণ\nফুরফুরে দেহ মন ভরে যায় প্রাণ।\nউদাসী বাতাসে দোলে জাগে শিহরণ\nমৌ মাছি ভ্রমর যতো মধু করে হরণ।\nভাবুক মনে প্রেমের...', '', 11, NULL, 'publish', 2220, 0, '2019-01-17 11:58:32', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (9, 2089, 14, 'মা', 'মা', '<!-- wp:paragraph -->\n<p>মেয়েটির নাম জানিনা। এক পাগলির গর্ভে জন্ম। পাগলী জন্ম দিয়ে পালিয়েছে। শিশু মেয়েটির কান্নায় আকাশ বাতাস ভারি হয়ে ওঠে। কেউ এগিয়ে আসেনা। শুকনো মাটির উপর শিশুটির লাল মুখ কেমন যেন নিলাভ হয়ে যায়। একটি পৌঢ়া আধ বয়সী একজন মহিলা এগিয়ে আসে। কিছুক্ষনের মধ্যেই লোকজনের জটলা বেধে যায়। সবাই ছি ছি করতে থাকে। এমন কামডা কিডা কইরলো? কার পাপের ফসল এই মেয়িডা? সকলের মুখে একই প্রশ্ন। এত সুন্দর মায়িডা ফেলি রেখি গেছে কিডা? হদিস পাই না। পৌঢ়া সকিনা বেগম মেয়েটিকে কোলে জাপটে ধরে। সকিনা নিঃসন্তান। সকিনার আঠাশ বছরের তীব্র প্রতিক্ষার প্রতীক হিসেবে মেয়েটিকে মানুষ করতে চাই। বুকে আগলে রেখে নিজের সন্তানের অভাব পুরণ করতে চায়। সকিনা বলে ওঠে, ওরে আল্লা আমারে দিছে। আমিই মানুষ কইরবো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সকিনা বেগম যখন মেয়েটিকে নিয়ে ফিরে আসতে চাই ঠিক তখনই একজন বোবা আধবয়সী পাগলী মেয়েটিকে ছো মেরে কেড়ে নেয় তার কাছ থেকে। সকিনা বেগম কিছুৃই বলতে পারে না। পাগলী পরম আদরে মেয়েটিকে বুকে জাপটে ধরে। মেয়েটির কান্না তখনও বন্ধ হয়নি। পাগলি ক্ষেপে যায়। ক্রোধে হাত পা ছুড়তে থাকে? কৌতুহলী দর্শকের মনে তখনও কৌতুহল ভর করে। পাগলীর এরাম সর্বনাশ কইল্লো কিডা? সকিনা দুরে দাড়িয়ে হা হুতাশ করে। কেউ কেউ বলে পাগলীরে ধরে চুল কেটে গ্রাম ছাড়া করে দে। কেউ বলে থাক পাগলী নেড়ে আর কী লাভ হবেনে? কিন্তু মেয়িডার কি গতি হবে? পাগলীর কাছে থাকলি মেয়িডা নির্ঘাত মরি যাবেনে। পাগলী ক্ষেপে যায়। সকিনা বেগম কি করবে কিছু বুঝে উঠতে পারে না। সে একটু দুরে সরে যায়। পাগলী মেয়েটিকে আবার মাটিতে শুয়ে রেখে একটা ইট নিয়ে উৎসুক জনতার উপরে হামলে পড়ে। তাড়া করে। তারপর ঘন্টার পর ঘন্টা পার হয়ে যায় পাগলীর আর খোজ থাকে না। সকিনা বেগম আবারও মেয়েটিকে কোলে তুলে নেই। পাগলি আসার আগেই তাকে এখান থেকে পালাতে হবে। সে প্রাণপনে পা চালায়। তার সমস্ত শক্তি দিয়ে সে দৌড়াতে থাকে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পাগলীর গোঙানীর আওয়াজ ক্রমেই বাড়তে থাকে। তার গোঙানীর আওয়াজে আকাশ বাতাস ভারি হয়ে ওঠে। কোথাও তার মেয়েকে খুঁজে পাওয়া যায়না। বোবা পাগলী নিজের বুক চাপড়ে কাঁদে। তন্ন তন্ন করে খুঁজতে থাকে তার মেয়েকে। মুখ দিয়ে আও আও আওয়াজ বের হয়। পাগলীর মাতৃত্ববোধ আরও প্রবল হতে থাকে। পাগলী আর নিজেকে সামলাতে পারে না। উদভ্রান্ত হয়ে দিগবিদিক ছুটে বেড়ায়। চোখ বেয়ে অঝোর ধারায় বৃষ্টি নামে। এলোমেলো দৌড়াতে থাকে। হুমড়ি খেয়ে পড়ে যায়। লোকজন হা হা শব্দে হেসে ওঠে। যেন মজার ব্যপার দেখছে সবাই। পাগলী উঠে আবার দৌড়াতে থাকে। পাগলী এখন জীবনের কাছে সম্পূর্ণ পরাজিত । দিনের আলোয় পাগলীকে আর দেখা যায় না। রাতের বেলায় পাগলীর অস্পষ্ট কান্নার আওয়াজ শোনা যায়। কিন্তু তাকে আর খুঁজে পাওয়া যায় না। কেউ বলতে পারে না পাগলী কোথায় গেছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যেদিন ফুলমতিকে নিয়ে সকিনা বেগম কুলচারা গ্রামে এসে নতুন বাসা বাধে ঠিক তার উনিশ দিনের মাথায় তার স্বামি মারা যায়। সকিনা বেগম অকুল পাথারে পড়ে মেয়েকে নিয়ে। তার স্বামির রেখে যাওয়ার সম্পত্তির উপর ভর করে বেশ ভালভাবেই তাদের সংসার চলে যায়। মেয়েকে বেশ আদরেই বড় করেছে সকিনা। ফুলমতিকে একটা স্থানীয় স্কুলে ভর্তি করিয়েছে। দেখতে দেখতে বেশ কয়েকটি বছর পার হয়ে যায়। এদিকে ফুলমতিকে নিয়ে কথা ওঠে গ্রামে। কেউ কেউ বলে ফুলমতি সখিনার মেয়ে নয়। পাগলির মেয়ে। এই নিয়ে সখিনার দুশ্চিন্তার শেষ নেই। কেউ কেউ সখিনার মুখের উপরেই এমন কথা বলে। সকিনা রেগে যায়। ফুলমতি বড় হয়েছে। তাকে বিয়ে দিতে হবে। কেউ যদি তার মেয়েকে নিয়ে এমন কথা বলে তার কি বিয়ে হবে? সখিনার গলার আওয়াজ বেড়ে যায়। কোমরে কাপড় পেচিয়ে ঝগড়া করে। তার গলার সমস্ত জোর দিয়ে প্রমান করতে চায় ফুলমতি তারই মেয়ে। ফুলমতি অবাক বিস্ময়ে তাকিয়ে থাকে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পাগলী এসেছে গ্রামে। পাগলী রাস্তার পাশে দাড়িয়ে থাকে। পাগলীর বয়স হয়েছে। বৃদ্ধা পাগলীর পাগলামী আবার বেড়েছে। সে ছোট ছোট বাচ্চা দেখলে ছুটে গিয়ে জড়িয়ে ধরতে চায়। ছেলেমেয়েরা ভয় পাই। ঘৃণা করে। পাগলীর শরীর দিয়ে তীব্র দুর্গন্ধ বেরয়। ছোট ছোট বাচ্চারা অতীষ্ঠ পাগলীর অত্যাচারে। পাগলীর গলা দিয়ে আও আও আওয়াজ বেরোয়। তার ভেতরে মাতৃত্ববোধ জেগে ওঠে। কিন্তু কেউই তার কাছে যেতে চাই না। গ্রামের লোকজন ক্ষেপে যায় পাগলীর উপর। তার কারণে বাচ্চারা বিদ্যালয়ে যেতে ভয় পায়। শেষ বয়সে পাগলীর মাতৃত্ববোধ চরমে উঠেছে। সে তার সন্তানকে খুঁজে পেতে মরিয়া। সবাইকে তার সন্তান ভেবে আদর করতে চায়। একটু বুকে জড়িয়ে ধরে পূর্ণ তৃপ্তিতে মাতৃত্বের স্বাদ নিতে চায়। কিন্তু লোকজনের মনে শঙ্কা। কেউ কেউ ধারণা করে এ পাগলী হতে পারেনা। এ নিশ্চয় বাচ্চাচোর দলের সদস্য। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বেশ কিছুদিন ধরে ফুলমতিকে লক্ষ্য করছে পাগলী। পাগলীর তীব্র বাসনা ফুলমতিকে একটু জড়িয়ে ধরবে। একদিন আচমকা পাগলী কোথা থেকে ছুটে এসে ফুলমতিকে জড়িয়ে ধরে । ফুলমতি তখন স্কুলে যাচ্ছিল। ফুলমতি ভয়ে চিৎকার চেচামেচি করে । পাগলী ফুলমতির হাত শক্ত করে ধরে রাখতে চায়। ফুলমতি হাত ছাড়িয়ে নেবার তীব্র চেষ্টা করে। কিন্তু পারে না। ফুলমতি কাঁদে আর বলে কিডা? কিডা আপনি? আমারে ছেড়ি দেন। পাগলী হাত ছাড়ে না। পাগলী কেমন কুই কুই আওয়াজ বের করে তার গলা দিয়ে। পাগলীর চোখেও কেন জানি জল চলে আসে। ফুলমতির চেচামেচি আরও বেড়ে যায়। লোকজনের জটলা বেঁধে যায়। সবাই এসে পাগলীকে জাপটে ধরে। পাগলী চুপ হয়ে যায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কেউ কেউ বলে ও বোবাও না পাগলীও না ওরে ধরি আইচ্চা করি পিডাও সব সত্যি বেরি আসপেনে। কেউ কেউ বলে ওর মেরে গ্রামতি তাড়ি দেও। গ্রামে তড়িত সালিশ বসে। খবর পেয়ে সকিনা বেগমও ছুটে আসে। যেহেতু ফুলমতিকে কেন্দ্র করে ঘটনা ঘটেছে সেহেতু ফুলমতির মা সকিনা বেগম রাগে দুঃখে ক্ষোভে ফেটে পড়ে। হঠাত এই পাগলীকে দেখে মন খারাপ হয়ে যায় তার। এই ফুলমতিই পাগলীর সন্তান। এই পাগলীর গর্ভেই ফুলমতির জন্ম। সকিনার বুঝতে আর বাকি থাকে না। সকিনাকে দেখে ফের বিগড়ে যায় পাগলী। সে পাগলা কুকুরের মত সকিনার উপরে ঝাপিয়ে পড়ে। সকিনাকে মাটিতে ফেলে চুল ধরে টানতে থাকে। সকলে কেমন হতভম্ব হয়ে যায়। না আর পারা যায় না। সবাই মিলে পাগলীর হাত ছাড়ানোর চেষ্টা করে। পাগলীর গলা দিয়ে আও আও আওয়াজ প্রবল হতে থাকে। সবাই তাকে টেনে হেচড়ে সেখান থেকে নিয়ে এসে একটি রশ্মি দিয়ে তাকে গাছের সাথে বেঁধে ফেলা হয়। ফুলমতি স্তম্ভিত। সে কিছুই বুঝে উঠতে পারে না। কি করবে তার চোখ দিয়ে টপ টপ করে জল গড়িয়ে পড়ে। সে পাগলীর চোখের পানে চেয়ে থাকে। কেমন একটা মায়া জন্মায়। হঠাত ঘৃণায় মনটা রি রি করতে থাকে। যে তার মায়ের উপর এমন হামলে পড়েছে তার উপরে মায়া কেন? বিচারে বলা হয় পাগলীর মাথার চুল সব কেটে ফেলা হবে। পাগলীর উপরে চলে কিল ঘুষি আর লাথি। পাগলী আ উ শব্দ করে কাঁদতে থাকে। লোকজন হো হো শব্দে হেসে ওঠে। যেন সবাই একটা মজার খেলা দেখছে। সবাই মজা পাচ্ছে। কেন জানি ফুলমতির প্রচন্ড মায়া হয়। ইচ্ছে করে এখান থেকে ছাড়িয়ে নিয়ে অন্য কোথাও পাগলীকে রেখে আসতে কিন্তু পারে না। পাগলীর চুল কেটে দড়ি দিয়ে বেধে অনেক দুরের একটি জঙ্গলে ফেলে দেওয়া হয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ফুলমতির মন ভীষণ খারাপ। বিয়ের আসর থেকে তার বিয়ে ভেঙ্গে গেছে। এমন রুপবতি মেয়ের বিয়ে ভেঙ্গে যাওয়ার কারণ কী? কারণ একটায় তার নাকি জন্মের ঠিক নেই। তার বাবার পরিচয় নেই। বিয়ে বাড়ি পুরো স্তম্ভিত। কারো মুখে কোন কথা নেই। ফুলমতি কিছুই বুঝে উঠতে পারে না। কি করে যেন বর পক্ষ জেনে গেছে ফুলমতির সকিনার মেয়ে না। সে একটা পাগলীর মেয়ে। সে একটা পাপের ফসল। ফুলমতির রাগে দুঃখে ক্ষোভে আত্মহত্যা করতে ইচ্ছে করে। গ্রামে একটি সালিশ বসবে। গ্রামের মাতব্বর বলে গেছে। আরও বলে গেছে এ গ্রামে কোন অজাত কুজাত জারজের জায়গা নেই। ফুলমতি ফুফিয়ে ফুফিয়ে কাঁদে। আসল সত্যটা তার আজ জানতেই হবে। সত্য জানার জন্য তার মনটা উতলা হয়ে ওঠে। সে একটি ধর্মগ্রন্থের উপর হাত রেখে তার মায়ের কাছে আসল সত্যটা জানতে চায়। সকিনা সত্য জানিয়ে দেয়। আরও জানিয়ে দেয় যে পাগলিকে মেরে অত্যাচার করে এ গ্রাম থেকে তাড়ানো হয়েছে সে তার মা। ফুলমতি হাওমাও করে কাঁদতে থাকে। তার যে বিয়ে ভেঙ্গে গেছে সে জন্য সে কাঁদছে না। এ সমাজে যার বাবার পরিচয় নেই তার কোথাও স্থান হয় না। একটু পরেই তাকে নিয়ে সালিশ বসবে। হয়তো তাকেও তার মায়ের মত এ গ্রাম থেকে তাড়ানো হবে। সে জন্যও কাঁদছে না ফুলমতি। সে জানে আর তার এ গ্রামে জায়গা হবে না। এ গ্রাম কেন কোন গ্রামেই জায়গা হবে না। সে ঠিক করে সে আত্মহত্যায় করবে। নইলে সারা জীবন তাকে অপমান সহ্য করে বেচে থাকতে হবে। না না তা হতে পারে না। তার আগে তার পাগলী মাকে খুঁজে বের করতে হবে। জানতে হবে বাবার পরিচয়। কোন কিছুই ঠিক করতে পারে না ফুলমতি। হঠাতই লোকজনের হৈচৈ শুনতে পায় ফুলমতি। লাশ! লাশ! সবাই একটি লাশকে ঘিরে আহাজারি করতে থাকে। ফুলমতি লোকজনের ভিড় সরিয়ে কাছে গিয়ে দেখেতে চায় কার লাশ। ফুলমতি আর তাকাতে পারে না। এই সেই পাগলীর লাশ! কোথা থেকে এসে আবার এই গ্রামেই মারা গেছে। ফুলমতি আর কিছুই বলতে পারে না। তার মাথাটা কেমন ঘুরে আসে। সে আচমকা মাথা ঘুরে পড়ে যায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © মাহির তাজওয়ার</p>\n<!-- /wp:paragraph -->', 'মেয়েটির নাম জানিনা। এক পাগলির গর্ভে জন্ম। পাগলী জন্ম দিয়ে পালিয়েছে। শিশু মেয়েটির কান্নায় আকাশ বাতাস ভারি হয়ে ওঠে। কেউ এগিয়ে আসেনা। শুকনো মাটির উপর শিশুটির লাল মুখ কেমন যেন নিলাভ হয়ে যায়। একটি পৌঢ়া আধ ...', '', 9, NULL, 'publish', 3050, 0, '2019-01-19 08:23:33', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (10, 2112, 15, 'নষ্ট প্রেমে কষ্ট', 'নষ্ট-প্রেমে-কষ্ট', '<!-- wp:paragraph -->\n<p>মানুষ ভেবে একমুঠো রোদ খেয়েছি<br>এক টুকরো ঝিনুক ব্যাথা দিয়ে যায়<br>রক্তাক্ত শরীর...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বৃথা যায় নষ্ট বিকেল<br>এখন দীর্ঘশ্বাস কে বড্ড বেশি আপন ভাবি<br>পরাধীন শৈশবের শুকনো গোলাপের মরমরে দীর্ঘশ্বাস<br>বলে দিয়ে যায়<br>নষ্ট প্রেম...<br>কষ্টের রোদ...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সত্যিই মানুষ ভেবে একমুঠো রোদ খেয়েছি<br>যেখানে বিড়ির ধুয়োয় অনাবৃত কষ্টের সুখ<br>আপন ভাবা দীর্ঘশ্বাস<br>এখন কবিতার পুঁজি...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © শাহরিয়ার জাহাঙ্গীর</p>\n<!-- /wp:paragraph -->', 'মানুষ ভেবে একমুঠো রোদ খেয়েছি\nএক টুকরো ঝিনুক ব্যাথা দিয়ে যায়\nরক্তাক্ত শরীর...\nবৃথা যায় নষ্ট বিকেল\nএখন দীর্ঘশ্বাস কে বড্ড বেশি আপন ভাবি\nপরাধীন শৈশবের শুকনো গোলাপের মরমরে দীর্ঘশ্বাস\nবলে দিয়ে যায়\nনষ...', '', 4, NULL, 'publish', 2821, 0, '2019-01-20 14:48:16', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (11, 2117, 2, 'নীলডুমুর', 'নীলডুমুর', '<!-- wp:paragraph -->\n<p>ফুলের মাধুর্য্য কুঁড়িতে বিনষ্ট হলে; অনাদরে ঝরে গেলে; ম-পে দলিত-মথিত হলে ফুল বিষয়ে ভুল হয়। অবশ্য কারো মতে ডুমুরের ফুল হয় না ফল হয়- কিন্তু আমি ফুল দেখেছি! না, ফুল তার নাম নয়; খুকিও নয়। তবে বাবার মুখে তাকে আমি খুকি ডাকতে শুনেছি। মা আমায় জিজ্ঞেস করেছিল, নুনু, আমাদের জন্যি তোমার কি কষ্ট হচ্ছে? <br>\nবিনয়ের অবতার হয়ে আমি কাঁধ ঝাঁকায়, না না খালা, আমার কোনো সমস্যা হচ্ছে না; আপনি নিশ্চিন্তে ঘুমান।<br>\nনিশ্চিন্ত না হলে মানুষের ভীড়ে খুকিকে রেখে কি ঘুমাতে পারতো! পরম নির্ভরতায় ঘুমায় ওরা। মাঝে মাঝে নাক ডাকার আওয়াজ শুনতে পাই; অস্পষ্ট স্বরে কি সব বলাবলি করে- সম্ভবত সংসারের জটিল হিসেব নিকেষ। খুকি মনে মনে বিরক্ত। চতুর্দিক ঘুরে এসে মায়াবী চোখ দুটো আমার চোখের ওপর স্থির হয়ে যায়। প্রতিক্রিয়া বুঝতে অপলক দৃষ্টিতে তাকিয়ে থাকে। মেয়েটির চোখেমুখে দ্বিধা, সংকোচ। বাবা-মার ঘুমন্ত মুখের পানে তাকিয়ে বিচলিত হয়। তার নিজেরও ঘুম প্রয়োজন। ইচ্ছে করলে বিছানার বেদখল স্থানে দিব্যি শুয়ে পড়তে পারে। বালিশ নেই; আমার মাথার নিচে কিছু বইপত্র। খুকি চাইলে বইগুলো আজন্মের মতো দিয়ে দিতাম। কেননা রাশিয়ান লেখকের বইগুলো তখন অপ্রয়োজনীয়! শুধু রাশিয়ান কেনো, যে কোনো প্রকারের বই অচ্ছুত! আমি মানুষ ঠকানোর বিদ্যা আয়ত্ব করেছি। লোন দিয়ে কিভাবে কিস্তি আনতে হবে; টাকা না পেলে জুলুম করতে হবে; ছ্যার ডাক আদায় করতে কি কি কারসাজি প্রয়োজন; কথার মারপ্যাচে কিভাবে সাধরন জনগনকে ঘায়েল করতে হবে; প্রভাবশালীদের সাথে কিরুপে সখ্যতা গড়তে হবে; একে অন্যকে গালাগালি করতে হবে; ঘরের চালা; হাতের বালা কিভাবে নিলামে চড়াতে হবে- এসব বিদ্যা আমার অস্থিমজ্জায়!<br>\nমৌসুমি বৌদিকে আমি ঠকিয়েছে!<br>\nআহা, মহারাজপুরের ওই বৌদিকে কত অকথ্য ভাষায় গালাগালি দিয়েছি। বৌদি কি জানতো, তার এই ঠাকুরপো এমন রুদ্রমূর্তি ধারণ করতে পারে! আমি নিরুপায়; সাধারণ সৌজন্যতা ভুলে রুগ্ন শরীরের বউটিকে যা বলার নয় তাই বলেছিলাম। কিস্তির বদলে শাঁড়ি দিতে চাইলে, আমি হাতের বালা দাবি করেছিলাম। বৌদি জলভরা কণ্ঠে বলেছিল, বালা দিলে স্বামীর অমজ্ঞল হয়।<br>\nআমি উপহাস করেছিলাম, স্বামী; যে স্বামী সংসারের খোঁজ রাখে না, সন্তানের ভাবনা ভাবে না; মাঝে মাঝে নিখোঁজ থাকে তার বেঁচে থেকে লাভ কি!<br>\nলাভ-লোকসান খুব ভালো বুঝি। মানবিকতার শেষ বিন্দুটুকুন ট্রেনাররা নিংড়ে ফেলেছে। বড় ছ্যার আচমকা একদিন জিজ্ঞেস করে, কি কবি সাহেব, কেমন চলছে লেখালেখি?<br>\nকবি!<br>\nপাঠশালার জীবন থেকে লেখালেখি করি বটে তবে কবি নয়; গদ্য লেখক- পারিপার্শ্বিক সমাজব্যবস্থা ও নিজের সুখ-দুঃখ লিপিবদ্ধ করি। কিন্তু জীবনের ওই গোপন অধ্যায়ের কথা তো ছ্যারের জানার কথা নয়! লেখালেখি করা যেনো গর্হিত অপরাধ! শিক্ষিত লোকেরা নাসিকা কুঞ্জন করে; সুযোগ পেলে টিপ্পনী কাটে; ভবিষ্যত বিষয়ে হতাশার ব্যঞ্জণা, বুঝলেন পিন্টু সাহেব, কবিতা-টবিতা লিখে ভাত হবে না, উচ্ছন্নে যাবেন; তার চাইতে চাকরিতে মন দিন, অনেক বড় হতে পারবেন।<br>\nবড় হওয়া নিয়ে ছ্যারদের প্রচ- মাথাব্যথা। কলিগরা হাসাহাসি করে। তামাশার দৃষ্টিতে তাকায়। তামাশার কি দেখলো! লেখালেখির কথা বেমালুম চেপে যাই। ক্রেডিট অফিসার হিসেবে খুলনা থেকে নীলডুমুরগামী লঞ্চই বরং আমার জন্য নিরাপদ!<br>\nআহ, চর্তুদিকে নিরাপদ জীবনের সুঘ্রাণ!<br>\nঘুমজড়ানো চোখে লঞ্চের অভ্যন্তরে প্রথম আমি খুকিকে আবিষ্কার করি। মেয়েটি গুটিসুটি মেরে বসা। চোখে চোখ পড়লে ভয় ও লজ্জা যুগপৎ তাকে গ্রাস করে। ভয় অমুলক নয়। ক্ষুধার্ত নেকড়ের সম্মুখে শিকার কতক্ষণই বা নিরাপদ! তার চারপাশে অসংখ্য নেকড়ে। কেউ কেউ হা-পিত্যেশ করে; ঘোলা চোখে পূর্ণিমার চাঁদ খোঁজে। আমি ভাবি নিজের কথা। ঘুম ও বিছানার ইতিহাস খুব বেশি গৌরবের নয়। আজন্মের ঘুমকাতুরে। চোখ বুজলে দুনিয়া অন্ধকার! উত্তরের মাথা দক্ষিণে পৌছে; লুঙ্গি মাথায় ওঠে। বালিশ আকড়ে চোখ বন্ধ করে আরো কিছুক্ষণ ঘুমের ভ্যান করে শুয়ে থাকি। কেউ ডাকাডাকি করলে বিরক্ত হই। পাশে বসে আদর করে মা যখন চুলে বিলি কাটে তখন খুব ভালো লাগে; নিবিড় ভাবে দু’হাত দিয়ে মা’কে জড়িয়ে ধরি। <br>\nখুকিকেও কি তাহলে আঁকড়ে ধরেছিলাম! <br>\nচেষ্টা করেও মনে করতে পারি না। ধড়ফড় করে উঠে বসি। দু’হাত দিয়ে চোখ কচলায়; বুনো ফুলের গন্ধমাখা বাতাস ছুঁয়ে যায়। যাত্রীদের নিরীক্ষণ করি। অদুরেই ক’জন বখাটে। ভিডিও প্লেয়ারের বাংলা সিনেমার গানের চাইতে খুকির প্রতি তারা অধিক আগ্রহী। আগ্রহভরে আমাকে লক্ষ্য করে। মিনারেল ওয়াটারের বোতলে মুখ লাগিয়ে ঢকাঢক পানি পান করি। খুকি আঁড়চোখে তাকিয়ে। পানির বোতল এগিয়ে ধরতে মন চায়; সাহসে কুলোয় না। জীবনের নথিঁপত্র ঘাটতে শুরু করি; নদী ও নারীর উপস্থিতি অনুসন্ধান করি। ঝাপসা কিছু ছবি আসে বটে; ওই ছবির নিদৃষ্ট কোনো আদল নেই; কারো সাথে বিশেষ কোনো সংযোগ নেই। স্বপ্নের ঘোরে কারো কারো সংস্পর্শে পুলকিত হলেও বাস্তবে কেউ নেই- নিরস মরুভুমি! মরুর বুকে মরিচিকা দেখতে দেখতে ক্লান্ত আমি। অবশেষে সমুদ্রের কাছে; পূবালী বাতাসে ফসলের সম্ভার অনুভুত হয়! রাতের বুক চিরে লঞ্চ এগিয়ে চলে। মাঝে মাঝে ঝাঁকি ওঠে; ঝাঁকি সামলাতে না পেরে খুকির শরীরের ওপর হুমড়ে পড়ি কিংবা খুকি আমার ওপর। পর মূহুর্তেই চকিত হয়ে উঠি দুজন। সরে বসার চেষ্টা করি। চারদিকে মানব প্রাচির। তীল ধারনের ঠাঁই নেই! যুদ্ধুক্ষেত্রে ছড়িয়ে ছিটিয়ে থাকা লাশের মতোই যাত্রিরা ছড়িয়ে ছিটিয়ে। রাতের লঞ্চ এমনই হয়! স্থান দখলের প্রতিযোগিতা চলে। বিছানা, কাঁথা বা চাঁদর পেতে ঘুমানোর আয়োজন করে। আমিও ঘুমিয়ে পড়েছিলাম। হয়তো খুকির সংস্পর্শে ঘুমের দৈর্ঘ্য সংকুচিত হয়েছে! স্মৃতির দৈর্ঘ্য ক্রমশ লম্বা হয়। আমি তখন দশম শ্রেনীর চৌকাঠে। রাতের পড়া শেষ করে মাত্রই চোখ বন্ধ করে শুয়েছি। নদীর ওপার থেকে বাঁশির সুর ভেসে আসে; কলতলায় রাখালের কণ্ঠধ্বনী; গোয়াল পালানো বাছুরের খোঁজে ব্যতিব্যস্ত সে। ঠিক তখনি ধীরপায়ে কেউ একজন আমার পাশে এসে বসে; চোখে চোখ রাখে। আহা, কি মায়াবী চোখ! অপলক দৃষ্টিতে চেয়ে থাকি; সে চোখে সমুদ্রের গভিরতা। একটু একটু করে সমুদ্রের অতলে তলিয়ে যেতে থাকি। মনে হয়, স্বপ্ন দেখছি! রাখালের কথা স্মরণ করি; বাঁশির সুর আগের মতোই উজানের পথে; বটশাখায় হরিয়ালের জ্যান্তব কাঁচর-ম্যাচর! মেয়েটি আমায় হাতছানি দিয়ে কাছে ডাকে। ছুঁয়ে দেখার সাধ জাগে। কিন্তু চোখ মেলে তাকাতেই সে হারিয়ে যায়; একখ- আলোর ঝলকানি অনুভব করি!<br>\nপরী মেয়ে!<br>\nঅনেকদিন পরে খুকি হয়ে পরী মেয়েটি ফিরে এসেছে! সেই চোখ, সেই নাক, হাতে সোনার বালা, কানে ঝুমকো লতা। আজও মায়ার কাজল পরে এসেছে! ভিতরে ভিতরে উসখুস শুরু হয়। চিমটি কাঁটতে ইচ্ছে করে। না, অলিক নয়; রক্ত-মাংসের খুকি আমার পাশে বসা! ইচ্ছে করলে শুতে পারি; তবে ঘুম আসবে না উপরন্ত মেয়েটির সংকোচ বাড়বে। <br>\nলঞ্চের ছাদে এসে দাড়াই। দুপাশে সুন্দরবন; মাঝ বরাবর নৌযান এগিয়ে চলেছে। পানি কেটে ভাগ হয়ে যাচ্ছে। ইঞ্জিনের শব্দের সাথে জলের স্রােত মিলেমিশে একাকার। তন্ময় হয়ে সম্মুখে তাকাই। বৃষ্টিমাখা বাতাস। বনের গভীরে ঘোর অন্ধকার। তীর ঘেঁষে মাঝে মাঝে আলোর দিশা চোখে পড়ে। মাছের প্রতিক্ষায় জেলেরা অপেক্ষা করছে। ভাটির টান শুরু হলে খালের পানি নিচে নেমে আসবে; তখন অসংখ্য মাছ তাদের জালে আটকা পড়বে। চন্দ্র-মেঘের খেলা চলে। মেঘের আড়ালে চাঁদ ঢাকা পড়লে আঁধারের ঘনত্ব বেড়ে যায়। খুকির চোখেমুখেও আঁধার। আলোর পরিবর্তে আমি কী তাকে আঁধার দিয়েছি! ইস, জড়িয়ে ধরলে আজন্মের মতো মেয়েটি আমায় ক্ষমা করবে না। অন্য দশজনের মতো আমাকেও একপাল্লায় ওজন করবে। <br>\nদুর থেকে ভেসে আসে বন্যপ্রাণীর হুংকার! দৃশ্যপট বদলে যায়। রহস্যে ঘেরা সুন্দরবন। বাঁকে বাঁকে বিপদের আশংকা তথাপি জীবন ও জীবিকার টানে মানুষ এখানে না এসে পারে না। রায়মঙ্গল নদীর মোহনায় রক্ত হীম হয়ে আসে। লঞ্চের গায়ে বড় বড় ঢেউ এসে ছলাত ছলাত আছাড় খায়। নৌযান দুলে ওঠে। আমি ও খুকি দুলতে থাকি; দুলতে থাকে আমার পৃথিবী। খুকির গরম নিঃশ্বাস মুখে লাগলে বুকের মধ্যে তোলপাড় শুরু হয়। আহা, কাছে থেকেও মেয়েটি কত দুরে! মনে মনে তাকে কামনা করি। কামনার আগুণে আমার ভিতর-বাইরে দগ্ধ হই। আগুনপাখি হয়ে খুকিকে নিয়ে দূর আকাশে উড়াল দিই। মেঘের গালিচায় একে-অন্যকে আলিঙ্গণ করি। আহা কি মায়াবি চোখ! দেবী দূর্গার মতোন মায়ার কাজল পরানো! কিছুতেই চোখ ফেরানো যায় না। শরীরের সাথে শরীর মিশিয়ে দু’হাত দিয়ে গলা জড়িয়ে নিবিড়ভাবে চাঁদের পানে তাকিয়ে থাকি; খুকিও! তখন মনে হয় একজীবনে চাঁদ দেখার তৃঞ্চা শেষ হওয়ার নয়। <br>\nবাস্তবের মাটিতে ফিরে এলে মরে যেতে ইচ্ছে করে। রায়মঙ্গলের জলে লঞ্চটি ডুবে গেলে খুকি আর আমার মধ্যে কোনো বিভেদ থাকবে না; কথা বলতে না পারার আক্ষেপ থাকবে না!<br>\nনাম কি!<br>\nবাড়ি কোথায়!<br>\nকোথায় নামবে সে!<br>\nখুকির চোখে কাতরতা। মুখের উপর লেপ্টে থাকা চুল আলগোছে সরিয়ে দেয়। দাঁতে ক্লিপ চেপে ধরে শক্ত করে চুল বাঁধে। হতাশাময় দৃষ্টিতে দুরের আকাশ পানে তাকায়। দীর্ঘশ্বাস আড়াল করে। বখাটেদের চোখে চোখ পড়তেই ভ্রুঁ জোড়া কুঁচকে যায়। তখন আমার পানে তাকায়। খুকির মনের ভিতরটা পড়ে দেখতে চেষ্টা করি। তার ভিতরেও কি ভাঙাগড়ার খেলা চলছে?<br>\nদহন ক্রমশ ঘণীভুত হয়। গন্তব্য নিকটবর্তী হতে থাকলে বিষণœতার মাত্রা উর্ধ্বমুখী হয়। দিনের আলো জেগে উঠলেও আমার মধ্যে গাঢ় অন্ধকার। খুকি নির্বিকার। আনত চোখে পায়ের পাতায় চোখ রাখে; আনমনে দাঁত দিয়ে নখ কাটে। জগত-সংসার তাকে আর আমাকে বিচ্ছিন্ন করে দিচ্ছে! এ জীবনে হয়তো দেখা হবে না; কিংবা হতেও পারে! মনের মধ্যে নানাবিধ ভাবনা; চিনচিনে ব্যথার অনুভুতি। ইচ্ছে হয়, খুকির মাথায় হাত রাখি; তার গন্তব্য সম্পর্কে জিজ্ঞেস করি। নাহ, পারিনি; কাপুরুষের মতো নেমে এসেছিলাম। নারায়নপুর লঞ্চঘাটে পাথর চোখে অনেকক্ষণ তাকিয়ে ছিলাম; খুকিও! মনের ভিতরটা সেদিন ঠিকঠাক পড়তে না পারলেও আজ বুঝতে পারি, মেয়েটি তার জীবন নাটকে আমায় প্রত্যাশা করেছিল; হাতে হাত রেখে পথ চলতে চেয়েছিল।<br>\nচলার পথে অসংখ্য মানুষের দেখা পেয়েছি; কারো সাথে সখ্যতা হয়েছে; হাসাহাসি করেছি, আড্ডা দিয়েছি, ঠাট্টা করেছি কিন্তু খুকির জন্য যা হয়েছে তা আর কারো জন্য হয়নি। দৃষ্টির আড়ালে হারিয়ে না যাওয়া পর্যন্ত তাকিয়ে ছিলাম। জল ভরা নয়নে মেয়েটিকে কাঁদতে দেখেছি; ওড়নার আঁচলে মুখ লুকাতে দেখেছি!<br>\nকেনো কেঁদেছিল খুকি!<br>\nকি বলতে চেয়েছিল সে!<br>\nভুল; সব ভুল। চোখের জল না দেখলে হয়তো এভাবে ভুলের মাসুল দিতে হতো না; অসুস্থ সজ্জায় প্রহর গুনতে হতো না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>দুই</strong></em><br> ওই চোখে নিবেদনের ভঙ্গি ছিল; নির্ভরতা ছিল- তা না হলে সারারাত্রি আমার সংস্পর্শে বসে থাকবে কেনো! কেনোই বা ঘনঘন দীর্ঘশ্বাস আড়াল করবে! আমার দীর্ঘশ্বাস বেড়ে চলে। কয়রার জীবন কিছুতেই মানিয়ে নিতে পারছিলাম না। একজোড়া চোখ অহর্ণিশ কাছে ডাকে; বুকের মধ্যে হাহাকার জাগে। অফিসের কাজে আমাদি, মদিনাবাদ, গোবরা, হরিনখোলা, বেতকাঁশি, কাঠমার চর, মহারাজপুর-সহ প্রত্যন্ত অঞ্চল চষে বেড়াই; কিস্তির ফাঁকে ফাঁকে খুকিকে অনুসন্ধান করি। কারনে অকারনে দুরের রাস্তায় পাড়ি জমাই; খুলনা থেকে নীলডুমুর, নীলডুমুর থেকে খুলনা- নাহ, খুকি নেই!<br> কিস্তিজীবন ভালো লাগে না, অল্পতেই হাঁপিয়ে উঠি। মাঠের কিনারে দাঁড়ালে শূন্যতা আরো বাড়ে। ফসলহীন বিস্তির্ণ মাঠ। মাঝে মাঝে চিঙড়ির ঘের। গুমোট অন্ধকার ভালো লাগে না। ভোরের আলোয় কপোতাক্ষের তীরে এসে দাঁড়াই। চর্তভুজ আকৃতির জাল নিয়ে ছেলে-বুড়ো-মেয়ে রেনু সংগ্রহ করে। গারস্থ্য জীবনের চিত্রও ভিন্ন। সুন্দরবনকেন্দ্রিক জীবন চরাচর। কাঠ কাটা, গোলপাতা সংগ্রহ, মধু আহরণ, মৎস্য শিকার, জাল বোনা- বিচিত্র পেশা! পান-সুপারি ছাড়া এক মূহুর্ত চলে না! অবসর মুহুর্তে ঘরের দাওয়ায় টাঙানো দোলনায় দোল খায়। আমিও দোল খাই। খুকির দোলনায় দুলে দুলে হয়রান। টাকা-পয়সার হিসেব কষতে গেলে মাথার মধ্যে চক্কর পাড়ে। খুব সকালে ঘুম থেকে উঠলে থরথর করে শরীর কাঁপে। মনে হয়, এই বুঝি পড়ে যাবো! প্রশান্তির লাগি ৪ নং কয়রায় ছুঁটে যাই। সুইচ গেটের ওপর দাঁড়িয়ে থাকি। পাশে কাশিয়াবাদ ফরেষ্ট রেঞ্জ। ডিঙি নৌকাগুলো সারি সারি ঘাটে বাঁধা। বাতাসের দোলায় হঠাৎ হঠাৎ দুলে ওঠে। ভাড়া নৌকায় বনের অভ্যন্তরে প্রবেশ করি। ভয়ার্ত পরিবেশ। কীটপতঙ্গের নিরবিচ্ছিন্ন চিৎকারে অপার্থিব আবহ সৃষ্টি হয়েছে। ভয়ে গা ছমছম করে। দুপাশ থেকে ঘন ডাল ঝুকে পড়ে আলো-আঁধারীর সৃষ্টি হয়েছে। বাঁধের ওপর দাঁড়ালে হরিনের দেখা মেলে। ভাটা আরম্ভ হলে বুড়ো বানরগুলো কাঁদার মধ্যে গড়াগড়ি খায়। কালেভদ্রে বাঘের দেথা মেলে। কয়রাবাসীর জীবনে ঘুব বেশি বাঘের উৎপাত। মাছ ধরতে গিয়ে কেউ কেউ লাশ হয়ে ফিরে আসে। তবুও বনের ওপর রাগ করে থাকতে পারে না। বাঘ বিষয়ে বিস্তর আলোচনা- নাম মুখে আনে না, মামা বলে সম্মোধন করে। শুক্রবার নাকি মামার জন্মদিন! কেউ সেদিন বনে যায় না; হাত-পা গুটিয়ে ঘরের দাওয়ায় বসে থাকে; আকাশের পানে মুখ করে হাঁ-পিত্যেশ করে। একদিন জঙ্গলে না গেলে তাদের চলে না; পরিবার পরিজন অভুক্ত থাকে তথাপি জঙ্গলের পথে পা রাখতে বুক কাঁপে।<br> কুসংস্কার!<br> আমি হাসাহাসি করি। মানুষগুলো আহত হয়। কে কবে বাঘ দেখেছে; কেমন করে গলা ফুটো করে রক্ত খেয়েছে; বিড়াল পায়ে কেমন করে চলাফেরা করে- বহুমাত্রিক সব জল্পনা-কল্পনা। অথচ মানুষগুলো জানে না, বাঘের চেয়ে কিস্তি অনেক বেশি ভয়ংকর! বাঘের হাত থেকে কেউ কেউ হয়তো প্রাণ নিয়ে পালাতে পারে, কিন্তু কিস্তির কবলে পড়লে বিপদ অনিবার্য; মৃত্যুর পরেও রেহাই মেলে না! রক্তচোষা বাদুরের মতো জনগণকে তারা রক্তহীন করে চলেছে। আমি নিজেও যেন বাদুর! বাদুরের মতো আঁধার পছন্দ করি। কিস্তির টাকা পরিশোধ করতে ব্যর্থ হলে রক্তঠোটে হামলে পড়ি। রাগে-ক্ষোভে ফুঁসতে থাকি। কাঁদাজল মাথায় করে রক্তের নেশায় ছুটতে থাকি। মালি বাড়ির বীনা বৌদি দেনার দায়ে পালিয়েছিল। তাতেও রক্ষা মেলেনি; দলবল সাথে নিয়ে দুরের পথ পাড়ি দিয়ে বাবার বাড়ি হাজির হয়েছিলাম! বৌদি সেদিন ভুত দেখার মতোই চমকে উঠেছিল; অনুনয়-বিনয় করে দুদিন সময় প্রার্থণা করেছিল; বাবা-মার সামনে অপমান না করার জন্যে কাকুতি মিনতি করেছিল; আমি শুনিনি, গায়ের ঝাল মেটাতে যা বলার নয় তাও বলেছিলাম!<br> বৌদির জন্য দুঃখ হয়। গলায় দড়ি নিয়ে মেয়েটি মরেছে! বীনা বৌদির মৃত্যুর জন্য আমিই দায়ী! আমিই তার বাঁচার পথ রুদ্ধ করে দিয়েছি; আমার কারনেই জীবনের প্রতি ঘৃণা জন্মিয়েছে; বেচে থাকা অর্থহীন মনে হয়েছে! শুধু বীনা কিংবা মৌসুমি নয় অসংখ্য দায় আমার; অনেক অপকর্মের দোসর আমি। ভার কাধে নিয়ে মাঝে মাঝে ঘুম হয় না। নিশাচর পাখির সঙ্গি হয়ে জেগে থাকি। জীবনের হিসেব মেলাতে ব্যতিব্যস্ত! হায়, বাদুর না হয়ে মানুষ হলে হয়তো খুকির দেখা মিলতো; হয়তো ফুলের গন্ধে আকুল হয়ে জীবন ও যৌবন উপভোগ্য হতো! মাঝে মাঝে এও মনে হয়, খুকির সাথে দেখা না হলে ভালো হত! অর্জিত বিদ্যা পুঁজি করে সাফল্যের সিঁড়ি ভাঙতে পারতাম! মানুষ ঠকানোর বিদ্যা বেশ তো রপ্ত করেছিলাম! অথচ খুকির ছোয়ায় জীবনের সমিকরণ বদলে গেল। হারিয়ে ফেলা বিবেক নতুন করে জাগ্রত হলো; ছাঁইচাপা আগুন জ্বলে উঠলো। মনে মনে সংসারের ছবি আঁকি। সমিতিতে আগত মানুষগুলোকে দেখে ভুল হয়। ছাত্র ইউনিয়নের খ- খন্ড মিছিল স্পষ্ট হয়ে ওঠে। ব্যানার, ফেস্টুন, মিছিল, পোষ্টার, লিফলেট- নির্যাতিত মানুষের মুক্তির লক্ষ্যে অসংখ্য আয়োজন। নিজের মধ্যে অর্ন্তদ্বন্ধ¦। নিরন্তর ভাঙাগড়ার খেলা। আমার হাতে মৃত্যুর পরোয়ানা। স্বাক্ষরের মাধ্যমে মৃত্যু নিশ্চিত হয়; পরিবার ক্ষয়ে যায়; সমাজ ধ্বংস হয়। বীনা বৌদির সন্তান দুটো অসহায়। মায়ের জন্য কেঁদে কেঁদে চোখের জল শুকিয়ে গেছে; কতদিন না খেয়ে রাত্রে ঘুমিয়ে পড়ে। মন্টুদা পুনরায় বিয়ে করেছে। রমজান আলীর কুঁড়েঘর নিলামে উঠেছে! এক টুকরো আকাশ তার নিত্য সঙ্গি। জাল হারিয়ে গগন মাঝি দিশেহারা! মৌসুমি বৌদির বুকে দীর্ঘশ্বাস বাজে। স্বামীর ফিরে আসার ক্ষণ কেবলই দীর্ঘ হয়! হাতে শাখা থাকলে বোধহয় এমনটা হত না!<br> একজন খুকি নিরন্তর আমাকে তাড়া করে। কখনো বীনা কখনো মৌসুমি কখনো নামহীনা ফুল হয়ে চোখ পাকায়। চোখে আঙ্গুল দিয়ে ভুলগুলো দেখিয়ে দেয়; শুধরানোর তাড়না অনুভব করি। উৎভ্রান্তের মতো পথ চলি। রঙিন ফুলের পাশে নিজেকে অন্ধকার মনে হয়। ছাদের উপর এসে দাঁড়ালে হুঁ হুঁ করে বাতাস খেলা করে; প্রকৃতির সৌন্দর্য্য স্পষ্ট হয়ে ওঠে। খুকির শূন্যতা অনুভব করি তখন। জীবনের কারবার অর্থহীন মনে হয়। গভীর রাতে চোরাকারবারিরা আসে; হরিণের মাংস দিয়ে যায়। কলিগরা মজা করে খায়। কেওড়ার ফলের মৌসুমে মাংস যেমন টক হয় আমার অনুভুতিও টকযুক্ত; কিছুতেই মাংস খেতে পারি না; একজোড়া হরিণচোখ আমার গলা আটকে ধরে।<br> ভুল করেছিলাম আমি।<br> আরো কিছুদিন নীলডুমুরের পথে পথে ঘুরতে চেয়েছিলাম; লবন-জলের সংস্পর্শে বসত করতে চেয়েছিলাম কিন্তু নিয়তী সে পথ রুদ্ধ করে দিয়েছে। অসুস্থ দেহে শিকড়ের কাছে ফিরে এসেছি। কুমার নদের ধারে, বাঁশ বাগানের ছায়ায় সারাক্ষণ শুয়ে থাকি। সুস্থ জীবনের স্বপ্ন দেখি। অথচ স্বপ্ন পূরণ হওয়ার নয়। শরীরময় অসুখের জীবানু। বিষন্নতায় মগজের পানি কমতির পথে। তীল তীল করে ক্ষয়ে যাচ্ছি। মাঝে মাঝে যন্ত্রণা প্রকট হয়। শ্বাস-প্রশ্বাস দ্রুত ওঠানামা করে। দাঁতে দাঁত চেপে তখন শুয়ে থাকি। চোখ বন্ধ করলে পরকালের রাস্তা দেখতে পাই। মনে হয়, এই বুঝি নিঃশ্বাস থেমে যাবে; থেমে যাবে জীবনের কোলাহল। ডাক্তারের চোখে সরষেফুল। কবিরাজ অবশ্য ডুমুরফুলের কথা বলে; ওই ফুলের ছোঁয়ায় পুনরায় নাকি কক্ষপথে ফিরতে পারি আমি! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br> ওই চোখে নিবেদনের ভঙ্গি ছিল; নির্ভরতা ছিল- তা না হলে সারারাত্রি আমার সংস্পর্শে বসে থাকবে কেনো! কেনোই বা ঘনঘন দীর্ঘশ্বাস আড়াল করবে! আমার দীর্ঘশ্বাস বেড়ে চলে। কয়রার জীবন কিছুতেই মানিয়ে নিতে পারছিলাম না। একজোড়া চোখ অহর্ণিশ কাছে ডাকে; বুকের মধ্যে হাহাকার জাগে। অফিসের কাজে আমাদি, মদিনাবাদ, গোবরা, হরিনখোলা, বেতকাঁশি, কাঠমার চর, মহারাজপুর-সহ প্রত্যন্ত অঞ্চল চষে বেড়াই; কিস্তির ফাঁকে ফাঁকে খুকিকে অনুসন্ধান করি। কারনে অকারনে দুরের রাস্তায় পাড়ি জমাই; খুলনা থেকে নীলডুমুর, নীলডুমুর থেকে খুলনা- নাহ, খুকি নেই!<br> কিস্তিজীবন ভালো লাগে না, অল্পতেই হাঁপিয়ে উঠি। মাঠের কিনারে দাঁড়ালে শূন্যতা আরো বাড়ে। ফসলহীন বিস্তির্ণ মাঠ। মাঝে মাঝে চিঙড়ির ঘের। গুমোট অন্ধকার ভালো লাগে না। ভোরের আলোয় কপোতাক্ষের তীরে এসে দাঁড়াই। চর্তভুজ আকৃতির জাল নিয়ে ছেলে-বুড়ো-মেয়ে রেনু সংগ্রহ করে। গারস্থ্য জীবনের চিত্রও ভিন্ন। সুন্দরবনকেন্দ্রিক জীবন চরাচর। কাঠ কাটা, গোলপাতা সংগ্রহ, মধু আহরণ, মৎস্য শিকার, জাল বোনা- বিচিত্র পেশা! পান-সুপারি ছাড়া এক মূহুর্ত চলে না! অবসর মুহুর্তে ঘরের দাওয়ায় টাঙানো দোলনায় দোল খায়। আমিও দোল খাই। খুকির দোলনায় দুলে দুলে হয়রান। টাকা-পয়সার হিসেব কষতে গেলে মাথার মধ্যে চক্কর পাড়ে। খুব সকালে ঘুম থেকে উঠলে থরথর করে শরীর কাঁপে। মনে হয়, এই বুঝি পড়ে যাবো! প্রশান্তির লাগি ৪ নং কয়রায় ছুঁটে যাই। সুইচ গেটের ওপর দাঁড়িয়ে থাকি। পাশে কাশিয়াবাদ ফরেষ্ট রেঞ্জ। ডিঙি নৌকাগুলো সারি সারি ঘাটে বাঁধা। বাতাসের দোলায় হঠাৎ হঠাৎ দুলে ওঠে। ভাড়া নৌকায় বনের অভ্যন্তরে প্রবেশ করি। ভয়ার্ত পরিবেশ। কীটপতঙ্গের নিরবিচ্ছিন্ন চিৎকারে অপার্থিব আবহ সৃষ্টি হয়েছে। ভয়ে গা ছমছম করে। দুপাশ থেকে ঘন ডাল ঝুকে পড়ে আলো-আঁধারীর সৃষ্টি হয়েছে। বাঁধের ওপর দাঁড়ালে হরিনের দেখা মেলে। ভাটা আরম্ভ হলে বুড়ো বানরগুলো কাঁদার মধ্যে গড়াগড়ি খায়। কালেভদ্রে বাঘের দেথা মেলে। কয়রাবাসীর জীবনে ঘুব বেশি বাঘের উৎপাত। মাছ ধরতে গিয়ে কেউ কেউ লাশ হয়ে ফিরে আসে। তবুও বনের ওপর রাগ করে থাকতে পারে না। বাঘ বিষয়ে বিস্তর আলোচনা- নাম মুখে আনে না, মামা বলে সম্মোধন করে। শুক্রবার নাকি মামার জন্মদিন! কেউ সেদিন বনে যায় না; হাত-পা গুটিয়ে ঘরের দাওয়ায় বসে থাকে; আকাশের পানে মুখ করে হাঁ-পিত্যেশ করে। একদিন জঙ্গলে না গেলে তাদের চলে না; পরিবার পরিজন অভুক্ত থাকে তথাপি জঙ্গলের পথে পা রাখতে বুক কাঁপে।<br> কুসংস্কার!<br> আমি হাসাহাসি করি। মানুষগুলো আহত হয়। কে কবে বাঘ দেখেছে; কেমন করে গলা ফুটো করে রক্ত খেয়েছে; বিড়াল পায়ে কেমন করে চলাফেরা করে- বহুমাত্রিক সব জল্পনা-কল্পনা। অথচ মানুষগুলো জানে না, বাঘের চেয়ে কিস্তি অনেক বেশি ভয়ংকর! বাঘের হাত থেকে কেউ কেউ হয়তো প্রাণ নিয়ে পালাতে পারে, কিন্তু কিস্তির কবলে পড়লে বিপদ অনিবার্য; মৃত্যুর পরেও রেহাই মেলে না! রক্তচোষা বাদুরের মতো জনগণকে তারা রক্তহীন করে চলেছে। আমি নিজেও যেন বাদুর! বাদুরের মতো আঁধার পছন্দ করি। কিস্তির টাকা পরিশোধ করতে ব্যর্থ হলে রক্তঠোটে হামলে পড়ি। রাগে-ক্ষোভে ফুঁসতে থাকি। কাঁদাজল মাথায় করে রক্তের নেশায় ছুটতে থাকি। মালি বাড়ির বীনা বৌদি দেনার দায়ে পালিয়েছিল। তাতেও রক্ষা মেলেনি; দলবল সাথে নিয়ে দুরের পথ পাড়ি দিয়ে বাবার বাড়ি হাজির হয়েছিলাম! বৌদি সেদিন ভুত দেখার মতোই চমকে উঠেছিল; অনুনয়-বিনয় করে দুদিন সময় প্রার্থণা করেছিল; বাবা-মার সামনে অপমান না করার জন্যে কাকুতি মিনতি করেছিল; আমি শুনিনি, গায়ের ঝাল মেটাতে যা বলার নয় তাও বলেছিলাম!<br> বৌদির জন্য দুঃখ হয়। গলায় দড়ি নিয়ে মেয়েটি মরেছে! বীনা বৌদির মৃত্যুর জন্য আমিই দায়ী! আমিই তার বাঁচার পথ রুদ্ধ করে দিয়েছি; আমার কারনেই জীবনের প্রতি ঘৃণা জন্মিয়েছে; বেচে থাকা অর্থহীন মনে হয়েছে! শুধু বীনা কিংবা মৌসুমি নয় অসংখ্য দায় আমার; অনেক অপকর্মের দোসর আমি। ভার কাধে নিয়ে মাঝে মাঝে ঘুম হয় না। নিশাচর পাখির সঙ্গি হয়ে জেগে থাকি। জীবনের হিসেব মেলাতে ব্যতিব্যস্ত! হায়, বাদুর না হয়ে মানুষ হলে হয়তো খুকির দেখা মিলতো; হয়তো ফুলের গন্ধে আকুল হয়ে জীবন ও যৌবন উপভোগ্য হতো! মাঝে মাঝে এও মনে হয়, খুকির সাথে দেখা না হলে ভালো হত! অর্জিত বিদ্যা পুঁজি করে সাফল্যের সিঁড়ি ভাঙতে পারতাম! মানুষ ঠকানোর বিদ্যা বেশ তো রপ্ত করেছিলাম! অথচ খুকির ছোয়ায় জীবনের সমিকরণ বদলে গেল। হারিয়ে ফেলা বিবেক নতুন করে জাগ্রত হলো; ছাঁইচাপা আগুন জ্বলে উঠলো। মনে মনে সংসারের ছবি আঁকি। সমিতিতে আগত মানুষগুলোকে দেখে ভুল হয়। ছাত্র ইউনিয়নের খ- খন্ড মিছিল স্পষ্ট হয়ে ওঠে। ব্যানার, ফেস্টুন, মিছিল, পোষ্টার, লিফলেট- নির্যাতিত মানুষের মুক্তির লক্ষ্যে অসংখ্য আয়োজন। নিজের মধ্যে অর্ন্তদ্বন্ধ¦। নিরন্তর ভাঙাগড়ার খেলা। আমার হাতে মৃত্যুর পরোয়ানা। স্বাক্ষরের মাধ্যমে মৃত্যু নিশ্চিত হয়; পরিবার ক্ষয়ে যায়; সমাজ ধ্বংস হয়। বীনা বৌদির সন্তান দুটো অসহায়। মায়ের জন্য কেঁদে কেঁদে চোখের জল শুকিয়ে গেছে; কতদিন না খেয়ে রাত্রে ঘুমিয়ে পড়ে। মন্টুদা পুনরায় বিয়ে করেছে। রমজান আলীর কুঁড়েঘর নিলামে উঠেছে! এক টুকরো আকাশ তার নিত্য সঙ্গি। জাল হারিয়ে গগন মাঝি দিশেহারা! মৌসুমি বৌদির বুকে দীর্ঘশ্বাস বাজে। স্বামীর ফিরে আসার ক্ষণ কেবলই দীর্ঘ হয়! হাতে শাখা থাকলে বোধহয় এমনটা হত না!<br> একজন খুকি নিরন্তর আমাকে তাড়া করে। কখনো বীনা কখনো মৌসুমি কখনো নামহীনা ফুল হয়ে চোখ পাকায়। চোখে আঙ্গুল দিয়ে ভুলগুলো দেখিয়ে দেয়; শুধরানোর তাড়না অনুভব করি। উৎভ্রান্তের মতো পথ চলি। রঙিন ফুলের পাশে নিজেকে অন্ধকার মনে হয়। ছাদের উপর এসে দাঁড়ালে হুঁ হুঁ করে বাতাস খেলা করে; প্রকৃতির সৌন্দর্য্য স্পষ্ট হয়ে ওঠে। খুকির শূন্যতা অনুভব করি তখন। জীবনের কারবার অর্থহীন মনে হয়। গভীর রাতে চোরাকারবারিরা আসে; হরিণের মাংস দিয়ে যায়। কলিগরা মজা করে খায়। কেওড়ার ফলের মৌসুমে মাংস যেমন টক হয় আমার অনুভুতিও টকযুক্ত; কিছুতেই মাংস খেতে পারি না; একজোড়া হরিণচোখ আমার গলা আটকে ধরে।<br> ভুল করেছিলাম আমি।<br> আরো কিছুদিন নীলডুমুরের পথে পথে ঘুরতে চেয়েছিলাম; লবন-জলের সংস্পর্শে বসত করতে চেয়েছিলাম কিন্তু নিয়তী সে পথ রুদ্ধ করে দিয়েছে। অসুস্থ দেহে শিকড়ের কাছে ফিরে এসেছি। কুমার নদের ধারে, বাঁশ বাগানের ছায়ায় সারাক্ষণ শুয়ে থাকি। সুস্থ জীবনের স্বপ্ন দেখি। অথচ স্বপ্ন পূরণ হওয়ার নয়। শরীরময় অসুখের জীবানু। বিষন্নতায় মগজের পানি কমতির পথে। তীল তীল করে ক্ষয়ে যাচ্ছি। মাঝে মাঝে যন্ত্রণা প্রকট হয়। শ্বাস-প্রশ্বাস দ্রুত ওঠানামা করে। দাঁতে দাঁত চেপে তখন শুয়ে থাকি। চোখ বন্ধ করলে পরকালের রাস্তা দেখতে পাই। মনে হয়, এই বুঝি নিঃশ্বাস থেমে যাবে; থেমে যাবে জীবনের কোলাহল। ডাক্তারের চোখে সরষেফুল। কবিরাজ অবশ্য ডুমুরফুলের কথা বলে; ওই ফুলের ছোঁয়ায় পুনরায় নাকি কক্ষপথে ফিরতে পারি আমি! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © পিন্টু রহমান</p>\n<!-- /wp:paragraph -->', 'ফুলের মাধুর্য্য কুঁড়িতে বিনষ্ট হলে; অনাদরে ঝরে গেলে; ম-পে দলিত-মথিত হলে ফুল বিষয়ে ভুল হয়। অবশ্য কারো মতে ডুমুরের ফুল হয় না ফল হয়- কিন্তু আমি ফুল দেখেছি! না, ফুল তার নাম নয়; খুকিও নয়। তবে বাবার মুখে তা...', '', 9, NULL, 'publish', 2068, 0, '2019-01-20 15:03:17', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (12, 2134, 16, 'খনা-পুরুষতন্ত্রের ঈর্ষার বলি এক নারী', 'খনা-পুরুষতন্ত্রের-ঈর্ষার', '<!-- wp:paragraph -->\n<p>বাংলা সাহিত্যে বহু প্রবাদ-প্রবচন রয়েছে, যেগুলো শুধু শুধুমাত্র সাহিত্য নয় বরং দর্শন এমনকি বিজ্ঞানসম্মত বা বাস্তবসম্মতও বটে। এক সময় এগুলোর চর্চা ছিল। এখন এই চর্চাটা কমে গেলেও মানুষের ভেতর থেকে একেবারে হারিয়ে যায়নি। এর মধ্যে উল্লেখযোগ্য হল খনার বচন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p><em>“পৌষ গরমি বোশেখ জাড়া<br> প্রথম আষাঢ়ে ভরে গাড়া”</em></p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p> -অর্থাৎ, পৌষ মাসে গরম থাকলে এবং বৈশাখ মাসে ঠা-া থাকলে আষাঢ়ের প্রথমেই খুব বৃষ্টি হবে- ডোবা গাড়া জলে ভরে যাবে। <br> এরকম অসংখ্য প্রবাদ বা বচন এ অঞ্চলে প্রচলিত রয়েছে। এগুলোর বক্তা একজন বিদুষী নারী যার নাম খনা। তাই এগুলো খনার বচন নামে পরিচিত। যদিও অনেকেই খনার বচনের অনেক শ্লোককে কুসংস্কার বলে আখ্যা দিতে পারেন, বিশেষ করে এই আধুনিক যুগে। কিন্তু আমাদেরকে বুঝতে হবে খনার বচন সৃষ্টির সেই সময় ও প্রেক্ষাপটকে। তাছাড়া পুরোটাই যে কুসংস্কার নয় এবং অধিকাংশই বাস্তবসম্মত তা বলার অপেক্ষা রাখে না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু খনার বচনকে অবহেলা করার কোন কারণই নেই। কারণ খনার বিজ্ঞানভিত্তিক বচনগুলো এ অঞ্চলের জলবায়ু ও মহাকাশের গ্রহ-নক্ষত্রসমূহের গবেষণা থেকে প্রাপ্ত। অবশ্য কখনও এগুলো সংরক্ষণের ব্যবস্থা নেয়া হয়নি। অথচ গ্রামের মানুষগুলো এখনও এই বচনগুলো মেনে চলে। নিঃসন্দেহে খনার বচনকে কেবল লোকবচন না বলে বিজ্ঞান হিসেবে আখ্যায়িত করা যায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>খনার নাম প্রায় আমরা সবাই জানি। বিশেষ করে গ্রামের মানুষের কাছে খনা অধিক পরিচিত। কৃষি, আবহাওয়া ও সংসার জীবনের নানা বিষয় নিয়ে খনার বচনগুলো এখনও মানুষের মুখে মুখে রয়েছে এবং তার বচন বা শ্লোকগুলো নির্ভুলভাবেই প্রতিফলিত। ফলে বাংলাদেশের শতকরা ৯০ জন কৃষকই খনার বচন সম্পর্কে অবহিত। কিন্তু বেশিরভাগই মুখস্ত আওড়াতে পারে না। ফলে অনেক বচনই সংরক্ষণের অভাবে হারিয়ে গেছে এবং নতুন করে সংগ্রহ করাও প্রায় অসম্ভব। বাংলা পঞ্জিকায় কিছু সংখ্যক খনার বচন দেয়া আছে। কিন্তু তার সংখ্যা একদমই কম। একারণেই সহস্রারাধিক বচনের মধ্যে আমারা পাই বেশি হলেও দুইশত।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কে ছিল এই খনা? এটাও অধিকাংশ বাঙালি জানে। খনা সম্পর্কে বাংলা ও উড়িয়া এই দুই ভাষাতেই কিংবদন্তি রয়েছে। খনা যার প্রকৃত নাম লীলাবতী ছিল লংকা দ্বীপের রাজকুমারী। লংকা দ্বীপবাসী তথাকথিত রাক্ষসগণ একদিন সবংশে তার পিতা মাতাকে হত্যা করে এবং শিশু রাজকুমারী লীলাবতীকে হস্তগত করে। ঠিক একই সময়ে, উজ্জয়িনীর মহারাজ বিক্রমাদিত্যের নবরত্ন সভার অন্যতম জ্যোতির্বিদ পণ্ডিত বরাহ ভুল গণনাবশত জানতে পারলেন যে তাঁর পুত্র অকালে মারা যাবে। তাই তিনি শিশু সন্তানকে একটি বাক্সে ভরে নদীতে ভাসিয়ে দেন। বাক্সটি ভাসতে ভাসতে লংকা দ্বীপে পৌঁছালে দ্বীপবাসী শিশুটিকে উদ্ধার করে এবং লীলাবতীর সাথেই লালন-পালন করতে থাকে। দ্বীপবাসী শিশুটির নাম রাখে মিহির। উভয়েই দ্বীপবাসীদের নেতার আশ্রয়ে বড় হতে থাকে এবং শিক্ষা-দীক্ষা ও জ্যোতিষবিদ্যা আয়ত্ত করতে থাকে। এক সময় লীলাবতী ও মিহির জ্যোতিষশাস্ত্রে পারদর্শী হয়ে উঠল। লীলাবতী ও মিহির দুজন দুজনের প্রেমে পড়ে যায় এবং বিয়েও করে তারা। <br> তখন লীলাবতী ও মিহির দ্বীপবাসীদের বন্দিদশা থেকে পালাবার পথ খুঁজতে থাকে। একদিন গণনা করে নিরাপদ দিন দেখে সাগর পাড়ি দিয়ে তারা চলে আসে ভারতবর্ষে। লীলাবতী জানতে পেরেছিল মিহির ভারতবিখ্যাত জ্যোতির্বিদ বরাহের পুত্র। সুতরাং উভয়েই উজ্জয়িনী নগরে এসে নিজেদের পরিচয় দেয়। মিহিরের পিতা তাদের সানন্দে গ্রহন করেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এদিকে লীলাবতীর জ্যোতিষশাস্ত্রে অগাধ জ্ঞানের কথা চারিদিকে ছড়িয়ে পড়ে। মহারাজ বিক্রমাদিত্য লীলাবতীকে রাজসভায় প-িত হিসেবে আসন দান করেন। ফলে লীলাবতী অন্যান্য প-িতদের ঈর্ষার কারণ হতে থাকে। ঈর্ষান্বিত হতে থাকে বরাহ এবং মিহিরও। একদিন পিতা-পুত্র মিলে পরামর্শ করল লীলাবতীর জিহবা কেটে নেবার। পিতৃ আদেশে মিহির লীলাবতীর জিহবা কেটে নেয়। কিন্তু মাত্রাতিরিক্ত রক্ত ক্ষরণে লীলাবতী মারা যায়। জিহবা কেটে নেবার আগে লীলাবতী মিহিরকে অনুরোধ করেছিল কিছু কথা বলার সুযোগ দেবার। মিহির সে সুযোগ দিলে লীলাবতী তখন কৃষি, আবহাওয়া তত্ব, জ্যোতিষশাস্ত্রীয় তথ্য এবং মানবজীবনের বিভিন্ন কথা বলে যায়। যা পরবর্তীকালে বোবার বচন বা খনার বচন (খনা অর্থ হল বোবা) নামে পরিচিত। <br>\nএটাকে সাধারণভাবে নেবার সুযোগ নেই। বরং বলা চলে চিরকাল ধরে টিকে থাকা পুরুষতন্ত্রের নোংরা আঘাত যা একজন নারীর সমৃদ্ধি মেনে নিতে পারেনি। সমাজ চিরকাল নারীকে অধস্তন করতে চেয়েছে, খনার ক্ষেত্রেও তার ব্যতিক্রম ঘটেনি। নারীর গৌরব বা খ্যাতি যেন পুরুষের কাছে অসম্মানের হয়ে দাঁড়িয়েছে এবং পুরুষতন্ত্র দমিয়ে রাখতে চেয়েছে নারীকে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>খনার মত আরও একজনের নাম উঠে আসে, তার নাম হাইপোশিয়া। মিশরের এই নারী গণিতসহ নানা বিষয়ে এতটাই পারদর্শী ছিলেন যে আলেকজান্দ্রিয়া লাইব্রেরিতে তার বক্তৃতা শুনতে দূর-দূরান্ত থেকে মেধাবীরা ভীড় করতো। কিন্তু পুরুষতান্ত্রিক সমাজব্যবস্থা একজন নারীর এই সমৃদ্ধি সহ্য করতে পারেনি। তাকে নগ্ন করে কয়েক টুকরো করে হত্যা করা হয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বলে রাখি- নারীর প্রতি এরকম বৈষম্য আরোপ করতে আশ্রয় নেয়া হয় ধর্মের। ফলে দেখা যায় কোনো ধর্মই নারীকে যোগ্য সম্মান দিতে পারেনি। এক জায়গায় তাকে দেবি রূপে উপস্থাপন করা হয়েছে, অন্যখানে তাকে ভোগ্যপণ্য বানানো হয়েছে। এ প্রসঙ্গে উল্লেখ করা যায়- নারীকে দমিয়ে রাখতে একসময় নারীর সংবেদনশীল অঙ্গ ক্লাইটোরিস বা ভগাঙ্কুর কেটে দিয়ে নারীর খৎনা করানো হত। এবং পুরুষতন্ত্র দীর্ঘদিন এই বিভৎস প্রথা চালু রেখেছিল যাতে নারী যৌন ক্ষমতা অনুধাবন না করতে পারে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমরা গার্গীর কথা জানি। ব্রহ্মজ্ঞানে সে সবাইকে পরাজিত করলেও তাকে দেয়া হয় দ্বিতীয় স্থান। কারণ সে নারী, বিশ্বামিত্রের মতন বাঘা বাঘা তাত্ত্বিকেরা তার নীচে থাকা যে বেমানান। আসল ব্যাপারটা হল পুরুষতন্ত্র।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু খনার মত এখনও নারী আপন যোগ্যতায় উঠে আসছে এবং চ্যালেঞ্জ ছুঁড়ে দিচ্ছে পুরুষতন্ত্রের বিরুদ্ধে এটাই বড় কথা। ফলে ধর্মের শাসন আর পুরুষতন্ত্রের গ-ি ডিঙিয়ে নারী বাইরে বের হয়েছে। সাহিত্য থেকে শুরু করে বিজ্ঞান চর্চা কোনোটাতেই নারী পিছিয়ে নেই। তাছাড়া সভ্যতার শুরুতে নারীর হাত ধরেই চালু হয়েছিল পৃথিবীর কৃষি ব্যবস্থা যা আমরা ভুলে যাই। সেই প্রাচীন পৃথিবীতে নারী-পুরুষে কোনো বৈষম্য ছিল না। অথচ সভ্যতা যত এগিয়েছে নারীকে ততই আবদ্ধ করে রাখার প্রয়াস চালিয়েছে পুরুষতন্ত্র। পুঁজিবাদী ও ভোগবাদী সমাজের বিকাশে নারী হয়ে পড়েছে আরও অসহায়। কিন্তু মেরি ওলস্টানক্রাফট বা বেগম রোকেয়ার মত নারীরা প্রথা ভেঙ্গে এগিয়েছেন। ফলে নারী নানা ক্ষেত্রে নোবেল পুরস্কারও জিতছে, রাষ্ট্রও পরিচালনা করছে। এ যেন যুগে যুগে খনাদের বিজয়। পুরুষতন্ত্রের যূপকাষ্ঠে সেদিন খনার আত্মাহুতি নারীকে থামিয়ে দিতে পারেনি। সভ্যতার ক্রমবিকাশে নারী বার বার প্রমাণ করেছে নারী কেবল পুরুষের সেবাদাসী বা ভোগ্যপণ্য নয়, এমনকি কেবল গৃহে আবদ্ধ থেকে গৃহিনীর কাজ বা শিশুপালন করার জন্যও নয়, বরং সমাজের যেকোনো কিছুতে সে অবদান রাখতে সক্ষম।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তথ্যসূত্র: বাংলা পঞ্জিকা, খনার বিজ্ঞান-অরূপ রাহী।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © সুদেব চক্রবর্তী</p>\n<!-- /wp:paragraph -->', 'বাংলা সাহিত্যে বহু প্রবাদ-প্রবচন রয়েছে, যেগুলো শুধু শুধুমাত্র সাহিত্য নয় বরং দর্শন এমনকি বিজ্ঞানসম্মত বা বাস্তবসম্মতও বটে। এক সময় এগুলোর চর্চা ছিল। এখন এই চর্চাটা কমে গেলেও মানুষের ভেতর থেকে একেবারে হ...', '', 3, NULL, 'publish', 2787, 0, '2019-01-22 15:59:31', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (13, 2139, 17, 'প্রেমের দোলা', 'প্রেমের-দোলা', '<!-- wp:paragraph -->\n<p>মোর ভাবনার হৃদয়ে বাজে প্রেমেরও সুর,<br>তবুও বলো কেনো তুমি এতো দূর?<br>প্রেমেরও সুরে দোলে তোমার এলোকেশ, দুল,<br>নাচে পাখি, নাচে ফুল আরও নাচে শঙ্খমুকুল।<br>দোলে মন, দোলে ওগো তব হৃদয় মন্দিরে,<br>বিরহী সন্ধ্যায় পূর্ণিমার চাঁদ উঠে মনেরও মাঝারে।<br>ভালোবাসার স্নিগ্ধ পরশ লুটায়ে পড়ে চরণ তলে,<br>জ্যোৎস্নার আলো মাখাব ওগো তোমার অঙ্গে ঢেলে।<br>রংধনুর রঙ্গে স্বপ্ন &nbsp;রাঙ্গাব আমার ছোট্ট নীড়ে,<br>বাঁধব ঘর চাঁদের হাঁটে মিলিয়ে সুর তোমার তরে।<br>দোলে ওগো কেশ তোমার বসন্তের দখিনা বাতাসে,<br>হৃদয় যমুনায় তরঙ্গ খেলে দেখো হেসে হেসে।<br>তুমি মোর প্রেয়সী ওগো প্রাণের প্রিয়তমা,<br>তোমার জন্য আজও মনে সব ভালোবাসা জমা</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © বান্টি দেব</p>\n<!-- /wp:paragraph -->', 'মোর ভাবনার হৃদয়ে বাজে প্রেমেরও সুর,\nতবুও বলো কেনো তুমি এতো দূর?\nপ্রেমেরও সুরে দোলে তোমার এলোকেশ, দুল,\nনাচে পাখি, নাচে ফুল আরও নাচে শঙ্খমুকুল।\nদোলে মন, দোলে ওগো তব হৃদয় মন্দিরে,\nবিরহী সন্ধ্যায় পূর্ণ...', '', 11, NULL, 'publish', 2417, 0, '2019-01-23 13:32:11', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (14, 2144, 18, 'পাখিবিলাস', 'পাখিবিলাস', '<!-- wp:paragraph -->\n<p>জানালায় ঠক ঠক শব্দে ঘুম ভেঙে যায়। বিছানার সাথে সাক্ষাৎটা শেষ রাতেই হয়েছিল। তাই এই সাত-সকালে চোখ খুলতে একদমই ইচ্ছে হচ্ছিল না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গতকালকে যখন কুড়িগ্রাম থেকে ঢাকার উদ্দেশ্যে রওয়ানার প্রস্তুতি নিচ্ছি, তখন আকাশ উজ্জ্বল। মনটাও চনমনে আর ফুরফুরে ছিলো। প্রিয়তমার হাসিখুশি মুখের আড়ালের কষ্ট আর মায়ের গম্ভীর মুখের ছবি আমাকে দুই মেরুর ভাবনায় ডুব দিতে বাধ্য করলেও সময়টাকে বেশ উপভোগ করি। হালকা খাবার খেয়ে বিছানায় শরীর রাখতেই আকাশ ভেঙে বৃষ্টি শুরু হলো, সেই সাথে প্রচন্ড গর্জন ও শিলাবর্ষণ। বাড়িতে মিস্ত্রিরা ঘরের কাজ করছে। সাজুও ঢাকা যাওয়ার সঙ্গি আমার। ঘড়ির কাটা নয়টা পেড়িয়ে গেলো। অথচ প্রকৃতির কোনো পরিবর্তন নেই। বাস কাউন্টারে সাড়ে নয়টায় উপস্থিত হওয়ার কথা। ইতোমধ্যে কাউন্টার থেকে জানানো হয়, বাস ছাড়তে আরও আধাঘন্টা দেরি হবে। বাসবিলম্বের খবর পেয়ে একটু ভালোই লাগল। দরজা-জানালা বন্ধ করে বাড়ির সবাই একঘরে বসে আছি। শিলাবৃষ্টি ও বাতাসের তা-ব বৃদ্ধি পাচ্ছে। বড় ভাইয়ের তিন বছরের বাচ্চা ইমন আকাশের গর্জনে তার মায়ের বুকে লীন হয়ে আছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভয়ঙ্কর তা-ব চালিয়ে দশটার দিকে বাতাস ও শিলাবৃষ্টি থেমে গেলো। কিন্তু বৃষ্টি সমান তালেই চলছে। কাউন্টার থেকে ফোন আসে দ্রুত কাউন্টারে যেতে হবে, বাস ছাড়বে। আব্বু আমাদের রেডি হতে বলে ছাতা নিয়ে বাজারে চলে যায় রিক্সা আনতে। বাইরে শিলা দেখে হতবাগ হয়ে যাই, এমন শিলা আগে কখনো দেখিনি। যতদূর চোখ যায় সাদা আর সাদা। আশ্চর্য হয়ে তাকিয়ে থাকি। মাত্র কয়েক মিনিটের শিলাবৃষ্টিতে সমস্ত গ্রামটাকে অচেনা লাগছে। বৃষ্টি কমে গেলো, চারিদিক থেকে কান্নার শব্দ। বাহিরে বের হয়ে দেখি- শিলার আঘাতে গৃহস্থের হাঁস-মুরগি মারা গেছে, বাগানেও মরে পড়ে আছে বেশ কিছু পাখি। স্কুল মাঠে দুই-তিনটি ছাগল, একটি গরু শিলাবৃষ্টির আঘাতে ক্ষত-বিক্ষত হয়ে পড়ে আছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটি কুকুর হাঁপাচ্ছে। আমাকে সামনে যেতে দিচ্ছে না। বারবার তাগাদা দিচ্ছে সামনে না যেতে। তবুও এগিয়ে গিয়ে দেখি মালেকা বেগমের নিথর দেহ ব্যঙ্গ করছে আমার দিকে চেয়ে। চারিদিক থেকে একটা কান্নার ধ্বনি বাতাসে মিশে পরিবেশকে ভারি করে তুলছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সময়টা ফসলের না। কিন্তু রঙিন ও হলুদ আমগুলো শিলার উপর শুইয়ে আছে পরম মনবেদনায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এত কিছু ভাবার সময় কই? সাজু ও আমি এমন পরিস্থিতিতেও ভিজে বাস কাউন্টারে যাই। ছোট-বড় শিলাগুলো চাকার তলে পিষ্ট করে বাস সামনের দিকে এগুচ্ছে। আমাদের কাপড় পুরোই ভিজে শরীরের সাথে লেপ্টে আছে। সাজু কান্না করছে। বাসের বেশ কিছু সিট খালি পড়ে আছে- বাস জার্নি করা তো দূরের কথা অনেকেই পরিস্থিতিই সামলে উঠতে পারেনি। যারা এসেছে তাদের সকলের অবস্থাও বেশ শোচনীয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঢাকায় পৌঁছাতে রাত এগারোটা প্রায়। নব্বই ছুঁই ছুঁই ভাষাসৈনিক আমার ল্যান্ড লেডি আমার অপেক্ষা করতে করতে অবশেষে খাবার খেয়ে নিয়ে আমার অপেক্ষায় বসে আছেন। বাসা পৌঁছে ল্যান্ড লেডিকে সালাম দিয়ে কুশল বিনিময় করে পোশাক পরিবর্তন করেই সাজুকে ফোন দিলাম। কারণ পথিমধ্যে সাজু ওর বাসা উত্তরায় নেমে গেছে, আর আমি বনানীতে চলে আসলাম। <br>\nসাওয়ার শেষে ফোনে চার্জ দেবো এমন সময় ল্যান্ড লেডি কল। কল পেয়ে তার রুমে গিয়ে দেখি একটি চড়–ই পাখি উড়াউড়ি করছে। জানালা, দরজা খুলে দিলেও বের হতে পারছে না। সমস্ত ঘরময় সে উড়াউড়ি করছে। রুম থেকে পাখিটাকে বের করে দেওয়ার চেষ্টা করেও ব্যর্থ হয়ে অবশেষে ল্যান্ড লেডিকে গুড নাইট জানিয়ে নিজের বিছানায় এসে শুইয়ে পড়লাম।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঠক ঠক শব্দে যখন ঘুম ভাঙল তখন পৃথিবী উজ্জ্বল। চোখ খুলে দেখি, জানালায় একটি কাক ঠোঁট দিয়ে শব্দ করছে। আরেকটি কাক তাকে উৎসাহ দিচ্ছে। আমি ঘুমের ভান করে শুইয়ে থাকি। কাকটি আমাকে জাগাতে না পেরে নারিকেল গাছের ছায়ায় গিয়ে বসে। মনে হচ্ছে- তখন সঙ্গে কাকটি আবারও তাকে বুঝিয়ে পাঠায়। এভাবে প্রায় পাঁচ মিনিট চেষ্টা করেও উপায় না পেয়ে দু’জনেই আমার জানালায় এসে বসে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমি বিছানা থেকে উঠে ছাদে ভাত ও চাউল ছিটিয়ে দেই। মনের আনন্দে খেয়ে চলে যায়। একটু পর পর বিভিন্ন পাখি খাবার খেতে আসে। গতকালকের কথা ভুলে যাই সব। মানুষ হয়ত এমনি, নিজে নিরাপদে থাকলে অতীত বেমালুম ভুলে যায়। তবে ভুলতে পারে না স্থায়ীভাবে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গতবছর যখন বাড়ির ছাদে এই রুমটি করে থাকার ব্যবস্থা হয়। তখন থেকেই অক্লান্ত পরিশ্রম করে ছাদের একাংশে বিভিন্ন রকম ফল ও ফুলের গাছ লাগিয়ে বাগান করেন ল্যান্ড লেডি। তাকে সব ধরণের সহযোগিতা করি। ঢাকা শহরের অধিকাংশ নার্সারি থেকে গাছ সংগ্রহ করে আনতাম। বিদেশ থেকেও গাছ আনা হতো। তুলসি, পুদিনা, কারীসহ বিভিন্ন ঔষধি গাছের সমাহার রয়েছে বাগানে। গাছ লাগানোর প্রাথমিক কাজ শেষ করেই আমরা মনোযোগ দেই পাখিদের অভয়ারণ্য সৃষ্টিতে। প্রতিদিন সকালে এবং বিকালে পাখিদের জন্য নানা ধরণের খাবার ছিটিয়ে দেই। কিন্তু পাখি আসে না। সারাদিন ছাদে চোখ রাখি কখন একটা পাখি আসবে আর খাবার খাবে। এভাবে প্রায় দশ বারো দিন পর দেখা গেলো দুইটি চড়–ই পাখি। কিছুক্ষণ পরে ছয়-সাতটি। পরেরদিন সকালে ঘুম থেকে জেগেই দেখি একঝাঁক চড়–ই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ল্যান্ড লেডি ও আমি লুকিয়ে লুকিয়ে পাখিদের খাবার খাওয়া দেখি। খুশিতে আত্মহারা হই। এমন খুশি মনে হয় কখনো হইনি। গাছের যত্ম ও নতুন একটি ফুল এলেও যেনো খুশিতে নাচতে ইচ্ছে করে। শিশুসুলভ আচরণে একজন আরেকজনকে ডেকে দেখাতাম। ধীরে ধীরে প্রায় অনেক জাতের পাখির আনাগোনা ছাদের উপর এখন। সকালে খাবার দিতে দেরী হলেই শুরু হয় পাখিদের চিৎকার। প্রায় প্রতিদিন সকালেই পাখিদের চিৎকারে ঘুম ভেঙে যায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সকাল সকাল ঘুম ভেঙে গেলো তাই ফজরের নামাজ পড়ে গাছের যত্ন নিয়ে পাখিদের খাবার দেই। দেখতে দেখতে সকাল কেটে গেলো। কিন্তু কোনো পাখির শব্দ নেই ছাদে। বারবার রুমে যাই আর ছাদে আসি। কোনো পাখির দেখা মেলে না। কাজে বাইরে বের হই, সারাদিন ব্যস্ত থাকি। মন পড়ে থাকে ছাদের উপর। ভাবতে থাকি নিশ্চয়ই পাখিগুলো এসে খাবার খাচ্ছে। কিন্তু কাজের ব্যস্ততায় দেখতে পাচ্ছি না। মনটা বিষন্ন হয়ে যায়। বাসা ফিরতে ফিরতে রাত হয়ে যায়। ক্লান্ত শরীর নিয়ে রাতের খাবার খেয়ে ঘুমিয়ে পড়ি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সকালে ঘুম ভাঙে না। কাক দুটোও জানালায় শব্দ করে না। বিছানায় পড়ে থাকি। সকাল নয়টা বাজে তবুও বিছানা ছাড়তে মন চায় না। বাইরে বের হয়ে দেখি গতকালের সব খাবার এখনও পড়ে আছে। আরো খাবার ছিটিয়ে দেই। চেয়ার নিয়ে বসে থাকি পাখিদের অপেক্ষায়। অপেক্ষার পালা শেষ করে একসময় কাজে বেরিয়ে যাই। কোথাও মন বসে না। কাজে ভুল হয়। ফোনে প্রিয়তমার সাথে সাধারণ কথায়ও বিরক্ত হই। মায়ের সাথেও কথা কম বলি পাছে খারাপ ব্যবহার করে ফেলি এই ভয়ে। এভাবেই বেশ কয়েকদিন কেটে যায়। <br>\nসকাল সকাল ঘুম থেকে উঠে ল্যান্ড লেডির দেখভাল করার মেয়েকে বলি- <br>\nকয়েকদিন ধরে কাক ও কোনো পাখিকেই দেখি না। কারণ কি হতে পারে বলতে পারো? <br>\nসে উত্তর দেয়- <br>\nসেদিন রাতে আপনি অনেক কাজ করে ঘুমালে? <br>\nহ্যাঁ। <br>\nআমি সকালে ঘুম থেকে উঠে দেখি, কাক আপনার জানালায় ঠোঁট দিয়ে শব্দ করছে। আবার কা কা করে বাড়ি মাথায় তুলছে। তাই আমি লাঠি নিয়ে তাড়িয়ে দিয়েছি। জানেন, কতো কষ্ট করে ফুলের বিজ লাগিয়েছি। পাখিগুলো সব গাছ ঠোঁট দিয়ে উপড়ে ফেলছে। কিছু কিছু অবশ্য খেয়েছেও। কার গায়ে জ্বর না আসে বলেন?<br>\nআমি স্থির হয়ে বোবার মতো সব শুনতে থাকি। ল্যান্ড লেডির এই আয়য়া যে আমাকে অনেক স্নেহ করে সেটা জানি। কার উপর রাগ করবো? এই অল্পশিক্ষিত আয়য়াই তো আমার অসুস্থতার সময়ে সেবা করেছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিছু না বলে, বাসা থেকে বের হলাম। বনানী বাজারে বিদ্যুৎ লাইনের তারে অসংখ্য কাক জমা হয়ে কা কা ধ্বনিতে বাতাসকে মাতাল করে দিচ্ছে। এক এক করে সবগুলোর দিকে তাকিয়ে থাকি। সবগুলো কাক যেনো নিজের কাজে ব্যস্ত। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রাস্তায় বের হলেই কাক দেখতে পাই অসংখ্য। সব কাকের ভীড়ে আমি সেই দু’টো কাককে খুঁজতে থাকি। কাক দুটো যেনো আমার সন্তান। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কয়েকদিনের মধ্যে অন্য পাখিরা ধীরে ধীরে ফিরতে শুরু করলো। কিন্তু সকালের ঘুম ভাঙাতে আর…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © এনাম রাজু</p>\n<!-- /wp:paragraph -->', 'জানালায় ঠক ঠক শব্দে ঘুম ভেঙে যায়। বিছানার সাথে সাক্ষাৎটা শেষ রাতেই হয়েছিল। তাই এই সাত-সকালে চোখ খুলতে একদমই ইচ্ছে হচ্ছিল না।\nগতকালকে যখন কুড়িগ্রাম থেকে ঢাকার উদ্দেশ্যে রওয়ানার প্রস্তুতি নিচ্ছি, তখন আক...', '', 9, NULL, 'publish', 2024, 0, '2019-01-23 15:41:20', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (15, 2170, 19, 'শব্দের যঠর ভাঙে', 'শব্দের-যঠর-ভাঙে', '<!-- wp:paragraph -->\n<p>তুমি যখন বলো, কবিতা লিখবে-<br>কোথাও যেন হাসনাহেনা ফোটে<br>ঠুমরীর আবেশী সুরে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তুমি যখন বলো, কবিতা লিখবে-<br>একটা তর্জনী কী মোলায়েম আদরে <br>পিঠের ঠিক মাঝখানে <br>বয়ে যাওয়া এক নদীর আহ্বান করে। <br>ধুসর চাদর ছুঁড়ে ফেলেে<br>আকাশ নিজেকে সাজায়। <br>বুড়িগঙ্গার কালি মাখা জল<br>ধবল শশ্রুষাকে কাছে ডাকে। <br>যদি তুমি বল কবিতা লিখবে, <br>বাউণ্ডুলে হবে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © সাবিনা পারভীন লিনা</p>\n<!-- /wp:paragraph -->', 'তুমি যখন বলো, কবিতা লিখবে-\nকোথাও যেন হাসনাহেনা ফোটে\nঠুমরীর আবেশী সুরে।\nতুমি যখন বলো, কবিতা লিখবে-\nএকটা তর্জনী কী মোলায়েম আদরে\nপিঠের ঠিক মাঝখানে\nবয়ে যাওয়া এক নদীর আহ্বান করে।\nধুসর চাদর ছুঁড়ে ফেলেে\nআকাশ...', '', 4, NULL, 'publish', 2814, 0, '2019-01-24 17:22:05', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (16, 2180, 20, 'ভালোবাসার আনন্দ', 'ভালোবাসার-আনন্দ', '<!-- wp:paragraph -->\n<p>তোমাকে ভালোবাসতে পারাই আমার আনন্দ;<br> পৃথিবী থেকে চাঁদ অবধি<br> তোমাকে নিয়ে কল্পনার রাজ্য আমার।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এক মুহূর্তের কল্পনাও আমার তোমাকে নিয়ে<br> আমাকে ভাসিয়ে নিয়ে যায় হিমালয় চূড়ায়—সুনামি হয়ে<br> সিডরের মতো লন্ডভন্ড করে আমার হৃদয় বন।<br> হাজার বছরের চাপা পড়া রাজস্মৃতির মতো জেগে ওঠে ভালোবাসা<br> প্রাকৃতিক প্রলয় ভেদ করে হয়ে ওঠে প্রতœ সম্পদ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্মৃতির জাদুঘরে সাজিয়ে রাখা প্রেম<br> হঠাৎ ঘূরপাক খেতে খেতে ধেয়ে আসে আমার দিকে<br> দুহাতে কবিতা বেরিয়ে আসে দুই সহস্র একসাথে;<br> কবি- শিল্পি- গায়ক হই তোমাকে ভালবেসে<br> কখোনো কবিতা, কখোনবা চিত্রকর্ম হয়ে উঠি…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © ইয়াছিন আযীয</p>\n<!-- /wp:paragraph -->', 'তোমাকে ভালোবাসতে পারাই আমার আনন্দ;\nপৃথিবী থেকে চাঁদ অবধি\nতোমাকে নিয়ে কল্পনার রাজ্য আমার।\nএক মুহূর্তের কল্পনাও আমার তোমাকে নিয়ে\nআমাকে ভাসিয়ে নিয়ে যায় হিমালয় চূড়ায়—সুনামি হয়ে\nসিডরের মতো লন্ডভন্ড করে আমা...', '', 4, NULL, 'publish', 2759, 0, '2019-01-26 12:20:56', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (17, 2187, 21, 'শৈশবের বিজয় দিবস', 'শৈশবের-বিজয়-দিবস', '<!-- wp:paragraph -->\n<p>সকালটা কেমন জানি আজ অদ্ভূত লাগছে। মনে হচ্ছে সব কেমন শান্ত,  স্বাধীন। আরে! আজ তো বিজয় দিবস। তার জন্যই বোধহয় প্রকৃতিও নিজের স্বাধীনতার  বর্হিপ্রকাশ করছে। চারদিক থেকে&nbsp; যেন জানান দিচ্ছে আজ বিজয় দিবস। আমার এখনও  বেশ ভালোভাবেই মনে আছে ক্লাস ওয়ানের কথা। বিজয় দিবস কী তা আমার প্রথম  বুঝতে পারা! ১৫ই ডিসেম্বর স্কুল থেকে বলা হয়েছিল ১৬ ই ডিসেম্বর স্কুলে  যাওয়ার জন্য। আমি সকাল সকাল ঘুৃম থেকে উঠে পড়ি। তখন বাবাকে দেখি কতগুলো ছোট  ছোট পতাকা বারান্দায় লাগাচ্ছিল। আমি বাবাকে বেশ কৌতূহল নিয়ে জিজ্ঞেস করি,<br> -বাবা, এগুলো কেন লাগাচ্ছ?<br> -আজ বিজয় দিবস, তা তো তুমি জানো।<br> -হ্যাঁ, বাবা।<br> -অনেক কষ্টের বিনিময়ে এ দেশের স্বাধীনতা অর্জিত হয়েছে। তার জন্যই পুরো  বাংলাদেশের মানুষ এ দিনটিকে জাঁকজমকের সাথে পালন করে। সেজন্য আমিও বিজয়  দিবসকে যতটুকু পারি নিজেরমত করে পালন করি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাবার কথা শোনার পর চলে গেলাম গোসল করতে। গোসল করে নতুন জামা  পড়ে স্কুলের দিকে রওনা হলাম। স্কুলের গেইটে প্রবেশের সাথে সাথে মনটা কেন যেন  আনন্দে ভরে উঠল। স্কুলের পুরো দেয়াল, মাঠ সব খানেই ছোট ছোট লাল-সবুজের  পতাকার সাজ। এর মধ্যেই র‌্যালি, কুচকাওয়াজ, সাংস্কৃতিক অনুষ্ঠান, রচনা  প্রতিযোগিতা, ছবি আঁকার প্রতিযোগিতা শুরু হয়ে গেল। অনুষ্ঠান শেষে বাড়ি ফিরে  এলাম। বাসায় এসে দাদিকে স্কুলের গল্প শুনাতাম। এভাবেই কেটে গেল ছোটবেলার বিজয়  দিবস। কখনও কখনও সারারাত ধরে কাগজের পতাকা দিয়ে ছাদে স্মৃতিসৌধ  বানাতাম, দুপুরে চড়ুইভাতি খেলতাম আর সন্ধ্যা হলেই বাবার হাত ধরে বিজয় মেলায়  যেতাম। এমনিভাবে কেটে গেল প্রাইমারি স্কুলের বিজয় দিবস।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যখন হাই স্কুলে উঠলাম তখন বিজয় দিবসে ডিসপ্লেতে এটেন্ড  করতাম। তাই কয়েকদিন আগে থেকেই ডিসপ্লের জন্য রিহার্সাল শুরু হতো। নিজেদের  মধ্যে একটা কম্পিটিশন হতো। কারণ যারা ভালো করত তারাই সামনে থাকত। আর  আগেরদিন রাতে খুব চিন্তায় থাকতাম। কত মানুষের সামনেই না করতে হবে! তাই রাতে  স্কুল ড্রেসটা বারবার দেখতাম, কোনো দাগ আছে কিনা? কোথাও কুঁচকে আছে কিনা? ভোর  বেলা স্কুলে যাওয়া, সেখান থেকে স্টেডিয়াম। তখনই বিজয়ের আনন্দটা বুঝা যেত। এখন  তো বড় হয়ে গেছি। শৈশবের মতো করে বিজয় দিবস পালন করা হয় না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © চৈতি দাস অদিতি</p>\n<!-- /wp:paragraph -->', 'সকালটা কেমন জানি আজ অদ্ভূত লাগছে। মনে হচ্ছে সব কেমন শান্ত, স্বাধীন। আরে! আজ তো বিজয় দিবস। তার জন্যই বোধহয় প্রকৃতিও নিজের স্বাধীনতার বর্হিপ্রকাশ করছে। চারদিক থেকে যেন জানান দিচ্ছে আজ বিজয় দিবস। আমার...', '', 8, NULL, 'publish', 2898, 0, '2019-01-26 13:49:41', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (18, 2258, 22, 'ইতিহাস থেকে লেখা', 'ইতিহাস-থেকে-লেখা-2', '<!-- wp:paragraph -->\n<p>ইতিহাস হবে রক্ত খচিত<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; টোলবে না বাহুবল,<br> পৃথিবীর বুকে শিরনোয়াবে না<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; বহ্নি হবে ধরাতল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> ভয়কে জয় করে যারা<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; গেঁথেছে বিজয় মালা,<br> সত্যকে যদি ভুলণ্ঠিত করতে চাই<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; জ্বালা আগুন জ্বালা</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কবিতা হবে বিদ্রোহের বাণী<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; গদ্য হবে মুক্তির পথ,<br> উপন্যাস হবে শান্তির গান<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; গল্প হবে শাণিত শপথ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> জীর্ণ কুটিরে&nbsp; করিয়া বসবাস<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; দেখেছি যুদ্ধের রূপ,<br> নারী সেদিন তুলেছে গর্জন<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; থাকেনি তারা চুপ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> সবুজের বুকে রক্ত নিশান<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; উড়িয়েছিল কারা?<br> পূর্ণ বুকখানা করেছে খালি<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;মা&nbsp;হয়েছে&nbsp; সর্বহারা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> মলিন মায়ের বদন খানি<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; আজকে হয়েছে জড়,<br> খোকা যদি থাকতো বেঁচে<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; কত যে হত বড়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> আঁধারকে করেছে ভ্রুকুটি অন্ধকার<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; হিংস্র হায়েনার দল,<br> ২৫ শে মার্চের কালোরাত্রিতে<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ঝরিয়েছে রক্ত ঢল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> যতদিন রবে বঙ্গ নামটি<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ইতিহাসের পাতায় লেখা,<br> ততদিন জ্বলবে শুন্য গৃহে<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; লেলিহান অগ্নি শিখা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> পৃথিবীর মানচিত্রে ছোট্ট তুমি<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ইতিহাস লেখা হবে না শেষ,<br> তোমাকে জানাই হাজার সেলিউট<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; বিশ্বের বিস্ময়&nbsp; বাংলাদেশ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © রাকিবুল ইসলাম</p>\n<!-- /wp:paragraph -->', 'ইতিহাস হবে রক্ত খচিত\nটোলবে না বাহুবল,\nপৃথিবীর বুকে শিরনোয়াবে না\nবহ্নি হবে ধরাতল।\nভয়কে জয় করে যারা\nগেঁথেছে বিজয় মালা,\nসত্যকে যদি ভুলণ্ঠিত করতে চাই\nজ্বালা আগুন জ্বালা\nকবিতা হবে বিদ্রোহের বাণী\nগদ্য হ...', '', 4, NULL, 'publish', 2749, 0, '2019-01-29 10:15:48', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (19, 2263, 68, 'অধিবাস্তববাদঃ নাট্যসাহিত্য এবং চিত্রশিল্পেঃ রূপক এবং সংকেতের প্রয়োগ', 'অধিবাস্তববাদঃ-নাট্যসাহি', '<!-- wp:paragraph -->\n<p>ধারণামন্ডিত নাট্যগঠনরীতির মৌলিক উৎসমুখ চিরন্তন উপলব্ধিজাত অনুসন্ধিৎসার অনিশ্চিত, অস্থির, অনির্দিষ্ট এবং অলৌকিক একটা কিছু প্রাপ্তির অনির্বচনীয় সুখবোধে আক্রান্ত অতি সূক্ষ্ম অথচ সংহত একটি চরম উত্তেজিত আকাঙ্ক্ষার দূর্লভ সফলতার লক্ষণ বলে এক শ্রেণির নাট্যকার এবং চিত্রশিল্পীরা মনে করে থাকেন। তারা এ ধারণাটিকে সকলের কাছে বিশ্বাস-সিদ্ধ করাতে চান যে, ওই উৎসমুখে সৃষ্ট লক্ষণটি নিরন্তর বিচিত্র ভঙ্গিতে ঋজুতায় এবং দৃঢ়তায় স্বাভাবিকের চাইতে অনেক বেশি উন্নত- এবং যেটিকে বিংশ শতাব্দীর গোড়া থেকে ওই শ্রেণির ব্যক্তিবর্গ অসঙ্কোচে ‘অধিবাস্তববাদ’- বলে প্রতিষ্ঠা করবার চেষ্টা করতে থাকেন। &nbsp;এবং এই মতবাদটিকে প্রতিষ্ঠার জন্যে সাহিত্যের পরিমন্ডলে আন্দোলনও গড়ে তুলবার উদ্যোগ গ্রহণ করে চলেন। &nbsp;আর সে কারণে আন্দোলনকারীদের মধ্যে এক ধরণের ‘অহংবোধ’- এর মতো একটি নিশ্চিত স্বপ্ন-বিলাসী অবিমিশ্র সুখবোধেরও উৎপত্তি ঘটতে থাকে। &nbsp;এ কারণে যে, আন্দোলনকারীরা সাহিত্যের পুরোনো জরায়ুতে ‘অধিবাস্তববাদ’-নামীয় একটি নতুন ভ্রুণের সৃষ্টি করতে যাচ্ছেন-বিশেষতঃ নবতর নাট্যরীতি এবং চিত্ররীতি গঠনের ক্ষেত্রে। &nbsp;কিন্তু একই সঙ্গে তারা যে তাদের সম্ভাব্য সৃষ্টির বিপরীতে একটি প্রশ্ন উদ্রেককারী চিহ্নেরও অনিবার্য উত্থানকে সম্ভব করে তুলছেন- সে দিকটিকে তারা তাদের গ্রাহ্যতায় আনয়নের মোটেও প্রয়োজনবোধ করেন না। তাদের বিচক্ষণ মেরুকরণের সহজাত প্রবণতাই শুধু তাদের নতুন নির্মিতির অহংবোধ থেকে সহস্র সুবর্ণরেখায় বর্ণিল হয়ে একটি কেন্দ্রীভূত অনধিগত অথচ উচ্চাভিলাষী ভ্রান্ত এবং মেকী বুদ্ধিবৃত্তিক পরিপূর্ণতার (ইনডাকটিভ ইনটেলেকচুয়াল প্লেন্টিচ্যুড)- দিকে অগ্রসরমান থেকেছে- যেখানটিতে তারা তাদের ‘অহংবোধ’-এর মূল শেকড়টি প্রোথিত করেছেন। এবং যথার্থভাবেই এ অগ্রসরমান পদসঞ্চারের অহংকারী চলাচল বর্তমান অধিবাস্তববাদী নাটকের বিষয়বস্তুতে বাস্তবতাহীনতা এবং আঙ্গিকগত নির্মাণের মূল টেকনিক এবং এর সর্বশেষ উত্তরায়ন- কিন্তু যা কখনই সর্বজন গ্রাহ্যতার কাছাকাছি এসে পৌঁছুতে পারেনি। যেহেতু বাস্তবতা বহির্ভূত ‘অধিবাস্তববাদ’ কখনই স্বয়ংসম্পূর্ণ নয়। বরং এক ধরণের আরোপণ। আর সে অর্থে বাস্তবতার শরীরকে ‘অধিবাস্তববাদ’ নামের একটি বিশেষ আবরণে আবৃত করে নবতর তরঙ্গ সৃষ্টির প্রয়াস সর্বার্থেই ব্যর্থতায় নিমজ্জিত। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কালোত্তরণের কালানুক্রমিক ধারায়\nবিবর্তমান বিশ্বসাহিত্যে নাটকের যে অপ্রতিহত প্রবলতম বেগবান গতিপ্রবাহ সর্বশেষ স্তরে\nতা ঐ অধিবাস্তববাদী (এ্যাবসার্ডিজম) চিত্তচৈতণ্যভুক্ত অথবা চিত্তচৈতণ্যজাত অসার বুদ্ধিগত\nক্ষেত্রজ উপাদান-সমৃদ্ধ প্রাচুর্যের (ইনডাকটিভ ইনটেলেকচুয়াল প্লেনটিচ্যুড)- Tremendous\nRevelation-কেই বোধের নিগূঢ় অভ্যন্তরে সংস্থাপিত করবার চেষ্টা করে অব্যাহত এবং অনিবার্যভাবে।\nঅথচ এটিকেই তারা গ্রহণ করেছেন তাদের চিন্তাশীলতার অগ্রগামী উৎসের মৌলিকত্ব হিসেবে।\nএই মৌলিকত্বকে ভিত্তি করে যেখানে বেট্রল্ট ব্রেখটের সুররিয়ালিষ্টিক সচেতনতার বিশ্লেষণাত্মক\nক্ষিপ্রতাবোধ ইউজিন ইয়োনেস্কো’র ইথিক্যাল ইনানসিয়েশনের অন্তর্লোকে একটা বিশিষ্ট প্রভাব\nসম্পাতি সত্ত্বার মতো অতি সূক্ষ্ম ভূমিকা পালনে সক্ষম থেকেই আরো বীর্যবান একটি পৃথক\nসম্রাজ্য সৃষ্টি সম্ভবের ইঙ্গিতকে সমৃদ্ধ করে তোলে যদিও- কিন্তু সেখানে বোধের গভীরতম\nতীব্রতাই প্রথম শর্তে অন্বিষ্ট- যা সাধারণভাবে অবশ্যই ইনফিজিব্ল এবং ইনভিজিব্ল- বাস্তবতার\nনিরিখে যা কোনোভাবেই গ্রহনযোগ্যতার অবকাশ রাখে না। যেহেতু এ তীব্র বোধের ‘পারপাস ওরিয়েন্টেড’-\nকার্যক্রমের বিস্তৃতি এবং নিবিড় আবেদনের প্রসারমানতা অত্যন্ত সাধারণভাবে দৃষ্টিগ্রাহ্য\nতো নয়ই বরং দূর্লক্ষ্য। পরিমাণগতভাবে সাধারণ মানুষের কতটা প্রত্যক্ষ-প্রত্যাশা পূরণে\nসক্ষম সে প্রশ্নটিই এখানে প্রত্যয়সিদ্ধ। আর এ প্রশ্নটিও সঙ্গত কারণ এবং স্বভাবতঃই মূলগতভাবে\nপ্রসঙ্গ বিচ্ছিন্ন নয় অথবা প্রসঙ্গ থেকে দূর-স্থিতিরও কোন প্রমাণ অথবা চিহ্ন বহন করে\nনা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অধিবাস্তববাদ অর্থাৎ ‘অত্যধিক\nবাস্তবতা’। ইংরেজিতে যাকে বলা হয় ‘Sur-realism’- আভিধানিক ভাষায় সোজা বাংলায় যার অর্থ\nদাঁড়ায় ‘মগ্ন চৈতন্যের রূপায়ণ’, ‘স্বপ্নের মতো বানানো খাপছাড়া বস্তুর একত্র সমাবেশ’-ইত্যাদি।\n‘অধিবাস্তববাদ’-থিওরীর এই হলো মৌলিক নির্যাস। &nbsp;নাটক ব্যতীত আর একটি বিশেষ শিল্পের ক্ষেত্রে এই নির্যাসের\nপ্রাবল্য অতিমাত্রিক। &nbsp;শিল্পটি হলো ‘চিত্রকলা।’\n&nbsp;চিত্রশিল্পীরা এই থিওরীটির মৌলিক নির্যাস টুকুকে\nযথেষ্ট প্রাচুর্যপূর্ণ আগ্রহের সাথে নিজেদের একচ্ছত্র স্বাধীন চিন্তা প্রবাহে স্থাপন\nকরে তাদের সৃজিত চিত্রকর্মে এমনভাবে প্রয়োগ করেন- যাতে শিল্পী চিত্রটির মাধ্যমে যে\nবার্তাটি সাধারণ মানুষের কাছে পৌঁছে দিতে চান- সে লক্ষ্যটিই অন্তিমে ব্যর্থ হয়ে যায়।\nঅর্থাৎ প্রকারান্তরে সাধারণ মানুষের কাছে ওই চিত্রকর্মটি হয়ে ওঠে চূড়ান্তভাবে অস্পষ্ট\nএবং দুর্বোধ্য। কোনো আবেদনই সৃষ্টি করতে পারে না সাধারণ মানুষের মননে। এই শ্রেণিভুক্ত\nচিত্রকরবৃন্দ তাদের চিন্তার পলিতে এ ধরনের একটি ধারণার বীজকে হয়তো রোপন করতে চান যে,\nSur-realism’- এর অর্থই হলো ‘Neo-Modernism’. অর্থাৎ ‘মাত্রাধিক আধুনিকতা’। এবং তাদের সৃষ্টিতে\nএই অত্যাধুনিকতা প্রতিষ্ঠা করে তারা আত্মভাবনার মগ্নতায় নিমজ্জিত থেকে একটি ভিন্ন ধরণের\nসুখবোধে আপ্লুত হতে চান এই ভেবে যে,- এই অত্যাধুনিক ধরণের চিত্রকর্মগুলিই তাদের এক\nএকজনকে এক একটি ‘মাইলষ্টোন’-এ রূপান্তরিত করে প্রজন্মের পর প্রজন্ম ধরে মানুষের অন্তরের\nমাঝে বাঁচিয়ে রাখবে অনন্তকাল ব্যাপী। কিন্তু এই অত্যাধুনিক চিত্রকর্ম সৃষ্টি করতে গিয়ে\nতারা এমন কিছু সৃষ্টি করেন- যা তাদের সৃজন শক্তিকেই প্রশ্নবিদ্ধ করে তোলে এবং তাদের\nশিল্পী সত্ত্বা সাধারণের দৃষ্টিতে অস্বচ্ছ আরশির ওপর পতিত অতীব অস্পষ্ট ছায়ার আকৃতি\nনিয়ে তাদের চেতনার গভীরতম প্রদেশে একটি স্থিরীকৃত নেতিবাচক আসনের সৃষ্টিকে অনিবার্য\nকরে তোলে। যা একজন শিল্পীকে নিশ্চিত করেই সাধারণের সান্নিধ্য থেকে অনায়াসে কেড়ে নিয়ে\nঅতিদূর কোনো ভিন্নলোকে স্থাপন করে। সাধারণের মানসলোক এবং শিল্পী মননের মাঝখানে সৃষ্টি\nকরে এক বিশাল ব্যবধানের- যা কোনোভাবেই একজন প্রকৃত শিল্পীর কাক্সক্ষনীয় হতে পারে না।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যে কোনো মহৎ সৃষ্টির মর্মমূলেই\nতো মানব কল্যাণের অঙ্কুরটির পল্লবায়িত হয়ে উঠবার কথা। মানব কল্যাণ সাধিত হলে বিশাল\nপ্রকৃতির মঙ্গল সাধনও সম্ভব হয়ে ওঠে- এটিই তো স্বতঃসিদ্ধ। কিন্তু স্রােষ্টার কল্পনা\nপ্র¯্রবনের মর্মমূলে যদি সে অঙ্কুরটির পল্লবায়ন না হয় তাহলে তার সৃষ্ট যে কোনো সৃষ্টি\nমানবকূলের কোনো মঙ্গলই বয়ে আনবে না। এবং তার কালের সীমানা পেরিয়ে পরবর্তী কালে প্রবেশের\nদরোজাটিও তার জন্যে রুদ্ধ হয়ে যাবে। কালোত্তীর্ণ হবার সুযোগ সে কখনই পাবে না। আর স্রষ্টা\nযদি তার সৃষ্টির মাধ্যমে কালকে অতিক্রম করতে ব্যর্থ হন তাহলে তার নিজের অস্তিত্বও কোনো\nকালেই বর্তমান থাকবে না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এই প্রেক্ষিতকে সামনে রেখে একটি\nছোট্ট উদাহারণ দেয়া যেতে পারে। ধরে নেয়া যাক, একজন চিত্রকর এমন একটি ছবি আঁকলেন যে\nছবিটিতে লক্ষিত হলো- চিত্রপটের ওপরের দিকের দু’কোণে একটি পূর্ণাঙ্গ চাকার খন্ডিত দু’টি\nঅংশ এবং ওই চিত্রপটের নীচের দিকে আর একটি খন্ডিত অংশ -যা বিক্ষত। অর্থাৎ পুরো চাকাটিই\nভগ্ন। ভগ্ন চাকাটির ওই খন্ডিত অংশটির পাশেই একটি পা বিহীন একজন শ্রমিকের ছায়া- যার\nএক হাতে একটি হাতুড়ি আর অন্য হাতে খুঁচরো কিছু যন্ত্রপাতি- যা দিয়ে শ্রমিকটি ওই খন্ডিত\nঅংশটির ভেঙ্গে যাওয়া অংশটিকে সারিয়ে তুলবার চেষ্টা করছে। এখানে চিত্রটিতে শিল্পী বিভিন্ন\nরং এর Combination- এর মাধ্যমে তার তুলির নিখুঁত আঁচর টেনে চাকাটির খন্ডিত অংশ গুলির মধ্যে সংযাগ\nস্থাপন করে বোঝাবার চেষ্টা করেছেন এটি একটি পূর্ণাঙ্গ চাকা। মেরামত শেষে চাকাটির খন্ডিত\nঅংশগুলিকে একত্রিত করা হলে চাকাটি সচল হয়ে উঠবে। বিষয়বস্তু হিসেবে চাকাটিকে তিনি নির্বাচিত\nকরেছেন সম্ভবতঃ এ কারণে যে, একটি সচল ঘূর্ণায়মান চাকা নিশ্চিত গতিময়তার প্রতীক। জীবন\nচক্রের ঘূর্ণায়মানতা থেমে গেলে জীবন স্থবির হয়ে পড়ে। আর জীবন স্থির হয়ে গেলে প্রকৃতিও\nতার মাধুর্য হারিয়ে ফেলে এবং প্রকৃতির অপরিমেয় রূপ, রস, গন্ধেরও আর কোনো মূল্য থাকে\nনা। কেননা মূল্যায়নের বস্তুটিই যে মূল্যায়নের আগেই নিঃসার হয়ে পড়েছে। জীবনরোহিত প্রকৃতির\nমূল্যও তখন আপনা আপনিই তিরোহিত হয়ে যায়।&nbsp;&nbsp;&nbsp;\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখন এই চিত্রটি যখন একজন সাধারণ\nদর্শক প্রত্যক্ষ করবেন তখন তিনি কি চাকাটির বিচ্ছিন্ন খন্ডিত অংশ গুলিকে সংযুক্ত করে\nএকটি পূর্ণাঙ্গ সচল চাকার আকৃতিকে তার মানসলোকে প্রতিষ্ঠা করতে পারবেন? তিনি কি শিল্পীর\nকল্পনাগামীতার স্রােতঃস্বিনী নদীতে অবগাহন করতে সক্ষম হবেন? উত্তরটি অবশ্যই হবে নেতিবাচক।\nকেননা সাধারণ দর্শকটি বুঝতেই পারবেন না যে শিল্পী চিত্রটিতে কী বোঝাতে চেয়েছেন অথবা\nচিত্রটির মাধ্যমে তিনি কি কথা বলতে চেয়েছেন সাধারণ মানুষের সাথে। অনেক চেষ্টা করেও\nযখন তিনি বুঝতে ব্যর্থ হবেন তখন স্বাভাবিকভাবেই চিত্রটির সম্মুখে তিনি আর দাঁড়াবেন\nনা। অন্য কোথাও নিজেকে সরিয়ে নেবেন। অতঃপর তিনি তার পেলবতা মিশ্রিত মসৃণ মনোভূমির আর্দ্রতা\nথেকে ওই ছবিটির অস্তিত্বটিকে কোনো দ্বিধা না করেই মুছে ফেলবেন চিরদিনের জন্যে। দ্বিতীয়বার\nআর ছবিটিকে নিয়ে ভাবতে চাইবেন না মোটেই। এই যদি হয় বাস্তবতা তাহলে অধিবাস্তববাদীতার\nথিওরী প্রয়োগ করে শিল্পী যা সৃষ্টি করলেন সেই সৃষ্টিকে অবলম্বন করে এবং সেই সৃষ্টির\nমাধ্যমে শিল্পী কি সাধারণ মানুষের মাঝে বেঁচে থাকতে পারবেন অনন্তকাল ধরে? পারবেন না।\nসাধারণ মানুষের মনের মনিকোঠা থেকে শিল্পীও হারিয়ে যাবেন চিরকালের মতো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এটি গেল মূলতঃ চিত্রশিল্পে অধিবাস্তববাদী\nরূপের অতি ক্ষুদ্র একটি উদাহারণ। ঠিক একইভাবে নাট্যশিল্পেও অধিবাস্তববাদী রূপটিকেও\nবিবেচনা করা যেতে পারে। &nbsp;যে কোনো ভাবেই হোক\nএকজন মধ্য বয়সী মানুষ একটি জ্বলন্ত অগ্নিকুন্ডে নিক্ষিপ্ত হয়ে জ্বলে যাচ্ছে। কিছুতেই\nসে সেই অগ্নিকুন্ডের ভেতর থেকে বেরিয়ে আসতে পারছে না। &nbsp;জ্বলে যেতে যেতে মহাশুণ্য আর পাতালের সর্বশেষ স্তর\nতোলপাড় করে আর্তনাদ করছে, সবার কাছে বক্ষ দীর্ণ করা বাঁচার আকুতি জানাচ্ছে। কিন্তু\nহাজার হাজার মানুষ দূরে দাঁড়িয়ে থেকে শুধু লোকটির অনিবার্য মৃত্যু যন্ত্রণা প্রত্যক্ষ\nকরছে, কেউই লোকটিকে বাঁচাবার জন্যে এগিয়ে আসছে না। &nbsp;লোকগুলির মধ্যে একজনও ওই প্রজ্জ্বলমান অতি হিংস্র অগ্নিশিখার কাছাকাছি\nআসবার সাহস কুলিয়ে উঠতে পারছে না। &nbsp;অসহায়ের\nমতো শুধু লোকটির মৃত্যুক্ষণটির জন্যে অপেক্ষা করছে। এক সময় লোকটি মৃত্যুকাতর যন্ত্রণা\nনিয়ে নিঃশেষ হয়ে গেল। ওর আর বাঁচা হলো না। &nbsp;ওর চার পাশে যত তৃণলতা, সবুজ ঘাস, কীট, পতঙ্গ- যা\nকিছু ছিল সবই পুড়ে ছাই হয়ে গেল। কিছুই রক্ষা পেল না।&nbsp;&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এটি হলো একটি সাধারণ নাটকের অতি\nসাধারণ একটি বাস্তব দৃশ্য। এই দৃশ্যটিকেই যদি অধিবাস্তববাদী প্রলেপ দিয়ে এভাবে দৃশ্যমান\nকরা হয়- যেখানে দেখা যাবে- মৃত্তিকার কোনো অস্তিত্ব ব্যতীতই মহাশূণ্যের ওপরে গোটা মহাশূণ্য\nজুড়ে বিশাল বনভূমি। সেই বনভূমিতে প্রচন্ড দাবানলের সৃষ্টি হয়েছে। চোখের পলক না পড়তেই\nপুড়ে যাচ্ছে সব বৃক্ষকূলের পত্র, পল্লব, শাখা, প্রশাখা, কান্ড সবকিছু। সেই দাবানলে\nএকজন কাঠুরে আটকা পড়ে বৃক্ষরাজির সাথে সে-ও পুড়ে মরছে। তার প্রকট চিৎকারে অস্থির হয়ে\nস্বর্গ থেকে দেব দেবীরা নেমে এসেও লোকটিকে বাঁচাতে পারলো না। লোকটির জীবন-দীপটি নিভে\nগেল। এক সময় দাবানল স্তিমিত হতে হতে একেবারে শান্ত হয়ে এলো। দাবানলের চিহ্নমাত্রও আর\nকোথাও লক্ষিত হলো না। এরপর দেখা গেল যে লোকটি পুড়ে ছাই হয়ে গিয়ে মৃত্যুর কাছে পরাভূত\nহয়েছিল সেই কাঠুরে লোকটি আবার জীবন্ত হয়ে স্বর্গ থেকে নেমে আসা দেব দেবীদের সঙ্গে দিব্বি\nদু’পায়ে হেঁটে হেঁটে মহাশূণ্যেই মিলিয়ে গেল। পূর্বের বনভূমিকেও আর মহাশূণ্যে দৃশ্যমান\nহলো না। সবকিছুই সাধারণ মানুষের দৃষ্টিতে বাস্তবতায় ফিরে এলো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তুলনামূলক বিচারে প্রথম দৃশ্যটি\nথেকে দ্বিতীয় দৃশ্যটির চরিত্র একেবারেই আলাদা। সাযুজ্য শুধুমাত্র একটি বিষয়েই। দু’টি\nদৃশ্যেই একটি মানুষ অগ্নিদগ্ধ হয়ে মৃত্যু বরণ করল- এটুকুই। কিন্তু তারপরেই দ্বিতীয়\nদৃশ্যে দেখা গেল যে কাঠুরে লোকটি দাবানলের কবলে পড়ে ভয়াবহ মৃত্যুকে আলিঙ্গন করেছিল\nসেই লোকটিই আবার দাবানল থেমে গেলে পুনরায় জীবন ফিরে পেয়ে পায়ে হেঁটে দেব দেবীদের সঙ্গে\nস্বর্গের উদ্দেশ্যে যাত্রা করল। অর্থাৎ নাটকের এই দৃশ্যটিতে অধিবাস্তববাদী নাট্যকার\nযা সৃষ্টি করলেন তা প্রকৃত অর্থে শুধু অবাস্তবই নয় বরং একেবারেই উদ্ভট- যা একজন সাধারণ\nদর্শকের উপলব্ধি আর অভিজ্ঞানের পুরোপুরি বাইরের এবং বিশ্বাসের সম্পূর্ণই পরিপন্থি।\nসাধারণ দর্শক এ দৃশ্যটিকে উপলব্ধি করবেন নিতান্তই নিস্ফল আধ্যাত্মিকতার নিছক একটি সান্তনা\nএবং বাস্তবতার বিপক্ষে একটি চরম ব্যর্থতা আচ্ছাদিত বাস্তবতাহীনতার অবিশ্বাস্য প্রকাশ\nহিসেবে। আর এ কারণেই দর্শকবৃন্দ এই অধিবাস্তববাদী দৃশ্যটিকে কোনোমতেই তাদের চৈতন্যলোকে\nস্থাপন করতে পারবেন না। ফলশ্রুতিতে নাট্যকারও কখনই সাধারণ দর্শকের মাঝে তার স্থায়ী\nআসন গড়ে নিতে কোনোমতেই সক্ষম হবেন না। উদ্ধৃত চিত্রশিল্পীর মতোই তাকেও সাধারণ মানুষের\nমন থেকে চিরদিনের মতো সময়ের পূর্বেই ‘স্বেচ্ছা-নির্বাসনে’ যেতে হবে। এবং এটিই সবচাইতে\nবড় বাস্তবতা। এবং এখানে অধিবাস্তবতার কোনো স্থান নেই।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অধিবাস্তববাদীতার Form কে নিয়ে\nআলোচনা করবার পূর্বে আরও দু’টি বিশেষ Form কে নিয়ে আলোচনা করতে হবে। এবং শুধু আলোচনাই\nনয় ঋড়ৎস দু’টির চুলচেরা বিশ্লেষণও করতে হবে। ০১. রূপক (Allegory) এবং ০২. প্রতীক অথবা\nসংকেত (Symbol). প্রথমটি জ্ঞানগত অর্থাৎ Objective, দ্বিতীয়টি ভাবগত অর্থাৎ Subjective.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখন আমরা Form দু’টিকে বিশ্লেষণ\nকরবার প্রয়োজনেই প্রখ্যাত বি্িরটশ সাংকেতিক কবি ও নাট্যকার W . B Yeats- এর ‘রূপক’\nএবং ‘সংকেত’- এর পার্থক্য সম্পর্কিত একটি মন্তব্যকে বিবেচনা করব- </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>A Symbol is indeed the possible expression of some invisible essence, a transparent lamp about a spiritual flame; while Allegory is one of many possible representation of an embodied thing, or familiar principle, and belongs to fancy, and not to imagination; the one is revelation, the other an amusement. Symbolism said things which could not be said so perfectly in any other way, and needed but a right instinct for its understanding, while Allegory said things which could be said as well, or better, in another way, and needed a right knowledge for its understanding. The one gave dumb things voices, and bodiless things bodies; while the other read a meaning heard or seen, and loved less for the meaning than for its own sake.</p><cite> (ideas of good and Evil). </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>রূপকের তাৎপর্য বুদ্ধি-ভিত্তিক। বচন অথবা সংলাপের অর্থ সংলাপের কোন মর্মার্থটিকে ইঙ্গিত করছে- সেটিকে বোঝাতে পারলেই মোটামুটি রূপকের উদ্দেশ্য সিদ্ধ হতে পারে। অর্থাৎ Objective’র বাইরে এর চলাচল সম্ভব হয়ে ওঠে না। এর কার্যক্রমের নির্দিষ্ট অঞ্চল জ্ঞানের ক্ষেত্রজ ভূমিতে। আবার বুদ্ধিবৃত্তিক চেতনার ঘনত্বের মাত্রা সাপেক্ষে এর অর্থের তারতম্যও হতে পারে। সে ক্ষেত্রে রূপকের অর্থ এককের মধ্যে সীমায়িত না থেকে একাধিকেও বিস্তৃত হওয়ার সম্ভাবনাই বেশী থাকে। কিন্তু সংকেতের ঘণিভূত আবেদন মানুষের অনুভূতির অভ্যন্তরে, কল্পনার বহুগামীতায়। যে ভাবানুষঙ্গতা বস্তুজগতকে অতিক্রম করে মানুষের অনুভূতির বিশাল ‘ভাব-সমুদ্রে’ নিয়ত সঞ্চরণশীল সেই সত্যকে উদ্ধার করে একটি বিশেষ রূপের আধারে প্রতিষ্ঠা করবার প্রচেষ্টাই সংকেতের মূল কাজ এবং লক্ষ্য। নাটকের ক্ষেত্রে এর আখ্যানবস্তু, সংলাপ, চরিত্র, ঘটনাবলী ইত্যাদি বিভিন্ন প্রকারের ইঙ্গিত-ব্যঞ্জনার মাধ্যমে বাস্তবাতীত লীলাভূমির, ইন্দ্রিয়াতীত মহাসত্যের প্রচ্ছদকে মানুষের চিত্তলোকে মুদ্রিত করে। সেই অপরূপ ভাব বা সত্য প্রতীকের মাধ্যমে উত্তেজিত কল্পনার অতিবিচিত্র লীলাপথ বেয়ে মানুষের চিন্তা-তরঙ্গের গভীরতম প্রদেশে প্রবেশ করে এক অনির্বচনীয় সুখানুভূতির সৃষ্টিকে সম্ভব করে তোলে। এবং সেই দিব্যানুভূতির ভেতর এর যথার্থ তাৎপর্য এর স্বরূপ-মূর্তিকে অনিন্দ্য-সুন্দর কুসুমের মতো বিকশিত করে তোলে। এই নিখাদ সত্যের যে তাৎপর্য অথবা স্বরূপ তা অবশ্যই এক এবং চিরন্তন। বুদ্ধি-শক্তির কোনো মাত্রাই তাকে ভিন্ন রূপ প্রদান করতে পারে না। সে অর্থে রূপক সীমার ভেতর নিরুদ্ধ থেকেই একটি পরিপূর্ণ বিশেষ রূপ অর্থাৎ জ্ঞানকে উদ্ঘাটনে সচেষ্ট হয়। পক্ষান্তরে সংকেত সীমার অভ্যন্তরে ক্রিয়াশীল থেকেও অসীমের সন্ধানে ব্যাপৃত হয় এবং অসীমের অনুদ্ঘাটিত বিশাল ভাব-সত্য এবং সৌন্দর্যকে উদ্ধার করে মানুষের মনের গহীনে স্থাপন করে। সে দিক থেকে বিবেচনা করলে রূপকে কোনো রহস্যময়তা অথবা স্বাভাবিকতার বাইরে ভিন্ন কিছু সৃষ্টির প্রয়োজন হয় না, নির্দিষ্ট একটি জ্ঞানকে উন্মোচন করতে পারলেই রূপকের উদ্দেশ্য সিদ্ধ হয়। কিন্তু সংকেতের পূর্ণ সফলতা নির্ভর করে তারই সৃষ্ট আবহ অথবা পরিবেশের সুদৃঢ় কাঠামোগত আকৃতি নির্মিতির ওপর। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিশিষ্ট সংকেত বিশেষজ্ঞ Arthur\nSymons- এর মতে- </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>Symbolism- in which art returns to the one pathway, leading through beautiful things to the element. It is an attempt to spiritualise literature, to evade the old bondage of exteriority. Description is banished, that beautiful things may be evoked magically ; the regular beat of verse is broken in order that words may be fly upon subtler wings…..Here, then, in this revolt against exteriority, against rhetoric, against matetialistic tradition, in this endeavour to disengage the ultimate essence, the soul of whatever exists can be realised by the consciousness ; in this dutiful waiting upon every symbol by which the soul of things can be made visible, literature bowed down by so many burdens, may at last attain liberty, and its authentic speech.</p><cite> (The Symbolist Movement in literature).  </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>উদ্ধৃত মতের আলোকে বিশিষ্ট সাহিত্যিক\nএবং নাট্য-বিশেষজ্ঞ ড. উপেন্দ্রনাথ ভট্টাচার্যের রচনা থেকে আর একটি উদাহারণ দেয়া যেতে\nপারে- </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘সাহিত্য ভাষার মারফতে যে-অর্থ\nব্যক্ত হয়, সংকেত সেই অর্থকে বিপুল আবেগ এবং গভীর ও অব্যর্থ জ্ঞানের সঙ্গে আমাদের মনে\nসংক্রামিত করে। সেই সংকেত-মাধ্যমে উপস্থাপিত অর্থকে আমরা নুতন আলোকে, নুতন চেতনায় লাভ\nকরি। সংগীতে আমরা সংকেতের প্রভাব বুঝিতে পারি। গানের কথাকে যখন আমরা সুরের মধ্য দিয়া\nপাই, তখন তাহার নুতন এক অর্থ, এক অনির্বচনীয় তাৎপর্য হৃদয়ের অন্তঃস্থলে প্রবেশ করে।\nএই সুর একটা সংকেত। এই সংকেতই আমাদের মনে বিচিত্র অনুভূতির সৃষ্টি করে এবং অসীমের অন্দর-মহলে\nআমাদের লইয়া যায়।’ </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp; বিখ্যাত সমালোচক A.N. Whitehead- এর সংকেতের কার্যকারিতা\nসম্পর্কিত ধারণাটি এ রকমের-&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>Symbolism is no mere idle fancy or corrupt degeneration; it is inherent in thevery texture of human life. Language itself is a symbolism. Mankind, it seems, has to find a symbol in order to express itself. Indeed ‘expression’ is ‘symbolism’… The function of the symbolic elements in life, is to definite, manageable, reproducible, and also to be charged with their own emotional efficacity; symbolic transference invests their correlative meanings with some or all these attributes of the symbols, and thereby lifts the meanings into an intensity of definite effectivenessÍas elements in knowledge, emotion, and purpose… In every effective symbolism there are certain aesthetic features shared in common. The meaning acquires emotion and feeling directly excited by the symbol. This is the whole basis of the art of literature, namely, that emotions and feelings excited by the words should fitly intensify our emotions and feelings arising from contemplation of the meaning…The same principle holds for all the more artificial sorts of human symbolism; - for example, it’s religious art, Music is particularly adapted for this symbolic transfer of emotions….</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>এই হলো সংকেতের অতীব মহার্ঘ মূল্যমান\nএবং কর্মক্ষম শক্তির শেকড়। যে শেকড় থেকে উত্থিত হয় অতি সূক্ষ্ম, জটিলতম এবং অতীন্দ্রিয়\nভাব-সত্যের মর্ম-সৌন্দর্যের অনুভূতিটি। এই সৌন্দর্য মন্ডিত ভাবানুভূতিকে একটি শীর্ষ\nমাত্রায় রূপায়নের লক্ষ্যেই শিল্পী সাহিত্যিকবৃন্দ তাদের সৃষ্টিতে সংকেতের ব্যবহার করে\nথাকেন। এবং এটিকে সঠিক প্রয়োগের মাধ্যমে তারা সফলতাও লাভ করেন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এ বিষয়টিকে বিবেচনার জন্যে গ্রহণ করে অগ্রসর হলে বিশ্বখ্যাত নাট্যকার ইবসেনের কয়েকটি নাটক আপনা আপনিই দৃষ্টিসীমায় স্থাপিত হয়ে যায়- ‘A Doll’s House, ‘Hedda gabler’, ‘Rosmersholm’, ‘The Wild Duck’. ‘The Master Builder’- প্রভৃতি নাটকে ইবসেন যথেষ্ট মুন্সীয়ানার সাথে সংকেতের ব্যবহার করেছেন। এবং তিনি উত্তীর্ণ হয়েছেন। ইবসেন ছাড়াও পাশ্চাত্যের অতি আধুনিক নাট্যকার Eugene O’neill-I তার কোনো কোনো নাটকে এই সংকেতের ব্যবহার করেছেন। বিশেষতঃ তার ‘The Hairy Ape’- নাটকের একটি দৃশ্যে নিশ্চল, নিশ্চুপ পুতুল সাদৃশ্য কতগুলি নারী পুরুষের যে আবির্ভাব ঘটিয়েছেন তারা আর কেউই নয় একেক জন যেন একেকটি যান্ত্রিক রোবটের প্রতীক- যাদের মধ্যে রক্ত মাংস নেই, আবেগ নেই, উচ্ছ্বাস বিহীন, প্রাণচঞ্চলতা বিহীন অত্যাধুনিক যান্ত্রিক সভ্যতার জড়ায়ুতে জন্মিত- যারা কতগুলি নিছক পুতুল ব্যতীত আর কিছুই নয়। নাট্যকার অত্যন্ত সচেতনভাবেই যান্ত্রিক সভ্যতাকে মানুষের আবেগ, উচ্ছ্বাস, প্রাণ চাঞ্চল্যকে কেড়ে নেবার হিংস্র দানবীয় শক্তি হিসেবেই বোঝাতে চেয়েছেন এবং এই পুতুল-সাদৃশ্য মানুষগুলিকে তিনি যান্ত্রিক সভ্যতার মর্মান্তিক শিকারের প্রতীক হিসেবে গ্রহণ করে সংকেতার যথার্থতাকে প্রতিষ্ঠা&nbsp; করেছেন। নাটকটির নামকরনেও নাট্যকার সংকেতের ব্যবহার করেছেন। নাটকটির ‘The Hairy Ape’- অর্থাৎ ‘লোমশ গরিলা’ নামকরনটি সেই সংকেতকেই ধারণ করে। সাধারণতঃ এই প্রজাতির প্রাণীগুলি স্বভাবগত ভাবেই হিংস্র প্রকৃতির হয়ে থাকে। এই নামকরনটি করে Eugene O’neill- গোটা যান্ত্রিক সভ্যতাকেই হিংস্র লোমশ গরিলা হিসেবে Symbolize” করবার প্রয়াস পেয়েছেন। সংকেত প্রদান করেছেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ইবসেন তার ‘A Doll’s House’- নাটকে নায়িকা নোরার জীবনের অন্তর্দ্বান্দ্বিকতার ভয়াবহ দূর্ভার যন্ত্রণা, বিভিন্ন কারণে স্বামীর ভালোবাসাকে একান্ত আপনার করে নেবার ক্ষেত্রে প্রবল সন্দেহে সন্দিগ্ধ হওয়া এবং সে ভালোবাসার ওপর কোনোমতেই বিশ্বাস স্থাপন করতে না পারা- যার প্রেক্ষিতে সার্বক্ষণিক একটি অদৃশ্য আতঙ্ক এবং ভীতির তাড়নায় আত্ম-তাড়িত হয়ে উন্মাদ অস্থিরতার কাছে নিজেকে সমর্পণ করা, কখনো কখনো প্রচন্ড আত্মাভিমানে জর্জরিত হয়ে আপন ঘর ত্যাগ করে অনিশ্চিত উদ্দেশ্যের পথে নিরুদ্দেশ হয়ে যাবার স্থির সংকল্প নির্মাণ করা- সবকিছু মিলিয়ে নোরার অন্তর্লোকে যে ভয়ঙ্কর ঘূর্ণিঝড়ের উত্থান তারই সংকেত হিসেবে ‘Tarantella’- নামীয় একটি ‘দ্রুতলয়ের ঘূর্ণি নৃত্যের’ সৃষ্টি করেছেন নাটকটির একটি দৃশ্যে- যা নোরার অন্তর্জগতের উন্মত্ত ঝড়ের আঘাতে আহত, বিধ্বস্ত মানসিক অবস্থার অত্যন্ত আবেগী অবস্থানকে অত্যন্ত নিখুঁতভাবে তুলে এনেছে দর্শকদের সামনে। এই Tarantella’- নামীয় ‘দ্রুতলয়ের ঘুর্ণি নৃত্যটিকেই’ নাট্যকার নোরার মানসিক ভাব-সমুদ্র চিত্রের সংকেত হিসেবে ব্যবহার করেছেন একটি পরিপূর্ণ সফল সংকেত হিসেবে- যা দর্শক, নাট্য-বিশেষজ্ঞ, বিভিন্ন শ্রেণির নাট্যকার এবং সাহিত্যিকদের কাছেও মূল্যায়িত এবং আদৃত হয়েছে যথার্থ হিসেবে। এ ধরণের সংকেতের ব্যবহার ইবসেনের প্রায় সবক’টি নাটকে রয়েছে। আশ্চর্যের বিষয় সংকেত প্রয়োগের ক্ষেত্রে ইবসেন তার কোনো নাটকেই ব্যর্থ হন নি। আর নাট্য-সাহিত্যে সংকেতের সার্থকতা এখানেই।&nbsp;&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যদি ইবসেনের ‘Hedda Gabler’- নাটকের মূল বিষয়ের\nঅতলান্তকে স্পর্শ করা যায় তাহলে সে নাটকটিতেও ‘A Doll’s House’- নাটকের নায়িকা নোরার\nমতোই ‘Hedda Gabler’-না টকের নায়িকা Hedda-\nএর মানসলোকের&nbsp;\nঅতি সূক্ষ্ম একটি বিপর্যস্ত অনুকৃতির সঙ্গে পরিচিত হতে হয়। নোরা যখন তার স্বামীর\nভালোবাসার ওপর বিশ্বাস হারিয়ে ফেলে Hedda-\nও যেন কতকটা সেভাবেই তার ভালোবাসবার পাত্র, তার একান্ত\nপ্রিয়তম ‘Eilert Lovborg’-কেও একটি শিল্প-সম্মত আনন্দোজ্জ্বল `Vine-Leaves’- সীমাহীন\nসৌন্দর্যের প্রতীক হিসেবে গ্রহণ করে তার স্বপ্নের সৌন্দর্যের মাত্রাকে কয়েকগুণ বাড়িয়ে\nতুলতো। এটি করে Hedda- চরম সুখ এবং আত্মতৃপ্তি অনুভব করতো। কারণ `Vine-Leaves’-টি ছিল\nগ্রীসের সুরা দেবতা ‘Bacchus’ এর গভীর ভাবের অনুষঙ্গের সঙ্গে ওতপ্রোতভাবে জড়িত। কেননা\nসাধারণতঃ পানভোজন জাতীয় আনন্দ উৎসবের ভেতর দিয়ে যে উচ্ছ্বাস এবং উন্মত্ততা প্রকাশিত\nহয় তারই প্রকাশিত রূপটি ছিলো `Vine-Leaves’. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যখ থেকে ‘Eilert Lovborg’-এর\nসঙ্গে Hedda- এর বন্ধুত্বের সম্পর্কটি ঘণিভূত হতে শুরু করে তখন থেকেই Hedda-‘Eilert Lovborg’-কে\nতার স্বাপ্নিক অবয়বে মাথার শীর্ষে সেই `Vine-Leaves’- শোভিত এক অনিন্দ্য-সুন্দর, দিব্যকান্তি\nমহান পুরুষ হিসেবেই প্রতিষ্ঠা করেছিলো। বন্ধুত্বের এক পর্যায়ে Hedda- এর সঙ্গে চরম অন্তরঙ্গ\nহয়ে এবং Hedda-কে বিশ্বাস করে তার জীবনের অনেক মদ্যপান এবং নারী ঘটিত গোপন কাহিনী অবলীলায়\nHedda-কে বলেছিলো। কিন্তু Hedda-র আত্যাশ্চার্য মানসিক গঠন এবং প্রকৃতি সম্পর্কে ‘Eilert\nLovborg’- এর সূক্ষ্ম কোনো ধারণাই ছিলো না। যে কারণে Hedda- কর্তৃক সে প্রত্যাখ্যাত\nহয়। কেননা এই ধরণের জীবন প্রবাহকে Hedda-\nকর্তৃক সে প্রত্যাখ্যাত হয়। কেননা এই সব সময়ই তীব্র\nঘৃণার সাথেই তুলনা করতো। এই ধরণের যাপিত জীবনের ওপর একাধারে তার ছিলো প্রচন্ড বিতৃষ্ণা\nএবং ভীতি। যে কারণে এক সময় তাদের সম্পর্ক বন্ধুত্বের মাত্রা অতিক্রম করে আরও ঘনিষ্ট\nহবার পূর্বেই রণের জীবন প্রবাহকে Hedda-\nঅত্যন্ত কৌশলে এবং বিচক্ষণতার সাথে ‘Eilert Lovborg’-কে\nপ্রত্যাখ্যান করেছিলো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Hedda- যেভাবে স্বর্গীয় সৌন্দর্য,\nউচ্ছ্বাস এবং আনন্দে বর্ণোজ্জ্বল মস্তকের ওপর `Vine-Leaves’ শোভিত - ‘Eilert Lovborg’-কে\nনিজের অবচেতন মনের উঠোনে স্থাপন করে নিরবধি এক বিশেষ ধরণের সুখ অনুভব করতো ‘Eilert\nLovborg’- তার জীবনের ইন্দ্রিয়জ কামনা, বাসনাকে বাস্তবে রূপায়ণের যে বর্ণনা Hedda-কে দিয়েছিলো\nতাতে ‘Eilert Lovborg’-কে গ্রহণ করবার সব স্বপ্নই Hedda- র জীবন থেকে মুছে\nগিয়েছিলো। বিশেষতঃ গায়িকা Diana- এর বাড়ীতে Diana’ র সাথেই যখন ‘Eilert Lovborg’-\nএর চরম কেলেঙ্কারির কথা Hedda- বিশ্বস্ত সূত্রে জানতে\nপারলো তখন Hedda’র প্রতিক্রিয়া ছিলো এ রকমের- ‘Then he had no vine-leaves in his\nhair’. অর্থাৎ Hedda’ র জীবনের মহাপুরুষ হিসেবে- ‘Eilert Lovborg’ র অবস্থান নিমেষেই চিরদিনের মতো তিরোহিত হয়ে গিয়েছিলো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘A Doll’s House’- নাটকে যেমন\nএকটি উন্মত্ত ঘূর্ণি নৃত্যকে সংকেত হিসেবে ব্যবহার করে নোরার ‘জীবন-ঝড়ের’ তান্ডবকে\nপ্রকাশ করা হয়েছে ঠিক একইভাবে এ নাটকটিতেও `Vine-Leaves’কে একটি চমৎকার সংকেতকে ব্যবহার\nকরে Hedda’ র মনোলোকের সুচি ¯িœগ্ধতাকে শুভ্রতার আলোকে উপস্থাপন করা হয়েছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এ কথা তো সত্যি যে, যদিও সাহিত্য-শিল্পে\nভাবের প্রকাশ ঘটে সাধারণভাবে ভাষার মাধ্যমে এবং অপেক্ষাকৃত স্থুলভাবে। কিন্তু এই স্থুলতার\nবাইরেও যে সুক্ষ্মাতিসূক্ষ্ম, অনিশ্চিত এবং অনির্দিষ্ট ভাব স্থুলতার গভীরাভ্যন্তরে\nস্থিত থাকে যাকে কেবলমাত্র নিবিড় অনুভবগামীতার মাধ্যমেই উপলব্ধি করা যায়- যে ভাবের\nঅফুরন্ত সমগ্রতাকে অবশ্যই শুধুমাত্র ভাষার মাধ্যমে উদ্ঘাটন করা যায় না। সে ভাবের পরিপূর্ণ\nআকৃতিগত রূপায়নের জন্যে প্রয়োজন হয় ভাষার বাইরের অন্যকিছুর। এই ‘অন্যকিছুটিই’ হলো\n‘সংকেত’ অথবা ‘Symbol’. এই সংকেত মানুষের কল্পনাগামীতার সম্মুখের অযুত নিযুত দূরায়ত্ব\nবাধার দরোজাকে উন্মুক্ত করে দিয়ে অপার ভাব-সমুদ্রে বিচরণ করবার সুযোগ করে দেয় অনায়াসেই।\nমানুষ তার চৈতন্যলোকের মগ্নতা দিয়ে এই ভাব-সমুদ্রে নির্বাধ বিচরণে ব্যাপৃত থেকে একটি\nএকটি করে ‘অরূপ-রতন’কে তুলে আনে তার মানসিক আকাক্সক্ষা পূরণের লক্ষ্যে। এটিই হলো সংকেতের\nস্বার্থকতা। এখানে এই প্রেক্ষিতে আর একটি উদ্ধৃতি নিশ্চিত উল্লেখের দাবী রাখে- “শিল্পীর\nযথার্থ প্রকাশ স্বার্থকতা লাভ করে সংকেত-প্রয়োগে। সংকেতই অনির্দেশনীয়কে নির্দিষ্ট করে,\nঅব্যক্তকে কৌশলে ব্যক্ত করে, অরূপকে রূপময় আভাসের মধ্যে বন্দী করে।” জার্মান নাট্যকার\nহাউপট্ম্যান তার শেষ দিকের কয়েকটি নাটক রচনায় এই সংকেতের কাছেই সমর্পিত হয়েছিলেন। প্রথম\nদিকে যদিও তিনি বাস্তববাদী নাট্যকার হিসেবেই প্রতিষ্ঠিতি পেয়েছিলেন। রুশ নাট্যকার আন্দ্রিভ\nযখন সাংকেতিকতাকে আশ্রয় করে তার ‘The Life of Man‘-নাটকটি রচনা শেষে মঞ্চস্থ করেছিলেন\nতখন তার অভিভূত দর্শকরা তাকে প্রশ্ন করেছিলো- ‘কেন তিনি এমন অভিনব পন্থায় নাটকটি লিখলেন?\nউত্তরে তার মন্তব্যটি ছিলো- “প্রত্যেক সাহিত্য-শিল্পীই তার বক্তব্য যাতে সুন্দর শিল্প-সম্মতভাবে\nপ্রকাশ করা যায়, তারই চেষ্টা করেন। তিনিও তার বক্তব্য এই রীতিতে প্রকাশ করলে যথাযথ\nএবং ভালোভাবে প্রকাশিত হবে- এই ধারণা এবং বিশ্বাস থেকেই সাংকেতিকতার রীতিটিকে তিনি\nগ্রহণ করেছিলেন। এই রীতি ব্যতীত অন্য কোনো রীতিতেই তার বক্তব্য তার আকাক্সক্ষা অনুযায়ী\nযথাযথভাবে প্রকাশ করা সম্ভব হবে না বলেই তিনি এই রীতিটিকে গ্রহণ করেছিলেন।” &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘Rosmersholm’- নাটকে ইবসেন Foot-bridge-\nনামের একটি প্রতীকের সৃষ্টি করেছেন। যে Foot-bridge- টি গোটা নাটকটিকে\nঅব্যাহতভাবে প্রভাবিত করেছে প্রতি মূহুর্তে। দর্শকদের কল্পনা-প্রবাহে দারুণ এক মর্মান্তিকতা\nস্থায়ী এক অনুভবের উপলব্ধিকে প্রতিষ্ঠিত করেছে। কারণ নাটকটির বিষয়বস্তু এমনই যে, Foot-bridge- টি না থাকলেই বরং\nমনে হতো নাটকটি অসম্পূর্ণই থেকে গেল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘The Wild Duck’- নাটকে ইবসেন\nWild Duck টিকেই একাধারে রূপক এবং সংকেত হিসেবে ব্যবহার করেছেন। নাটকের কেন্দ্রিয় চরিত্র\n`Old Ekdal- এর দুঃসহ অস্বাভাবিক, চাঞ্চল্যবিহীন, নিস্তরঙ্গ, নিঃসঙ্গ জীবনের চূড়ান্ত অসহায়ত্বকে\nতিনি একটি আহত বুনো হাঁসের রূপক হিসেবে গ্রহণ করে সেই বুনো হাঁসটিকেই আবার সংকেতে রূপান্তরিত\nকরে `Old Ekdal’- এর জীবনের সাথে তুলনা করেছেন। যে বুনো হাঁসটিকে আবার ওই নাটকের আর একটি চরিত্র\n‘Werle’- এর নির্মমতার ছুরি দিয়ে আহত করা হয়েছে-যা শুধু Old Ekdal- এর জীবনকেই আহত করে\nনি বরং নাট্যকারের জীবনকেও আহত করেছে বলে ওই নাটকে নাট্যকার ইঙ্গিত করেছেন- যেটি নাট্যকার\nকোনো প্রশ্নের অবকাশ না রেখেই স্পষ্ট করেছেন। একটি নির্দিষ্ট রূপককে সংকেতে রূপান্তরিত\nকরে সেই সংকেতের মাধ্যমে নাটকের গোটা বিষয়বস্তুর নিগুঢ়তম ভাবকে মানুষের মর্ম মূলে প্রোথিত\nকরেছেন নাট্যকার ইবসেন। যদি ইবসেন সংকেতটি ব্যবহার না করতেন তাহলে হয়তো নাটকটিকে ‘সফলতা-জ্ঞানে’\nবিবেচনা করা যেত কি না- প্রশ্নটি থেকেই যেত চিরকালের জন্যে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘The Master Builder’- নাটকটিতেও ইবসেন অত্যন্ত\nবিচক্ষণতার সাথে নিখুঁত এবং অতিসূক্ষ্মভাবে রূপক এবং সাংকেতিকতাকে ব্যবহার করেছেন।\nনাটকটির প্রতিটি দৃশ্যের পরতে পরতে রূপক এবং সাংকেতিকতার প্রভাব-সম্পাতি ভূমিকা কোনো\nপ্রকার প্রশ্ন ছাড়াই স্পষ্ট। Master Builder Halvard Solness- এর একটি প্রতিশ্রুতিকে\nকেন্দ্র করে মানুষের অপূর্ব বাসগৃহ, গির্জার চূড়া, শুন্য আকাশে বিশালতম অতুল-মোহনীয়\nপ্রাসাদতুল্য সৌধ নির্মাণ এবং Mrs. Solness- কর্তৃক দীর্ঘকাল ধরে অতীব সৌন্দর্যমন্ডিত\nনয়টি পুতুলকে আগলে রেখে পরম যত্ন আর মমতায় সিক্ত করে সংরক্ষণ করন- যার মাধ্যমে তার\nস্ত্রীর মনোবৈকল্যকে একটি রূপকের আকারে তুলে ধরা সবকিছুই ওই নাটকে সংকেত হিসেবেই চিত্রিত।\nএসব সংকেতের চিত্রায়ন করা হয়েছে কেবলমাত্র Master Builder Halvard Solness- এর গোপন প্রণয়-সঙ্গী\nHilda Wangle’কে দশ বছর পর তার নিজ-কল্পিত একটি রাজ্যদান করা এবং তাকে সে রাজ্যের রাজকুমারী\nবানিয়ে দেবার প্রতিশ্রুতির সার-শুন্যতা প্রমাণ করবার এবং Hilda Wangle’কে সূক্ষ্ম প্রতারনাপূর্ণ\nমিথ্যে স্বপ্ন-তন্দ্রায় আপাদমস্তক ডুবিয়ে রেখে তাকে নিজের ইচ্ছেমত ব্যবহার করবার পরিপুষ্ট\nইঙ্গিত হিসেবে। প্রকৃত অর্থেই যেকোনো মানুষকে যদি কোনো অলৌকিক স্বপ্নের চূড়ায় অধিষ্ঠিত\nকরবার প্রলোভন দেখানো যায় এবং সে যদি এ প্রলোভনে প্রলোভিত হয়ে প্রলোভনটিকে একবার বিশ্বাস\nকরে তাহলে সে শুধু সেই স্বপ্নের শিখরে উঠতেই চাইবে। নীচের দিকে তাঁকাবার কোনো প্রয়োজনই\nসে মনে করবে না। কিন্তু যে মুহুর্তে তার সে স্বপ্নটি তাসের প্রাসাদের মতো একটি নিঃশ্বাসের\nআঁচড়েই ভেঙ্গে পড়বে তখন সে আর অক্ষত থাকবে না। সংশ্লিষ্ট নাটকে নাট্যকার রূপক এবং সংকেতের\nভেতর দিয়ে সেই প্রখর বাস্তবতাকেই নিপূণভাবে দর্শকদের সামনে মেলে ধরেছেন। নাটকটিতে সংকেতের\nপ্রয়োগ না ঘটালে যা কখনই সম্ভব হতো না। সেদিক থেকে ইবসেন সংকেতাশ্রয়ী নাট্যকার হিসেবে\nশতভাগ সফল বোধকরি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখানে এটি বলা প্রাসঙ্গিক যে,\nসংকেত-শিল্পের কাজই হলো- জ্ঞানের বাইরে, দৃশ্যমানতার আড়ালে থেকে ভাবের অভ্যন্তরে যে\nবিশাল অপার্থিব লোকালয়, অদৃশ্য, অজ্ঞেয় জগত, সে জগতের বহুবিচিত্র অনুভূতির অভিজ্ঞানকে\nএকটি বিশেষ রূপের আকারে আকৃতি দিয়ে মানুষের নিস্তব্ধ চৈতন্যকে আলোড়িত করা। রবীন্দ্রনাথের\nকিছু কিছু নাটকেও এ ধরণের রূপক এবং সংকেতের স্থিতি দৃশ্যমান। বিশেষতঃ ‘প্রকৃতির প্রতিশোধ’,\n‘ডাকঘর’, ‘শারোদোৎসব’, ‘রাজা’, ‘অচলায়তন’, ফাল্গুনী’, ‘মুক্তধারা’, রক্তকরবী’, কালের\nযাত্রা’- প্রভৃতি নাটকে স্বাচ্ছন্দ্যে রূপক এবং সংকেতের ব্যবহার করেছেন রবীন্দ্রনাথ।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘প্রকৃতির প্রতিশোধ’- নাটকে যে সন্ন্যাসী প্রকৃতির অফুরন্ত রূপ, রস, গন্ধকে অগ্রাহ্য করে প্রকৃতির ওপর প্রতিশোধ নেবার জন্যে প্রকৃতির অসীমতার অতিদূরে অবস্থানের লক্ষ্যকে মোক্ষ জ্ঞানে একটি গুহার নির্দিষ্ট একটি ক্ষুদ্র সীমায়তির ভেতরেই অসীমকে আবদ্ধ করে নিজের অপরিপক্ক চিন্তা-সীমার ক্ষুদ্র আয়োতনে উদ্ধার করতে চেয়েছেন- সেই সন্ন্য্াসীই আবার নিতান্তই একটি অস্পৃশ্য, অসহায়, অন্ত্যজ শ্রেণির নিজ কন্যবৎ বালিকা- যে বালিকাটিকে অস্পৃশ্য বলে, অন্ত্যজ বলে কেউই আশ্রয় দান করে নি সেই বালিকাটিকে নিজে আশ্রয় দিয়ে সন্ন্যাসী একদিকে যেমন কুসংস্কার এবং জাতিভেদ প্রথার বিরুদ্ধে নিজের সংস্কারমুক্ত অবস্থানকে স্পষ্ট করেছেন ঠিক তেমনি বালিকাটির প্রাণ কেঁড়ে নেয়া শ্রদ্ধা, ভালোবাসা আর মমতার কাছে শেষ পর্যন্ত নিজেকে সমর্পণ করে গুহা থেকে বেরিয়ে এসে প্রভাতী সূর্যের বিকীর্ণমান অভূতপূর্ব সৌন্দর্য, স্নিগ্ধ প্রভাতী আলোয় উছলিত প্রকৃতি-রূপের পরিপূর্ণ সুধা-ভান্ড থেকে সে সুধা পান করবার জন্যে উদ্বেলিত হয়ে ওঠেন এবং প্রকৃতি সম্পর্কিত সন্ন্যাসীর ভ্রমাত্মক ধারণা এবং ভ্রান্ত সিদ্ধান্তের বন্দীত্ব থেকে মুক্তি দিয়ে প্রকৃতির অপার সৌন্দর্যকে আলিঙ্গন করবার যে সুযোগ কন্যা-সম ওই অস্পৃশ্য, অসহায় বালিকাটি করে দিয়েছে- কৃতজ্ঞতা জানাবার জন্যে তার কাছেই ছুটে গিয়ে প্রমাণ করেছেন অসীমকে কখনই সীমার ফ্রেমে আবদ্ধ করা যায় না। কিন্তু বালিকাটিকে কৃতজ্ঞতা জানাবার তার এ প্রচেষ্টা সফল হয় না। উর্দ্ধশ্বাসে গুহামুখে ফিরে গিয়ে তিনি প্রত্যক্ষ করেন বালিকাটির প্রাণশুন্য দেহটি গুহা মুখেই পড়ে রয়েছে। গুহার ভেতর প্রবেশ করবার আর কোনো প্রয়োজন হয় না সন্ন্যাসীর। ক্ষুদ্র গুহার ক্ষুদ্রত্বের অভ্যন্তরে আত্মগোপন করবার পথটি চিরদিনের মতো রুদ্ধ করে দিয়ে গেছে বালিকাটির নিস্পাপ মৃতদেহটি। এখানে খুবই সূক্ষ্মভাবে লক্ষ্যণীয়- যে প্রকৃতির ওপর প্রতিশোধ নেবার জন্যে অর্থাৎ প্রকৃতির অসীমত্বকে নিজের মধ্যে ধারণ করে তাকে নিয়ন্ত্রণ করবার জন্যে যে সন্ন্যাসী দৃঢ়-সংকল্পিত ছিলেন সেই প্রকৃতিই সন্ন্যাসীর সংকল্পকে চূর্ণ বিচূর্ণ করে দিয়ে সন্ন্যাসীর ওপরই চূড়ান্ত প্রতিশোধ গ্রহণ করলো। সসীমের মধ্যে অসীমের অনুসন্ধান যে নিস্ফল- এ শিক্ষাই বালিকাটি সন্ন্যাসীকে দিয়ে গেলো।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু যে অসহায়, সকরুণ অশ্রুসজল\nবালিকাটিকে দেখে ওর অসহায়ত্ব এবং করুণতাকে সহ্য করতে না পেরে যে সন্ন্যাসী বলেছিলেন-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>আয় বাছা, বুকে আয়, ঢাল অশ্রুধারা,<br>ভেঙ্গে যাক্ এ পাষাণ তোর অশ্রুস্রাতে,<br>আর তোরে ফেলে আমি যাব না বালিকা,<br>তোরে নিয়ে যাব আমি নুতন জগতে।</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>এ কথাগুলি বলে বালিকাটিকে আশ্রয় দেবার পর সন্ন্যাসীর মনে দারুণ প্রতিক্রিয়ার সৃষ্টি হয়। সন্ন্যাসীর মনে হয় প্রকৃতির মায়ার বাঁধন থেকে বেরিয়ে এসে আবার তিনি মায়ার বাঁধনেই জড়িয়ে পড়ছেন। এ বোধ থেকে তিনি উচ্চারণ করেন-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>রাক্ষসী, পিশাচী, ওরে তুই মায়াবিনী-<br>দূর হ, এখনি তুই যারে দূর হয়ে।<br>এত বিষ ছিল তোর ওইটুকু মাঝে<br>অনন্ত জীবন মোর ধ্বংস ক’রে দিলি।<br>ওরে তোরে চিনিয়াছি-আজ চিনিয়াছি<br>প্রকৃতির গুপ্তচর তুই রে রাক্ষসী,<br>গলায় বাঁধিয়া দিলি লোহার শৃঙ্খল।</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>সন্ন্য্যাসীর এ ধরণের কথা শুনে\nবালিকাটি মূর্ছা গেলে, মূর্ছিতা বালিকাটিকে গুহা মুখে ফেলে রেখেই সন্ন্যাসী অরণ্যের\nমাঝে পালিয়ে যান। অরণ্যে পালিয়ে গিয়েও সন্ন্যাসী বালিকাটির করুণ, কাতর কন্ঠস্বরকে ভুলতে\nপারেন না। ঝড়, ঝঞ্চা আর চমকিত বিদ্যুতের তান্ডবের মধ্যেও বালিকাটির অসহায় ছোট্ট মুখ\nখানি যেন বারবার করে সন্ন্যাসীর হৃৎপিন্ডকে দুমড়ে, মুচড়ে দিতে থাকে। পরিবর্তিত হয়ে\nযায় সন্ন্যাসীর অন্তর্লোক। সন্ন্যাসব্রত ত্যাগ করেন সন্ন্যাসী এই বলে-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>যাক্, রসাতলে যাক্ সন্ন্যাসীর ব্রত!<br>(ছুঁড়িয়া ফেলিয়া) দূর কর, ভেঙ্গে ফেল দন্ড কমন্ডলু<br>আজ হতে আমি আর নহি রে সন্ন্যাসী!<br>পাষাণ সংকল্পভার দিয়ে বিসর্জন<br>আনন্দে নিঃশ্বাস ফেলে বাঁচি একবার।</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>এ নাটকে সন্ন্যাসীর মানসলোকে তুমুল\nঅন্তর্দ্বন্দ সৃষ্টির মূল উপাদানটিই হলো- রঘু-কন্যা সেই বালিকাটি। যদিও নাটকটিতে বালিকাটির\nছায়ার মতো একটি শীর্ণ রেখাচিত্রকেই অঙ্কন করা হয়েছে তারপরেও এই শীর্ণ রেখাচিত্রটিই\nসন্ন্যাসীর মনোজগতে প্রতিষ্ঠিত সীমা এবং অসীমের দ্বান্দিকতাকে তার শ্রদ্ধা, ভালোবাসা\nএবং মমতা দিয়ে প্রচন্ডভাবে আঘাতের পর আঘাত করে সেই দ্বান্দিকতার নিরসন ঘটিয়ে সন্ন্যাসীকে\nচরম সত্যের আসনে প্রতিষ্ঠিত করে। এই আসনে অধিষ্ঠিত হয়েই সন্ন্যাসী বালিকাটির ¯েœহ, প্রেম, ভালোবাসাকে উপেক্ষা করবার আত্ম-যন্ত্রণাকে প্রকাশ করে এভাবে-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>বাছা- বাছা-কোথা গেলি। কী করিলি রে-<br>হায় হায়-একি নিদারুণ প্রতিশোধ।</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>নাটকটিতে সন্ন্যাসী ‘সীমা’র একটি\nরূপক মাত্র। আর শীর্ণ রেখাচিত্রে অঙ্কিত ‘বালিকা’টি ওই রূপকটিকে ভেঙ্গে রূপকটির ভেতর\nথেকে পূর্ণাঙ্গ পরিবর্তিত সন্ন্যাসীকে বের করে এনে সত্যের মুখোমুখি দাঁড় করাবার বিপুল,\nবিশাল সংকেত অবশ্যই- যাকে কোনোমতেই অস্বীকার অথবা অগ্রাহ্য করা যায় না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এটি রবীন্দ্রনাথের প্রথম নাটক-যেটিতে\nতিনি গান অথবা সঙ্গীতের ওপর আশ্রয় গ্রহণ করেন নি। নাটকটি ‘নাট্য-জ্ঞানে’-উত্তীর্ণ কিনা\nসেটি ভিন্ন বিষয়। তবে তার প্রথম নাটকেই তিনি ‘রূপক’ এবং ‘সংকেত’-এর ব্যবহার করেছেন-\nএটি অভিনব। এবং এই অভিনব সৃষ্টির অভিনবত্বে তিনি সফল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রবীন্দ্রনাথের আর একটি নাটক-\n‘ডাকঘর’। এ নাটকটিতেও রবীন্দ্রনাথ রূপক এবং সংকেতের ব্যবহার করেছেন অত্যন্ত সচেতনভাবেই।\nডাকঘর নাটকের কেন্দ্রীয় চরিত্র একটি শিশু-যার নাম অমল। নাট্যকার শিশুটিকে রুগ্ন বলেছেন,\nআবার নাটকটির গভীরে প্রবেশ করলে বোঝা যায় প্রকৃত অর্থে শিশুটি রুগ্ন নয়- ওকে রুগ্ন\nবানানো হয়েছে। অশিক্ষিত, মূর্খ, এক গ্রাম্য কপট শাস্ত্রাচারী কবরেজ ওকে রুগ্ন, অসুস্থ\nবানিয়ে দিয়েছে। আসলে অমলের কোনো রোগই নেই, সে সম্পূর্ণ সুস্থ। কবরেজ তার মিথ্যে বিদ্যের\nঅহংকার প্রকাশ করবার উদ্দেশ্যে এবং সন্তান হিসেবে শিশুটিকে গ্রহণকারী নিঃসন্তান মাধব\nদত্তের কাছ থেকে অর্থোপার্জনের লক্ষ্যে শিশুটিকে একটি বদ্ধ ঘরে আটকে রেখে ওকে সুস্থ\nকরে তুলবার যে ব্যবস্থাপত্র প্রদান করে সেটি এ রকমের- শিশুটির শরীরে কোনোভাবেই শরতের\nআলো, হাওয়া লাগানো যাবে না। বদ্ধ ঘরের বাইরে ওকে কিছুতেই নেয়া যাবে না- এ সব করলে ওকে\nসুস্থ করে তোলা যাবে না, ওর রোগ বেড়েই চলবে। মধাব দত্ত শিশুটির মঙ্গলাকাক্সক্ষায় কবরেজের\nকথাই মেনে নেয়। অমলকে বদ্ধ ঘরের চার দেয়ালের ভেতরেই আবদ্ধ করে রাখে। কিন্তু এসব করেও\nঅমলের রোগ সারে না বরং দিন দিন ও আরও দূর্বল হয়ে পড়ে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অমল ওই ঘরের চার দেয়ালের বাইরে\nবেরিয়ে আসতে চায়। &nbsp;ঘরের একটি মাত্র খুব ছোট্ট\nজানালা দিয়ে ও বাইরে খেলাধুলারত ওর বয়সের ছেলে মেয়েদের খেলাধুলা দেখে, ওদের সঙ্গে কথা\nবলতে চায়। অমল শুনেছে ওদের বাড়ীর সামনে ডাকঘর বসবে। আরও শুনেছে ওর কাছে রাজার চিঠি\nআসবে। এসব শুনে ও জানতে চায় রাজার চিঠি কবে আসবে? কোন ডাকহরকরা সে চিঠি বয়ে নিয়ে আসবে,\nযে বা যারা বয়ে নিয়ে আসবে তাদের নাম কি? ছেলেরা ওকে বলে একজনের নাম বাদল, আর একজনের\nনাম শরৎ, আরও অনেক আছে। কখনও কখনও ওর ঘরের সম্মুখ দিয়ে হেঁটে চলা দইওয়ালাকে ডেকে বলে-যে\nরকম করে তুমি ডেকে বলো- ‘দই দই দই- ভালো দই’- এ সুরটি তুমি আমায় শিখিয়ে দাও।’ আবার\nকখনো বা শশী মালিনীর কন্যা সুধাকে কাছে ডেকে ওর কাছে ফুল চায়। ঘরের বাইরে বহুবিচিত্র\nকর্মচঞ্চল মানুষজনের কর্মকান্ড ও দেখে। ওই মানুষগুলি যেন ওর প্রাণ কেড়ে নেয়, ওর ছোট্ট\nএতটুকু মন আকুলি বিকুলি করে। ওদের সঙ্গে মিশতে না পেরে, ওদের সান্নিধ্যে আসতে ব্যর্থ\nহয়ে অমল উৎকন্ঠিত হয়, বিমর্ষ হয়ে পড়ে। সুদূরের প্রশান্ত নীলাকাশ যেন ওকে হাতছানি দিয়ে\nডেকে কাছে নিতে চায় কিন্তু অমল পারে না যেতে। ও জানালার পাশে নিশ্চুপ বসে থেকে দূর\nপাহাড়ের দৃশ্য অবলোকন করে। ছাতুর পুটলি বাঁধা লাঠি কাঁধে পথচলা পথিকের ঝরনার জলে পা\nডুবিয়ে পার হয়ে যাওয়া দেখে অমলও ওদের মতো করে বাইরে বেরিয়ে এসে পথ চলতে চায়। কিন্তু\nও কিছুই পারে না। কেবলই বেশী বেশী করে অসুস্থ হয়ে পড়ে।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এই যে নিস্পাপ শিশু মনের প্রাণ\nকেড়ে নেয়া, হৃদয় তোলপাড় করা আকুতি, সীমানা ছাড়িয়ে যাওয়া প্রকৃতির অপার সৌন্দর্য-সুধা\nপান করবার আকাক্সক্ষা, অসীমের মাঝে নিজেকে বার বার নতুন করে আবিস্কার করবার কামনা-\nএর সবকিছুকেই প্রতারণাপূর্ণ নিষেধাজ্ঞার ঢাকনা দিয়ে রুদ্ধ করা হয়েছে- এর অনিবার্য ফলটি\nপেয়েছে অমল চিরনিদ্রায় শায়িত হয়ে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঠাকুরদা যখন ওকে বলে- ওর কাছে\nরাজার চিঠি আসবে। শুধু চিঠিই নয় রাজ-কবরেজও আসবে এবং রাজার এ ছোট্ট বন্ধুটিকে দেখবার\nজন্যে স্বয়ং রাজাও আসবেন- তখন অমল পুলকিত হয়, কী এক অসীম আনন্দে উচ্ছ্বসিত হয়ে ওঠে\nঅমল। কিন্তু রাজার চিঠি আর আসে না, শুধু প্রতীক্ষাই সার হয় অমলের। তবে রাজদূত একদিন\nআসেন। সেদিনই সন্ধ্যার পর তিনি বদ্ধ ঘরের দরোজা ভেঙ্গে ঘরে প্রবেশ করে সকলকে জানিয়ে\nদেন- আজ মধ্যরাত্রিতে রাজা আসবেন রাজ কবরেজকে সঙ্গে নিয়ে তার এ বালক বন্ধুটিকে দেখবার\nজন্যে। এর মধ্যেই রাজকবরেজ গৃহে প্রবেশ করে বদ্ধ ঘরের সব জানালা, দরোজা খুলে দিয়ে অমলের\nশিয়রের বসে বলেন-‘ওর ঘুম আসছে, প্রদীপের আলো নিভিয়ে দাও, -এখন আকাশের তারাটি থেকে আলো\nআসুক। ওর ঘুম এসেছে।’ ঠিক তখনই শশী মালিনীর মেয়ে সুধা ফুল নিয়ে এসে ঘুমন্ত অমলকে দেখে\nকবরেজকে জিজ্ঞাসা করে- ‘ও কখন জাগবে?’ রাজ কবিরেজের উত্তরটি ছিলো-‘এখনি, যখন রাজা এসে\nওকে ডাকবেন।’ উত্তরে সুধা কবরেজকে বলেছিলো-‘তখন একটি কথা ওর কানে কানে বলো যে, সুধা\nওকে ভোলেনি।’ কী অপূর্ব, অদ্ভুত ভালো লাগা! কিন্তু সুধা জানে না যে, অমল আর কোনোদিনই\nএই ঘুম থেকে জেগে উঠবে না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখন যদি নাটকটিকে অতিব সূক্ষ্মভাবে\nবিশ্লেষণ করা যায় তাহলে দেখা যাবে- এই ঘুমটিই অমলের মৃত্যুর প্রতীক অর্থাৎ সংকেত। আবার\nযেহেতু এই মৃত্যুর মাঝেই অমল তার অসীমত্বকে প্রাপ্ত হয়েছে। যেটি তার জীবদ্দশায় সম্ভব\nহয়ে ওঠে নি মানুষেরই সৃষ্ট কিছু উদ্দেশ্যাশ্রিত নিষেধাজ্ঞার কারণে। সেইহেতু সর্বশেষ\nবিশ্লেষণে অমলের মৃত্যুই এ নাটকের অসীমতার প্রতীক অথবা সংকেত। ডাকঘরটি বিশ্ব-প্রকৃতির\nরূপক । আর রাজা স্রােষ্টার প্রতীক। প্রকৃতির এই ডাকঘর থেকে রাজার চিঠি দিবারাত্রি ছয়টি\nঋতু ডাকহরকরার রূপক হিসেবে প্রতিটি মানুষের ঘরে ঘরে পৌঁছে দিচ্ছে কালের ক্রমান্বয়িকতার\nপথ ধরে। সে সূত্র সঙ্গত কারণেই এখন এ কথা নিঃসঙ্কোচে বলা যায় যে, ‘ডাকঘর’- নাটকটি অত্যন্ত\nনির্জলাভাবে সাংকেতিক নাটকের ক্ষেত্রে একটি মাইলষ্টোন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রবীন্দ্রনাথের উল্লেখিত অবশিষ্ট\nনাটকগুলিও রূপক এবং সংকেতাশ্রিত। তবে সেগুলির মধ্যে বিশেষতঃ ‘রাজা’ এবং ‘কালের যাত্রা’-\nনাটক দু’টিতে বোধকরি সাংকেতিকতা একটি ভিন্ন মাত্রা লাভ করেছে। নাটকের মূল বিষয়বস্তুর\nপূর্ণাঙ্গ ভাব প্রকাশের ক্ষেত্রে রূপক এবং প্রতীক অথবা সংকেত-এর প্রয়োজন যে অনিবার্য-\nএটি রবীন্দ্রনাথ অত্যন্ত সফলভাবে প্রমাণ করেছেন। রবীন্দ্রনাথের এ জাতিয় অন্যান্য নাটকগুলি-\nযেমন, শারোদোৎসব, ফাল্গুনী, অচলায়তন, মুক্তধারা, রক্তকরবী প্রভৃতিতে এ প্রমানের দৃষ্টান্ত\nউজ্জ্বল। সে কারণে এ নাটকগুলিকে নিয়ে আর বিশদ আলোচনা করা হলো না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Phenomenal form of creation–\nএর আভ্যন্তরীক পরিমন্ডলে যে বোধের স্থিতি সীমাহীন সকর্মক শক্তিতে বিশ্বাসী এবং বলবান,\nঅন্ত এবং অনন্তের মধ্যবর্তী অঞ্চলকে নিয়ে মগ্ন চৈতন্যের অন্তরালে আত্মদর্শনের নিজস্ব\nদর্পনে অতলান্তিক আত্মোদ্ধারের যে প্রবৃত্তি নিচয়ের নিঃসৃত বেগ সঞ্চারী উপস্থিতি -\nযা শেষ মুহূর্তে ইচ্ছাবিরোধী, একই সাথে রূপক এবং সাংকেতিকতার অন্তর্গত নিজস্বতায় আশ্রয়\nখোঁজে নিজস্ব নিয়মেই। মনে করা হতে পারে তার প্রভাবাশ্রিত যুগন্ধর বিকাশও স্বাভাবিক\nপদ্ধতিতে রূপান্তরিত হয়ে যায় অধিবাস্তববাদী ইনফিজিবল এবং ইনভিজিবল জটিলতায়। কিন্তু\nপ্রকৃত অর্থে তা নয়। মূলতঃ অন্ত এবং অনন্তের সীমা এবং অসীমের মৌলিক দ্বিধা দীর্ণতায়\nপ্রতিযোগী প্রেরণা প্রাপ্ত হয়েই এবং সে বিরোধের সূত্র ধরেই শেষ পর্যন্ত creation’ টি আশ্রয় গ্রহণ করে\n‘রূপক’ অথবা ‘সাংকেতিকতা’য়। তবে সাংকেতিকতায় আশ্রয় গ্রহণ করবার লক্ষণটিই অধিক মাত্রার।\nসঙ্গত কারণেই তখন আর এটিকে ‘অধিবাস্তবতা’র মোড়কে আবৃত করে গ্রহন করা যায় না। কেননা\n‘বাস্তব’ বাস্তবই। ‘বাস্তব’ শব্দটির সম্মুখে “অধি’- নামীয় আর একটি শব্দকে আরোপ করে,\nঅতি-অবাস্তবকে “অধিবাস্তব’-বানিয়ে দিয়ে বাস্তবতাকে উদ্ধার করা যায় না। করলে সেটি ‘মেকী’-\nহয়ে যায়। বাস্তব এবং অধিবাস্তবের মাঝে যে ব্যবধান তা কখনই হ্রাসপ্রাপ্ত হয় না। বরং\nউভয়ই দ্বিধা-দীর্ণ হয়ে যায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেশজ উৎপাদনের বিস্তৃতিতেও সে\nপ্রত্যক্ষ প্রবাহী দ্বিধাদীর্ণিত বিরোধের অনিবার্য আর্বিভাব ন্যূনতম ক্ষীণদেহীতায় উৎকীর্ণিত\nহলেও বিস্তৃতির সার্বিক পরিধিতে তার উদ্দাম প্রাবল্য যেকোন অর্থেই দূর্লক্ষ্য তো নয়ই\nবরং অনুপেক্ষণীয়। দেশীয় নাট্যকার সাইদ আহমেদ - ঐ শ্রেণিগত চিত্ত চৈতন্যের প্রখর রৌদ্রালোকে\nঅনন্তর উদ্ভাসিত হয়েছেন তার - ‘কালবেলা’ নাটকে- প্রচন্ডতম বিরোধের প্রচন্ডতম বিস্ফোরণ\nঘটিয়ে। কিন্তু তারপরেও তিনি অধিবাস্তবতার ওপর বিশ্বাস স্থাপন করতে না পেরে শেষ পর্যন্ত\nআশ্রয় গ্রহণ করেছেন সাংকেতিকতার ওপর। যার যথার্থ প্রমাণ পাওয়া যায় তার ‘কালবেলা’-নাটকের\n‘লোকটা’- নামীয় একটি চরিত্রের কন্ঠ থেকে উচ্চারিত একটি সংলাপ থেকে। ‘কালবেলা’- নাটকের\n‘লোকটা’- নামে চিহ্নিত চরিত্রটির উচ্চারিত সংলাপটি এ রকমের-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘লোকটাঃ এখানে ঘোরেও না কিছু, হেলেও না কিছু। সবকিছুর উর্দ্ধগতি- এই অন্ধকার গোলক ধাধা থেকে মুক্তির একমাত্র উপায়।’ অস্তিত্বের কেন্দ্রবিন্দু উদ্ধারে মূল্যায়নগতভাবে ইন্দ্রিয়জঃ জ্ঞানের যে বিভিন্নতা স্বতঃসিদ্ধ সে জ্ঞানের পরিধিতে বিচরণ করেই ‘লোকটা’-যখন উচ্চারণ করে- ‘সবকিছুর উর্দ্ধগতি- এই অন্ধকার গোলক ধাধা থেকে মুক্তির একমাত্র উপায়।’ ‘উর্দ্ধগতি’- অর্থাৎ অগ্রগামীতাকেই যখন স্থবিরতা থেকে, গোলক ধাধা থেকে মুক্তির প্রথম এবং সর্ব শেষ পন্থা হিসেবে স্থির করা হয় তখন অন্ধকার থেকে আলোর পৃথিবীতে প্রবেশ করে মুক্তির অপরিমেয় প্রাণভরা আস্বাদ লাভ করবার একমাত্র সংকেত হয়ে দাঁড়ায় ‘অগ্রগামীতা’-যা উর্দ্ধগতির প্রতীক। আর প্রতীক অথবা সংকেতের সার্থকতা এখানেই। এবং কোনোভাবেই যে অধিবাস্তবতা প্রকৃত বাস্তবতা নয়- এটিই চিরন্তণ সত্য।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © সরদার মোহাম্মদ রাজ্জাক<br></p>\n<!-- /wp:paragraph -->', 'ধারণামন্ডিত নাট্যগঠনরীতির মৌলিক উৎসমুখ চিরন্তন উপলব্ধিজাত অনুসন্ধিৎসার অনিশ্চিত, অস্থির, অনির্দিষ্ট এবং অলৌকিক একটা কিছু প্রাপ্তির অনির্বচনীয় সুখবোধে আক্রান্ত অতি সূক্ষ্ম অথচ সংহত একটি চরম উত্তেজিত আ...', '', 3, NULL, 'publish', 3428, 0, '2019-01-29 14:22:14', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (20, 2274, 23, 'দিনের শেষে', 'দিনের-শেষে', '<!-- wp:paragraph -->\n<p>তিহান কে আমি বললাম থাপ্পড় খাবি?<br>তিহান বললো, \\"হ্যা খাবো। তবে বেশি করে ঝাল মরিচ মাখিয়ে দিস। জানিস ই তো আমি মিষ্টি জিনিস খেতে পারি না।\\"<br>রাগে আমার গা কিড়মিড় কিড়মিড় করছে।<br>তিহান আমার কাজিন। বয়সে সপ্তাহ খানিকের বড়। মাঝে মাঝে এমন ভাব নেয় যে আমার কত গুরুজন ও। যদিও আমি তেমন পাত্তা দিই না। <br>আজ যেমন ছুটতে ছুটতে চলে আসছে। বলে কি, “স্পৃহা দেখ দেখ আমাদের বাসার ছাদে একটা হুনুমান এসেছে একদম তোর মত দেখতে। একসাইডে সিঁথি করে দুইটা ক্লিপ মেরে দিলে হুবহু তুই।\\"<br>আমি রাগে দাঁত কটমট করতে করতে ওকে জব্দ করার উপায় খুঁজতে লাগলাম। <br>অবশ্য বেশি দেরি করা লাগলো না। বিকাল নাগাদই অস্ত্র পেয়ে গেলাম। রান্নাঘরে একটা ইঁদুর মরে ছিলো। গন্ধে টেকা যাচ্ছিলো না। কাজের মেয়ে ঝাড়ু দিয়ে বাইরে বের করে আনতেই ওর সাথে প্ল্যান করতে বসে গেলাম। মাগরিবের নামাজের পর ওর সাথে চুপিচুপি মই নিয়ে গিয়ে তিহানের জানালার নিচের ওয়ালে স্কচটেপ দিয়ে ভালোমতো ইঁদুর টাকে এঁটে দিয়ে আসলাম। <br>আমার সাথে বাদঁরামি। নে এইবার সারা রাত ইঁদুরের গন্ধ খা</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্পৃহাকে রাগাতে এত ভালো লাগে আমার। অল্পতেই রেগে যায় মেয়েটা। আর রাগলেই  নাকের পাটা ফুলে যায়। চোখ দিয়ে মনে হয় আগুনের ফুলকি বের হচ্ছে। এত কিউট  লাগে দেখতে। এজন্যই ওকে এত বেশী রাগাই। অবশ্য আজ মনে হয় একটু বেশী বেশীই  হয়ে গেছিলো। যেভাবে হাতের মুঠি পাকিয়ে ছিলো আরেকটু হলেই মনে হয় ঘুষি খেতাম।<br>  কিন্তু আমার ঘরের ভিতর এমন বিদঘুটে গন্ধ আসছে কোথা থেকে। সারাঘর আতিপাতি  করে খুঁজেও কিছু পেলাম না। নাকমুখ গুঁজে লাইট অফ করে ওর ভিতরেই শুয়ে পড়লাম।  কিন্তু রাত দুইটা নাগাদ আর সহ্য করতে পারলাম না। ঘুমের ভিতরেও যেন নাকে  গন্ধ ধাক্কা দিচ্ছে। শেষমেশ কাঁথা বালিশ নিয়ে ড্রয়িংরুমের সোফায় শুয়ে রাত  কাটালাম। সকালে উঠতেই দেখি মাথা একপাশে ঘুরাইতে পারছিনা। ঘাড়ে চরম ব্যাথা।  বুঝলাম সোফায় শোয়ার জন্যই এই অবস্থা। রুমে ঢুকতেই আবার সেই বিকট গন্ধ।  আম্মু আমি আর তিতুন মিলে দু\'ঘন্টা ধরে সারা রুমের আনাচে-কানাচে,তোষক বালিশ  উল্টিয়ে পাল্টিয়েও গন্ধ বের হবার মত কিছু খুঁজে পেলাম না। শেষে দুই বোতল  এয়ার ফ্রেশনার, বডি স্প্রে দিয়ে গন্ধ তাড়াতে চেষ্টা করলাম। তিতুন তো ভয়ে  ভয়ে বলছে, \\"ভাইয়ার ঘরে নিশ্চয় জ্বিন ঢুকছে। এটা জ্বিনের গায়ের গন্ধ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বদটার উপযুক্ত শাস্তি হয়েছে। এখন নাকি ঘাড় ঘুরাইতে পারছে না। তিতুনের কাছ  থেকে সব কিচ্ছাকাহিনী শুনে খুশিতে আমি বাকবাকুম। আমার সাথে মামদোবাজি করার  ফল এখন বুঝুক।তিতুনের হাত ধরে লাফাইতে লাফাইতে ওদের বাড়ি যেয়ে বললাম, \\"কিরে  তিহান ভূতে নাকি তোর ঘাড় মটকায়ে দিছে?\\" <br> তিহান ম্লান হেঁসে বললো, \\"আর বলিস না, রাত থেকে কি উৎপাত ই যে শুরু হইছে, দুচোখের পাতা এক করতে পারছি না।\\"<br>  তিহানের ম্লান মুখের দিকে তাকিয়ে হঠাত করেই আমার বুকের ভিতর ধ্বক করে  উঠলো। খুশিতে আত্মহারা হওয়ার বদলে আমার কেমন যেন কষ্ট কষ্ট একটা মিশ্র  অনূভুতি হচ্ছে। আমি ছলছল চোখে তিহানের দিকে তাকিয়ে রইলাম</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্পৃহা ইদানীং আমার সাথে কেমন যেন ছাড়া ছাড়া একটা আচরণ করছে। ঠিক বুঝে  উঠতে পারছি না। গত সাতদিনে তো ওর সাথে এমন কোন অন্যায় করিনি। তাহলে হইলো কী  ওর? নাহ একবার ভেবে দেখতে হচ্ছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> -কিরে স্প্রিং কি করিস?<br> -আমাকে স্প্রিং বলবি না কিন্তু।<br> -আচ্ছা যা বলব না। কিন্তু আমাদের বাড়ির ছাদে তুই কী করিস? তোদের ছাদ নাই, যা।<br> -যাচ্ছি। থাক তুই তোর ছাদ নিয়ে।<br> -বাপরে! একবার বলতেই চলে যাচ্ছিস। তুই এত ভদ্র হলি কবে থেকে?<br> স্পৃহা কোন উত্তর না দিয়ে নিচে নেমে এল। ইদানীং তিহানের তুচ্ছ করে বলা যেকোন কথাতেই হুটহাট করে ওর চোখে পানি চলে আসে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তিহান ভ্যাবলার মত কিছুক্ষণ একলা ছাদে দাঁড়িয়ে থাকল। অন্য কোনদিন হলে  স্পৃহাকে তো বকে বকেও নিচে পাঠানো যেত না। আজ কয়দিন কি যে হয়েছে ওর একেক  সময় একেক আচরণ করছে। তিহান কিছুই বুঝে উঠতে পারছে না</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বড় খালার  বাড়িতে এ কয়দিন খুব মজা হলো। তিহানের মনটা আজ বেশ ভালো। বড়খালু সৌদি থেকে  দেশে ফিরেছে, সবার জন্যই কমবেশি জিনিসপত্র নিয়ে এসেছে। খালা তাই খবর  পাঠিয়েছিলো। তিহানের সবচেয়ে পছন্দ হয়েছে ওর হাতঘড়িটা। তিতুনের জন্য ফোন  নিয়ে এসেছে একটা। তিহান অবশ্য সুযোগে আছে তিতুনকে পটিয়ে ফোনটা নিজের করে  নেওয়া যায় কিনা। অবশ্য তিতুন যে বজ্জাত মেয়ে, নাও দিতে পারে। তবে এজন্য  স্পৃহাকে পটাতে হবে। তিতুন আবার স্পৃহা বলতে পাগল। স্পৃহা যা বলে তিতুন তাই  শোনে। বাস থেকে নেমে এইসব হাবিজাবি ভাবতে ভাবতেই তিহান বাড়ির কাছে পৌছে  গেল।<br> .<br> বাসায় ঢুকে আম্মু আম্মু বলে ডেকেও যখন কাউকে পাওয়া যাচ্ছে  না তখন ব্যাগটা নামিয়ে রেখে \'গেলো কোথায় সবাই\' বলে নিচে নেমে স্পৃহাদের  ওখানে আম্মুকে খুঁজতে যাচ্ছি। উঠানেই ছোট চাচ্চুর সাথে দেখা। আমার হাতে  পাঁচশো টাকার একটা নোট দিয়ে বললো, \'তাড়াতাড়ি বাজারের থেকে দই নিয়ে আয়।  বড়ভাই ভুল করে টকদই নিয়ে চলে আসছে। মেহমানদের সামনে বেইজ্জতের একশেষ।\'<br> কিসের মেহমান কিসের কি শোনার আগেই ছোট চাচ্চু উধাও। তাড়াতাড়ি করে দই আনতে ছুটলাম।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>\n দই নিয়ে চাচীদের ড্রয়িং রুমে ঢুকতেই দেখি একগাদা মানুষ। আম্মু তাড়াতাড়ি \nআমার হাত থেকে দই নিয়ে পিরিচে পিরিচে বাড়তে শুরু করে দিয়েছে। কারা এসেছে \nকিসের কি হচ্ছে এটা যে কারো কাছে শুনব সেই সুযোগও নেই। সবাই মহা ব্যস্ত। \nবিরক্ত হয়ে সাবিতের রুমে ঢুকলাম, দেখি আমার ছোট স্পাই কোন খবর দিতে পারে \nকিনা। স্পৃহা আমাকে যতটা অপছন্দ করে ওর ছোটভাই সাবিত আমার ঠিক ততটাই ভক্ত। এ\n বাড়ির সব খবরাখবর আমি সাবিতের কাছ থেকেই পাই।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> ঘরে ঢুকে দেখি স্পৃহা খুব সেজেগুজে বসে আছে।<br> \'কিরে ভূতনী এত সাজছিস ক্যান? তোর বিয়ে নাকি?\' হাসতে হাসতেই জিজ্ঞাসা করলাম। <br> স্পৃহা উত্তর দিলো, \'ওদের দেখে পছন্দ হলে আজই বিয়ের ডেট ফাইনাল করে যাবে।\'<br> -তোকে সত্যি সত্যি দেখতে আসছে?<br> -কেন তুই জানিস না?<br> -জানব কিভাবে। তুই কি বলছিস আমাকে?<br> -তুই যে খালার বাসায় বেড়াতে গেছিস সেটা বলছিস আমাকে?<br> -আমি খালার বাসায় তোকে বলে যাইনি তাই তুই বিয়ে করে ফেলবি?<br> -আমি কি বলেছি আমি বিয়ে করব?<br> -বিয়ে করবি না তাইলে এত সাজগোজ করছিস কেন?<br> -আমি সাজছি তাতে তোর সমস্যা কী?<br> - আমার সমস্যা থাকবে কেন?<br> -তিহান শোন আমার মেজাজ খারাপ করবি না।<br> -তুই ই আমার মেজাজ খারাপ করছিস।<br> -তুই যা এখান থেকে।<br> -তুই যা।<br>  স্পৃহার সাথে ঝগড়াঝাঁটি করে ঘরে এসে শুয়ে থাকলাম।স্পৃহাকে ছেলেপক্ষ দেখতে  আসছে অথচ দুইবাড়ি মিলে কেউ আমাকে জানাতে পারল না। অন্তত স্পৃহার তো উচিত  ছিলো আমাকে একটা ফোন দিয়ে জানানো। বাড়ির সবার প্রতি চাপা একটা অভিমান নিয়ে  রাত্রে না খেয়েই ঘুমিয়ে পড়লাম।<br> সকালে ঘুম থেকে উঠেই আম্মুর রুমে গেলাম। <br> আম্মু তখনও নামাজের পাটিতে। কোরআন শরীফ পড়বে বোধহয়। আমি কোন ভূমিকা না করে সরাসরি বললাম, \'আম্মু আমি স্পৃহাকে বিয়ে করব।\' <br> ঘরের ভিতর একটা বাজ পড়লেও মনে হয় আম্মু এতটা অবাক হত না যতটা অবাক আমার কথা শুনে হল।<br> আমার নিজের কণ্ঠই আমার কাছে অপরিচিত শোনা যাচ্ছিলো।মনে হচ্ছিলো আমি না কেউ যেন আমার কণ্ঠ দিয়ে কথা বলিয়ে নিচ্ছে।<br>  পরপর কয়দিন এটা নিয়ে বাড়ির সবাই মিলে একসাথে বসাবসি করে খুব গ্যাঞ্জাম আর  কথা কাটাকাটি হল। অবশেষে সবাই মেনে নিল। ঠিক হল এখন শুধু বিয়ে পড়িয়ে রাখা  হবে, আর আমি চাকুরি পাবার পর স্পৃহাকে এবাড়িতে তুলে আনা হবে।<br> কিন্তু  বেঁকে বসল স্পৃহা। আমাকে নাকি সে কখনো ওইভাবে দেখেনি। আমাকে নাকি তার কাছে  বর বর লাগে না। এটা কোন কথা হইলো! স্পৃহা যে পুরো ব্যাপারটা এভাবে ভন্ডুল  করে দিবে এটা আমার ধারণাতেও আসেনি। স্পৃহাকে সবাই যখন আরো বোঝাতে গেলো ও  আরো বেঁকে বসল। সব মিলিয়ে ব্যাপারটা এমন ভজগট পাকিয়ে গেল যে আব্বু বড়চাচার  সামনে আর চাচী আম্মুর সামনে কথা বলতে অস্বস্তিতে ভোগে। আর স্পৃহার সাথে তো  আমার এরপরে আর দেখাই  হয় না। ও আমাদের এখানে আসা একেবারে বাদ দিয়ে  দিয়েছে।আমিও আর লজ্জায় ওই বাড়িমুখো হই না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঈদের আগেরদিন রাত্রে  চাঁদ দেখার জন্য সবাই ছাদে উঠেছে। পিচ্চিপাচ্চারা সব হৈচৈ গ্যাঞ্জাম করছে।  স্পৃহা দেখি রেলিং এ ভর দিয়ে এককোণায় দাঁড়িয়ে আছে। আমি কাছে এগিয়ে গেলাম। ও  একটু চমকে উঠে আমার দিকে ঘাড় ঘুরিয়ে তাকালো।<br> আমি বললাম, \'তুই আমাকে বিয়ে করবিনা কেন স্পৃহা?\'<br> স্পৃহা বলল, \'তুই যে আমাকে বিয়ে করতে চাস এটা আমাকে বলেছিস কখনও?<br> আমি মিনমিন করে বলার চেষ্টা করলাম, \'আমি যে তোকে ভালোবাসি তাইতো আমি সেদিনের আগে পর্যন্ত জানতাম না।\'<br>  স্পৃহা দেখি রাগে গজগজ করছে আর বলছে, \'সারাদিন স্প্রিং স্প্রিং করার কথা  মনে থাকে আর ভালোবাসার কথা বলতে মনে থাকে না মানুষের। যা তোর কিচ্ছু বলা  লাগবে না।\'</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্পৃহার সাথে আমার বিয়ের ছয় বছর পূর্ন হল আজ। অবাক করা বিষয় হচ্ছে আমি আজও ওকে কখনো মুখে ভালোবাসি বলি নাই</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভালোবাসা কি শুধু বলার বিষয়? কখনও কখনও ভালোবাসা শুধু উপলব্ধির। একে ধারণ  করতে হয় বুকের মধ্যিখানে। হারিয়ে যেতে দিতে নেই। তাই মুখে হাজারবার  ভালোবাসি বলার থেকে স্পৃহার মুখে হাসি এনে দিতেই আমি বেশি ভালোবাসি। কিন্তু  আমার পাগলি বউটা এটা বোঝে না, সে সারাদিন শুধু কানের কাছে মেশিনের মত  বলতেই থাকে আমি তাকে ভালোবাসি না। আমি আর কি করব আপাতত তার কথা এক কান দিয়ে  শুনি আর আরেক কান দিয়ে বের করে দিই। ভেবেছি আমাদের বিয়ের দশম বর্ষ  পূর্তিতে তার কানে একশবার ভালোবাসি বলব। দেখি সে এতে কত সুখ পায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © তামান্না স্নিগ্ধা</p>\n<!-- /wp:paragraph -->', 'তিহান কে আমি বললাম থাপ্পড় খাবি?\nতিহান বললো, \\"হ্যা খাবো। তবে বেশি করে ঝাল মরিচ মাখিয়ে দিস। জানিস ই তো আমি মিষ্টি জিনিস খেতে পারি না।\\"\nরাগে আমার গা কিড়মিড় কিড়মিড় করছে।\nতিহান আমার কাজিন। বয়সে সপ...', '', 9, NULL, 'publish', 2150, 0, '2019-01-30 14:09:27', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (21, 2291, 24, 'দেহ', 'দেহ-১', '<!-- wp:heading {\\"level\\":3} -->\n<h3>এক</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>পান্থপাদপেরা পাখা মেলে দাঁড়িয়ে থাকে, যেনো নরম অতীত; বিকেলের শান্ত আলোয় দেখা সেই কিশোরী চিবুক! অতীতেরা সাধারণত একান্নবর্তী। দুঃখরা সংসারী হলে চুম্বনেরা চলে যায় বনবাসে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চুম্বনের কথা উঠলে চোখের মাদকতায় জলকেলি খেলে কমলা সুন্দরী, প্রেমিক মন তবু সংশয়ী। অন্য পুরুষের ঠোঁটে স্ত্রীকে চুমু খেতে দেখা সেতারবাদকের সুরে দুঃখ গড়ালে, শিখে নিই উপেক্ষার মন্ত্র।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তোমাকে উপেক্ষা করেছিলাম বলে ভ্যাসলিনের কাটতি বেড়ে গিয়েছিলো বাজারে; আমরা রেখে এসেছি এইসব সম্ভাবনা। গলির মোড়ে, দেয়ালে দেয়ালে; বৈদ্যুতিক খুটির দূরত্বে রেখে এসেছি আমাদের স্পর্শ। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বৈদ্যুতিক তারে লটকে থাকা বাদুড়ের জীবন নিয়ে কি করে এগোই বলো! বরং এসো আমাদের গোপন গল্পের জন্য শ্মশানে চণ্ডালের কাছে যাই, আত্মাদের আড্ডায় বসে কাঠ আর ঘিয়ের অনুপাত নির্ণয় করি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>দুই</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>তাকাও আমার দিকে, কেননা আমি তোমার চোখের দিকে তাকিয়ে পার করে দেবো সৌরচক্র। তাকাও অপলক, যেনো কোনোভাবেই আমার চোখ অন্যকিছু না দেখে; কেননা সেইসব বিষ-দৃশ্য আমাকে হত্যা করবে বার বার! আমি বাঁচতে চাই!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দোহাই, তোমার ওই চোখ থেকে আমাকে সরতে দিও না, তাহলে সর্বনাশ হয়ে যাবে! কেননা আমি তাহলে দেখে ফেলবো মানুষের ভয়ানক রূপ! অথবা মুখোশের আড়ালে কিরকম বীভৎস বাসনায় লিপ্ত!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তাকাও আমার দিকে, দেখো এই চোখে কোনো পাপ নেই; কেবল আগুন পাবে এখানে। হে সুন্দর, তোমার চোখ থেকে আমাকে বঞ্চিত করো না; আমি যে দেখতে চাই না কোনো অসুন্দর! আমাকে আশ্রয় দাও, আমাকে ভস্ম করো! পবিত্র করো!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>তিন </h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>তোমার চোখে কিছুই লেখা ছিলো না হয়তো, তবু আমি পড়তে চাইতাম। তোমার গালে, ঠোঁটে কোনো অলৌকিকতা ছিলো কি না জানি না; অপার রহস্যময়তায় হারাতাম বারবার!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এভাবে একদিন পাখির মৃত্যুকে বীভৎস ভেবে তোমার বুকে চোখ বুজেছিলাম। ওখানে কোনো ধর্মশালা না থাকলেও পবিত্রতার প্রলেপে একটা প্রেমময় আকাশ ছিলো হয়তো! না হলে এমন উড়লাম কী করে!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমাদের সেইসব জড়াজড়ি বিকেল, আর সন্ধ্যাগুলো আলোচ্য হয়েছিলো যাদের টেবিলে, আড্ডায়; চায়ের কাপে কিংবা মদের গেলাসে চুমুক দিতে দিতে তাঁরা কোনোদিন ভাবতেই পারেনি আমাদের যৌথযাপনের রহস্য! জানতে পারেনি আমি তোমার পুরুষ, অথবা তুমি আমার নারী। অথবা আমরা বিসর্জন দিয়েছিলাম পরস্পরের দূরত্ব!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>চার</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>নাভি থেকে নেমে গেছে চাঁদ, চোখের চৌবাচ্চায় ঘুমের সাঁতার, চুমুরা গেছে নক্ষত্রপাড়ায়; আমাদের রাতগুলো দেহ ছেড়ে অন্য কোথাও চলে গেছে হয়তো। নইলে বালিশ কেন আলাদা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমাদের আঙুল থেকে একদিন চুইয়ে নামতো রোদ, উত্তাপে উত্তাপে দুমড়ে যেতো হাড়ের বসতি! রোমশবনে নেচে নেচে হাঁপাতো ‘বনিএম’! কোরাসে কোরাসে গেয়ে যেতো ‘রাশপুটিন’!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একদিন আমাদের ত্বক থেকে ত্বকে প্রবাহিত হতো বিদ্যুৎ! দূর থেকেই টের পেতাম রক্তের যাতায়াত! ঘামের গন্ধ কী তা জানতামই না, নাসারন্ধ্রে কেবল চুলের সৌরভ, ঠোঁটের ঘ্রাণ!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখন আমাদের পিঠজুড়ে কেবল শীতের আবাস, বুকের কপাটে নেই সেই জলের উল্লাস! এখানে এখন বয়সী বৃক্ষের স্থবিরতা। শুকনো নদীর পারে যেমন সারি সারি নৌকার উপুর শুয়ে থাকা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>পাঁচ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>আঙুলের নৈঃসঙ্গ টের পায় করতল, কনুইয়ে ভর করে অপেক্ষা করে বাহু, একটা আস্ত সাহারা লেপ্টে আছে বুকজুড়ে! তুমি জানোনি কোনোদিন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যে রাস্তায় তুমি হেঁটে যেতে রোজ, দাঁড়াতে, অপেক্ষা করতে; সে রাস্তার ধুলোরাও প্রিয় ছিলো খুব! ল্যাম্পপোস্ট, দেয়াল, ছেড়া পোস্টার, ম্যানহোলের ভাঙা মুখ; মুখস্থ সব!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তুমি জানোনি এইসব অপচয়, পায়ে পায়ে হেঁটে যাওয়া ঘুরপথের গল্প বলিনি তোমায়; কারণ সব কথা বলে দিলে হৃৎপিণ্ড ফাঁকা হয়ে যায়। তাহলে আমার আর কিছুই থাকে না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তুমি তো ছিলে না কোনোদিন, অথবা যদি না থাকো, তবে ওই রাস্তার রহস্যগুলো অন্তত থাক; সব দেহ মজে না দেহের খোলসে, কোনো কোনো দেহে থাকে মনের প্রাসাদ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>ছয়</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>বাইরে ঝড়! বাইরে রোদ! বাইরে হিমশীতল! বাইরে মেঘলা আকাশ! বাইরে যেও না। এখন আর বলে না কেউ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রাতের তারারা থাকে বুকের কাঁপনে! মিটিমিটি জ্বলে দুঃখ! সহজে হয় না সহজ কাজ; হারানো প্রহর ফেরে না কখনো, কচুর পাতায় এখন আর জলেরা দাঁড়াতে চায় না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেহ থেকে মন আলাদা হলে দেহে আর কোনো প্রেম থাকে না; তখন দলিতমথিত প্রত্যঙ্গরা অহেতুক হাঁপায় শুধু!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাইরে প্রেমিক, বাইরে পুরুষ, বাইরে ধার্মিক, বাইরে মানুষ! বাইরে যেও না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>সাত</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>কালো মেয়ের নাকে নোলোক<br>\nকালো মেয়ের চোখে কাজল<br>\nকালো মেয়ের ঠোঁটে হাসি<br>\nএইসব চিন্তার উঠোনজুড়ে দুর্ভাবনারা বসে থাকে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ও মেয়ে তুমি কেঁদো না<br>\nও মেয়ে তুমি ভেবো না<br>\nও মেয়ে তুমি জেগো না<br>\nএকদিন কেউ এসে বলে যাবে<br>\nএই অপেক্ষায় কাটানো বেলা শেষে<br>\nসকলেই বলে গেলো: রঙটা আরেকটু উজ্জ্বল হলে কেটে যেতো মেঘ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটা উজ্জ্বল চকচকে রিং<br>\nসোনার হোক, রুপার হোক<br>\nএকটা নিবিড় আংটির জন্য<br>\nঅপেক্ষা করে অনামিকা<br>\nঅপেক্ষা করে কালো দেহের অভিশাপে দগ্ধ কালো মেয়ে!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আর ওইদিকে দুনিয়া মাতিয়ে গেলো ‘বনি এম’<br>\nকালো মানুষের গলায় সুর মেলালো নাচলো, গাইলো, সাদা সাদা মানুষেরা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পল রোবসন, মাইকেল, বব মার্লে<br> কালো কালো দেহ নাচিয়ে গাইলো জীবনের গান, মানবতার গান।<br> আর পৃথিবীর সকল রাজপথ আর জেলখানায় পৌঁছে গেলো সেইসব মানুষের খবর! যেখানে লেখা ছিলো কালো কালো অক্ষরে কালো কালো মানুষের নাম---মার্টিন লুথার কিং, নেলসন ম্যান্ডেলা…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>আট</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>একটা অদ্ভুত সুর বেজে গেলো চিরকাল… হাড়ের গিটারে, শিরার তারে তারে টুং টাং… টুং টাং…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সেই সুর বাজাতে চাইলাম বারংবার! যে সুর অবিরাম মরুভূমির মতো বিশুষ্ক প্রান্তরে প্রান্তরে ফোটাতে পারতো সবুজ পাতা, হলুদ ফুলের মতো উজ্জ্বল দুপুর; প্রেয়সীর হাসির মতো বৈকালিক উদ্যানে মেলা বসাতে পারতো যে সুর। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>খুঁজলাম সেই বাদকের ঘরবাড়ি, পেলাম না কোথাও। কেবল কান পেতে শুনলাম সেই সুর! অন্তর্গত বেদনার মতো একাই বাজালাম, একাই গাইলাম। কেউ শুনলো না সেই সুর, জানলো না কেউ কোনোদিন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\\"level\\":3} -->\n<h3>নয়</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>তোমার দিকে ধেয়ে এলো নদী<br>\nতোমার দিকে ছুটে এলো সড়ক<br>\nতোমার দিকে নেমে এলো চাঁদ<br>\nতবু তুমি গুটিয়ে যেতে থাকলে নিজের দিকে!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটা বিষণ্ন সাপের সাথে খেলছিলো ঝগড়াটে রোদ<br> একটা রাগি বেজির সাথে হাসছিলো বৃষ্টির জল<br> আর আমি পান করে নিলাম বিষের গেলাস!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটা দৃশ্য বদলে দিতে পারে এইসব আখ্যান<br>\nএকটা চাহনি পালটে দিতে পারে চলার গতি<br>\nআর আমিও পেরিয়ে যেতে পারি লোকালয়<br>\nফেলে আসতে পারি সকল সম্ভাবনা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তোমার উপস্থিতিই কেবল খুলে দিতে পারে সকল সম্ভাবনার দ্বার, পূর্ণ করতে পারে সকল আয়োজন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> </p>\n<!-- /wp:paragraph -->', 'এক\nপান্থপাদপেরা পাখা মেলে দাঁড়িয়ে থাকে, যেনো নরম অতীত; বিকেলের শান্ত আলোয় দেখা সেই কিশোরী চিবুক! অতীতেরা সাধারণত একান্নবর্তী। দুঃখরা সংসারী হলে চুম্বনেরা চলে যায় বনবাসে।\nচুম্বনের কথা উঠলে চোখের মাদকতা...', '', 4, NULL, 'publish', 3294, 0, '2019-02-01 13:17:45', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (22, 2304, 25, 'বোবা জানালা', 'বোবা-জানালা', '<!-- wp:paragraph -->\n<p>তোমার মাথার উপরে আকাশ,<br>তোমার পায়ের নিচে মাটি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেয়ালে টিকটিকি ঘুমায়, পর্দা সরালেই খোলা জানালা<br>জানালার রেলিঙে আমি বিষণ্ণ কাক দেখি<br>জানালা খুলে দিলে, দেখি তোমার চোখ।  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বোবা জানালা বোঝে না মানুষের ভাষা<br>তবু যতটুকু বোঝা যায়, কবিতার মতো<br>তবু যতটুকু চাওয়া যায়, প্রেমিকের মতো<br>আমি জানি, কাক আমার দিকে ফিরেও তাকাবে না কোনদিন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> তুমি ঘরের ভেতরে গেলে, আকাশ কোথায় রাখো<br>দুয়ার খুলোনি তুমি বহুদিন হলো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © পার্থ মল্লিক</p>\n<!-- /wp:paragraph -->', 'তোমার মাথার উপরে আকাশ,\nতোমার পায়ের নিচে মাটি।\nদেয়ালে টিকটিকি ঘুমায়, পর্দা সরালেই খোলা জানালা\nজানালার রেলিঙে আমি বিষণ্ণ কাক দেখি\nজানালা খুলে দিলে, দেখি তোমার চোখ।\nবোবা জানালা বোঝে না মানুষের ভাষা\nতব...', '', 4, NULL, 'publish', 2770, 0, '2019-02-04 11:27:42', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (23, 2312, 26, '‘গুহা’ পত্রপোন্যাস', 'গুহা', '<!-- wp:paragraph -->\n<p>\nলেখক: সানাউল্লাহ সাগর<br> প্রকাশনী: অনুপ্রাণন প্রকাশন<br> প্রচ্ছদ : আল নোমান<br> ধরন : পত্রোপন্যাস<br> পৃষ্ঠা : ১১২<br> মলাট মূল্য : ২৪০ টাকা\n\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সৌখিন ফটোগ্রাফার  শুভ্র। তার পৃথিবী মমতাহীন শূন্যতায় ভরা। একে একে কাছের মানুষদের প্রস্থান  তার জীবনকে ক্যামেরার ক্লিকের সাথে বন্দি করে ফেলে। এক সময় তার নিঃসঙ্গ  জীবনে আসে দুঃখ ভাগ করে নেয়ায় আগ্রহী মানুষেরা। হয়তো তারা একই মানুষ। ভিন্ন  তাদের নাম। তারা সেতু-ঋতু-রূপা অথবা স্বাতী। যারা শুভ্র’র মনস্তাত্ত্বিক  ভাবনা-যৌন বিশ্বাস-উড়ন্ত নেশা ও বিপন্ন ক্ষতের সাথে ইচ্ছায় অনিচ্ছায় জড়িয়ে  যায়। অথবা তারা কেউ না। শুধু শুভ্র। শুধু নিঃসঙ্গ একজন মানুষ। নিজস্বতায়  নিমগ্ন। যে ক্রমশ ঢুকে যায় অচেনা এক জগতে! নিষিদ্ধ ভাষা ও চিঠির ভাঁজে...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘গুহা’ একটি রোমান্টিক পত্রোপন্যাস। ‘গুহা’ যৌন বিশ্বাস, ব্যক্তি চিন্তার  স্বাধীনতা, সমকালীন পীড়া ও নারীবাদ-নারী সামাজ চিন্তা ভিত্তিক একটি  রোমান্টিক পত্রোপন্যাস... </p>\n<!-- /wp:paragraph -->', 'লেখক: সানাউল্লাহ সাগর\nপ্রকাশনী: অনুপ্রাণন প্রকাশন\nপ্রচ্ছদ : আল নোমান\nধরন : পত্রোপন্যাস\nপৃষ্ঠা : ১১২\nমলাট মূল্য : ২৪০ টাকা\nসৌখিন ফটোগ্রাফার শুভ্র। তার পৃথিবী মমতাহীন শূন্যতায় ভরা। একে একে কাছের মানুষদ...', '', 1, NULL, 'publish', 2891, 0, '2019-02-05 09:15:48', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (24, 2317, 27, 'গোধূলিতে পাওয়া প্রশ্ন', 'গোধূলিতে-পাওয়া-প্রশ্ন', '<!-- wp:paragraph -->\n<p>এই যে নগ্ন রোদের ভালোবাসায়<br> আগলে রাখো <br> কৈশর-যৌবন<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; শেষকালও।<br> গোধূলির মৃত্যুলগ্নে জানতে ইচ্ছে করে <br> তোমার পুষে রাখা<br> সাবালিকা ঘাসবনে<br> ভালোবাসার জন্ম হয় কীভাবে?<br> জন্মনিয়ন্ত্রণ পিলের গলাকাটা শাষণ<br> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; কিংবা ভাইসম্প্রদায়ের দখলে থাকা<br> শকুনি চাবুক ভেদ করে<br> কীভাবে লিখে যাও নৌকাবিলায! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমাকে শেখাও ডুবসাতারে মেতে <br> স্বপ্ন সোঁজার ছলাকলা,<br> বিনিময়ে মিটিয়ে দেবো<br> প্রেম সায়রে পাড়ের কড়ি।  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © সোহেল সবুজ</p>\n<!-- /wp:paragraph -->', 'এই যে নগ্ন রোদের ভালোবাসায়\nআগলে রাখো\nকৈশর-যৌবন\nশেষকালও।\nগোধূলির মৃত্যুলগ্নে জানতে ইচ্ছে করে\nতোমার পুষে রাখা\nসাবালিকা ঘাসবনে\nভালোবাসার জন্ম হয় কীভাবে?\nজন্মনিয়ন্ত্রণ পিলের গলাকাটা শাষণ\nকিংবা ভাইসম্প্...', '', 4, NULL, 'publish', 2524, 0, '2019-02-05 12:10:15', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (25, 2327, 28, 'আর্য পূর্ব বাংলা: সূচনা', 'আর্য-পূর্ব-বাঙলা', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"> <strong>প্রকাশিত পর্ব সমূহ</strong><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be/\\">আর্য পূর্ব বাংলা: সূচনা</a><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%8f%e0%a6%95/\\">আর্য পূর্ব বাংলা: এক</a><br>*  <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%a6%e0%a7%81%e0%a6%87/\\">আর্য পূর্ব বাংলা: দুই</a> </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রাচীন বাংলা জনপদের প্রাচীনত্ব নিরুপন সহজসাধ্য নয়, সে কারণে আর্য পূর্ব বাংলার অস্থিত্ব অনুভূত হলেও গবেষকগণের বক্তব্য এ ক্ষেত্রে অস্পষ্ট। বরং সর্বাংশে ইতিহাস সম্মত না হলেও</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“বাঙালীর আদী অনার্য” পন্ডিতগণের এ সিন্ধান্ত সর্বক্ষেত্রে স্বীকৃত। আর্য নামক সুসভ্য(?) জাতি গোষ্ঠীর আগমনে স্থানীয় অনার্য নামক অসভ্য জাতি ধীরে ধীরে সভ্য হয়ে ওঠে। সত্য হওয়া আর্যত্ব লাভ অর্থে ব্যবহৃত হত। বাঙলা ভাষা এই আর্য আগমনের ফল। বলা হচ্ছে “বাঙলা ভাষার মূল প্রাচীন ভারতীয় আর্য(সংস্কৃত)ভাষা”</p><cite> ড. সুকুমার সেন- বাঙলা সাহিত্যের ইতিহাস, ১ম খ-, ৪র্থ সংকলন ১৯৬৩ কলিকাতা, পৃঃ ৭ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>আর্য পূর্ব বাংলার ভাষা স্লেচ্ছ, ভ্রষ্ট, অনাচারী। জাতি হিসেবে বাঙালি ‘দাস’ বা ‘দস্যু।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“ভাষা হিসেবে বাঙলা কিন্তু কুলিন নয়”। হিন্দু-আর্য ভাষার প্রাচ্য শাখা আদৌ কুলীন বলে গন্য হতনা; তার কারন বাঙালী জাতটাও আসলে বড় বেশী কুলীন জাত নয়।”</p><cite>গোপাল হালদার- বাঙলা সাহিত্যের রূপরেখা, প্রথম খণ্ঢ, মুক্তধারা প্রকাশন ১৯৭৪, ঢাকা, পৃঃ ৩</cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>বাঙলা ভাষা বা বাঙলা ভাষা বা বাঙালি জাতির ঐতিহ্য অনুসন্ধানে আগ্রহী পাঠক বা সচেতন ব্যক্তিবর্গকে বার বার ঠোকর খেতে হয়েছে। পন্ডিতগণের অনুমিত ভাষ্য এবং ইতিহাস পাঠ থেকে ধারণা জন্মেছে বাঙালীর ইতিহাস অগৌরবের, এ জাতির আত্ম মর্যাদা নেই। শুধু তাই নয়; অনার্যদের অবস্থা এতটাই অস্রাব্য ছিল যে,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“এদেশে এলে আর্যদের জাতি যেত, দুঃসাহসিক আর্য যুবকেরা এদেশে যাতায়াত করলে তাদের ভালে ‘ব্রাত্য’ “কলঙ্ক তিলক একেঁ দেয়া হত।”</p><cite>অসিত কুমার বন্দ্যোপাধ্যয়-বাংলা সাহিত্যের সম্পূর্ণ ইতিবৃত্ত নতুন সংস্করণ ১৯৯৪, ঢাকা, পৃঃ ২</cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>অনার্য শব্দটি আজও অশালীন এক কথার গালি হিসাব প্রচলিত। কিন্তু বাঙালির ইতিহাসে এই বক্তব্য কতটা যুক্তি যুক্ত বা বাঙালির প্রাচীন সভ্যতা কতটা গৌরবময় তা নিরুপন করা প্রয়োজন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাংলা জনপদে বারবার বিদেশী বিজাতির আগমন ঘটেছে। বাংলার সভ্যতা এবং সমৃদ্ধিই বিজাতি আগমনের প্রধান কারণ। লক্ষাধিক বছর পূর্বেও এদেশে জনবসতি ছিল উল্লেখযোগ্য পর্যায়। এখানকার আবহাওয়া জলবায়ু তৎকালীন সময়ে জীবন ধারণে ছিল সমজ সাধ্য। শুধু তাই নয়, যুক্তিগ্রাহ্য খুববেশি উপকরণ না থাকলেও অবস্থা বিশ্লেষণে সহজেই অনুমান করা যায় প্রাচীণ যে ক’টি সভ্যতা পৃথিবীতে আজও সাক্ষ বহন করছে বাঙলার অবস্থান ছিল তদরুপ। প্রাপ্ত প্রত্ম-তাত্বিক নির্দশনসমূহ নিরীক্ষণে এবং যুগে যুগে বাংলায় আগত জাতি গোষ্ঠীর নৃ-তাত্ত্বিক বিশ্লেষণে সর্বপরী গ্রীক ও চীন লেখকগণের গ্রন্থ পর্যালোচনা করলে বাঙলার প্রাচীন সভ্যতার সুষ্পষ্ট প্রমাণ পাওয়া যায়। পূর্বে দক্ষিণ ভারত অর্থ্যাৎ বর্তমান বাংলাদেশে ‘আর্য’ আগমন ঘটে খ্রীষ্টীয় প্রথম সনের দিকে, কিন্তু খ্রিষ্টপূর্বে ৫০০ বছর পূর্বে বাংলা একটি স্বাধীন সার্বভৌম রাষ্ট্র ছিল। গ্রীস ব্যতীত গোটা ইউরোপীয় সভ্যতার পূর্বে, বাঙালি সুসভ্য ছিল। বাংলায় জ্ঞান অম্নেষা কেন্দ্র, নগর সভ্যতা, রাজপথ, রাজধানী, প্রতিরক্ষা ব্যবস্থা, শিল্প, বাণিজ্য এবং সাংস্কতিক পরিমন্ডল, বাঙালির বীরত্বগাঁধার প্রমাণ ইতিহাসে, ধর্ম ও রাজনৈতিক বিশ্নেষণাগ্রন্থে উল্লিখিত। এতসত্ত্বেও বাঙালির ইতিহাস ও ঐতিহ্যের সুস্পষ্ট কোনো দলিল না খাবার কারণ রহস্যময়। কেউ কেউ মনে করেন প্রাচীন গ্রীসে ইতিহাস লেখার জন্য যেমন ‘হেরোডেটিসি’ ও ‘যুকিডিডিস’ ছিলেন, বাংলার তেমন কেউ ছিল না। এ বক্তব্য অনুমানও মাত্র। এমন ধারণা অমূলক নয়- বাঙলির যথার্থ ইতিহাস রচিত হয়েছিল। বঙ্গ জনপদের রাজ কবিগণের অনেক সাহিত্য কর্মে তখনকার জীবন ধারা ও মানস চিত্র লিপিবদ্ধ ছিল তা সংরক্ষিত নেই বা ধ্বংস করে ফেলা হয়েছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরবর্তী সময়ে (বাংলা ভাষা প্রতিষ্ঠার পরে যখন বাংলায় গ্রন্থ রচনা শুরু হল) বাঙলার সঠিক ইতিহাস উদঘাটনে বা সংরক্ষণে&nbsp; উৎসাহহীনতা লক্ষিত হয়। এর কারণ দ্বিবিধ। প্রথমতঃ ধর্মীয় অনুভূতি ঐতিহাসিকগণকে উদার হতে দেয়নি। দ্বিতীয়ঃ বাঙালি জাতীয়তাদের পরিচয় দান ছিল অগৌরবের। সেকারণে আর্য বা অন্য বিজাতি কর্তৃক বাঙালি নিধন ও সভ্যতার বিলুপ্তির প্রমাণ না খুঁজে সমকালীন সচেতন সমাজ আত্মগৌরব প্রতিষ্ঠার তাগিদে কেউ বা আর্যত্ব লাভে প্রতিষ্ঠিত বা তুর্কী বংশজাত বলে নিজ নিজ পরিচয় উদ্ঘাটনে ব্রতী হয়েছেন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>বাঙালী হিন্দু ছিল উত্তর ভারতীয় আর্য গৌরবে এবং রাজপুত মারাঠার ঐতিহ্য গর্বে স্ফীত। আর মুসলমান ছিল আরব ইরানীয় জ্ঞাতিত্ব মোহে অভিভূত</p><cite>ড. আহমদ শরীফ- ‘বাঙলা ও বাঙালি’ গ্রন্থের ভূমিকাংশে </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>তা সত্ত্বেও বাংলা সাহিত্য বিশারদগণ, ইতিহাসবিদগণ, ভাষা তাত্ত্বিকগণ অস্কুটাকার হলেও যে সব অনুমিত লক্ষণ উপস্থাপন করেছেন তার সাথে আধুনিক কালের আবিস্কার আর্য পূর্ব বাংলা জনপদের প্রাচীনতার প্রমাণ সুদৃঢ় করেছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © হারিস মিজান</p>\n<!-- /wp:paragraph -->', 'প্রকাশিত পর্ব সমূহ\n* আর্য পূর্ব বাংলা: সূচনা\n* আর্য পূর্ব বাংলা: এক\n* আর্য পূর্ব বাংলা: দুই\nপ্রাচীন বাংলা জনপদের প্রাচীনত্ব নিরুপন সহজসাধ্য নয়, সে কারণে আর্য পূর্ব বাংলার অস্থিত্ব অনুভূত হলেও গবেষকগণ...', '', 2, 3, 'publish', 3662, 0, '2019-02-06 00:01:15', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (26, 2338, 26, '‘পুরাণভূমি’ উপন্যাস', 'পুরাণভূমি-উপন্যাস', '<!-- wp:paragraph -->\n<p> লেখক: পিন্টু রহমান<br> প্রকাশনী:  নাগরী <br> প্রচ্ছদ : আল নোমান<br> ধরন : উপন্যাস<br> পৃষ্ঠা : ১১৬<br> মলাট মূল্য : ১৮০ টাকা </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সাতচল্লিশের দেশভাগের প্রত্যক্ষ ফল হিসেবে ভিটেমাটি হারিয়ে অসংখ্য মানুষ উদ্বাস্তে পরিণত হয়েছিল। জীবন বাঁচানোর তাগিদে শিকড়চ্যূত মানুষ যে যেভাবে পেরেছে পালিয়েছে। ফলে পরিবার-পরিজন, গোত্র-গোত্রে, সমাজে-সমাজে বিভাজন তীব্রতর হয়েছে। একদিকে দেশভাগের ক্ষত অন্যদিকে সাম্প্রদায়িক দাঙ্গা; দাঙ্গা কবলিত একটি পরিবারের উত্থান-পতনের কাহিনী অবলম্বনে রচিত হয়েছে পিন্টু রহমানের উপন্যাস পুরাণভূমি। ভূমিপুত্রের জীবন ক্ষোভ-আক্ষেপ, আশা-ভালবাসা, লড়াই-সংগ্রাম এবং যাপিত জীবনাচার বিশ্বাসযোগ্য মাত্রায় উপস্থাপিত হয়েছে। ব্যক্তিজীবনের সাথে রাজনীতির মেলবন্ধনে উপন্যাসটিতে ভিন্নমাত্রা সংযোজিত হয়েছে। </p>\n<!-- /wp:paragraph -->', 'লেখক: পিন্টু রহমান\nপ্রকাশনী: নাগরী\nপ্রচ্ছদ : আল নোমান\nধরন : উপন্যাস\nপৃষ্ঠা : ১১৬\nমলাট মূল্য : ১৮০ টাকা\nসাতচল্লিশের দেশভাগের প্রত্যক্ষ ফল হিসেবে ভিটেমাটি হারিয়ে অসংখ্য মানুষ উদ্বাস্তে পরিণত হয়েছিল। জ...', '', 1, NULL, 'publish', 2748, 0, '2019-02-07 11:32:27', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (27, 2345, 29, 'ছলচাতুরি', 'ছলচাতুরি', '<!-- wp:paragraph -->\n<p>সত্যি আমি মাঝসাঝে তোমার সাথে মিথ্যে বলি অল্পস্বল্প।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিষন্নতা, অবসাদের গল্পকথা হয়তো কিছু রঙ মেশানো পুরোপুরি সত্যি নয়। <br>জানো, কিসে আমার ভয়? যদি তোমার স্পর্শ না পাই! <br>খানিক বিষাদ, অবসাদের প্রগাঢ় এক রঙের প্রলেপ; গল্প সাজাই।<br>বাজাই কোন বিউগলের করুণ সুরে। কাছেই থাকো কিংবা দূরে <br>মন খারাপের গল্পগুলো হয় কখনো স্পর্শকামী ছলচাতুরি<br>তুমি তো সে বাৎসায়নের বদ্যি-ওঝা<br>ছোঁয়ায় কেমন আরোগ্য হয় গভীর বিষাদ সবই তোমার জানা বোঝা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তাই কখনো মিথ্যে বলি স্পর্শ পেতে<br>একটু খানি ছুঁয়েই দেখো কেমন করে হরিষ জাগে দিনে রাতে।<br>আমি যখন বিষন্নতায় ডুবতে থাকি তুমি তখন অস্থিরতায় ঠোঁট <br>ছোঁয়াবে সত্যি জানি<br>পেলব আঙুল, নাকের ডগা, নাভির অতল সবই দেবে অধর কোণে।<br>না হয় একটু রঙ মেশানো <br>এমনতরো মিথ্যে বলায় পাপের নামতা কে আর গোনে! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমার নামে ‘মিথ্যেবাদী’ নতুন করে হয়তো তুমি লিখে রাখবে অভিধানে<br>অল্প কিছু স্পর্শকামী মিথ্যে কথা বুঝেও না বোঝার ভানে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © আহমেদ শরীফ শুভ</p>\n<!-- /wp:paragraph -->', 'সত্যি আমি মাঝসাঝে তোমার সাথে মিথ্যে বলি অল্পস্বল্প।\nবিষন্নতা, অবসাদের গল্পকথা হয়তো কিছু রঙ মেশানো পুরোপুরি সত্যি নয়।\nজানো, কিসে আমার ভয়? যদি তোমার স্পর্শ না পাই!\nখানিক বিষাদ, অবসাদের প্রগাঢ় এক রঙে...', '', 4, NULL, 'publish', 2428, 0, '2019-02-07 13:44:53', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (28, 2365, 26, '‘রাজকন্যার আহ্নিক’ গল্পগ্রন্থ', 'রাজকন্যার-আহ্নিক-গল্পগ', '<!-- wp:paragraph -->\n<p> লেখক: আহমেদ শরীফ শুভ<br> প্রকাশনী:  প্রকাশ পাবলিকেশন্স<br> প্রচ্ছদ : আব্দুল হালিম মন্টু <br> ধরন : গল্পগ্রন্থ<br> পৃষ্ঠা : ১০০  <br>মলাট মূল্য :২০০ টাক<br>প্রাপ্তিস্থান:  বইমেলায় প্রাপ্তিস্থান \'টাঙ্গন\', স্টল নম্বর ৩৯০ (সোহরাওয়ার্দী উদ্যান)  এবং \'প্রকাশ\' (লিটল ম্যাগাজিন চত্বর, বাংলা একাডেমি প্রাঙ্গন)।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>\'রাজকন্যার আহ্নিক\' লেখকের দ্বিতীয় গল্পগ্রন্থ। ছোট বড় দশটি গল্প নিয়ে একশ\' পৃষ্ঠায় সাজিয়েছেন গ্রন্থটি লেখক। গল্পগুলো মূলতঃ মধ্যবিত্ত নগর জীবনের কাহিনী। লেখকের বেড়ে উঠা মধ্যবিত্ত নগর জীবনে, তাই এ জীবনকে লেখক ভালোভাবে পর্যবেক্ষন করতে পারেন। \'রাজকন্যার আহ্নিক\' সে সব পর্যবেক্ষনেরই প্রতিফলন। লেখক আমাদের চারপাশের নানা ঘটনাগুলো মানব জীবনের জটিল মনস্তত্ত্বের টানাপোড়েন লব্ধি হিসেবেই দেখেছেন এই গ্রন্থে, জৈবিক তাড়নার কথা এসেছে তার অবশ্যম্ভাবী অনুষঙ্গ হিসেবে। আরও এসেছে নিটোল প্রেমের খুনসুটি, সাংসারিক সংঘাত এবং শারীরিক সীমাবদ্ধতায় বৈরি রণাঙ্গনে সংগ্রামের কথাচিত্র। মুক্তিযুদ্ধের গল্পও আছে একটি, তাও শহুরে যুদ্ধের ক্যানভাসে আঁকা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমাদের চারপাশের অনেক ঘটনাই সমাজগ্রাহ্য হয় না। আমরা সেগুলো না দেখার ভান করে পাশ কাটিয়ে চলি। কখনো কখনো আমাদের সমাজ একটা ডিনায়্যালের মধ্যে থাকে। তাতে কিন্তু ঘটনাগুলো বসে থাকে না, আপন পথে এগিয়ে চলে। সে সব ঘটনার কিছু কিছু নির্যাস লেখক তুলে এনেছেন গল্পগুলোতে।  লেখকের মতে - </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>মনস্তাত্ত্বিক টানাপোড়েনের গল্পগুলো কখনো কখনো খুব বেশি কনফ্রন্টিং হয়।  আমার গল্পগুলো ঠিক ততটুকু সাহসী হতে পেরেছে বলে মনে হয় না। কখনো কখনো লেখকের সাহস পাঠকের সাহসের বিবেচনায় নির্ধারিত হয়। তবে সচেতন পাঠক বাকিটুকু সাহসের আভাস পাবেন তা নির্দ্বিধায় বলা যায়।&nbsp;&nbsp;</p><cite>-   আহমেদ শরীফ শুভ </cite></blockquote>\n<!-- /wp:quote -->', 'লেখক: আহমেদ শরীফ শুভ\nপ্রকাশনী: প্রকাশ পাবলিকেশন্স\nপ্রচ্ছদ : আব্দুল হালিম মন্টু\nধরন : গল্পগ্রন্থ\nপৃষ্ঠা : ১০০\nমলাট মূল্য :২০০ টাক\nপ্রাপ্তিস্থান: বইমেলায় প্রাপ্তিস্থান \'টাঙ্গন\', স্টল নম্বর ৩৯০ (সোহরাওয...', '', 1, NULL, 'publish', 2791, 0, '2019-02-10 09:52:27', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (29, 2372, 28, 'আর্য পূর্ব বাংলা: এক', 'আর্য-পূর্ব-বাঙলা-এক', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\">  <strong>প্রকাশিত পর্ব সমূহ</strong><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be/\\">আর্য পূর্ব বাংলা: সূচনা</a><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%8f%e0%a6%95/\\">আর্য পূর্ব বাংলা: এক</a><br>*  <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%a6%e0%a7%81%e0%a6%87/\\">আর্য পূর্ব বাংলা: দুই</a>  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সহজভাবেই বলা যায় যে সুপ্রাচীন কাল থেকেই বাঙলার জনবসতি স্থাপন হয়েছিল। প্রসঙ্গেক্রমে উল্লেখ আবশ্যক বর্তমানে বাঙালি বলতে বাংলা ভাষী ও বাংলাদেশীকে বুঝায়। যদি ও </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“বাঙলা নামটি মুসলমানের অধিকার কালের দিকেই চলিত হইয়াছিল। ”</p><cite> - ড. সুকুমার সেন – পূবোক্ত পৃঃ ১ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>মূলত: বঙ্গ শব্দ থেকে বাঙলা হয়েছে যার অর্থ জলাভূমি। আবুল ফজল তার ‘আইন ই আকবরী’ গ্রন্থে লিখেছেন যে, বঙ্গ শব্দের সাথে আলযুক্ত হয়ে- হয়েছে বাঙ্গালা। আল শুধু ক্ষেত্রের (জমির) আল নয়, ছোট বড় বাঁধ অর্থেও ব্যবহৃত। প্রাচীনকালে রাজাগণ ১০ গজ প্রশস্ত উঁচু ২০ গজ বিশাল আকার আল নির্মাণ করতেন (Enbankment)। বর্তমানেও বৃহত্তর বরিশাল ও ফরিদপুরের অনেক স্থানে “বাঙলা” দেয়া শব্দটি জলা ভূমিতে বাঁধ দেয়া অর্থে ব্যবহৃত হয়। বাংলা বন্যা ও বাদলের দেশ, বাংলার সাথে তাই আল (বাঁধ) ঘনিষ্ঠে অনুষঙ্গ। কেউ কেউ বলেন বাঙ্গলা সংস্কৃত শব্দ, এর সাথে আল প্রত্যয় যুক্ত। এ বক্তব্য যুক্তিগ্রাহ্য কি? মুসলমান আমলে যা বাংলা নাম ধারণ করেছে তা শুধু বঙ্গ নয় বাংলা ভাষা-ভাষী ভূ-ভাগ। প্রাচীন যুগে এর বিভিন্ন অঞ্চল ভিন্ন ভিন্ন নামে পরিচিত ছিল। যেমন বঙ্গ, পুন্ড, রাঢ়, বরেন্দ্র, গৌড়, লক্ষানাবর্তী, সমতট, হরিকেল প্রভৃতি। ইতিহাস বলে- </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“বঙ্গ একটি অতি প্রাচীন জনপদ ছিল। আরণ্যক ব্রাক্ষণে ইহার উল্লেখ পাওয়া যায়। বৌদ্ধ ধর্ম গ্রন্থগুলিতে যে ষোলটি জনপদেরউল্লেখ করা হয়েছে ইহাদের মধ্যে বঙ্গ জনপদের নাম আছে। ”</p><cite> - ড. মুহম্মদ আব্দুর রহিম, ড. আব্দুল মমিন চৌধুরি, ড. এ বি এম মাহামুদ, ড.  সিরাজুল ইসরাম- বাংলাদেশের ইতিহাস, নওরোজ অষ্টম সংস্করণ ১৯৯৯, পৃঃ ১৪ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>শুধু বঙ্গ নয়, সমগ্র বাঙালির (বর্তমানে যাদের ভাষা বাঙলা) প্রাচীন অবস্থান সুস্পষ্ট ভাবে প্রমাণিত। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাংলার প্রাচীনতা নির্ণয়ে গবেষকগণের বক্তব্য স্মরণ করা যেতে পারে। ভূ-তত্ত্ব জরিপে ড. তোফায়েল আহমদ </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“১০ লক্ষ বছর আগে প্লোইস্টোসিনযুগে বাংলাদেশে প্রথম মানুষের আগমন ঘটে...। ”</p><cite> - ড. তোফায়েল আহমেদ - যুগে যুগে বাংলাদেশ, নওরোজ কিতাবিস্তান, ১ম সংকলন- ১৯৯২ পৃঃ ১৪ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>বাঙালীর অস্তিত্ব অনুসন্ধানে রাম শরণ শর্মা </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“খ্রীষ্ট জন্মের পাঁচ লক্ষ বছর আগে থেকেই ভারতীয় উপমহাদেশে মানুষের বসবাস শুরু হয়েছিল। প্রায় একই সময় থেকে এই এলাকার মানুষ জীবিকার সঙ্গে পরিচিত ছিল। ”</p><cite> - রাম স্বরণ শর্মা – প্রাচীন ভারত, পরঙ্গ রাজ্য পুস্তক পরিষদ, কলিকাতাম ১৮৮৯, পৃঃ ২৬-২৭ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>আবিস্কৃত নিদর্শন সমূহ নিরীক্ষে অজয় কর বলেন </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>“প্রত্ন প্রস্তর যুগ থেকেই উপমহাদেশের অন্যান্য অঞ্চলের মতোই বাংলাদেশে যে মানুষের বসবাস শুরু হয়েছিল এ থেকে তা বুঝা যায়। ”</p><cite> - অজয় কর – বাঙলা ও বাঙালি – খান ব্রাদার্স, ১ম সংখ্যা ১৩৩৬ ঢাকা, পৃঃ ১৪ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>এরুপ অসংখ্য বক্তব্য উস্থাপন করা সম্ভাব, ভূ-তাত্ত্বিক শ্রেনী বিশ্লেষণে এসব বক্তব্যের পক্ষে অজস্র যুক্তিদ্বার করানো যায়। যেমন টারশিয়ারী যুগে সৃষ্ট শিলা বর্তমান চট্টগ্রম, সিলেট, ময়মনসিংহ, পশ্চিম বঙ্গের রাজমহল, মেদিনিপুর দার্জিলিং প্রভৃতি অঞ্চল সৃষ্টির প্রমাণ মেলে। প্লাইন্টোসিন কালের পলি- পশ্চিমবঙ্গ, বরেন্দ্র ভূমি, ভাওয়াল, মধুপুরগড় ও কুমিল্লা অঞ্চল সৃষ্টির মূল উপযোগ, বিবিধ নিদর্শন ও যুক্তিযুক্ত বক্তব্যের আলোকে অনুমান করা হয় লক্ষাধিক বছর পূর্বে ও এ অঞ্চল ছিল মানুষের পদচারণায় শরব। প্রাচীন সমাজ কেন্দ্রীক নির্বাহের জন্য বাংলা অঞ্চল ছিল উপযোগী। সমুদ্র তীরবর্তী পলিযুক্ত উর্বর সমতল মাটি চাষাবাদের সূচনায় সহজ সহায়ক ছিল। এছাড়াও বাংলার সমতল বনভূমিতিতে অসংখ্য পশু পাখির বসবাস ছিল। শিকারের তাগিদে বাংলাদেশীকে তাই তাদের কালের আবিস্কৃত হাতিয়ার তৈরীতে পারদর্শী হতে হয়েছে। পাথর শীশা, তামা, লোহা ও ব্রঞ্জ ব্যবহারে পারদশীতার নিদর্শন বাংলায় প্রাপ্ত হয়েছে বহুস্থানে। পান্ডু রাজার চিবিতে প্রাপ্ত নিদর্শনের আলোকে ঐতিহাসিকগণ মনে করেন প্রাচীন দক্ষিণ পশ্চিম বাংলার মানুষেরা ধানচাষ, নীলগাই ও সম্বরের মতো পশু শিকারে পারদর্শী ছিল। শুধু প্রাচীন কাল আলোচ্য বিষয় নয়; সভ্যতার সাথে তালমিলিয়ে বাঙলার মানুষ এগিয়ে এসেছে সভ্যতার পরিপূর্ন পর্যায়। বিশ্ব সভ্যতার যাত্রালগ্নে খ্রীষ্ট জন্মের ৭০০০ বছর পূর্বে নীলনদের তীরে মিশরীয় সভ্যতা, টাইগ্রিসের তীরে মেস্ট্রোপটেমিয়া, সিন্ধুনদের তীরে সিন্ধুসভ্যতা এবং হোয়াংহো নদীর তীরে হোয়াংহো নদীর তীরে উর্বর ভূখন্ড সমূহে যখন গড়ে উঠেছে ঐশ্চর্যশালী নগরায়ন। তখন বঙ্গোপসাগর তীর ঘেঁষে বাঙলাদেশে ও গঙ্গা নদীর তীরে গড়ে উঠেছে ভিন্ন ধরণের সভ্যতা। বিশ্বের ইতিহাসে সুস্পষ্ট কোনো উল্লেখ না থাকলেও অনুমান করা যায় জীবন যাপনের উপযোগিতা ও সম্পদের দিক থেকে এ সভ্যতা ছিল অন্যদের চেয়ে সমৃদ্ধ। আধুনিক গবেষণায় এ সভ্যতার অস্কুট অস্থিত্ব স্কীকৃত হলেও এর সঠিক কোন নামকরণ হয়নি। তবে সমুদ্রের নামানুসারে এবং জনপদের প্রাচীনতা বিচারে এ নগরায়নকে ‘বঙ্গ সভ্যতা’ নাম করণ করা যৌক্তিক। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রত্ন তাত্ত্বিক যুগ বিভাজন পূর্বক প্রাপ্ত ভূ-তাত্ত্বিক নিদর্শন সমূহের ব্যাখ্যা দানের পূর্বে বাংলার সীমানা অনুমান আবশ্যক। পূর্বে যে ষোলটি অঞ্চল বা ভিন্ন সীমারেখায় জনপদের উল্লেখ করা হয়েছে বর্তমান বাঙলায় তার অধিকাংশের অবস্থান। উল্লিখিত জনপদ সমূহের সীমানা স্থায়ী ভাবে নির্ধারণ সম্ভব হয়নি কখনো। প্রাচীন কালে বঙ্গ নামক যে অঞ্চলের কথা বলা হচ্ছে তার সুনির্দিষ্ট ভৌগোলিক সীমার কোনো প্রমাণ মেলে না। বর্তমান বাঙলাদেশের দক্ষিণ পশ্চিম অঞ্চল বৃহত্তর ফরিদপুর, বরিশাল এবং বিক্রমপুর নামে যা পরিচিত ছিল (বর্তমানে অন্য নামে পরিচয়) বঙ্গের অর্ন্তগত। সমগ্র উত্তর বঙ্গ বরেন্দ্র নামে পরিচিত ছিল, বর্তমান রাজশাহী বগুড়া অঞ্চল। ঐতিহাসিক বিশ্লেষণে বরেন্দ্রের সাথে পুন্ড্রের পৃথকীকরণ কঠিন রংপুর, রাজশাহী, দিনাজপুর বগুড়াকে প্রাচীন পুন্ড্র জনপদ বলা যায় যার রাজধানী ছিল পুন্ড্রনগর। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গৌড় ও লক্ষণাবতীর অবস্থান অভিন্ন অনুভূত হয়। গৌড় রাজের সময় এর রাজধানী হয় কর্নসূবর্ন বর্তমানে যা ভারতের মুর্শিদাবাদে। প্রাচীন বঙ্গের নিকট বসতি জনপদ সমতট। চীনা পর্যটক হিউয়েন সাঙ এর ভাষ্য মতে সমতট বর্তমান কুমিল্লা নোয়াখালী ও চট্টগ্রাম অঞ্চল। হরিকেল বাঙলার পূর্বপ্রান্ত, আধুনিক সিলেট যা তখন বঙ্গ জনপদের আওতাভূক্ত ছিল। প্রাচীন সীমানা অনুসন্ধানে দেখা যায় উল্লিখিত জনপদ সমূহের আলাদা রাজধানী এবং শাসনকর্তা ছিল তা সত্ত্বেও সমগ্র ভূ-ভাগের নাম “বাংলা” করণের কারন বঙ্গের সম্পদ, ঐতিহ্য, বঙ্গরাজের আধিপত্য এবং ভাষার নির্দিষ্ঠ করণ বলে মনে করা যেতে পারে। কেননা জনপদ সমূহের আলাদা রাষ্ট্র ভাষা ছিল বলে কোনো সু-নির্দিষ্ট প্রামাণিক দলিল পাওয়া যায়নি। ড. নিহার রঞ্জন রায় প্রাচীন বাঙালীর বসতি সীমা নির্ধারণ করেছেন এভাবে “উত্তরে হিমালয় হইতে নেপাল সিকিম ও ভোটান রাজ্য। উত্তর পূর্ব দিকে ব্রহ্মপুত্র নদ উপত্যকা, উত্তর পশ্চিম দিকে দ্বার বঙ্গ পর্যন্ত ভাগীরথীর উত্তর সমস্তরালবর্তী সমভূমি, পূর্ব দিকে গাড়ো খাসিয়া ত্রিপুরা-চট্টগ্রাম শৈলশ্রেণী বাহিয়া দক্ষিণে সমুদ্র পর্যন্ত। পশ্চিমে রাজমহল-সাত্ততাল পাটনা -ছোটনাগপুর মালভূমি ধলভূম কেওঞ্জর মৈয়ুরভঞ্জের শৈলময় অরণ্যময় মালভূমি; দক্ষিণে বঙ্গোপসাগর। ” বাঙলা ভাষার বিকাশ পূর্বে ড. রায়ের উল্লিখিত অংশের অবদান স্বীকৃত হলেও বাঙালীর প্রচীনতা নিরুপনে তা সর্বাংশে গৃহিত নয়। আর্য পূর্ব বাঙলা বা প্রাচীন বাঙালি বলতে বর্তমানে বাংলাদেশসহ যে সব অঞ্চলের ভাষা বাংলা আর্থাৎ বাঙালি বসতি অঞ্চলসমুহকে বোঝানো হচ্ছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> © হারিস মিজান</p>\n<!-- /wp:paragraph -->', 'প্রকাশিত পর্ব সমূহ\n* আর্য পূর্ব বাংলা: সূচনা\n* আর্য পূর্ব বাংলা: এক\n* আর্য পূর্ব বাংলা: দুই\nসহজভাবেই বলা যায় যে সুপ্রাচীন কাল থেকেই বাঙলার জনবসতি স্থাপন হয়েছিল। প্রসঙ্গেক্রমে উল্লেখ আবশ্যক বর্তমানে ...', '', 2, 3, 'publish', 4305, 0, '2019-02-10 12:38:03', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (30, 2384, 30, '\'দায়\'', 'দায়', '<!-- wp:paragraph -->\n<p>বিয়ের আগে কি আপনার স্ত্রীর সাথে\nপরিচয় ছিল?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,মায়ের পছন্দে বিয়ে করেছি।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার কোন পছন্দ ছিল না?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জ্বী মানে স্যার,মা প্রথমে পছন্দ\nকরে আমাকে পাঠিয়েছিলেন। আমি পছন্দ করে সম্মতি দেই,তারপর বিয়ে হয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তার আগে কি কোন মেয়ের সাথে আপনার\nসম্পর্ক ছিল?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,এমন কিছু ছিল না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কোন মেয়ের সাথে প্রেম-টেম করেননি?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার, কখনো না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনিতো মাদকাসক্ত ছিলেন এবং কয়েক\nমাস নিরাময় কেন্দ্রেও ছিলেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জি¦ স্যার। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এমনটা কখন থেকে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আসলে স্যার বাবার সাথে মায়ের ডিভোর্সের\nপর মা আমাকে তার সাথে নিয়ে আসেন। পরে মায়ের অন্যত্র বিয়ে হয়ে যায়। লেখাপড়া তেমন করতে\nপারিনি। একসময় খারাপ ছেলেদের পাল্লায় পড়ে নেশার সাথে জড়িয়ে যাই। পরে আমার উশৃঙ্খলপনা\nদেখে মা ভেবেছিলেন হয়তো বিয়ে দিলে ঠিক হয়ে যাব, তাই বিয়ে দেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিয়ের পর কি ঠিক হয়েছিলেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,আমার স্ত্রীর প্রচেষ্টায়\nনিরাময় কেন্দ্রে যাই এবং সেখানে চিকিৎসা নিয়ে স্বাভাবিক হই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনিতো মাদকসহ গ্রেফতার হয়েছিলেন\nএবং জেলও খেটেছিলেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তা স্যার অনেক পর। তখন আমার বড়\nমেয়ের বয়স ৪ বছর ছিল। গাড়ি চালাতাম। একসময় মাদকচক্রের সাথে জড়িয়ে যাই। টাকার লোভে আমার\nগাড়িতে করে মাদক বহন করতাম। একদিন র‌্যাবের হাতে ধরা পড়ি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনি জেলে কতোদিন ছিলেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রায় তিন মাস। পরে জামিনে ছাড়া\nপাই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনাকে জেল থেকে কে ছাড়িয়েছিল?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমার স্ত্রী। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার স্ত্রী আপনাকে খুব ভালবাসে,তাই\nনা?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভালবাসে না সেটা বলবো না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্ত্রীর সাথেতো আপনার প্রায় ঝগড়া\nহয় এবং তাকে মারধরও করেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জ্বী মানে স্যার মাঝে মধ্যে একটু\nআধটু হয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কেন,আপনার স্ত্রী কি খুব খারাপ?\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তেমনটা বলবো না স্যার। খারাপি কিছু\nনজরে পড়েনি। মাঝে মধ্যে মাথা গরম হয়ে যায়। মাথাটা সেও গরম করে। কী করবো-সারাদিনে বাসায়\nগেলাম। গিয়ে একটুও শান্তি পাই না। এটা না সেটা তুচ্ছ বিষয় নিয়ে বকবক শুরু করে। কিছু\nএকটা নিয়ে শুরু করলে আর থামে না। এতো পরিশ্রম করেও কোন কূল পাই না। সে মনে করে আমি\nএকটা অপদার্থ, নিষ্কর্মা। সংসারে আমার কোন অবদান নেই। যেমন মনে করেন স্যার, হাতে টাকা\nনেই। সব সময়তো আর হাতে টাকা পয়সা থাকে না। কোন একটা জিনিস নিতে পারলাম না-তখন আর তাকে\nকে রুখে? পেছনের সবকিছু অস্বীকার করবে। যেন আমি তাকে জীবনেও কিছু দেইনি। শুধু তাই না\nস্যার, রাগ উঠলে আমাকে তুই তুকারি করে কথা বলে,আমার মোটেও সহ্য হয় না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার সংসার কেমনে চলে মানে আয়ের\nউৎস কী?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আয় বলতে স্যার ছোটখাটো একটা ব্যবসা\nআছে। আগে গাড়ি ছিল। র‌্যাবে ধরার পর আর উদ্ধার করতে পারিনি। এখন এই ব্যবসা নিয়ে কোন\nমতে আছি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বর্তমান আয়ে কি আপনার সংসার চলে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বর্তমান আয়ে না স্যার আমার সংসার\nহচ্ছে হাবিয়া দুযখ;এখানে সারা দুনিয়া ঢেলে দিলেও ভরবে না। কি বলবো স্যার,আমার স্ত্রীর\nবিলাসিতা দেখলে আপনি অবাক হবেন। টাকা পয়সার টানপড়ন,ঋণধার এসব কারনে আরও মাথা ঠিক থাকে\nনা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনি কি আর কোন বিয়ে করেছেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মিথ্যা কথা স্যার। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরকীয়া সম্পর্ক?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সম্পূর্ণ মিথ্যা স্যার। আমার স্ত্রীর\nবানানো কথা। সে এটা রটিয়েছে। সেদিন সালিসে সবার সামনে বলেছি-যদি বিয়ে করে থাকি বা কারো\nসাথে আমার সম্পর্ক থাকে তাহলে প্রমাণ দিক। সে কোন প্রমাণ দিতে পারেনি। ও স্যার আমাকে\nঅযথাই সন্দেহ করে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার সন্তানদের প্রতি আপনার ভালবাসা\nকেমন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তা স্যার বুঝাতে পারবো না এবং দেখাতেও\nপারবো না। তাদের জন্যইতো আমার সব শ্রম। অনেকবার ভেবেছি স্ত্রীকে ডিভোর্স দিয়ে দেই।\nকিন্তু ওদের কথা ভেবে পারিনি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এমন কি হতো যে আপনার স্ত্রীর সাথে\nঝগড়ার করছেন, ঝগড়ার মূহুর্তে মেয়ের গায়ে কি হাত তোলতেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার কখনো হাত তোলেছি বলে মনে\nহয়নি। তবে রাগের মাথায় কখনো ধমক টমক দিতাম। কি বলবো স্যার আমার কাছে কখনো পুরো পৃথিবী\nঅসহ্য লাগে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়ের সাথে আপনার সম্পর্কটা কেমন\nছিল,যেমন ধরেন সে কি আপনার সাথে আন্তরিকতার সাথে,মন খোলে কথা বলতে পারতো?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ও স্যার তেমন কথা বলতো না। আমি\nবাসায় গেলে দূরে দূরে থাকতো। লজ্জায় না ভয়ে ঠিক বুঝতাম না। খুব গম্ভীর স্বভাবের ছিল।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ওর কোন প্রয়োজনের কথা যেমন-বই-খাতা,জামা-কাপড়\nএসবের কথা আপনাকে বলতো না?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,ওর মায়ের কাছে বলতো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গত মাসের শুরুর দিকে একবার আপনার\nস্ত্রী ঝগড়া করে বাপের বাড়ি চলে যায়, তা কি সত্য?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জি¦ স্যার?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এমনটা আগেও হয়েছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জি¦ স্যার।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গত মাসে যখন আপনার স্ত্রী তার বাপের\nবাড়ি চলে যায় তখন বাসায় কে ছিল?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমার মেয়ে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সে কি একা ছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জি¦, স্যার। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার বাসাতো খুব একা, এর আগে কখনো\nআপনার মেয়ে বাসায় একা থেকেছে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনাকে তখন রান্না-বান্না করিয়ে\nকে খাওয়াইছে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আমার মেয়ে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এর আগে কি কখনো সে রান্না-বান্না\nএসব করেছে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এর আগে কখনো নিজ হাতে প্লেটটা ধুয়েছে\nবলেও মনে হয় না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রান্না ঘরে ও নিজ থেকে গিয়েছিল\nনা আপনি বাধ্য করেছিলেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আসলে স্যার তখন মেজাজ ভাল ছিল না।\nবেরিয়ে যেতাম,ফিরতে রাত বারোটা একটা বেজে যেত। ওর সাথে তেমন কথা হতো না। ঘরে এসে সবকিছু\nঠিকঠাক পেতাম। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনি বাসায় ফিরতেন রাত বারোটায়\nএকটায়! তার আগ পর্যন্ত আপনার মেয়ে কি বাসায় একা থাকতো?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জ্বী মানে স্যার...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এর আগে কখনো এমনটি হয়েছিল?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নিরব...। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আচ্ছা, আপনি এখন আসতে পারেন। প্রয়োজনে\nআপনার সাথে আবারো কথা হবে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দুই.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মিসেস সুলতানা,আপনার মেয়েতো খুব\nমেধাবি ছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জ্বী স্যার...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আহ! কাঁদবেন না প্লিজ। স্বাভাবিক\nহয়ে কথা বলুন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>লেখা পড়ায় সব সময় ভাল ছিল। পিএস\nসি,জে এস সি পরিক্ষায় গোল্ডেন পেয়েছে। ক্লাসে ফার্স্ট ছিল...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনি কাঁদবেন না প্লিজ। একটু স্বাভাবিক\nহয়ে কথা বলার চেষ্টা করুন। আচ্ছা সে প্রসঙ্গে পরে আসছি। আপনার কোলের বাচ্ছাটির বয়স\nকতো?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেড় বছর হয়েছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নাম কী রেখেছেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রাফি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শুধু রাফি?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,আহমদ শরিফ রাফি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাহ! খুব সুন্দর নামতো,কে রেখেছে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ওর বাবা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাবা খুব ভালবাসেন তাই না?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ওদের সাথে কোন সমস্যা নেই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সমস্যাটা কি শুধু আপনার সাথে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কী বলবো স্যার,উনার আচরনতো এই ভাল\nএই খারাপ। আমাকে একদম সহ্য করতে পারেন না। সব সময় সন্দেহ করেন। ঘরে এসেই ছুঁতো খুঁজেন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সমস্যাটা কোন জায়গায় বলে মনে করেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সমস্যাটা ঠিক কোন জায়গায় বুঝতে\nপারছি না। উনি সংসার সম্পর্কে খুব উদাসিন। রাত বারোটা-একটা করে ঘরে ফেরেন। সন্তানদের\nলেখা পড়া,অসুখ বিসুখ সব আমাকে দেখতে হয়। সংসারে কখন কি প্রয়োজন সেদিকে মোটেও খেয়াল\nরাখেন না। এসব নিয়েই কথা বললেই ঝগড়া শুরু করেন। কখনো আমাকে অযথা মারধর করেন। কি বলবো\nস্যার, যেমন ধরেন ঘরে এসে দেখলেন পেছনের রুমের জানালাটা খোলা। এই অজুহাতে ঝগড়া শুরু\nকরে দিবেন। আমি নাকি পিছের বাসার কার সাথে কথা বলি। আরো অনেক কিছু স্যার। তুচ্ছ কারণে\nঝগড়া-ঝাটি মারধর করেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার সাথে তার এসব সমস্যা কি প্রথম\nথেকেই চলে আসছে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সমস্যাতো স্যার প্রথম থেকেই ছিল।\nমাদকাসক্ত ছিলেন। অনেক কষ্ট করে ঠিক করেছি। অনেকদিন খুব ভালো হয়ে চলেছেন। তারপর বিভিন্নভাবে\nসমস্যা দেখা দেয়। সংসারে উদাসীন। টুকটাক বিষয় নিয়ে ঝগড়া। কখনো কম কখনো বেশি। তবে এই\nকয়েক মাস থেকে একটু বেশি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনার স্বামী কি আর কোন বিয়ে করেছেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সঠিক জানিনা। তবে তার আচার আচারণে\nআমার এমনটিই সন্দেহ হয়। তার ইচ্ছা আমি যেন চলে যাই। বিশ্বাস করেন স্যার,এই মানুষটার\nসাথে সংসার করার মোটেও ইচ্ছা নেই। কয়েকবার ভেবেছি ডিভোর্স দিয়ে চলে যাবো। কিন্তু এই\nবাচ্চাদের দিকে চেয়ে,তাদের ভবিষ্যতের দিকে তাকিয়ে পারিনি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়ের সামনেও কি আপনাদের কলহ হতো?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কী বলবো স্যার,উনার বিবেক বোধ কিছুই\nনেই। এদের সামনেই আমাকে মারধর করেন। এমনও হয় মারার সময় কোলের বাচ্ছাটাকে কেড়ে নিয়ে\nফ্লোরে রেখে আমাকে মারধর করেন। কান্না শুনে মেয়ে এসে কোলে নিয়ে বাইরে বের হয়ে যেতো।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্যাড, ভেরি স্যাড! আচ্ছা, যেদিন\nঘটনা ঘটেছিলো সে দিন কি আপনি বাসায় ছিলেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>না স্যার,এর দুদিন আগে তার বাবার\nসাথে ঝগড়া হয়। আমাকে প্রচন্ড মারধর করেন। আমি কোলের এই বাচ্চাটিকে নিয়ে আমার বাপের\nবাড়ি চলে যাই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঘটনার দিন আপনি বাসায়ই ছিলেন না!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>...কাঁদছেন কেন? কাঁদবেন না প্লীজ।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আপনি শান্ত হোন... </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তিন.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সুলতানা এবং তার স্বামী মিলন সাহেব\nটেবিলের সামনে পাশাপাশি চেয়ারে মাথা নিচু করে বসে আছেন। শিশু সন্তানটি মায়ের কোলে ঘুমুচ্ছে।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মিষ্টার মিলন এবং মিসেস সুলতানা,\nআমি যা বলছি মনোযোগ দিয়ে শুনুন। আমি ব্যক্তিগতভাবে আপনাদের দুজনকে ভিন্নভাবে জিজ্ঞাসাবাদ\nছাড়াও আপনাদের প্রতিবেশী এবং আপনাদের মেয়ের বন্ধু-বান্ধব ও তার স্কুলের শিক্ষকদের সাথেও\nকথা বলেছি, ব্যাপক অনুসন্ধান করেছি। আপনারা যা অনুমান বা সন্দেহ করছেন তা মোটেও ঠিক\nনয়। মেয়েটি আত্মহত্যা করেছে তা সত্যি। আর এই আত্মহত্যার জন্য আর কেউ দায়ি নয়। একমাত্র\nদায়ি হলেন আপনারা। মেয়েটির মধ্যে অনেক সম্ভাবনা লুকিয়ে ছিল। ছিল অনেক স্বপ্ন। সুযোগ\nপেলে ডানা মেলে উড়তো। পরিচর্যা পেয়ে বড় হলে বড় কিছু একটা হতো। কিন্তু দুঃখজনক, আপনারা\nসবকিছুকে হত্যা করেছেন! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটি শিশু সুস্থ সুন্দরভাবে বেড়ে\nওঠার জন্য প্রথম শর্ত হচ্ছে একটি সুস্থ সুন্দর পরিবার। পিতা মাতার পারস্পরিক সদ্ভাব\nএবং মার্জিত আচরণ। যা সে আপনাদের কাছ থেকে পায়নি। এসব থেকে সে বঞ্চিত হয়ে মানসিকভাবে\nছিল হতাশাগ্রস্থ। আপনাদের দৈনন্দিন কলহ কেড়ে নিয়েছিল তার শৈশবের আনন্দ হাসি। সে ছোট\nহতে হয়েছে তার বন্ধু বান্ধবদের কাছে। আশপাশের মানুষজনদের কাছে। মানসিকভাবে ক্ষুন্ন\nহয়ে তার পৃথিবী হয়ে গিয়েছিল সংকীর্ণ,যেখান থেকে সে মুক্তি চেয়েছিল। মেয়েটা যখন অবুঝ\nছিল,আপনার হাত যখন আপনার স্ত্রীর গায়ে উঠতো,সে চিৎকার করে কাঁদতো। যখন একটু বড় হলো,পৃথিবীকে\nবুঝতে শুরু করলো তখন আপনাদের ঝগড়াঝাটি দেখে সে আর চিৎকার করে কাঁদতো না। খুব নিরবে\nচোখের জল ফেলতো আর ভাবতো। তার অসহায় ভাবনাটাই শেষ পর্যন্ত তাকে আত্মহত্যার দিকে নিয়ে\nযায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দুজনকেই বলছি, মন দিয়ে শুনেন। সংসারে\nমান অভিমান থাকতে পারে। কিন্তু তা যদি হয় ঝগড়াঝাটি মারামারির পর্যায়ে তা খুব জঘন্য\nএবং ঘৃণিত। স্বামী স্ত্রী পরস্পর পরস্পরকে বুঝতে হবে। এবং পরস্পরের মধ্যে থাকতে হবে\nশ্রদ্ধাবোধও। থাকতে হবে ধর্য্য, সহনশীলতা এবং সাধ্যের মধ্যে তুষ্টি। সুখ দুঃখ মিলিয়েই\nতো মানুষের জীবন। সময় সব সময় একভাবে নাও যেতে পারে। আর টাকা পয়সাও যে শুধু সুখ এমনটাও\nভুল। সংসারে টাকা পয়সার চেয়ে ভালবাসাটা গুরুত্বপূর্ণ। ভালবাসা থাকলে সুখ শান্তি পাশে\nথাকে, যা অর্থ দিয়ে কেনা যায় না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটি কথা স্মরণ রাখবেন-সন্তান যে\nকেউ জন্মাতে পারে। কিন্তু আদর্শ বাবা-মা সবাই হতে পারে না। আপনাদের মেয়ের করুণ পরিণতির\nজন্য আপনারা দুজনই দায়ি। বিশেষ করে একজন পুরুষ এবং গৃহকর্তা হিসাবে আপনি বেশি দায়ি।\nকোনভাবেই এর দায়ভার এড়াতে পারেন না। এখন আপনাদের কোলে যে সন্তানটি রয়েছে তারও ভবিষ্যৎ\nনির্ভর করছে আপনাদের বর্তমান আচরণের ওপর। ইচ্ছা করলে তাকে সুন্দরভাবে গড়তে পারেন,ইচ্ছা\nকরলে তারও ভবিষ্যৎ ধ্বংস করতে পারেন। তবে প্রতিটারই ভিন্ন ফলাফল রয়েছে। ক্ষতি যা হবার\nতা হয়ে গেছে। তা নিয়ে ভেবে আর কোন লাভ নেই। এখন আপনারা অতীতের ভুল থেকে শিক্ষা নিতে\nপারেন। আপনাদের কোলের এই সন্তানকে নিয়ে ভাবতে পারেন,স্বপ্ন দেখতে পারেন,নতুন করে সংসার\nসাজাতে পারেন। আমি চাই আপনাদের সংসার শান্তিময় হোক। আপনাদের সন্তানের ভবিষ্যৎ উজ্জ্বল\nহোক।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মিলন সাহেব নত মস্তকে শুধু হ্যাঁ সুচক মাথা নাড়ছেন। তার দু চোখ পানিতে ঝাঁপসা হয়ে গেছে। বার বার চোখ মুছছেন। মিসেস সুলতানা ফুপিয়ে ফুঁপিয়ে কাঁদছেন। তার গাল বেয়ে অশ্রু ঝরছে। হঠাৎ এক ফোটা তপ্ত অশ্রু কোলের বাচ্ছার নাকের পাশে পড়তেই সে ঘুম থেকে কেঁদে ওঠলো! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© জীম হামযাহ</p>\n<!-- /wp:paragraph -->', 'বিয়ের আগে কি আপনার স্ত্রীর সাথে\nপরিচয় ছিল?\nনা স্যার,মায়ের পছন্দে বিয়ে করেছি।\nআপনার কোন পছন্দ ছিল না?\nজ্বী মানে স্যার,মা প্রথমে পছন্দ\nকরে আমাকে পাঠিয়েছিলেন। আমি পছন্দ করে সম্মতি দেই,তারপর বিয়ে হয...', '', 9, NULL, 'publish', 2119, 0, '2019-02-11 15:16:06', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (31, 2391, 26, '‘গাছের দলের লোক’ ছড়ার বই', 'গাছের-দলের-লোক-ছড়ার-বই', '<!-- wp:paragraph -->\n<p> লেখক: ব্রত রায়<br> প্রকাশনী:   সারস প্রকাশনী <br> প্রচ্ছদ :  মামুন হোসাইন <br> ধরন : ছড়ার বই<br>মলাট মূল্য : ১২০ টাক<br>প্রাপ্তিস্থান:    সোহরাওয়ার্দী উদ্যানের ৩৮২ নং স্টলে ও লিটল ম্যাগাজিন চত্বরে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মানুষ প্রকৃতিরই অংশ৷ অথচ এই কথাটি মানুষ প্রায়ই ভুলে যায়৷\nযে কারণে প্রকৃতি ও পরিবেশ ধ্বংসের কারণ হয় সে৷ অথচ বুদ্ধিমত্তা, শুভবোধ, এগুলো\nমানুষেরই আছে এবং এগুলোর ব্যবহার করে প্রকৃতি, পরিবেশ এবং প্রকৃতিতে বসবাসকারী সকল অবোধ জীব ও প্রাণীর সুরক্ষা দেওয়ার দায়ও\nকিন্তু তার৷ তাই পৃথিবীতে দু\'রকমের মানুষ দেখা যায়৷ একদল পাখি শিকার করে, আরেকদল\nপাখির খাবার জোগায়৷ একদল গাছ কাটে, আরেকদল গাছ লাগায়, গাছের\nযত্ন করে৷ ছড়াকার ব্রত রায় শেষোক্ত দলটিকে বলছেন \'গাছের দলের লোক\'৷ তাঁর\nপ্রকৃতি ও পরিবেশ বিষয়ক এই নামের ছড়ার বইয়ে তিনি পরিবেশ ও প্রকৃতিপ্রেমকে উপজীব্য\nকরেছেন৷ তোমাদের জন্য লেখা এই ছড়ার বইয়ে রয়েছে গাছের কথা, ফুলের\nকথা, নদীর কথা, গ্রহ-উপগ্রহের কথা, সাগরতলের জীবনের কথা৷ রয়েছে গ্রামের কথা,\nঅপরিকল্পিত নগরায়নের কথা, অপরিণামদর্শী&nbsp; শিল্পায়ণের\nকথা৷ আমাদের পরিবেশ ও প্রতিবেশ আজ নানা কারনে বিপন্ন। তবুও তিনি স্বপ্ন দেখেন এমন এক পৃথিবীর যেখানে পরিবেশ\nহবে সকলের বাসযোগ্য । </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ছড়াগুলোর মধ্য দিয়ে তিনি পরিবেশ সচেতনতা ও প্রকৃতি প্রেমকে\nতোমাদের মধ্যে ছড়িয়ে দিতে চেয়েছেন৷ বাংলাভাষায় এরকম বই খুব বিরল৷</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;<br>\nচমৎকার প্রচ্ছদ করেছেন শিল্পী মামুন হোসাইন৷ সারস প্রকাশনী\nএনেছে বইটি যার মূল্য ১২০ টাকা৷ পাওয়া যাবে প্রাণের বইমেলায়\nসোহরাওয়ার্দী উদ্যানের ৩৮২ নং স্টলে ও লিটল ম্যাগাজিন চত্বরে।</p>\n<!-- /wp:paragraph -->', 'লেখক: ব্রত রায়\nপ্রকাশনী: সারস প্রকাশনী\nপ্রচ্ছদ : মামুন হোসাইন\nধরন : ছড়ার বই\nমলাট মূল্য : ১২০ টাক\nপ্রাপ্তিস্থান: সোহরাওয়ার্দী উদ্যানের ৩৮২ নং স্টলে ও লিটল ম্যাগাজিন চত্বরে।\nমানুষ প্রকৃতিরই অংশ৷ অথচ এই...', '', 1, NULL, 'publish', 2560, 0, '2019-02-12 13:56:35', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (32, 2397, 31, 'অস্তিত্ববাদ', 'অস্তিত্ববাদ', '<!-- wp:paragraph -->\n<p>কবিতার জন্ম হবে... <br>মৃত্যু নিশ্চিত জেনেওꟷ<br>তাইতো জাল বুনে চলেছে মাকড়সা। <br>জঠরে বড় করে তুলছে বংশধর। <br>অনসনে থাকা সঙ্গমরত টিকটিকি <br>টিকটিক করে জানান দেয়ꟷ<br>বংশের অস্তিত্ব। <br>ছারপোকা আর উকুনেরা <br>প্রতিযোগিতায় নেমেছে ডিম ছাড়ার;<br>থেমে নেই মশারাও । </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কবিতার জন্ম হবে... <br>তাইতো প্রতিনীধি টিকিয়ে রাখতেꟷ <br>মানুষের ভিতরে বড় হচ্ছে মানুষ;<br>ইউরেনিয়াম জড়ো হচ্ছে ক্রমানুসারে। <br>ক্ষমতানুসারে নেওয়া হচ্ছে তেলের দখল। <br>আবিস্কার হচ্ছেꟷ<br>অস্তিত্ব মুছে ফেলার যন্ত্র। <br>প্রতিনীধির হাতে মৃত্যু হচ্ছে <br>আরেক প্রতিনীধির ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© রাশেদ কিরণ</p>\n<!-- /wp:paragraph -->', 'কবিতার জন্ম হবে...\nমৃত্যু নিশ্চিত জেনেওꟷ\nতাইতো জাল বুনে চলেছে মাকড়সা।\nজঠরে বড় করে তুলছে বংশধর।\nঅনসনে থাকা সঙ্গমরত টিকটিকি\nটিকটিক করে জানান দেয়ꟷ\nবংশের অস্তিত্ব।\nছারপোকা আর উকুনেরা\nপ্রতিযোগিতায় নেমে...', '', 4, NULL, 'publish', 2783, 0, '2019-02-13 17:32:45', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (33, 2402, 28, 'আর্য পূর্ব বাংলা: দুই', 'আর্য-পূর্ব-বাঙলা-দুই', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\">  <strong>প্রকাশিত পর্ব সমূহ</strong><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be/\\">আর্য পূর্ব বাংলা: সূচনা</a><br>* <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%8f%e0%a6%95/\\">আর্য পূর্ব বাংলা: এক</a><br>*  <a href=\\"https://payasti.com/successive/%e0%a6%86%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%aa%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a6%ac%e0%a6%be%e0%a6%99%e0%a6%b2%e0%a6%be-%e0%a6%a6%e0%a7%81%e0%a6%87/\\">আর্য পূর্ব বাংলা: দুই</a>  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাঙালীর মন: কষ্টের কারণ এটুকু হতে পারে যে আমাদের প্রাচীন সভ্যতা,\nবীরত্ব গাঁথার ইতিকথা, প্রত্ন-তাত্ত্বিক বিষয় বিশ্লেষণে প্রমাণ করতে হচ্ছে, তার অর্থ\nএই নয় যে বাঙালীর ইতিহাস লজ্জাকর; অগৌরবের যাকে বলা হয় ‘অনার্য’। প্রাগৈতিহাসিক যুগ থেকে যেমন বাংলায়\nমানুষের বসবাস প্রমাণিত সত্য। তেমনি প্রাপ্ত প্রত্নতাত্ত্বিক নিদর্শন সমূহ থেকে জানা\nযায় প্রস্তর যুগ, প্রত্ন প্রস্তর যুগ, নব্য প্রস্তর যুগ, তাম্র প্রস্তর যুগ, এবং লৌহ\nযুগেও বাঙালি সমৃদ্ধ ছিল। মানব উন্নতির যেসব ধারাবাহিক লক্ষণ জানা যায় বাঙালি ঐতিহ্যও\nসমতালে প্রবাহিত। যেমন আগুন জ্বালানো এর ফলে মাটি দিয়ে নিত্য প্রয়োজনীয় বাসনপত্র তৈরি\nকরে আগুনে পুড়িয়ে ব্যবহারোপযোগি করা। আগুন জ্বালিয়ে খাদ্য দ্রব্য প্রস্তত করণ অর্থাৎ\nরান্নার প্রচলন করা এবং পদ্ধতিগত চাষাবাদের উদ্ভব করা। সমককালীন ইতিহাস পাঠে এবং উপাদান\nসমূহ নিরীক্ষে অনুমান করা যায় বাঙালি সেসব আবিস্কার কৃর্তির সমান দাবিদার, এর সপেক্ষে\nউপাদান অসংখ্য। বাংলাদেশের দক্ষিণ পশ্চিম সীমান্তে দুটো প্রস্তর যুগের হাতিয়ার আবিস্কৃত\nহয়েছে। হুগলি জেলার গোবিন্দপুরের কুনকুনুতে পাথরে তৈরি কুঠার পাওয়া গেছে। বর্তমানে\nফেনী জেলার ছাগলনাইয়ায় পুরাতন প্রস্তর যুগের শেষ দিকের পাথরে পরিনত হাত কুড়াল পাওয়া\nগেছে। চট্টগ্রামের সীতাকুন্ডেও প্রস্তর যুগের অস্ত্র পাওয়া গেছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>দক্ষিণ ভারতের মাদ্রাজে প্রত্ন প্রস্তর যুগের যে হাতিয়ার পাওয়া গেছে তার সাথে বাংলাদেশে পাওয়া নিদর্শনগুলোর সাদৃশ্য রয়েছে। আকারগত এবং দুটি অন্ত্র এই জাতের পাথর দিয়ে তৈরি। এ সব পাথর বাংলায় পাওয়া যায় না।</p><cite> - তোফায়েল আহমদ - পূবোক্ত পৃষ্ঠা, ১৬  </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>এ বক্তব্য থেকে দৃঢ় কন্ঠে উচ্চারণ করা যায় না যে প্রস্তর যুগেও বাঙালি সমূদ্র তীরে আত্ম মগ্নতায় আড়ষ্ঠছিল না। বিশ্ব সভ্যতার সাথে শুধু পরিচয়ই ছিলনা; বাণিজ্যিক সম্পর্কও ছিল সু-গভীর।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দিল্লী বিশ্ববিদ্যালয়ের প্রত্নতত্ত্ব বিভাগের অধ্যাপক ডাঃ দিলীপ\nকুমার চক্রবর্তী ১লা জানুয়ারী ১৯৮৯ সালে কুমিল্লার লালমাইর দক্ষিণ পশ্চিম প্রান্তে\nচণ্ডিমুড়ার কাছে আড়াইশর মতো অশ্নীভূত কাঠের হাতিয়ার পান। তার মধ্যে রয়েছে কুঠারাদি।\nহাতিয়ার গুলো উচ্চ প্যালিওলিথিক যুগের বিশ হাজার বছরের পুরানো বলে তিনি মনে করেন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>নরসিংদী জেলার উয়ারী বটেশ্বরে প্রন্ত প্রস্তর যুগের হস্ত কুঠার নব্য প্রস্তর যুগের বাটালী, কুঠার প্রভৃতি পাওয়া গেছে। তার থেকে এখানে মানব বসতি একলক্ষ থেকে দশ হাজার বছরের পুরানো বলে অনুমান করা যায়।</p><cite> - তোফায়েল আহমদ- পূবোক্ত পৃষ্ঠা ১৪ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>কেউ কেউ মনে করেন নরসিংদীতে প্রাপ্ত হাতিয়ার প্রস্তর যুগের শেষ\nদিকে এবং লোহা যুগের সুচনা কালের তৈরী। এছাড়াও চব্বিশ পরগনা জেলার ০১ থেকে ৩ লক্ষ বছরের\nপ্রাচীন নিদশর্ন পাওয়া গেছে। বাকুড়া জেলার খাতড়ায় পাওয়া গেছে প্রত্ন প্রস্তর যুগের\nহাতিয়ার। সভ্যতার বিবর্তনে মানুষ ক্রমশ ধাতুর ব্যবহার আয়ত্ত করে। তামা দিয়ে হাতিয়ার\nতৈরীতে সার্থকতা লাভ করে এই সময়কে ইতিহাসে তাম্রপ্রস্তর যুগ বলে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>এই তাম্র প্রস্তর যুগের নিদর্শনও বাংলাদেশে আবিষ্কৃত হইয়াছে। ১৯৬২-৬৩ সালে পশ্চিম বঙ্গ সরকারের প্রত্ন বিভাগ কর্তৃক পশ্চিম বঙ্গের বীরভূম ও বর্ধমান জেলায় অজয়, কুনুর ও কোপাই নদীর তীরে প্রত্ন তাত্ত্বিক খনন কার্জের ফলে এই অঞ্চলে তাম্রর-প্রস্তর যুগের নিদর্শন আবিস্কৃত হইয়াছে।</p><cite> - বাংলাদেশের ইতিহাস- পূবোক্ত পৃঃ ১৬ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>খ্রিষ্টপূর্ব দেড় হাজার বছর পূর্বের পান্ডুরাজার ডিবিতে প্রাপ্ত\nনিদর্শনে স্পষ্টতই অনুমান করা যায় বাঙালি পাথর, শীশা, তামা ও লোহার ব্যবহারে ছিল পরাঙ্গম।\nব্রোঞ্জ যুগের উন্নত সভ্যতার কথা শোনা যায় বাঙালায় তা দুর্লক্ষ নয়, মহাস্থান গড়ে খ্রিষ্টপূর্ব\nতৃতীয় শতকের শিলালিপিতে এর প্রমাণ রয়েছে। অতি সম্প্রতি বর্তমান শরিয়তপুর জেলার নড়িয়া\nউপজেলায় তামার তৈরী একটি বিশাল আকৃতির কামান প্রাপ্ত রয়েছে, এটির নির্মাণ কাল নিরূপিত\nহলে অনেক তথ্য বেরিয়ে আসবে, যা গবেষকগণের কাজ সহজ করে দিবে । </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আজ অবধী আবিস্কৃত উপকরণের দৃষ্টে বাঙালি সভ্যতার প্রাচীনতা সর্বাংশে\nলক্ষিত হয়। ভারত বর্ষে যখন আর্য নামক উন্নত সংস্তৃতির বাহকদের আগমন ঘটে। যারা এ উপমহাদেশে\nসভ্যতার আলোকিত করেছে বলে দাবী করা হয়। বাঙলায় প্রাপ্ত উল্লিখিত কতিপয় প্রত্ন তাত্ত্বিক\nনিদর্শন মনে করিয়ে দেয় যে, আর্য আগমনের বহু পূর্বেই ধারাবাহিক সভ্যতার সাথে বাঙালির\nপদচারণা ছিল সচল। এ বিষয়ে পরবর্তীতে আলোচনার প্রয়োজন রয়েছে, তার পূর্বে বাঙালি উন্নত\nসভ্যতা প্রমাণের আরও কিছু বিষয় উল্লেখ আবশ্যক। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রস্তর যুগের মানুষ দলবদ্ধ ভাবে বসবাস করতো। এই দলব্ধতার মাধ্যমে\nগড়ে উঠে সমাজ জীবনের বিধিবিধান, নেতৃত্বদান ও গ্রহণের প্রয়োজনীয়তা। সমাজিক রীতি নীতি\nমেনে সুশৃঙ্খল জীবন যাপনের অনুভূতি জাগ্রত হতে শুরু করে। এই যুগেই মানুষের কল্পনা শক্তি\nপ্রেরণা যোগায় নব উদ্ভাবনের এবং সেই চেতনার ফসল সুদৃশ্য এবং সহজ ব্যবহারপযোগী হাতিয়ার।\nআগুনের আবিস্কার ও ব্যবহার আয়ত্বে এনে মানুষের শিল্পী সত্ত্বার প্রকাশ ঘটে। মৃৎ শিল্পের\nশুরু তখন থেকেই। মৃৎপাত্র আজও সৌখিন উপকরণ হিসাবে সমাদৃত। প্রস্তরযুগ থেকে শরু করে\nলৌহযুগ পর্যন্ত বিশ্লেষণে অনুমান করা যায়। এই সময়ের মধ্যে মানুষ আদিম জটিল জীবনের সীমা\nঅতিক্রম করে ক্রম নগর সভ্যতার পত্তন ঘটায়। এ সময় পেশা ভিত্তিক জনধারা বিভাজন ঘটতে থাকে।\nকৃষক, হাতিয়ার প্রস্ততকারী (কামাড়), মৃৎশীল্পি, (কুমার) পশু শিকারীর পাশাপাশি সূচনা\nহয়, বণিজ্যের এবং মুদ্রা বিনিময়ের। বোধ করি প্রাচীন পন্য বিনিময় প্রথা থেকে মুদ্রা\nবিনিময় প্রথায় উন্নত হয়ে মানুষ বিভিন্ন শ্রেণিতে বিভক্ত হয়ে পড়ে। যার ফলে সমাজে উঁচু\nনীচু ভেদ সৃষ্টি হয় যা পরবর্তী সময় শ্রেণী দ¦ন্ধে রুপ নেয়। সে যা হোক নগর সভ্যতার\nপ্রধান অনুষঙ্গ বণিজ্যিক উৎপাদন এবং বাণিজ্যিক সমৃদ্ধির পরিচয় বহুক্ষেত্রে প্রমাণিত।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পূর্বে উল্লিখিত পান্ডুরাজার ডিবিতে স্টাটাইট (steatite) পাথরের কতগুলো চিহ্ন খোদিত একটি সীল\nপাওয়া গেছে, ঐতিহাসিকগণ মনে করছেন সীলটির খোদিত চিহ্ন চিত্রাক্ষর এবং ভূমধ্যসাগরীর\nক্রীট দ্বীপের এবং এর নির্মাণ কাল প্রায় সাড়ে তিন হাজার বছর পূর্বের। মানব সব্যতার\nপ্রাচীন আবাস স্তল ভূমধ্য সাগরীর ত্রীট দ্বীপের সাথে বাঙালির বাণিজ্যিক সম্পর্কের উৎকৃষ্ট\nউদাহরণ এটি। প্রাচীন বাঙলায় শিমূল তুলো দিয়ে কাপড় তৈরি করে বিক্রি করা হত। বাঙলায় তৈরী\nমশৃন কাপড় ব্যবহার তখনকার দুনিয়ায় ছিল আভিজাত্যের বিষয়। ‘খ্রিঃ পূর্ব চতুর্থ শতকে লেখা কৌটিল্যের অস্ত্রশাস্ত্রে বঙ্গ ও পুন্ডে উৎপাদিত\nবাঙ্গত ও পৌন্ড্রক নামক অত্যন্ত মিহি রেশমী কাপড়ের উল্লেখ আছে। প্রাচীন বাঙলার বস্ত্র\nশিল্পের প্রমাণ এখানে। রামায়নের অযোদ্ধাকান্ডে ‘কৈকয়ীর বর প্রার্থনা’ অধ্যায় বৃদ্ধ রাজা দশরথ বিষন্ন যুবতি স্ত্রী কৈকয়ীকে তুষ্ট করতে প্রতিশ্রুতি\nদেন অঙ্গ, বঙ্গের মধ্যে যে দ্রব্য কৈকয়ীর পছন্দ তাই এনে দেবেন। এ থেকে বলা যায় রামায়ন\nকালের বঙ্গের সভ্যতা জাত শিল্প সামগ্রীর শ্রেষ্ঠত্ব প্রমাণিত সত্য। এছাড়াও সেকালে হাতির\nদাত, মসলা, গুড়, সোনা, হীরা প্রভৃতি বাঙলার প্রধান বাণিজ্যিক দ্রব্য। বাণিজ্যিক সম্পর্ক\nছিল ইন্দোনেশিয়া চীন কম্পোডিয়া, থাইল্যান্ড, মায়ানমার, শ্রীলঙ্কা সহ সমগ্র আরবদেশ এবং\nইউরোপের সভ্য অংশের সাথে, প্লিনির ‘ইন্ডিকা’ নামক গ্রন্থ বাঙলার প্রাচীন বাণিজ্যের কথা আছে। টলেমী, দিওদোরাস, কার্টিয়াস,\nব্লুতার্ক, সলিনাস, স্টাবো প্রমুখ গ্রীক ও ল্যাটিন লেখকগণের গ্রন্থে এ বিষয়ের উল্লেখ\nরয়েছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘প্যারিপ্লাস অব দ্যা (ইরিত্রিয়ান) সি’ নামক গ্রন্থ যার রচনা কাল ৪৪ সাল বলে উল্লেখ রয়েছে। এ গ্রন্থে বাঙালির বাণিজ্যক\nপ্রতিষ্ঠার কাহিনী বর্ণিত হয়েছে এভাবে-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>‘অত:পর পথ পুনরায় বাঁকনেয় এবং ডানে মুক্ত সমূদ্র এবং বায়ে দূরে উপকুল রেখে জাহাজ চালালে পরে গঙ্গা দেখা যায়, এবং তার কাছেই পূর্ব দিকে সর্বশেষ সূবর্ণ ভূমির নিকটে নদী আছে নাম গঙ্গা এবং এই নদীর উপত্তি এবং বিলয় ঠিক নীল নদের মতো। এই নদীর তীরে এক হাট পত্তন আছে। তার নাম ও নদীর নাম একই গঙ্গা। এইখান দিয়ে আসে তেজপাতা, গাঙ্গেয় সুগন্দি তৈল ও মুক্তা এবং সর্বাধিক উৎকৃষ্ট প্রকারের মসলিস যাকে বলা হয় গাঙ্গেয়। শোনা যায় যে, এই সব স্থানের নিকটে সোনার খনি আছে এবং এক রকম সোনার মোহর চলে যাকে বলে কলতিস।’</p><cite> - খন্দকার মাহমুদুল হাসান – বাংলার প্রাচীন সভ্যতা ও পুরাকীর্তি, শিখা প্রকাশনি, ১ম প্রকাশ ২০০০, ঢাকা, পৃঃ ২৫ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>শুধু বাণিজ্যক সাফল্য নয়, বাঙালীর সাহসী অভিযানের সাফল্যের প্রমাণ\nরয়েছে, বাঙালীর বীর সিংহ বাহুর পুত্র বিজয় সিংহ ৫৪৪ খ্রিষ্ট পূবার্ধে এক অভিযানে প্রাচীন\nতা¤্রপনী বর্তমান\nশ্রীলংকা জয় করেন। তার নামানুসারে এর নামকরন হয় সিংহল, শ্রীলংকার ইতিহাসে আজও সে অধ্যায়\nউজ্জ্বল </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\\"wp-block-quote\\"><p>‘বিজয় কর্তৃক সিংহল বিজয় বঙ্গ দেশের তদানীন্তন কালের একটি অতিশ্রেষ্ঠ ও স্মরণীয় ঘটনা।... সিংহল বিষয়কেই আমরা বঙ্গদেশের সর্বশ্রেষ্ঠ কীর্তি বলিয়া মনে করি।’</p><p></p><cite> - দীনেশ চন্দ্র সেন – বৃহৎবঙ্গ, ১ম খ-, কলিকাতা ১৯৯৩, পৃঃ ৮৩-৮ </cite></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p> ©  হারিস মিজান</p>\n<!-- /wp:paragraph -->', 'প্রকাশিত পর্ব সমূহ\n* আর্য পূর্ব বাংলা: সূচনা\n* আর্য পূর্ব বাংলা: এক\n* আর্য পূর্ব বাংলা: দুই\nবাঙালীর মন: কষ্টের কারণ এটুকু হতে পারে যে আমাদের প্রাচীন সভ্যতা,\nবীরত্ব গাঁথার ইতিকথা, প্রত্ন-তাত্ত্বিক বিষয...', '', 2, 3, 'publish', 3435, 0, '2019-02-16 11:38:59', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (34, 2410, 2, 'রণগাজি বিশ্বাস: অবিভক্ত বাংলায় বাউল ধারার অন্যতম পথিকৃৎ', 'রণগাজি-বিশ্বাস-অবিভক্ত-ব', '<!-- wp:paragraph -->\n<p>রণগাজি বিশ্বাস; প্রকৃত\nনাম ফরিদ খান গাজি। ১৩৭১ খ্রিষ্টাব্দে পশ্চিমবঙ্গের হুগলি জেলার ত্রিবেনীতে (গঙ্গা,\nযমুনা ও স্বরসতী নদীর সংযোগস্থল) জন্মগ্রহণ করেন। তিনি ছিলেন বহুমুখী প্রতিভার অধিকারী,\nযার স্খূরণ তাঁর ব্যক্তিজীবনে\nপুরোমাত্রায় লক্ষণীয়। আধ্যাত্ব সাধনার পাশাপাশি একজন সমরবীদ ও স্থপতি হিসেবে নিজেকে\nপ্রতিষ্ঠিত করতে স্বক্ষম হয়েছেন। পান্ডুয়ার (পশ্চিমবঙ্গের মালদা জেলায় অবস্থিত) বিখ্যাত\nসাধক ও দরবেশ শেখ নূর কুতুবউল আলম (র.) এর প্রতিষ্ঠিত মাদ্রাসায় অধ্যয়ণরত অবস্থায় হযরত\nখানজাহান আলী (র.)’র সাথে তাঁর সখ্যতার সূত্রপাত। একথা ঐতিহাসিকভাবে\nস্বীকৃত যে, বাবার মৃত্যুর পরে হযরত খানজাহান আলী (র.) কে কর্মসংস্থান করে দেওয়ার জন্য\nজৈনপুরের (বর্তমানে ভারতের উত্তরপ্রদেশের অংশবিশেষ) সুলতান ইব্রাহীম শর্কীকে শেখ নূর\nকুতুবউল আলম পত্র প্রেরণ করেছিলেন। উক্ত পত্রের পরিপ্রেক্ষিতে সুলতান ইব্রাহীম শর্কী\n১৩৮৯ সালে হযরত খানজাহান আলী (র.)’কে তার বাহিনীতে সৈনিক\nহিসেবে নিযুক্ত করেন। ধারণা করা হয়, সেনাবাহিনীতে ভর্তির সময় হযরত খানজাহান আলী (র.)\nতাঁর একান্ত সহচর রণগাজি বিশ্বাসকেও সঙ্গে নিয়েছিলেন। রণক্ষেত্রে তাদের সাফল্যে সুলতান\nইব্রাহীম শর্কী অত্যন্ত খুশি হন; ফলে অতি অল্প সময়ের মধ্যে পদোন্নতি লাভ করেন। সাফল্যের\nধারাবাহিকতায় ১৩৯৪ সালে হযরত খানজাহান আলী (র.) জৈনপুর প্রদেশের জাবিতান (গর্ভণর) পদে\nঅধিষ্টিত হয়। বাংলায় তখন ইলয়াস শাহী বংশের শাসন চলছিল। কিন্তু দিনাজপুরের হিন্দু জমিদার\nরাজা গণেশের ষঢ়যন্ত্রের কারণে রাজ্যে সুস্থিরতা ছিল না; ১৪০০-১৪১১ খ্রিষ্টাব্দের মধ্যে\nগৌড়ের রাজা সাইফুদ্দিন হামযা শাহ’কে হত্যা করে রাজা গণেশ নিজেকে স্বাধীন রাজা\nহিসেবে দাবি করেন। মুসলমানদের জীবনে তখন চরম দুর্যোগ; গণেশের বাহিনী বাংলা থেকে মুসলমান\nনির্মুল করতে ব্যাপক হত্যাযজ্ঞ পরিচালনা করেন। মুসলমানদের রক্ষা করতে পান্ডুয়ার দরবেশ\nশেখ নূর কুতুবউল আলম জৈনপুরের সুলতানকে অনুরোধ করেন। মুসলমানদের দূর্দিনে সুলতান ইব্রাহীম\nশর্কী সেদিন সাহায্যের হাত প্রসারতি করেছিলেন, হযরত খানজাহান আলী (র.) এর নের্তৃত্বে\nবাংলায় অভিযান চালাতে বিশাল বাহিনী পাঠিয়েছিলেন। বাহিনীর সাথে কয়েকজন সুফি সাধক ও প্রকৌশলী\nএসেছিলেন- রণগাজি বিশ্বাস যাদের একজন। হযরত খানজাহান আলী (র.) দুই পর্বে বাংলায় অভিযান\nচালায়। প্রথম পর্বে অনেকটা বিনাযুদ্ধে রাজা গণেশকে বিতাড়িত করে তার পুত্র যদুকে (ইসলাম\nধর্ম গ্রহণ করে জালালুদ্দিন মুহাম্মদ নাম ধারণ করে) বাংলার মসনদে আসীন করেন। হযরত খানজাহান\nআলী (র.)’র বাহিনী জৈনপুরে ফিরে\nগেলে কুটকৌশলী রাজা গনেশ তার পুত্রকে ক্ষমতাচ্যূত করে পুনরায় রাজ্যের দখল নেয় এবং নির্বিচারে\nমুলমানদের হত্যা করে; ফলে নতুন করে বাংলা অভিযান অপরিহার্য হয়ে ওঠে। দ্বিতীয় পর্বে\nহযরত খানজাহান আলী (র.) চুয়াডাঙ্গার দৌলতগঞ্জ বন্দর দিয়ে ছোট্ট বাহিনী নিয়ে বাংলায়\nপ্রবেশ করেন। উল্লেখ্য চুয়াডাঙ্গার জীবননগর উপজেলায় ভৈরব নদীর তীরে অবস্থিত দৌলতগঞ্জ\nএকসময় গুরুত্বপুর্ণ নদীবন্দর ছিল। খানজাহান আলী’র বাহিনী ঝিনাইদহ জেলার\nকোটচাঁদপুরের হাকিমপুর হয়ে বারবাজারে প্রবেশ করে। বলার অপেক্ষা রাখে না, রণগাজি বিশ্বাস\nছিলেন ওই বাহিনীর বিশেষ সদস্য। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ইতিহাসের পাতায় বারবাজার\nএকটি ঐতিহাসিক নাম। শহরটি প্রথম শতকে গঙ্গারিডি রাজ্যের রাজধানী ছিল। হযরত খানজাহান\nআলী (র.) ও তাঁর অনুসারীদের আগমনে শহরটি নতুন করে প্রাণ ফিরে পায়; পুরাতন স্থাপনা সংস্কারের\nপাশাপাশি নতুন-নতুন পুকুর, মসজিদ, মক্তব গড়ে ওঠে। একজন স্থপতি হিসেবে নতুন স্থাপনার\nসাথে রণগাজি বিশ্বাসের নিবিড় সম্পৃক্ততা রয়েছে। শুধু বারবাজার নয় তৎকালীন সময়ে যশোরের\nমুরলী এবং বাগেরহাট-খুলনা-সাতক্ষীরায় নির্মিত অসংখ্য স্থাপনার সাথে তাঁর পরোক্ষ বা\nপ্রত্যক্ষ সম্পৃক্ততা বিদ্যমান। ১৪২৯ খ্রিষ্টাব্দে বাগেরহাটের নামকরণ খলিফাতাবাদ হওয়ার\nপূর্ব-মুহূর্ত পর্যন্ত রণগাজি বিশ্বাস বিস্বস্থ অনুচর হিসেবে হযরত খানজাহান আলী (র.)’র সাথে ছিলেন বলে ধারণা\nকরা হয়; এ সময়ে বাগেরহাট-সাতক্ষীরা অঞ্চলে বেশ কিছু যুদ্ধ সংঘটিত হয়; রাজা কর্ণওয়ালী,\nরাজা বলভদ্র দেব ও রাজা লালচন্দ্র সম্মিলিতভাবে খানজাহান আলীর রাজ্য প্রতিষ্ঠায় বাঁধা\nহয়ে দাঁড়ায়। কিন্তু সহচরদের বীরত্বপুর্ণ লাড়াইয়ে কোনো বাঁধাই তাঁর পথ অবরুদ্ধ করতে\nপারে না; কর্ণপুর, সামান্তাসেনা, রণভূমি রণজিতপুর, পিলজঙ্গ, রণবিজয়পুর, ফতেপুর, বিজয়পুরসহ\nবিস্তির্ণ এলাকায় মুসলামানদের নিয়ন্ত্রণ প্রতিষ্ঠিত হয়। যুদ্ধে বীরত্বপুর্ণ অবদানের\nজন্য হযরত খানজাহান আলী (র.) রণগাজি বিশ্বাসকে ‘গাজি’ উপাধীতে ভূষিত করেন।\n‘গাজি’ খেতাবের জন্য সরল সমিকরণ\nএরুপ যে, ইসলাম ধর্মমতে ধর্ম বিষয়ক কোন যুদ্ধে অংশগ্রহণকারী যোদ্ধা মারা গেলে শহীদ\nএবং বেঁচে থাকলে গাজি হিসেবে পরিচিত হয়। অতএব রণগাজি বিশ্বাসের ‘গাজি’ উপাধি বিষয়ে বিতর্কের\nকোন সুযোগ নেই! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নিবিড়ভাবে লক্ষ্য করলে\nদেখতে পাই, হযরত খানজাহান আলী (র.) ও তার অনুসারীরা রাজ্য বিস্তারের চাইতে ইসলাম প্রচারে\nঅধিক মনোযোগী ছিলেন। হয়তো এ কারণেই বাংলার মসনদ থেকে রাজা গণেশকে উৎখাত করে জৈনপুরে\nফিরে না গিয়ে বাংলায় ইসলাম প্রচার করেন; ধর্ম প্রচারের জন্য সুলতান ইব্রাহীম শর্কী\nও জালালুদ্দিন মুহম্মদ শাহ’র প্রেরণা ও চিশতিয়া তরিকার পীর শেখ নূর কুতুবউল\nআলমের নির্দেশনা পেয়েছিলেন। নির্দেশনা অনুসারে সদলবলে বাংলার দক্ষিণ অংশে রওনা হয়।\nবারবাজার থেকে যশোরের মুরলী হয়ে খুলনা-সাতক্ষীরার ভিতর দিয়ে বাগেরহাট পেঁছায়। হযরত\nখানজাহান আলীর ধর্ম প্রচারের কৌশল পর্যালোচনা করলে দেখা যায়, বিজিত অঞ্চল ছেড়ে নতুন\nঅঞ্চলে যাওয়ার সময় ওই অঞ্চলে ইসলাম প্রচারের জন্য একান্ত কাছের অনুচর বা শিষ্যদের রেখে\nযেতেন। বারবাজারের দায়িত্ব পেয়েছিলেন বড়গাজি খাঁ ও কালু শাহ, মেহেরপুরের দায়িত্বে পীর\nমেহেরুল্লা এবং মুরলীর দায়িত্বে শাহ গরিব ও বুরহান শাহ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>১৪২৯ খ্রি. পরবর্তী\nকোন এক সময়ে হযরত খানজাহান আলী (র.) এর নির্দেশে রণগাজি বিশ্বাস ইসলাম প্রচারের উদ্দেশ্যে\nআলমডাঙ্গা জনপদে উপস্থিত হয়; এবং আলমডাঙ্গা শহরের অনতিদূরে ফরিদপুর গ্রামের নির্জন\nপরিবেশে আস্তানা গাড়েন। ফরিদপুরে আস্তানা গাড়ার কারণ হিসেবে নানাজনের নানামত- সুফি-সাধকরা\nনির্জনতা পছন্দ করেন, এজন্য পাঙ্গাসিয়া খালের ওপারে নির্জন স্থানে অবস্থান নেওয়া! কারও\nকারও মতে, নতুন জনপদে উপস্থিত হয়ে জীবনের এই বিশেষ অধ্যায় তিনি (রণগাজি বিশ্বাস) নতুনভাবে\nআরম্ভ করতে চেয়েছিলেন, যেজন্য প্রয়োজন ছিল ফরিদপুরের মতো নির্জন ভূখন্ড। স্থাপত্যশিল্পের\nপ্রকরণগত নিরিখে গোলবাগান ও বাগেরহাটের স্থাপনার তত্বতালাশ করলে দেখি বদলে যাওয়া মানসিকতার\nপ্রতিচ্ছবি! ইট-কাঠ-পাথরের অট্টালীকার পাশাপাশি গোলবাগান অনেক বেশি নৈসর্গিক এবং আধুনিক\nমনস্কতার পরিচায়ক। ফরিদপুরের নির্জন প্রান্তরে রণগাজি বিশ্বাস যেনো এক বদলে যাওয়া সাধক;\nনয়ণের প্রান্তসীমায় বাঁক বদলের হাতছানি! একথা মিথ্যে নয় যে, নতুন জনপদ গড়ে ওঠার প্রধানতম\nপুর্বশর্ত হলো জলের প্রাপ্যতা- জলের প্রাপ্যতার জন্যই হয়তো পাঙ্গাসিয়ার তীরবর্তী এলাকা\nবেছে নেওয়া। উল্লেখ্য তৎকালীন সময়ে ফরিদপুরের পাশ ঘেঁষে পাঙ্গাসিয়া নামক খরস্ত্রোতা\nখাল বহমান ছিল। কালপরিক্রমায় পাঙ্গাসিয়ার অস্থিত্ব বিলুপ্তির পথে; ফরিদপুরের পাশ ঘেঁষে\nগোবিন্দপুর হয়ে আলমডাঙ্গা রেলস্টেশনের গাঁ বেয়ে সর্পিল গতিতে পাঙ্গাসিয়ার যে ক্ষীণ\nধারা কামালপুর-কুমারী অভিমুখে বয়ে চলেছে তা দেখে আন্দাজ করার উপায় নেই, এই সেই পাঙ্গাসিয়া!\nরণগাজি বিশ্বাস নিজেও হয়তো পাঙ্গাসিয়ার জলে ভেসে ভেসে সঙ্গী-সাথীদের নিয়ে ফরিদপুরে\nউপস্থিত হয়েছিলেন; ইসলাম প্রচারের জন্য আশেপাশের গ্রামগুলোতে ছড়িয়ে পড়েছিলেন। তবে ইসলাম\nপ্রচারের কাজটি সহজসাধ্য ছিল না। বিশেষত এলাকার মানুষের মধ্যে ধর্ম বিষয়ে বিশেষ আগ্রহ\nছিল না বললেই চলে; সারাক্ষণ বৈরাগ্য ভাব, কাজেকর্মে অনীহা, গান-বাজনায় বিশেষ অনুরক্ত।\nধর্ম প্রচারের ক্ষেত্রে রণগাজি বিশ্বাসও কৌশলী হয়েছিলেন, গান-বাজনাকে সিদ্ধি লাভের\nউপায় হিসেবে বিবেচনা করেছিলেন। সাধারণ জনগণকে আকৃষ্ট করতে এলাকাবাসীকে জমায়েত করে খাওয়া-দাওয়া\nও গান-বাজনার আয়োজন করতেন; গানে গানে ছড়িয়ে দিতেন ইসলামের অমর বাণী। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রণগাজি বিশ্বাসের এমনতর\nপরিবর্তন যে আরোপিত, ঠিক তা নয়; বরং স্বতস্ফূর্ত- জন্মসূত্রে তিনি এই স্বতস্ফূর্ততা\nঅর্জন করেছিলেন। পরিবারের মধ্যে ভিন্ন ভিন্ন ধর্মমত প্রচলিত ছিল। বাবা মুসলমান হলেও\nতাঁর আপন দুই চাচা সনাতন ধর্মানুসারী। জন্মস্থান ত্রিবেনীতে যেমন ভিন্ন ধর্মাবলস্বীদের\nমেলবন্ধন ছিল, তেমনি বন্ধন ছিল পারিবারিক পরিমন্ডলে; পারিবারিক সূত্রে বৈঞ্চব সম্প্রদায়ের\nধর্মাচার প্রত্যক্ষ করার সুযোগ হয়েছিল। শুধু হিন্দু-মুসলমান নয় ত্রিবেনীর সাথে খৃস্টান\nসম্প্রদায়েরর যোগসূত্র রয়েছে। জাফর খান গাজি মসজিদ এখনো আমাদের ধর্মীয় ঐক্যের কথা স্মরণ\nকরিয়ে দেয়। ইতিহাসের স্বাক্ষী হয়ে দাঁড়িয়ে থাকা মসজিদটি বাংলার প্রাচিনতম মসজিদ। ধারণা\nকরা করা হয় ওই জাফর খান গাজি’ই রণগাজি বিশ্বাসের পুর্বপুরুষ। ইখতিয়ার উদ্দীন\nমুহাম্মদ বিন বখতিয়ার খিলজির বাংলা জয়ের অব্যবহিত পরেই জাফর খান গাজি হিন্দুদের তীর্থস্থান\nত্রিবেনীতে হামলা চালায়; অসংখ্য মন্দির ভাংচুর করেন! জাফর খান গাজির নামে পরিচিত বিশেষ\nওই মসজিদটি কোন এক মন্দিরের ধ্বংসস্তুপের উপর নির্মিত! মসজিদের একপাশের দেওয়ালে হিন্দু\nদেব-দেবীর মূর্তি আঁকানো রয়েছে! এ থেকে ধারণা করা হয়, বস্তুত জাফর খান গাজি ছিলেন সুফিবাদের\nঅনুসারী। সম্ভবত সংক্ষুব্ধ হিন্দুদের ক্ষোভ প্রশমন করে শান্তিপুর্ণ সহাবস্থানের জন্য\nমসজিদের দেওয়ালে চিত্র অংকন করেছিলেন! তো, এমন একটি ধর্মীয় ও সাংস্কৃতিক পরিমন্ডলে\nজন্মগ্রহণের সূত্রে যে কেউ সুফিবাদের প্রতি ঝুঁকতেই পারে! কিন্তু আলমডাঙ্গা অঞ্চলে\nরণগাজি বিশ্বাস যে মত লালন ও প্রচার করেন তা সুফিবাদ থেকেও খানিকটা ভিন্নতর। এই ভিন্নতর\nবিষয়-আশয় এলাকার মানুষ স্বতস্ফূর্তভাবে গ্রহণ করেছিল। বলতে দ্বিধা নেই, সমকালে ওই বিশেষ\nমতের অনুসারীরা বাউল সম্প্রদায় হিসেবে পরিচিত। এ বিবেচনায় রণগাজি বিশ্বাস’ই অবিভক্ত বাংলায় বাউল\nসম্প্রদায়ের অন্যতম পথিকৃৎ! তাঁর অনুসরিত ধর্মাচার বৃহত্তর যশোর-কুষ্টিয়াসহ সারা বাংলায়\nছড়িয়ে পড়েছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রণগাজি বিশ্বাস এবং\nফরিদপুর নামটি অঙ্গাঅঙ্গিভাবে জড়িত। সাতশো ফকিরের (বাউল সাধক) গ্রাম হিসেবে খ্যাত ফরিদপুর\nগ্রামটি বাউল সম্প্রদায়ের নিকট তীর্থস্থান। সারা বাংলায় এমন গ্রাম আর একটিও পাওয়া যাবে\nনা, যেখানে এতো অধিক সংখ্যক বাউল বসবাস করে! গ্রামের দক্ষিণ পাশে অবস্থিত গোলবাগানটি\nসাধকের স্মৃতিচিহ্ন বহন করে চলেছে। বাগানের প্রতিটি গাছ তাঁর স্বহস্তে লাগানো। রণগাজি\nবিশ্বাস যে কত উঁচু মানের স্থপতি ছিলেন, বাগান না দেখলে তা বিশ্বাস করা কঠিন! সাম্প্রতিক\nসময়ে বৃক্ষ বা লতাগুল্ম দ্বারা ভাস্কর্য্য নির্মাণের যে প্রবণতা লক্ষ করছি, একজন রণগাজি\nবিশ্বাস তা ৬০০ বছর আগে করে দেখিয়েছেন! নিদৃষ্ট দূরত্বে তেঁতুল গাছ লাগিয়ে তিনি একটি\nবৃত্ত রচনা করেছেন। বৃত্তের যেমন বৈজ্ঞানিক তাৎপর্য আছে, তেমনি আছে জগত-সংসার- এমন\nকী ধর্মাচারের মাহাত্মি! অর্থাৎ এখনও যা আমাদের ভাবনায় অনুপস্থিত, তা ওই বিশেষ বৃত্তাকৃতির\nবাগানে ইঙ্গিতময়! ইঙ্গিতের মর্মার্থ অনুধাবনে বাউল সাধকরা তৎপর; বহুকৌণিক দৃষ্টিতে\nএকজন রণগাজি বিশ্বাসকে নিয়ে বাংলার বাউল সম্প্রদায় সাধনা করে চলেছেন! বৃক্ষ দ্বারা\nরচিত বৃত্তের ঠিক মাঝখানে এই মহান সাধকের মাজার। মাজারকে কেন্দ্র করেও রয়েছে অসংখ্য\nকিংবদন্তি! কথিত আছে বিশেষ ক্ষণে কালো কাপড়ে আবৃত হয়ে, ভক্ত পরিবেষ্ঠিত অবস্থায় তিনি\nধ্যানমগ্ন হয়েছিলেন। গুরুর জন্য ভক্তকূল অপেক্ষারত- কখোন ধ্যানভঙ্গ হয়! কিন্তু নিদৃষ্ট\nসময় পেরিয়ে গেলেও গুরুর সাড়া না পেয়ে পর্দা সরিয়ে লক্ষ্য করেন, গুরু সেখানে নেই; একটা\nসুড়ঙ্গ মাটির গভিরে চলে গেছে! তাঁর ভক্তরা মনে করে, বাউল ধারার পথিকৃৎ রণগাজি বিশ্বাস\nএভাবেই অর্ন্তধাণ হয়েছেন! অর্ন্তধাণ বিষয়ে ব্যক্তিতে ব্যক্তিতে মতপার্থক্য রয়েছে; অধিকাংশের\nমত তাঁর স্বাভাবিক মৃত্যু হয়েছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রণগাজি নামের আড়ালে\nপৈত্রিক নাম হারিয়ে গেলেও ফরিদপুর নামের সাথে সমার্থক হয়ে আছে ফরিদ খান গাজি। তাঁর\nনামানুসারেই যে গ্রামের নাম ফরিদপুর! বাউল সম্প্রদায়ের মানুষের কাছে তাঁর মাজারটি তীর্থ\nহিসেবে পরিগণিত। বিশেষ বিশেষ দিনে মাজারকে কেন্দ্র করে বিশেষ ওই (বাউল) বিশেষ সম্প্রদায়-সংশ্লিষ্ট\nআচার-অনুষ্ঠান পালিত হয়, দূর-দূরান্ত হতে ভক্ত-অনুসারীরা এসে সমবেত হয়; যেমনিভাবে একদা\nশিঁকড়ের সন্ধানে ছুঁটে এসেছিল বাউল সম্রাট লালন শাহ, সিরাজ শাহ, কুবির গোঁসাই, দুদ্দু\nশাহ, বেহাল শাহ, পাঞ্জু শাহ, খোদাবকশো শাহ, আবু বাক্কা শাহ, বনমালী শাহ, দুলাল শাহ-সহ\nঅসংখ্য বাউল সাধক। একজন রণগাজি বিশ্বাস অন্য সবার চাইতে এজন্য আলাদা যে নিজের আঁখড়া\nকেন্দ্রিক নিজস্ব ঘরানার জনগোষ্টি তৈরিতে সক্ষম হয়েছিলেন। এমনটা কিভাবে সম্ভব হয়েছিল\nতা গবেষণার দাবী রাখে। তবে একথা নিশ্চিত যে বহু গুণে গুনান্বিত রণগাজি বিশ্বাস ছিলেন\nদূরদৃষ্টি-সম্পন্ন; সরল পথে ধর্ম প্রচারে বাঁধার সম্মুখীণ হয়ে ভিন্ন কৌশল অবলম্বন করেছিলেন,\nএবং সফল হয়েছিলেন। ফরিদপুর গ্রামের প্রান্তদেশে তাঁর মাজারের অবস্থান পর্যালোচনা করে\nঅনুধাবন করতে পারি, লোকালয় হতে দূরে, নির্জনতায় পরিপুর্ণ অঞ্চলে ওই মহান সাধককে কেন্দ্র\nকরেই গ্রামের পত্তন ও বিকাশ। বিকাশধারায় যুক্ত মানুষগুলো আশেপাশের এলাকার বাসিন্দা\nছিল; রণগাজি বিশ্বাসের আধ্যত্ম সাধনায় প্রভাবিত ও বিশ্বাস স্থাপন করে নতুন নতুন বসতি\nস্থাপন করেছে- যে কারণে গ্রামটিতে সমমনা মানুষের আধিক্য লক্ষণীয়; সাতশো ফকিরের গ্রাম\nহিসেবে বিবেচিত। ফকির রণগাজি বিশ্বাসকে নিয়ে এলাকায় কিংবন্তির অভাব নেই, কাল পরস্পরায়\nকিংবদন্তিসমূহ উত্তরসূরীদের মাধ্যমে সমকাল পর্যন্ত বিস্তৃত। তাঁর নামের সাথে বিশ্বাস\nশব্দটি যুক্ত হওয়ার নিদৃষ্ট কোনো যুক্তি খুঁজে পাওয়া যায় না। গ্রামের বিশ্বাস গোষ্ঠির\nলোকজন নিজেদের রণগাজি বিশ্বাসের উত্তরপুরুষ হিসেবে দাবী করলেও আদতে তিনি ছিলেন অবিবাহিত!\nপালকপুত্রের বিষয়টি যেমন উড়িয়ে দেওয়া যায় না তেমনি বিশ্বাস; বিশ্বাসদের পুর্বপুরুষ\nহয়তো রণগাজি বিশ্বাসের পালকপুত্র ছিলেন। এমনও হতে পারে, কোন এক বিশ্বাস সাধকের খাদেম\nছিলেন; বিশ্বাসের দ্বীপশিখা প্রজ্জ্বলন করতে করতে সমকালীন এই বিশ্বাস গোষ্ঠী! স্ত্রী\nও সন্তান-সন্ততি না থাকার স্বপক্ষে বড় যুক্তি স্বয়ং ওই মাজার; যদি সন্তান-সন্ততি বা\nপরিবার-পরিজন পরিবেষ্ঠিত অবস্থায় তিনি ফরিদপুর গ্রামে বসবাস করতেন তবে একটি নয় উক্ত\nস্থানে একাধিক মাজার থাকার কথা! বাউল সম্রাট লালন শাহ’র ক্ষেত্রে আমরা লক্ষ্য\nকরি তাঁর (লালন শাহ) কবরের ঠিক পাশেই পালকমাতা মতিজান নেছার কবর; আশে-পাশে রয়েছে আরো\nকিছু কবর- যে কবরগুলোতে তাঁর একান্ত অনুচরদের সমাহিত করা হয়েছে! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাউল সম্প্রদায়ের নিকট\nসংগীতের আধ্যাতিকতা সর্বজনবিদিত। সহজ-সরল জীবনাচারে অভ্যস্থ বাউলরা গানে গানে সৃষ্টিকর্তার\nগুণকীর্তন করে। নানান প্রতিকুলতা পেরিয়ে বাউল মতবাদ সাধারণের অন্তরে ঠাঁই করে নেওয়ার\nঅন্যতম কারণ সংগীত; বাউলদের রচিত গীত শুধু বাংলা নয় বিশ্ববাসীর কাছে এখন গবেষণার বিষয়!\nগবেষণা প্রয়োজন রণগাজি বিশ্বাসের গান নিয়েও! যে মানুষটা গানে গানে এলাকাবাসীর কাছে\nধর্মের বাণী পৌছে দিয়েছেন, গানকে আশ্রয় করে ধর্মাচারের বিশেষ ধারা প্রচলন করেছেন, তার\nনিজের রচিত গান থাকবে না! না, এমনটি হতে পারে না; সংরক্ষণের অভাবে তাঁর গানসমূহ হয়তো\nহারিয়ে গেছে! সুখের কথা এই- গান না থাকলেও রণগাজি বিশ্বাস আছেন, আছে তাঁর স্মৃতিচিহ্ন;\nসাধারণ জনগণের মনে তিনি যেভাবে বিশ্বাসের শিঁকড় প্রোথিত করেছেন, তাতে এই মহান সাধক\nভাবিকালে আরও বিশিষ্ট উচ্চতায় আলোচিত হবেন; তাঁর প্রচারিত মতবাদ বিশ্ব-মানবতার মুক্তির\nউপলক্ষ্য হিসেবে গণ্য হবে বলে আমাদের বিশ্বাস!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© পিন্টু রহমান</p>\n<!-- /wp:paragraph -->', 'রণগাজি বিশ্বাস; প্রকৃত\nনাম ফরিদ খান গাজি। ১৩৭১ খ্রিষ্টাব্দে পশ্চিমবঙ্গের হুগলি জেলার ত্রিবেনীতে (গঙ্গা,\nযমুনা ও স্বরসতী নদীর সংযোগস্থল) জন্মগ্রহণ করেন। তিনি ছিলেন বহুমুখী প্রতিভার অধিকারী,\nযার স্খূরণ ...', '', 3, NULL, 'publish', 3214, 0, '2019-02-18 00:06:51', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (35, 2415, 32, 'মেলায় নাজমুল হুদার বই', 'মেলায়-নাজমুল-হুদার-বই', '<!-- wp:paragraph -->\n<p>অনুপ্রেরণামূলক বক্তা,\nলেখক ও জাতীয় বিতর্ক সংগঠক। বর্তমানে বাংলাদেশ ব্যাংকের উপ পরিচালক পদে কর্মরত। ছাত্রাবস্থা থেকেই তাঁর লেখালেখি। বিতর্ক,\nসংগঠন,\nসম্পাদনায় সখ্যতা। বিশ্ববিদ্যালয়ে পড়ার সময় বিভিন্ন টেলিভিশন চ্যানেলের বেশকিছু বিতর্ক ও মুক্ত আলোচনায় অংশ নেওয়া ছাড়াও সম্পৃক্ত ছিলেন বাংলাদেশ বেতার এর অনুষ্ঠান বিভাগে। লেখালেখির শুরুটা অবশ্য কবিতা দিয়ে,\nবাল্যবেলা থেকেই। জন্ম কুষ্টিয়া জেলায়। কৃষ্টি,\nসংস্কৃতি ও সাহিত্যানুকূল পরিবেশ ছিল তাঁর জন্য বাড়তি উৎসাহের উৎস। দেশের শীর্ষস্থানীয় জাতীয় দৈনিকসহ তথ্য মন্ত্রণালয়ের মাসিক সাময়িকীতে প্রকাশিত হয়েছে তাঁর অনুপ্রেরণামূলক নিবন্ধ। অমর একুশে গ্রন্থমেলা ২০১৭-এ প্রকাশিত তাঁর প্রথম বই\n‘ক্যারিয়ার ক্যারিশমা:\nসাফল্যের সাতপাঠ’\nতুমুল পাঠকপ্রিয়তা পায়। এছাড়া,\nশিশু-কিশোর ও তরুণদের জন্য\n‘বিতর্কে হাতেখড়ি’\nএবং\n‘বিশ্বনন্দিত বাংলাদেশি বিজ্ঞানী’\nতার উল্লেখযোগ্য প্রকাশনা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>২০১৯ সালের অমর একুশে গ্রন্থমেলায় নাজমুল হুদার সম্পাদনায় বাঙালি প্রকাশন থেকে প্রকাশিত হয়েছে\n‘আমার বিজয়ের গল্প’। বইটি পাওয়া যাচ্ছে অমুর একুশে গ্রন্থমেলার সোহরাওয়ার্দী উদ্যানের বাঙালি প্রকাশনের ১৮৯ নম্বর স্টলে। এছাড়াও\n‘বির্তকের হাতেখড়ি,&nbsp; বিশ্বনন্দিত বাংলাদেশি বিজ্ঞানী ও ক্যারিয়ার ক্যারিশমা’\nপাওয়া যাচ্ছে আলোঘর প্রকাশনের ৪৪০,\n৪৪১ নম্বর স্টলে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এছাড়াও বইমেলায় পাওয়া যাচ্ছে সদ্য প্রকাশিত নাজমুল হুদার কাব্যগ্রন্থ ‘আপন আয়নায় গোপন মুখ’। বইটি পাওয় যাচ্ছে বাঙালি প্রকাশনের ১৮৯ স্টলে। মূল্য ১৫০ টাকা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© ইমাম মেহেদী</p>\n<!-- /wp:paragraph -->', 'অনুপ্রেরণামূলক বক্তা,\nলেখক ও জাতীয় বিতর্ক সংগঠক। বর্তমানে বাংলাদেশ ব্যাংকের উপ পরিচালক পদে কর্মরত। ছাত্রাবস্থা থেকেই তাঁর লেখালেখি। বিতর্ক,\nসংগঠন,\nসম্পাদনায় সখ্যতা। বিশ্ববিদ্যালয়ে পড়ার সময় বিভিন্...', '', 1, NULL, 'publish', 3941, 0, '2019-02-18 10:19:09', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (36, 2479, 33, 'পরান বাউল', 'পরান-বাউল', '<!-- wp:paragraph -->\n<p>একাদশী তিথীতে চাঁদ চকোরীর মিলন সাঙ্গ করে দোল পূর্ণিমার ভরাট চন্দ্র বাঁশ\nবাগানের ফাঁক গলে যখন উদয় হলো তখন কেটে গেছে রাতের দ্বিপ্রহর । </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নিশিতন্দ্রা অধোঃজাগরণে পরান। দুচোখে তার ধর্মাবেশ ওযু করে তাহাজ্জুদ আদায়\nকরে নেয়। তার কাছে পৃথিবীর বলয়, মানুষের আচরণ, হাজার ভাষাভাষী আর নানান রঙের মানুষ\nনিয়ে কল্পনার এক বিশাল জগৎ চরাচর। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সদা চিন্তা খেলে যায় পরানের মস্তিষ্কে একই ঈশ্বরের দুনিয়ায় এত ধর্ম, এত উপাসনা,\nএত দলমতের ভিন্নতা; কেনো? </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কখনো সে তাবলীগ জামায়াতে যায় ৪০ দিন ব্যায় করে, কখনো বা আটরশি, ফুরফুরা, চরমোনায়।\nযখন যেখানে যে যেভাবে পরানকে দাওয়াত দিয়েছে সেটাই পরান হাসিমুখে কবুল করে তার সাথে\nশরিক হয়েছে, কাউকে না করেনি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরান লক্ষ্য করেছে সবাই তাকে নামাজের দিকেই আহ্বান করে, পিতা মাতার খেদমত করতে\nবলে, রোজা কালাম করতে বলে। কিন্তু পরানের মন মানে না তার কাছে ইসলাম ধর্ম মানে শুধু\nনামাজ রোজায় সীমাবদ্ধ নয়; আরও বেশি কিছু। কেউ তো বলেনা হাটার সময় খেয়াল রেখো পায়ের\nনিচে পিপড়া পড়ে যেনো মারা না যায়। সুদ-ঘুষ খেয়োনা, দৃষ্টি সংযত করো, নারীকে সন্মান\nদাও, খোদাপ্রাপ্তির ধ্যান করো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সবাই আছে তার দলের দলীয় কর্ম নিয়ে সাংগঠনিক রূপে তাই পরান গত ৫ বছর ঘরবন্দি\nথেকে ইবাদত করেছে দলের কাছে যায়নি। যার কাছেই গেছে সে নিজেদের সেরা বলে তবলা বাজিয়ে\nদেয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরানের চুল, দাড়ি বড় হয়ে রবীন্দ্রনাথ হওয়ার উপক্রম। পাড়ার ছেলেরা তার নাম দিয়েছে\nপরান বাউল। কেউ কেউ এসে খিস্তি খেওড় দিয়ে যায়- এতকাল নামাজ কালাম পড়ে শেষমেশ তুই নাড়ার\nফকিরের দলে যোগ দিলি? </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মনের ক্ষোভে দোল পূর্ণিমার রাতে পরান লালন শাহের মাজারে গিয়ে ফকির খুঁজতে থাকে।\nঅবশেষে একজনের সন্ধান পেয়ে বেশকিছু দিন বাদে পরান তার আখড়া বাড়িতে হাজির হলো এই ভেবে-\nসবই যখন দেখলাম তখন বাউলদের মতবাদ দেখতে আর দোষ কীসের । </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ফকিরের নিকট আসা যাওয়া পরানের বেড়ে গেলো। ফকির তাকে দীক্ষা প্রদান শুরু করলেন\nযতদুর জানা যায় শেষবার যখন পরানের নিকট জানতে চেয়েছিলাম তুমি কি কিছু পেলে? </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরান বলেছিল- যা অপরের মাঝে খুঁজে ছিলাম তা তাদের মাঝে ছিলো না আর তাদের মাঝে\nযাহা শুনে ছিলাম এখানে তার ব্যাখ্যা পেলাম। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরানের চুল এখন পিছনে ঝুটি করে বাঁধা। কিছু জিগ্যেস করলেই এক লাইন করে গান\nশুনিয়ে দেয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরান বাউল সাইকেল নিয়ে এ পথেই ফিরবে আমিও ফিরব, তুমিও ফিরবে সামনে পুকুর তারপর খাল তারপর ধানের মাঠ, ছোট্ট একটা নদী, সেখানে কলসী কাধে রমণীর বাচ্চাটি কাঁদছে, মসজিদে আযান হচ্ছে...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© মাহমূদুল হাসান</p>\n<!-- /wp:paragraph -->', 'একাদশী তিথীতে চাঁদ চকোরীর মিলন সাঙ্গ করে দোল পূর্ণিমার ভরাট চন্দ্র বাঁশ\nবাগানের ফাঁক গলে যখন উদয় হলো তখন কেটে গেছে রাতের দ্বিপ্রহর ।\nনিশিতন্দ্রা অধোঃজাগরণে পরান। দুচোখে তার ধর্মাবেশ ওযু করে তাহাজ্জুদ...', '', 9, NULL, 'publish', 2087, 0, '2019-02-19 12:23:57', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (37, 2492, 26, '‘রাত্রির রঙ বিবাহ’ কাব্যগ্রন্থ', 'রাত্রির-রঙ-বিবাহ-কাব্য', '<!-- wp:paragraph -->\n<p>লেখক: অরবিন্দ চক্রবর্তী<br>প্রকাশনী: বেহুলাবাংলা <br>প্রচ্ছদ : শতাব্দী জাহিদ <br>ধরন : কবিতা<br>পৃষ্ঠা : ৬৪  <br>মলাট মূল্য : ১৭৫ টাকা  <br>বয়ানের  ক্ষেত্রে জাক দেরিদার মতো ডিফারেন্স মানা এবং ডিফারেন্স ভাঙা অরবিন্দ  চক্রবর্তীর কবিতার অনিবার্য কৌশল। সময় ও মানুষের বৈচিত্র্যে যেকোনো বয়ানের  ‘কনটেক্সট’ পালটে যেতে বাধ্য। কারণ টেক্সট ব্যক্তির বয়ান বটে, অথচ তার পাঠক  অসংখ্য। পাঠের পদ্ধতি, পাঠের মনস্তত্ত্ব আর পাঠ-ব্যাখ্যার সংস্কার  বহুমাত্রিক। এ কারণেই দেরিদার মতো কবিতার বয়ানের ক্ষেত্রেও  বলা সম্ভব, কবিতার টেক্সট মূলত ‘সিস্টেম অফ ডিফারেন্স’, যেখানে বয়ানের  মর্মপাঠে থাকে অজস্র রূপ ও রূপান্তর, ক্রিয়া ও ক্রীড়া : যা জাদু বটে।  সে-অর্থে অরবিন্দ জাদুকর তো বটেই সেইসাথে তার কবিতার বয়ান প্রকৃত প্রস্তাবে  ‘সিগনিফাইয়ার’ অর্থাৎ দ্যোতকরাশির অনন্ত সম্ভাবনার এক এক্সক্লুসিভ মঞ্চ,  যেখানে উপস্থিত রয়েছে মাউথপিস ও রিসিভার। সেই মাউথপিসের আড়ালে রয়েছে  চেতনা-উন্মোচক ও মর্মোন্মোচক অনুশীলন— যা বহুস্বরপূর্ণ বিপজ্জনক প্রতিসংকেত  দ্বারা নিয়ন্ত্রিত। ফলে তার কবিতা প্রথাগত ভাষিক ব্যাকরণ ও বাগার্থকে  অস্বীকার করে নতুন ভাষিক সংকেত, প্রতিসংকেত, অধিসংকেতের বয়ানভূমি হাজির  করতে বাধ্য থাকে; যেখানে বিরাজ করে এক শব্দ থেকে আরেক শব্দের ভেতর  গ্রহান্তরের ফারাক— এই ফারাক থেকেই অরবিন্দ চক্রবর্তীর কবিতার বাগার্থ  আমাদের প্ররোচিত করে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© শিমুল মাহমুদ</p>\n<!-- /wp:paragraph -->', 'লেখক: অরবিন্দ চক্রবর্তী\nপ্রকাশনী: বেহুলাবাংলা\nপ্রচ্ছদ : শতাব্দী জাহিদ\nধরন : কবিতা\nপৃষ্ঠা : ৬৪\nমলাট মূল্য : ১৭৫ টাকা\nবয়ানের ক্ষেত্রে জাক দেরিদার মতো ডিফারেন্স মানা এবং ডিফারেন্স ভাঙা অরবিন্দ চক্রবর্তী...', '', 1, NULL, 'publish', 3943, 0, '2019-02-19 14:48:33', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (38, 2497, 34, 'এই শহরের সুখ', 'এই-শহরের-সুখ', '<!-- wp:paragraph -->\n<p>রুবি রেগে আছে। আমার মুখে হাসি। অভিমানে ফোন\nকেটে দেয়। ভিডিও কলেই কথা বলছিলাম স্ত্রী রুবির সাথে। বিদেশে থাকি কিন্তু মনটা পড়ে\nআছে দেশেই। মনের সাথে যুদ্ধ করে থাকতে হয় বিদেশের মাটিতে। আবার কল করি, রিসিভ করে অন্য\nদিকে তাকিয়ে আছে রুবি। কথা বলছে না। হাজারটা অভিযোগ শুধু ছেলের বিরুদ্ধে। আমাদের ছেলে\nবর্ণ। বয়স সাত বছর, কিন্তু কাজ কর্মে কুড়ি বছরের ভাব। সারাক্ষণ বিরক্ত করে ঘরের সবাইকে।\nএই বয়সেই নিয়ম ছাড়া চলাফেরা। রুবি যখন বর্ণের দুষ্টুমির কথা বলে কিছুই বলি না, হাসি।\nআমার চেহারায় মুচকি হাসি দেখে সে আরও রেগে যায়। হাসির কারণ আড়াল রাখি কিভাবে বলব বর্ণ\nআমার শৈশবকে মনে করিয়ে দেয়। ঠিক আমার সব স্বভাব পেয়েছে বর্ণ। সারাক্ষণ মাতিয়ে রাখতাম\nঘর। আমার কোনো কাজেও রুটিন ছিলো না। আব্বুর সাপোর্ট সব সময় আমার সাথে ছিলো। দুষ্টু\nহলেও সবার প্রিয় ছিলাম। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পাঁচ জনের একটা টিম ছিলো আমাদের, যখন যা ইচ্ছে\nতাই করতাম। পাঁচ জনের মধ্যে সিনিয়র এক ভাই ছিলেন তিনিই আমাদের সিনিয়র বন্ধু। উনাকে\nদলে রাখার কারণ ছিলো টাকা। আড্ডায় খরচ, যাত্রা পথে খরচ সবই সিনিয়র বন্ধু দিতেন। এমন\nকি ঋণ নিলেও ফিরত দিতাম না। উনাকে নিয়েই আমরা মজা করতাম। ভাবতাম উনি সহজ সরল কিন্তু\nএকদিন একান্তে আলাপের সময় বুঝলাম উনি সব বুঝেন কিন্তু আমাদের ছেড়ে যান না। মায়া লেগে\nগেছে, দুষ্টুমিও ভালো লাগে উনার। অনেক বিপদেই আপনের মতো পাশে পেয়েছি। আজ প্রবাসে বসে\nসব মিস করি তবুও জীবন যুদ্ধে প্রবাসে থাকতে হবে। শহরের প্রতি অলিগলি, আড্ডার প্রিয়\nজায়গাগুলো খুব মিস করি। আমার সুখ আমার পরিবার, বন্ধুরা আর প্রিয় শহরের মাটিকে খুব মিস\nকরি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ছোটবেলার একটা মজার কথা মনে হলে এখনও মনে মনে\nহাসি। পাশের বাসার দুই বছরের সিনিয়র মিলি আপুর সাথে প্রেম করেছিলাম। আপু জানতেন আমি\nক্লাস সেভেনে পড়ি, দেখতে একটু লম্বা আর মোটাসোটা ছিলাম বলেই এই ভাবনা। কিন্তু আমি পঞ্চম\nশ্রেণিতে পড়তাম আর আপু সেভেনে। নানান কালারের কাগজে ছোট ছোট চিরকুটে মনের কথা লিখতেন\nসিনিয়র প্রেমিকা মিলি আপু। আমিও ইঁচড়ে পাকার মতোই উত্তর দিতাম। প্রেম দীর্ঘ হয়নি বেশিদিন।\nপঞ্চম শ্রেণিতে যখন বৃত্তি পেলাম আম্মু সবার বাসায় মিষ্টি বিতরণ করেছিলেন। মিলি আপুদের\nবাসাও মিষ্টি নিয়ে গেছিলেন। ফাঁস হয়ে গিয়েছিলো জুনিয়র প্রেমিকের ভণ্ডামির কথা। এরপরে\nঅনেক চেষ্টা করে আর যোগাযোগ করতে পারিনি। প্রেম চলাকালীন অল্প সময়ে মিলি আপুর কাছ থেকে\nঅনেক গিফট পেয়েছিলাম। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বর্তমানে সিনিয়র প্রেমিকা মিলি আপু স্কুলের বাচ্চাদের\nপড়ান। বিয়ে এখনও করেননি। নিজেকে খুবই অপরাধী মনে হয়। আমার ছেলে বর্ণ উনার স্কুলের ছাত্র।\nস্ত্রী রুবি যেদিন জেনেছিলো সিনিয়র আপুর আর আমার প্রেম কাহিনী সে কি হাসি। মিলি আপুর\nসামনে রুবি যায় না। উনাকে দেখলে নাকি হাসি পায়। স্বামীর সাবেক প্রেমিকা আজ ছেলের শিক্ষিকা।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কখন যদি কেউ খারাপ ব্যাবহার করত তার পদবী দেয়া\nহতো আমাদের। তাকে নিয়ে পাড়ায় ট্রল হতো। এই ভয়ে কেউ আমাদের সাথে সহজে খারাপ ব্যাবহার\nকরত না। পাড়ার সকল কাজেই আমাদের প্রয়োজন হতো। সবাই জানত আমাদের ছাড়া সুন্দর আয়োজন বাস্তবায়ন\nসম্ভব না। একটা একটা সমস্যা হবেই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আব্বুর একমাত্র সন্তান ছিলাম। আবদারের সাথে সাথে\nপেয়ে যেতাম সব। মটর\'স এর ব্যবসা ছিলো আব্বুর। ব্যবসা প্রতিষ্ঠানের নাম ছিলো - মাজেদ\nমটর\'স। আমার নামেই আব্বু নামকরণ করেছিলেন। আব্বুর ছোট ভাই আমার একমাত্র চাচ্চু কানাডায়\nপরিবারসহ থাকেন। চাচ্চু আমাকে খুব বেশি ভালোবাসতেন। বলার আগেই পছন্দের সব কিছুই সামনে\nপেতাম। চাচ্চু বলতেন- বাবা মাজেদ আমার কলিজার টুকরা। একবার রাগ করে পাড়ার এক বড় ভাই\nধমক দিয়েছিলেন। সে কি কানড়বা পরে চাচ্চুর কাছে নালিশ। সে কি কাণ্ড পাড়ার ভাইয়াটিকে\nখুব মেরেছিলেন চাচ্চু। পরে বিচার পর্যন্ত গড়িয়েছিলো। আমাকে ছাড়া খেতেও পারতেন না। চাচ্চু\nএকটা মেয়েকে ভালোবাসতেন, বংশ ভালো না বলে আব্বু মেয়েটিকে চাচ্চুর জন্য মেনে নেননি।\nআব্বুর সাথে অভিমান করে চাচ্চু দেশ ছেড়েছিলেন। কানাডায় বিয়ে করে ওখানেই থেকে গেলেন।\nআর দেশে আসেননি কিন্তু আমার সাথে যোগাযোগের চেষ্টা করেছেন আব্বু ভাইয়ের সাথে অভিমানেই\nযোগাযোগ করতে দেননি। ব্যাংক ঋণ নিয়ে আব্বুর ব্যবসা প্রতিষ্ঠান চালু করেন, ভালোই চলছিলো।\nদিনরাত পরিশ্রম করে দাড় করিয়েছেন মাজেদ মটর\'স। আব্বুর একটাই স্বপ্ন- আমার ভবিষ্যৎ সুন্দর\nরেখে যাওয়া। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ব্যবসার কাজে আব্বু সকালে বাসা থেকে বের হলে\nরাতে ফিরতেন। দেখাই পেতাম না। আম্মুকেই বেশি জ্বালানোর সুযোগ পেতাম। আমার জ্বালাতনে\nঅতিষ্ঠ হয়ে আব্বুর কাছে নালিশ করেও কোন লাভ হতো না। বড় হয়ে আরও অগোছাল হয়ে গেলাম। রাত\nকরে বাড়ি ফিরতাম, দুপুর বারোটায় ঘুম থেকে উঠতাম। আম্মুর কাছে এসব অভিযোগ শুনতে শুনতে\nআব্বু চিন্তা করলেন ছেলেকে বিয়ে করালে হয় তো পরিবারের প্রতি সিরিয়াস হবে, আর নিজেকে\nনিয়ে ভাববে। সেটাই হলো, আব্বুর পছন্দ করা মেয়েকেই বিয়ে করলাম। কিন্তু আমার কোন পরিবর্তন\nনেই। ভেবেছিলাম দুদিন পরে হয় তো আমার অবস্থা দেখে বউ পালাবে। কিন্তু না খুবই ধৈর্যশীল\nমেয়ে রুবি। সে এমনভাবে চলে যেন আমার সব কিছুই সে বুঝে। কখন কি করব, কখন মন ভালো থাকে।\nকখন কি দরকার সবই রুবি আগেই টের পায়। জন্ম হয় বর্ণের। আব্বু আম্মু আমার চেয়েও বেশি\nখুশি। আম্মু সবচেয়ে বেশি খুশি সারা দিনই বর্ণকে নিয়ে খেলা। বর্ণের জন্মে পরিবারের আনন্দ\nযেন দ্বিগুণ বেড়ে গেলো। কিন্তু আমার কোনই পরিবর্তন নেই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হঠাৎ করে একদিন চাচ্চু দেশে ফিরে আসলেন। আমাদের\nবাসায় আসেননি আলাদা বাসায় উঠেছেন। আমরাও যোগাযোগের চেষ্টা করিনি। আব্বু বললেন, মাজেদ\nতোমার চাচ্চু যোগাযোগ করলে খারাপ ব্যাবহার করো না। আশ্বস্ত করলাম আব্বুকে। চাচ্চুর\nসাথে ভালোভাবেই কথা বলব। এত কিছুর পরেও ভাইয়ের প্রতি আব্বুর দরদ দেখে সত্যি ভালো লাগল।\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বন্ধুদের সাথে আড্ডা দিচ্ছিলাম। আম্মু ফোন করে\nজানাল আব্বু স্টোক করে হাসপাতালে। দ্রুত হাসপাতালে যাই। ডাক্তারের সাথে দেখা করে জানতে\nপারি স্টোক মারাত্মক ছিলো আলাহ রক্ষা করেছেন। তবে টেশনমুক্ত রেস্ট প্রয়োজন। কয়েকদিন\nপর বাবাকে বাসায় নিয়ে আসা হলো। মায়ের কাছে জানলতে পারলাম চাচ্চু বাবার সাথে দেখা করেছিলেন\nআইনি নোটিশ নিয়ে। উনার সম্পত্তির ভাগ চাই। ব্যবসা প্রতিষ্ঠান মাজেদ মটর\'স যে জায়গায়\nঅবস্থিত সেই জায়গাটুকুও চাই তার। এসব বিষয়ে তর্ক করেই আব্বুর এই অবস্থা। খুব ঘৃণা হলো\nচাচ্চুর প্রতি। ব্যবসা প্রতিষ্ঠান মাজেদ মটর\'স এর জায়গা দিয়েই ব্যাংক ঋণ তুলা হয়েছে।\nখুব চিন্তায় পড়ে গেলায়। জীবনের প্রথম এই পরিস্থিতিতে পড়েছি। বাবা অসুস্থ, চাচ্চুর আইনি\nলড়াই আর ব্যাংক ঋণ সব মিলে দিশেহারা হওয়ার মতো অবস্থা। স্বপ্নের মতোই উলটপালট হয়ে গেলো\nসাজানো ফুলবাগান। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চাচ্চু মামলায় জয়ী হলেন। উনার সম্পত্তি লিখে\nদেয়া হলো। ব্যাংক ঋণের টাকা পরিশোধের নোটিশ আসল। বসত ভিটা বিক্রি করে ভাড়া বাসায় উঠলাম।\nব্যাংক ঋণ পঞ্চাশ ভাগ পরিশোধ করে ব্যাংক অফিসারের কাছ থেকে মাসিক কিস্তিতে পরিশোধের\nঅনুমতি পেলাম। বাকি টাকার একটা অংশ ব্যাংকে আম্মুর নামে রাখলাম। বাসার কাজে লাগবে।\nচাকুরির অনেক চেষ্টা করলাম। অনেক জায়গায় ইন্টারভিউ দিলাম কোন জায়গাই চাকুরি হলো না।\nপরে জানলাম প্রাইভেট কোম্পানিতে লবিং এ চাকুরি হয় সরকারি চাকুরিতে ঘুষ লাগে। চাকুরির\nআশা ছেড়ে দিয়ে পরিবারের কথা ভেবে মধ্যপ্রাচ্যের ওমান যাওয়ার সিদ্ধান্ত নিলাম। আব্বু\nআম্মু প্রথমে রাজি না হলেও পরিস্থিতি ভেবে রাজি হলেন। স্ত্রীর মুখের দিকে তাকাতে পারিনি।\nবর্ণের জন্য কলিজাটা মুচড়ে উঠল। তবুও মনের সাথে যুদ্ধ করে দুঃসম্পর্কের আত্মীয় এক বড়\nভাইয়ের মাধ্যমে ওমান আসলাম। নামিদামি ভালো কোম্পানিতে চাকুরিও হলো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরিবার, অসুস্থ বাবা, ব্যাংক ঋণ অগুছালো এই আমাকে\nকত দায়িত্ববান বানিয়ে দিলো। সবাইকে খুব মিস করি কিন্তু কাউকে বুঝতে দেইনি। সবাই যাতে\nবুঝতে পারে ভালো আছি এভাবে কথা বলি। দিনরাত কাজ করতে শুরু করলাম। মাস শেষে বেতন নিতে\nগেলে ঝামেলা। সহকর্মীদের কাছে জানতে পারলাম দুই তিন মাস পর পর বেতন দেয়া হয়। মাথা আকাশ\nভেঙে পড়লো। কিছু করার নাই পাসপোর্ট কোম্পানির মালিকের হাতে তার কথাই চলতে হবে। দেশে\nফিরা সম্ভব না। এত দায়িত্ব। সহকর্মী এক বাংলাদেশির মাধ্যমে ডিউটির বাহিরে আলাদা কাজ\nশুরু করলাম। কোম্পানিতে ডিউটি টাইম বারো ঘন্টা, পরে আরও ছয় ঘন্টা অতিরিক্ত কষ্ট করে\nদেশে টাকা পাঠানো শুরু করি। চব্বিশ ঘন্টার মাঝে যোল ঘন্টাই কাজ। শ্রমের বিনিময়ে মজুরি\nমিলে না। এটা তো দয়ার টাকা না। কঠোর পরিশ্রমের বিনিময়ে উপার্জিত টাকা। এই টাকা দিতেও\nবাহানা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অনলাইনে বন্ধুদের সাথেও যোগাযোগ বন্ধ করে দিয়েছি।\nবন্ধুরা মজা করে নানান কথা বলে। এতোদিন দেশে না আসলে নাকি সুন্দরি স্ত্রী পরকিয়া করবে,\nপালিয়ে যাবে। সব কথা হজম করছি। যুদ্ধ করছি জীবনের সাথে। ছেলে বর্ণ দিন দিন বড়ো হচ্ছে\nতাকেও পিতার সেড়বহ থেকে বঞ্চিত হতে হচ্ছে। আত্মীয়-স্বজনের কত দাবি। মাঝে মাঝে মনে হয়\nএই পরিশ্রম দেশে করলেও ভালো টাকা রুজি করতে পারতাম কিন্তু পরিবারের সবাই এ কাজ করতেও\nতো দিতো না। এতো বড়ো হয়েছি আম্মু বা আব্বু কখনোই বাজারটা করতেও বলেন নি কিন্তু আজ এই\nআমি কত বদলে গেছি। নীড়ে ফিরে যাওয়া পাখির মতো ঘরে ফিরার ইচ্ছেকে দাফন দিতে হয়, স্বপ্নে\nবিভোর হতে পারি না। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রিয় শহরের প্রিয় মানুষগুলোর সাথে কাটানো সময়\nসত্যি আনন্দময়, স্মৃতিময়। আড্ডা, খেলাধুলা, মারামারি কত দুষ্টুমির ফ্রেমে বাধা আছে\nশৈশব। প্রত্যেক মানুষই মনে হয় তার বেড়ে উঠার শহর, শৈশবের শহরকে প্রিয় শহর বলবে। বড়ো\nহলে যান্ত্রিকা হয়ে যায় মানুষ, অনেক দায়িত্ব বেড়ে যায়। মানুষ আনন্দের স্মৃতি মনে রাখে,\nবেদনার অতীত ভুলে যায়। প্রাণের শহরের সুখের কথা কেউ ভুলতে পারে না। বিকেল নেমে এলেই\nমনে হয় পাড়ার মোড়ে চায়ের আড্ডার কথা। মাসের পরে যখন পরিশ্রমের টাকা হাতে আসে মনে হয়\nশৈশবে বাবার পকেটের টাকা সরিয়ে বন্ধুদের আড্ডায় টাকা খরচের কথা মনে পড়ে যায়। শৈশবে\nবেড়ে উঠা শহরেই প্রকৃত সুখ বাঁধা থাকে স্মৃতি আয়নায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সারাদিন কোম্পানির কাজ করে পার্ট টাইম কাজে গেলাম।\nখাবার হোম ডেলিবারি দেয়ার কাজ। খাবার নিয়ে দরজায় দাঁড়িয়ে আছি, অনেক্ষগণ পর দরজা খোলা\nহলো। দরজা খুলতে চমকে গেলাম চাচ্চু সামনে দাঁড়িয়ে আছেন। আমার হাতে খাবার ব্যাগ। বুঝতে\nবাকি রইলো না ওমান ঘুরতে বা ব্যবসার কাজে এসেছেন। চাচ্চু বললেন - মাজেদ তুই এখানে\n? </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কোন উত্তর না দিয়ে চাচ্চুর হাতে খাবার তুলে দিয়ে হাতে রাখা টাকাটা চু মেরে নিয়ে বিপরীতে হাঁটা শুরু করলাম। যে লোকটার জন্য বাবা আজ মৃত্যুর সাথে যুদ্ধ করছেন, আমার প্রবাসে আসা। এত কিছু তার সাথে আবার কি কথা।একটু সামনে এগিয়ে পিছনে তাকালাম। চাচ্চু অবাক দৃষ্টিতে তাকিয়ে আছেন। কেন পিছনে তাকালাম? কথা না বলে চলে আসলাম, তবুও পিছনে তাকানো হয় তো রক্তের টান...</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>©  মিনহাজ ফয়সল </p>\n<!-- /wp:paragraph -->', 'রুবি রেগে আছে। আমার মুখে হাসি। অভিমানে ফোন\nকেটে দেয়। ভিডিও কলেই কথা বলছিলাম স্ত্রী রুবির সাথে। বিদেশে থাকি কিন্তু মনটা পড়ে\nআছে দেশেই। মনের সাথে যুদ্ধ করে থাকতে হয় বিদেশের মাটিতে। আবার কল করি, রিসিভ...', '', 9, NULL, 'publish', 2819, 0, '2019-02-21 12:46:44', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (39, 2501, 26, 'নজরুলের শ্যামাসাধনা ও শ্যামাসংগীত', 'নজরুলের-শ্যামাসাধনা-ও-শ্', '<!-- wp:paragraph -->\n<p>লেখক: সাকার মুস্তাফা<br>প্রকাশনী: অন্বেষা প্রকাশন<br> প্রচ্ছদ: মোবারক হোসেন লিটন<br> বইয়ের ধরন: গবেষণাধর্মী গ্রন্থ<br> প্রাপ্তিস্থান: প্যাভিলিয়ন ১৮<br> বইয়ের মূল্য: ২৪০ টাকা</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অমর একুশে গ্রন্থমেলা ২০১৯-এ প্রকাশিত হয়েছে গল্পকার সাকার মুস্তাফার গবেষণাধর্মী গ্রন্থ “নজরুলের শ্যামাসাধনা ও শ্যামাসংগীত”। সাকার মুস্তাফা একজন গবেষক এবং সৃষ্টিশীল লেখক। বর্তমানে তিনি জাতীয় কবি কাজী নজরুল ইসলাম বিশ্ববিদ্যালয়ে ফোকলোর বিভাগে সহকারী অধ্যাপক হিসেবে কর্মরত। মাঠপর্যায়ের পর্যবেক্ষকদের কাজে লাগিয়ে তিনি লোকসংস্কৃতির নানাদিক উন্মোচনে অবিরাম পরিশ্রম করে যাচ্ছেন। বলতে গেলে, জীবনঘনিষ্ঠ গল্প রচনাতে তিনি যেমন সিদ্ধহস্ত তেমনি গবেষণায় তার আগ্রহ প্রবল। মূলত জাতীয় কবি কাজী নজরুল ইসলামের প্রতি প্রবল আগ্রহ থাকা এবং লোকসংস্কৃতি বিষয়ে দুর্বলতার কারণে তিনি নজরুল ইসলামের শ্যামাসংগীত নিয়ে এই গবেষণাটি করেছেন৷ অধ্যাপক ড. মো. জাহিদুল কবির এই বিষয়ে বলেছেন, “মাতৃশক্তি ও মাতৃপূজার বিষয়ে আমাদের চর্চার ধারাটি বহুদিনের হলেও শ্যামাসংগীত বিষয়ে বাংলা ও বাঙালির চর্চা খুব বেশি দিনের নয়।”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সে হিসেবে বলতে গেলে সাকার মুস্তাফার গবেষণাধর্মী এই গ্রন্থটি একটি অমূল্য সম্পদ হিসেবেই থাকবে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গ্রন্থটির প্রচ্ছদ করেছেন মোবারক হোসেন লিটন, গ্রন্থের বিষয়বস্তুর সাথে প্রচ্ছদটি মানানসই বলতে হবে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সাকার মুস্তাফার এ পর্যন্ত গবেষণা জার্নালের সংখ্যা দশটি। বর্তমানে তিনি “ঝপান নাট্যপালা: বিষয়বৈচিত্র্য ও পরিবেশনারীতি” এবং “মালাকার সম্প্রদায়: জীবন ও শিল্প” শিরোনামে দুটি প্রকল্পে গবেষণারত।</p>\n<!-- /wp:paragraph -->', 'লেখক: সাকার মুস্তাফা\nপ্রকাশনী: অন্বেষা প্রকাশন\nপ্রচ্ছদ: মোবারক হোসেন লিটন\nবইয়ের ধরন: গবেষণাধর্মী গ্রন্থ\nপ্রাপ্তিস্থান: প্যাভিলিয়ন ১৮\nবইয়ের মূল্য: ২৪০ টাকা\nঅমর একুশে গ্রন্থমেলা ২০১৯-এ প্রকাশিত হয়েছে গল...', '', 1, NULL, 'publish', 2916, 0, '2019-02-20 23:08:36', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (40, 2505, 26, 'মেলায় ইমাম মেহেদীর দুই বই', 'মেলায়-ইমাম-মেহেদীর-দুই-বই', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\">মুক্তিযুদ্ধে কুষ্টিয়ার নারী</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মুক্তিযুদ্ধে পদ পদবীর দায়িত্বে না থাকলেও নারীর অবদান বহুমাত্রিক। অস্ত্র হাতে রণাঙ্গণে, শরণার্থী শিবিরে, হাসপাতালে চিকিৎসক ও সেবিকা হিসেবে, কখনও সংবাদ, কথিকা, গানে, প্রচারণায় এবং সংগঠক হিসেবেও যথেষ্ঠ অবদান রয়েছে। দেশের জন্য সম্ভ্রম হারিয়েছেন অনেক বীর মাতা। মুক্তিযুদ্ধে কুষ্টিয়া জেলার অবদান বিশেষভাবে উল্লেখযোগ্য। সেই জনপদেরই কয়েকজন বীরত্বগাথা নারীর যুদ্ধদিনের কাহিনি ও যুদ্ধ পরবর্তী জীবনের বিভিন্ন বিষয় সাক্ষাৎকার ভিত্তিতে উঠে এসেছে গ্রন্থটিতে। সেইসঙ্গে বতর্মান মাননীয় প্রধানমন্ত্রীর সাথে কুষ্টিয়ার পাঁচ বীরকন্যার ছবি ও গল্প থাকছে আলোচনা আকারে। বইটি পাওয়া যাচ্ছে বইমেলার সোহরাওয়ার্দী উদ্যানে বেহুলা বাংলা প্রকাশনের ১২৩-১২৪ নং স্টলে। প্রচ্ছদ করেছেন শিল্পী চারুপিন্টু। মূল্য ২০০ টাকা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\">১৯৭১ ডাঁশার চাষী ক্লাব যুদ্ধ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মুক্তিযুদ্ধের আঞ্চলিক ইতিহাস অত্যন্ত গুরুত্বপূর্ণ। একাত্তর সালে ডাঁশা গ্রামের চাষী ক্লাব সংলগ্ন রাজাকারদের সাথে মুক্তিযোদ্ধাদের যুদ্ধ হয়। স্পটেই শহীদ হয় পাঁচজন, আহত হয় চারজন জাতির শ্রেষ্ঠ সন্তান। জীবদ্দশায় এখনও ওই যুদ্ধের কমান্ডারসহ বেঁচে আছেন যুদ্ধাহত চারজন। ৪৮ বছর পর খুঁজে বের করা হয়েছে শহীদ ইকবালের ছবিসহ জীবনী। আরেক মুক্তিযোদ্ধার বিধবা স্ত্রীকেও খুঁজে বের করা হয়েছে। সন্ধান পাওয়া শহীদ যোদ্ধার স্ত্রী-কন্যার। যেসব ঘটনা এতদিন লোকচক্ষুর আড়ালে ছিল। সেইসব অজানা অধ্যায় নিয়ে থাকছে ডাঁশার চাষী ক্লাব যুদ্ধের পুরো ঘটনার বর্ণনা, প্রতক্ষ-পরোক্ষভাবে জড়িতদের সাক্ষাৎকার। বইটি পাওয়া যাচ্ছে বইমেলার সোহরাওয়ার্দী উদ্যানে ‘বেহুলা বাংলা’ প্রকাশনের ১২৩-১২৪ নং স্টলে। প্রচ্ছদ করেছেন আল নোমান। মূল্য ২২০ টাকা।</p>\n<!-- /wp:paragraph -->', 'মুক্তিযুদ্ধে কুষ্টিয়ার নারী\nমুক্তিযুদ্ধে পদ পদবীর দায়িত্বে না থাকলেও নারীর অবদান বহুমাত্রিক। অস্ত্র হাতে রণাঙ্গণে, শরণার্থী শিবিরে, হাসপাতালে চিকিৎসক ও সেবিকা হিসেবে, কখনও সংবাদ, কথিকা, গানে, প্রচারণা...', '', 1, NULL, 'publish', 4327, 0, '2019-02-23 11:37:44', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (41, 2509, 68, 'বিষণ্ন বালিকা', 'বিষণ্ন-বালিকা', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>এক</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তখনও ভোর হয়নি। তখনও বাসন্তিকা বর্ণ-শোভায় শোভিত শাড়ীতে দুলে ওঠা ফাল্গুনের মেঘহীন\nআকাশের পূর্ব নীলিমা জুড়ে রক্তরাগে মোড়ানো রক্তিম সূর্যের পূর্বরাগের পাখনা মেলা সোনামাখা\nবিজড়ন দিগন্তের সীমানা ছুঁয়ে যায়নি। তখনও পাখিদের ডানা ঝাপটানোর শব্দ আর ঝগড়ার কোলাহলে\nমিশে যাওয়া প্রলাপে আকাশ চিরে চৌচির হয়ে যায়নি। তখনও ঘন ঘোর কুহেলিকার আস্তরন ভেঙ্গে\nপ্রভাতী অধর যামিনি শেষের শুভ্র-ধবল দিবসকে আহ্বান জানায়নি। না জানালেও ভরা রাত্রি\nজেগে থাকা অনেক দূরের কোনো ঘন অরণ্যের কোনো একটি বৃক্ষ-শাখায় বসে চোখ জুড়োনো, মনোলোভা\nএকটি চিরদিনের চিরচেনা মিষ্টি পাখি- ঘুঘু কী মিষ্টি কন্ঠে ওর সঙ্গিনীকে কাছে পাবার\nজন্যে আকুল হয়ে অবিরত ডেকেই চলেছে। আরও অতি দূর থেকে ওর সঙ্গিনীটিও বুঝি আরও কোনো একটি\nবনবৃক্ষের ডগায় বসে ওর সঙ্গীর আকুলিত আহ্বানে অবিরাম সাড়া দিয়েই চলেছে। ওর সাড়াতেও\nএকই আকুলতা জড়ানো। কিন্তু তারপরেও সঙ্গিনীটি ওর কাছে আসছে না। সঙ্গীটিও সঙ্গিনীটির\nকাছে যাচ্ছে না। অথচ ওদের দুজনের সাড়াতে বোঝাই যায় ওদের বিচ্ছেদ হয়নি। তবুও মনে হয়\nবিচ্ছেদের বেদনায় ওরা দুজনই দুজনের কাছে কেমন যেন সকরুণ বেদনা-বিধুর। যদিও ওদের ডাকে\nবেদনা বিধুরতার মাত্রাটি কী পরিমাণের- বোঝার কোনো উপায় নেই। তবুও ওদের সাড়া দেবার শব্দ-ভঙ্গিটি\nথেকে কিছুটা হলেও আঁচ করে নেয়া যায়- ওরা দু’জনই একে অপরের কাছে আসতে চায়। ভাবতে কষ্ট হয়\nনা যে, এই একটি মাত্র আগ্রহই ওদের দু’জনের কাছে অতি-প্রবল। কিন্তু কে কার কাছে আগে\nআসবে- এ সিদ্ধান্তটিই বোধকরি ওরা নিতে পারছে না। হয়ত সঙ্গিনীটি চাইছে সঙ্গীটিই ওর কাছে\nআগে আসুক, আবার সঙ্গীটি হয়ত চাইছে এর ঠিক উল্টোটি। হয়ত দুজনের কাছাকাছি আসবার মাঝখানে\nএ ধরনের একটি নিগুঢ় অভিমানবোধ ওদের দুজনের দুটি অন্তরকে এভাবেই ভিজিয়ে দিচ্ছে। এ কারণেই\nবুঝি কেউ কারুর কাছে আসতে পারছে না। তবে কোনো না কোনো এক সময় আসতে ওদের হবেই। একজনের\nঠোঁটের সাথে আর একজনের ঠোঁটকে যে কথা কইতেই হবে- না হলে যে ওদের অভিমানে চুর চুর\nবিরহ-ভাণ্ড পূর্ণ অমৃত-সুধা পান করবার কেউই থাকবে না। আর সে কারণেই যে ওদের পরস্পরকে\nএকে অপরের কাছে আসতে হবে ওই সুধা-ভাণ্ডে রক্ষিত অমৃতের স্বাদ গ্রহণ করবার জন্যে- এটি\nনিশ্চিত করেই বলা যায়।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শুন শান নিঝুম এই শেষ রাতের দিগন্ত বিস্তৃত শুন্যতার শেষ বিন্দু থেকে দু’একটি রাত-জাগা নিশাচর পাখি\nওদের বড় বড় ডানা ঝাপটিয়ে নিস্তরঙ্গ শুন্যতার হৃৎপিণ্ড চিরে চিরে মধুরিমার মমতা জড়ানো\nশব্দ-তরঙ্গ তুলে আকাশের অপর প্রান্তের বিন্দুটিকে ছঁয়ে দেখবার জন্যে বুঝি প্রাণপণ ধেয়ে\nচলেছে। নিঃসঙ্গ একটি বাদুর খুব কাছের একটি খেজুর গাছের রস নেমে আসবার জন্যে লাগানো\nকাঠিটিকে আঁকড়ে ধরবার চেষ্টা করছে। কিন্তু কাঠিটিকে দুপায়ে আঁকড়ে ধরে আর একটি বাদুর\nইতোমধ্যেই কাঠিটির ডগায় নেমে আসা খেজুরের রস পান করছে। আগন্তুক বাদুরটিকে ও কিছুতেই\nকাঠিটি স্পর্শ করবার সুযোগ দিচ্ছে না। ঝগড়া লেগে যাচ্ছে দুজনের মধ্যে। ঝগড়াটি শেষ পর্যন্ত\nএক পর্যায়ে সংঘর্ষে রূপ নিলে সবগুলি বিপজ্জনক মাপজোকহীন কুৎসিত দাঁত বের করে দুর্বোধ্য\nসব চ্যাচামেচি আর নিজেদের মধ্যে রক্তারক্তি করতে করতে দুটি বাদুরই খেজুর গাছটি থেকে\nবিদায় নিয়ে আঁধারের দুপ্রান্তে মিশে গেলো। কেউই কারও দিকে আর ফিরে তাকাবার এতটুকুও\nপ্রয়োজন বোধ করলো না মোটেই। আর প্রয়োজন বোধ করবেই বা কেন? কারণ দুজনের সংঘর্ষের পর\nএকজনের পক্ষে তো আর অপর জনের মুখের দিকে তাকানো সম্ভব নয়, তাকানো যায়ও না, নিজে থেকে\nসেধে গিয়ে কথাও বলা যায় না- ওদের একটি বিষম রকমের অহং বোধের বিষয় আছে না?। বোধকরি ওদের\nসে বোধটি একটু বেশীই- যেটি ‘বিষম’-শব্দটিকেও হার মানিয়ে দেয়।&nbsp;&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এ রকম একটি শিহরণ জাগানিয়া পরিবেশের মধ্যে আবার শত শত ঝি ঝি পোকার সমস্বরে বিরামহীন\nতুমুল একমাত্রিক চিৎকারের শ্রবণ দীর্ণ করা প্রতিযোগিতা যেন পরিবেশটিকে আরও ভয়াবহ রকমের\nত্রাসিত করে তুলছে। হাজার হাজার জোনাকির নিভে জ্বলা আলোর সাথে আঁধারের মাখামাখি যেন\nফাল্গুন শুরুর কুয়াশাচ্ছন্ন শেষ রাত্রিটিকে একটি অদৃশ্য ভীতির আকরে নিমজ্জিত করে চলেছে\nমুহূর্তে মুহূর্তে সেই নিভে জ্বলা আলো আর আঁধারের সাথে ছন্দ মিলিয়ে। এ এক অদ্ভুত বিধান\nখেয়ালী বিধির। অতিক্ষুদ্র একটি পতঙ্গের শরীরের একটি অংশ থেকে ততধিক ক্ষুদ্র একটি হলদে\nপ্রভার আলোক বিন্দু নিমেষে জ্বলে উঠে প্রকৃতিকে তিল পরিমাণের মিষ্টি আলোকের ঝিলিক দেখিয়ে\nতখনই আবার নিভে গিয়ে ঘোর আঁধারে ঢেকে দিচ্ছে প্রকৃতিকে। ঘন ত্রাস আর ভীতির মধ্যেও মননের\nকোথায় যেন একটি অপূর্ব ভালোরলাগার অনুভুতি অবচেতনাতেই ক্রিয়াশীল হয়ে যায় ক্ষণিকের জন্যে\nহলেও বুঝি বা।&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু ভালোলাগার এ মৌহূর্তিক অনুভূতিটি মোটেই আর অতিরিক্ত এতটুকু সময়ের জন্যেও\nস্থায়ী হয় না। কোথায় যেন মিলিয়ে যায় দূরের কোনো ঘন অরণ্যের মতো থোকা থোকা ঘনিষ্ঠ-ঘনত্বে\nপূর্ণ মাথা নোয়নো দীর্ঘাঙ্গী বাঁশ ঝাড়ের ভেতর থেকে ভেসে আসা রাত্রির শেষ প্রহর ঘোষণায়\nরত শৃগাল কুলের অবিশ্রান্ত শ্রুতি-বিরুদ্ধ আর বিকট কর্কশ চিৎকারের শব্দে। এ চিৎকারের\nবুঝি কোনও শেষও নেই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এবার যেন এক প্রকার আকস্মিকভাবেই সম্বিত ফিরে পায় একটি তীব্র খরস্রোতা নদী-কুমারিকা’র তিন কিলোমিটার দক্ষিণ\nদিক থেকে শুরু হয়ে উত্তর দিকে প্রলম্বিত বাঁধের রাস্তার ওপর দিয়ে একটি প্রাইভেট কারের\nষ্টিয়ারিংয়ে বসে দূরন্ত গতিতে ড্রাইভ করতে থাকা ত্রিশোর্ধ নারীটি। নদী ভাঙ্গনের কবল\nথেকে একটি জেলা শহরকে রক্ষা করবার জন্যে অনেক আগেই এ বাঁধটি নির্মাণ করা হয়েছিলো। এবং\nবাঁধটি নির্মাণের অনেক দিন পর সাধারণ মানুষ এবং যানবাহন চলাচলের উপযোগী করে বাঁধটির\nপুরোটাই পাকা সড়কে রূপান্তরিত করা হয়েছিলো। এতে নদী ভাঙ্গনের কবল থেকে শহরটিকে রক্ষা\nকরবার মাধ্যমে শহরের মানুষ জনের যথেষ্ট উপকার সাধিত হলেও নদীটির অপর পাড়ের বিশেষ করে\nচরাঞ্চলের মানুষদের দুর্ভোগের মাত্রাটি অনেকটাই বেড়ে গিয়েছিলো। বিশেষতঃ প্রতি বছর\nবর্ষা ঋতুতে। ওই ঋতুতে প্রবল বন্যার পানির প্লাবনে চর এলাকার অধিকাংশ বাড়ি ঘরই বিদ্ধস্ত\nহয়ে যেত। এবং প্রতি বছরই এ নির্দিষ্ট ঋতুটিতে চরম দূর্যোগের মুখোমুখি হয়েই কোনোমতে\nওদেরকে বেঁচে থাকতে হতো। এ বাঁধটি সেখানকার মানুষদের জন্যে বোধকরি বাস্তব অর্থেই সৌভাগ্যের\nচাইতে দূর্ভাগ্যের দূর্ভারই বয়ে এনেছিলো অধিক মাত্রায়। তারপরেও সেখানকার মানুষজন বিষয়টিকে\nমেনে নিয়েছিলো শুধু এ কারণে যে, বাঁধটি নির্মিত হবার ফলে শহরে যাতায়াতের সময়টি ওদের\nজন্যে অনেকটাই কমে গিয়েছিলো এবং যেহেতু ওরা কখনই নিজেদের যুগ যুগান্তরের ভিটে মাটি\nআর হৃদয় নিংড়ানো নির্যাস দিয়ে তৈরি করা পরিবেশ ত্যাগ করে শহরে গিয়ে শহরের সঞ্জীবন বিহীন\nপাথরের মতো কঠিন শুষ্ক মাটিতে নিজেদের বসতি নির্মাণ করতে পারেনি। কারণ ওরা সেটি করতে\nচায়নি। কোনো বড় ধরনের প্রলোভনের বিনিময়েও করতে চায়নি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>নারীটি প্রাণপণ চেষ্টা করছে ভোর হবার আগেই যাতে মূল নদীটির তীরে পৌঁছোনো যায়।\nআর সে কারণে গাড়ির গতি অব্যাহতভাবে বৃদ্ধি করেই চলেছে নারীটি। স্পীড মিটারের ইন্ডিকেটরটি\nসত্তর থেকে আশি কিলোমিটারের মধ্যে ওঠা নামা করছে। বহুদিন আগে পাকা হলেও বর্তমানের এ\nধরনের ভাঙ্গাচোরা একটি রাস্তায় কুয়াশাচ্ছন্ন শেষ রাত্রিতে এত স্পীডে গাড়ি চালানো যে\nকত ভয়ঙ্কর ভাবতেই চাইছে না নারীটি। ডান বাম কোনো দিকেই তাকাচ্ছে না ও। নিষ্পলক স্থির\nদৃষ্টি সম্মুখের দিকে নিবদ্ধ। গাড়িটিতে ফগ লাইট থাকবার কারণে শেষ রাত্রির কুয়াশা ভেদ\nকরে গাড়ি চালাতে খুব একটা সমস্যা হচ্ছে না ওর। বোঝা যায় গাড়ি চালাতে যথেষ্টই দক্ষ নারীটি।\nঅবশ্য গাড়ি ড্রাইভিংয়ে দক্ষতা অর্জনের নেপথ্যে ওর শৈশবের একটি ঘটনা মূখ্য ভুমিকা পালন\nকরেছিলো বলে ও মনে করে। বিষয়টিকে এই মুহূর্তে কিছুটা অস্বচ্ছ এবং রহস্যজনক বলে মনে\nহওয়াই স্বাভাবিক। তবে কিছু সময় পরই এই স্বাভাবিকতার নেপথ্যের কারণটি আপনা আপনিই পাঠকের\nকাছে স্পষ্ট হয়ে যাবে।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>দুই</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গাড়িটি চলছে তো চলছেই। থামবার কোনও লক্ষণ তো নেই-ই উল্টো গতির সীমা যেন সময়ের\nসাথে পাল্লা দিয়ে সময়ের সীমাকেই হার মানিয়ে দিচ্ছে- বিষয়টির পূনরুল্লেখ করা হলো শুধুমাত্র\nনারীটির সাহসের মাত্রাটিকে উপলব্ধি করবার জন্যে। একজন অবিবাহিতা নারী- যার বয়স এখনও\nতারুণ্যকে উত্তীর্ণ করেনি- যে অর্থে সে অবশ্যই একজন তরুণী। কিন্তু একজন নারী এবং একজন\nতরুণীর মধ্যে ভাবগত অর্থের দিক থেকে যে পার্থক্য সে পার্থক্যটি সম্ভবতঃ মহিলাটির ক্ষেত্রে\nপ্রযোজ্য নয়। যদিও একই ভাবগত কারণে প্রচলিত অর্থে মহিলা শব্দটিও তরুণীর ক্ষেত্রে অপ্রযোজ্য\nতারপরেও- এ অর্থে যে, তারুণ্যের কোনও লক্ষণই ওর চরিত্রে নেই। একজন তরুনীর স্বভাব সুলভ\nচপলতা অথবা প্রগলভতা, চঞ্চলতা, অকারণ উচ্ছ্বাস- এ সব কিছুর অনেক উর্ধ্বে উঠে গেছে ও\nঅনেক আগেই- হয়ত প্রখর বাস্তবতার মুখোমুখি দাঁড়িয়ে সমূহ প্রতিকুলতার বিরুদ্ধে বেঁচে\nথাকবার অসম যুদ্ধের অভিজ্ঞতা অর্জনের প্রেক্ষিতেই। বাস্তবতার মধ্যাহ্নিক প্রাখর্যই\nহয়ত ওকে বাধ্য করেছে সময়ের আগেই এ ধরণের একটি স্তরে উঠে আসতে। যে কারণে ও একজন ত্রিশোর্ধ\nতরুনী হলেও ওকে একজন নারী হিসেবেই গ্রহণ করা হয়েছে এ গল্পে। আর এ নারীটির মানসিক অবস্থান\nকোন স্তরে পৌঁছুলে ফাল্গুনের শেষ রাত্রির কুয়াশা ভেদ করে একজন বিশ্বস্ত সঙ্গীকেও সাথে\nনা নিয়ে একাই এ রকমের দূরন্ত গতিতে নির্জন বাঁধের নিকষ আঁধারে ঢাকা মাঝে মাঝে বাঁক\nএবং বিপদ-সংকুল রাস্তার ওপর দিয়ে গাড়ি চালাতে পারে ও- কিছুটা হলেও আঁচ করতে কষ্ট হয়\nনা। আশ্চর্য, সড়কের বাঁকগুলিতেও গাড়ির গতি ও কিছুতেই কমাতে চায় না। নারীটি কেমন যেন\nডেসপারেট হয়ে গেছে- এত স্পীডে গাড়ি চালালে গাড়িটি যে যেকোনো মুহূর্তে উল্টে গিয়ে কুড়ি\nপঁচিশ ফুট নীচের খাদে পড়ে যেতে পারে এবং তাতে ওর জীবনহানির শঙ্কাও যে প্রবল হয়ে উঠতে\nপারে- সে দিকটির কথাও বোধকরি একদমই ভাবছে না নারীটি। নিশ্চয়ই এমন কোনো জটিল সমস্যায়\nও আক্রান্ত- যা ওর গাড়ি চালানোর গতিসীমাটিই প্রমাণ করে দেয়- যে গতির কাছে ওর জীবনটিকেও\nও মনে করে একেবারেই তুচ্ছ। কী এমন সমস্যা ওর, যে সমস্যাটি ওর প্রচুর সম্ভাবনা-সমৃদ্ধ\nপ্রলম্বমান জীবনটিকেও একেবারে মৃত্যুর উপকেণ্ঠে এনে দাঁড় করিয়ে দিয়েছে। এখন এখানে যদি\nপ্রসঙ্গতঃই একটি বিষয় আপনা আপনিই এসে যায় তাহলে সেটিকে বোধ করি অগ্রাহ্য করবার কোনো\nঅবকাশ থাকে না। আর অগ্রাহ্য করতে চাইলেও হয়ত বিষয়টির অবস্থান পরোক্ষভাবে রয়েই যায়।\nতারপরেও যে বিষয়টি প্রত্যক্ষভাবে প্রায় সব মানুষের মননে একটি বিশেষ প্রভাব সম্পাতি\nভূমিকা অব্যাহতভাবে রেখে চলে- সেটি তার ব্যক্তিগত আকাঙ্ক্ষা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিন্তু এ ব্যক্তিগত আকাঙ্ক্ষাটিকে যদি আত্ম-সীমায়তির ভেতর একটি নির্দিষ্ট মাত্রাগত\nনিয়ন্ত্রণে আনয়ন করে স্থিত রাখা না যায় কেবল তাহলেই বিষয়টি একটি সমস্যার আকার ধারণ\nকরতে পারে। যদিও কোনও কারণে প্রত্যক্ষভাবে সে আকার নাও ধারণ করে তথাপি পরোক্ষভাবে ধারণ\nকরবার একটি সম্ভাবনা থেকেই যায়। আর মূলতঃ আশঙ্কাটি সেখানেই। এবং এ আশঙ্কার বিষয়টি মাথায়\nথাকবার পরেও নারীটি একেবারেই যেন ডেসপারেট। কোনো কিছুতেই সে নিজেকে স্বাভাবিক অবসস্থায়\nফেরাতে পারছে না। ভোর যতই এগিয়ে আসছে গাড়ির গতিও ততই বেড়ে যাচ্ছে। ভোর হবার আগেই নারীটিকে\nযে নদী তীরে পৌঁছুতেই হবে।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শেষ পর্যন্ত গাড়টি পৌঁছে গেলো কুমারিকা নদীর পূর্ব তীরে। তখন কেবলমাত্র ভোরের\nআলো ফুটতে শুরু করেছে। কুয়াশার কারণে তখনও আঁধারর প্রলেপ প্রকৃতি জুড়ে বিন্যস্ত থাকলেও\nপূর্ব দিগন্তে সূর্যের রক্তিম আভার রেখা অস্পষ্টভাবে দৃশ্যমান হচ্ছে। গাড়িটির ষ্টার্ট\nবন্ধ করে গাড়িটির ডান দরোজাটি খুলে যে মুহূর্তে নারীটি একটি পা বাড়িয়েছে নীচে নামবার\nজন্যে ঠিক সেই মুহূর্তেই প্রচণ্ড শব্দে পরপর বেজে উঠল কেন্দ্রিয় কারাগারের ভেতরের তিনটি\nঘন্টা। অর্থাৎ কারাগারে অবস্থানরত সকল কয়েদি এবং হাজতিকে তাদের স্ব স্ব ওয়ার্ড এবং\nকক্ষ ছেড়ে বাইরে বেরিয়ে আসতে হবে-বাজানো ঘন্টার শব্দগুলি তারই সঙ্কেত। এটি কারাগারের\nপ্রতিদিনের চিরাচরিত নিয়ম। সেন্ট্রিরা এক এক করে সব ওয়ার্ড এবং কক্ষের দরোজা খুলে দিয়ে\nদরোজার সামনে অপেক্ষারত। ধীরে ধীরে সব কক্ষ এবং ওয়ার্ড থেকে বেরিয়ে আসতে শুরু করলো\nকয়েদি এবং হাজতিরা। এরপর গুনে গুনে সবাইকে জেলখানার ভেতরের মাঠের নির্দিষ্ট স্থানে\nসারিবদ্ধভাবে দাঁড় করানোর পালা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>তিন</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঘন্টাধ্বনির তীব্র কর্কসতায় ঘুম ভেঙ্গে যাবার সাথে সাথে স্বপ্নটিও ভেঙ্গে গেলো\nজেলখানার কক্ষের মেঝের ওপর বেছানো একটি কম্বলের ওপর শায়িত নারীটির। নারীটির নাম লতিকা\nবিন্দি। বিন্দির জন্ম হয়েছিলো গ্রামের বাড়িতে। স্থানীয় ধাত্রীকে দিয়েই ওর প্রসব করানো\nহয়েছিলো। প্রসবের ব্যাথা উঠবার পরপরই বিভিন্ন ঔষধি লতা গুল্মের নির্যাসের মাধ্যমে তৈরি\nকরা এক প্রকারের ওষুধ প্রসুতিকে খাওয়ানো হয়েছিলো যাতে প্রসবটি নির্বিঘ্ন এবং সহজেই\nহতে পারে। ওষুধটি কাজ করেছিলো। বিঘ্নহীনভাবে জন্ম লাভ করে প্রথম পৃথিবীর আলো দেখেছিলো\nবিন্দি। জন্মাবার এক সপ্তাহ পর ওর কপালে একটি সুক্ষ্ম লাল টিপ পরিয়ে দিয়েছিলো ওর মা।\nগ্রামের মানুষজন ওই ধরণের টিপকে বিন্দি বলেই মনে করত। আর সে কারণেই ওর ডাক নামটি হয়ে\nগিয়েছিলো বিন্দি। ছমাস পর ওর বাবা ওই বিন্দি নামটির আগে আর একটি নাম জুড়ে দিয়েছিলেন-\nলতিকা। যেহেতু বাচ্চাটি প্রসবের আগে প্রসুতিকে লতা গুল্মের ঔষধি রস খাওয়ানো হয়েছিলো\nসেইহেতু ওর বাবা- আব্দুল্লাহ্ আইবেক আল মোহম্মদ বিন্দি শব্দটির সামনে লতিকা- শব্দটি\nবসিয়ে দিয়েছিলেন। আব্দুল্লাহ আইবেকের পিতা যেহেতু মনে করতেন তার বংশ সুলতানী আমলে ভারতের\nমহান শাসক সুলতান কুতুবুদ্দিন আইবেকের বংশ থেকে উদ্ভুত সেইহেতু পূত্রের নামের সাথে\nআইবেক পদবীটি সংযোজন করে দিয়েছিলেন তিনি। আর এতে তিনি এক ধরণের গর্ব অনুভব করতেন। সেই\nথেকে ওই পদবীটি তার পরবর্তী বংশধরদের বংশীয় পদবীতে প্রতিষ্ঠিত হয়ে গিয়েছিলো। এরই সূত্র\nধরে বিন্দির পিতা কন্যার নামের সাথে আইবেক পদবীটি জুড়ে দিয়েছিলেন। বিন্দির পূরো নামটি\nহয়ে গিয়েছিলো- লতিকা আইবেক বিন্দি। তবে সবাই ডাকত বিন্দি বলেই। বয়স বত্রিশোর্ধ। দীর্ঘঙ্গী,\nশ্যামল বর্ণে শোভিত একরাশ দীর্ঘ কালো চুলের ঝর্না স্পষ্ট করে দেয় ওর অটুট যৌবনের ইঙ্গিতটিকে।\nদৃষ্টি যেন হঠাৎ করেই আটকে যায় ওর চুল আর ঘন ভ্রু যুক্ত দীঘল দুটি চোখের ওপর। প্রথম\nদৃষ্টিতেই ভালো লাগার মতো দেহ-বল্লরী ওর। সহজে ভোলা যায় না। ও একটি কলেজের সহকারি অধ্যাপক।\nপেশা বলতে অধ্যাপনা অর্থাৎ শিক্ষকতা। এ ধরণের একটি মহান পেশার সঙ্গে জড়িত থেকে যে কাজটি\nও করেছে সেটি সমাজের চোখে চরম অপরাধ হিসেবে বিবেচিত হলেও ওর দৃষ্টিতে মোটেও তা নয়।\nএবং ওই কাজটির জন্যে ও বিন্দু পরিমান অনুতপ্ত তো নয়ই বরং ওই কাজটি ও নিজে করতে সক্ষম\nহওয়ায় পৃথক একটি গর্ব অনুভব করত নিজের ভেতর। এবং এই গর্ব অনুভব করবার কারণে নিজের জীবনটিকে\nও একেবারেই তুচ্ছ মনে করত। কারণ ও যে ঘটনাটি ঘটিয়েছিলো সে ঘটনায় অপরাধের যে মাত্রা\nতার চাইতেও কয়েক গুন বেশি অপরাধ ওর শৈশব জীবনে ঘটিয়েছিলো এই শিক্ষা পেশাতেই নিয়োজিত\nথাকা আর একজন শিক্ষক। আর সেই শিক্ষককৃত অপরাধের আঘাত আজও সে ভুলতে পারে না। প্রতিমুহুর্তে\nহনন করে চলে ওকে সেই আঘাতের সহ্যাতীত যন্ত্রণা। আর ওই যন্ত্রণা প্রশমনের জন্যেই ও ঘটনাটি\nঘটিয়েছিলো। এতে ও মনে করে ওর কোনো অপরাধ নেই। ও লজ্জিত অথবা দুঃখিত কোনোটিই নয়। সে\nজন্যেই ও ভাবত প্রতিমুহূর্তের আত্মহননের চাইতে একবারেই নিঃশেষ হয়ে যাওয়া অনেক সুখের।\nঅনেক তৃপ্তির। ওকে তো মানসিকভাবে হত্যা করা হয়েছে অনেক আগেই। এখন শুধু দৈহিকভাবে মৃত্যুর\nঅপেক্ষা। এই অপেক্ষার প্রহর শেষ হলেই ও যেন বাঁচে! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্বপ্নে ও দেখছিলো কুমারিকা নদীটি অতিক্রম করে ও প্রতিবেশী একটি দেশে প্রবেশ\nকরছে। প্রবেশ করবার পর জীবনটি হয়ত ওর একটি নিশ্চিন্ত স্থিতি লাভ করবে। বিন্দি মনে মনে\nযতই ভাবুক অথবা যতই মুখে বলুক জীবন ওর কাছে তুচ্ছ তবুও এ স্বপ্নটির মাধ্যমে স্পষ্ট\nহয়ে যায় ওর মনের অবচেতনে ও একটি নিশ্চিত নির্বিঘ্ন জীবন প্রত্যাশা করে। কিন্তু হলো\nনা। স্বপ্নটি ভেঙ্গে গেলো। একরাশ এলোচুল মাথায় নিয়ে কম্পিত পায়ে বেরিয়ে এলো নিজের কক্ষ\nথেকে। শুধু চারদিকটি একবার দেখে নিলো। আজ আটাশ জানুয়ারি। আজকে সর্বোচ্চ আদালত থেকে\nওর মামলার রায় দেয়া হবে। কিছু সময় পরেই ওকে নিয়ে যাওয়া হবে সেই আদালতের হাজতে। তারপর\nসেখান থেকে আদালতের কাঠগড়ায়। সাধারণতঃ সুপ্রিম কোর্টের এপিলেট ডিভিশন থেকে কোনো মামালার\nরায় ঘোষণার সময় সেই মামলার কোনো আসামী অথবা আসামীদেরকে আদালতে ডাকা হয় না। কিন্তু বিন্দির\nক্ষেত্রে একটি ব্যতিক্রম ঘটেছে। সর্বোচ্চ আদালতের ইচ্ছা এবং নির্দেশ অনুযায়ীই এই মামলার\nএকমাত্র আসামী লতিকা আইবেক বিন্দিকে রায় ঘোষণার সময় আদালতে উপস্থিত থাকতে বলা হয়েছে।\nকেন বলা হয়েছে সে বিষয়টি আদালত উল্লেখ করেনি। হয়ত আসামীর বয়স, পেশা-এ সবকিছুকে বিবেচণা\nকরে আসামীকে প্রত্যক্ষ করতে চেয়েছিলো আদালত। আর সে কারণেই বিন্দিকে আজ সর্বোচ্চ আদালতে\nউপস্থিত করা হয়েছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এরপর নিয়ম অনুযায়ী যা হবার তাই হলো। বিন্দিকে অদালতের কাঠগড়ায় নিয়ে আসা হলো।\nকাঠগড়ায় দাঁড়াল বিন্দি। একেবারেই নিস্প্রাণ, বিষণ্ন, চাঞ্চল্যহীন। প্রধান বিচারপতির\nনেতৃত্বে পাঁচ জন বিচারপতি সমন্বয়ে গঠিত সুপ্রিম কোর্টের এ্যাপিলেট ডিভিশনের পূর্ণঙ্গ\nবেঞ্চের নির্ধরিত বিচারপতিবৃন্দ এজলাসে একে একে তাঁদের আসন গ্রহন করলেন। আইনজীবি আর\nউৎসুক সাধারণ মানুষে এজলাস কক্ষ কানায় কানায় পূর্ণ। বিচারপতিবৃন্দ আসন গ্রহন করবার\nসঙ্গে সঙ্গে এজলাস কক্ষের সবাই তাদের আসন থেকে উঠে দাঁড়িয়ে ওঁদেরকে সম্মান জানাল। এরপর\nএজলাস জুড়ে পিন পতন নীরবতা। লতিকা বিন্দি কাঠগড়ায় স্থানুর মতো দাঁড়ানো। নিস্প্রান,\nনিস্প্রভ বিন্দি। চোখে মুখে ভাবান্তরনের কোনো লক্ষনের চিহ্ন মাত্র নেই। পুতুলের মতো\nদাঁড়িয়ে থাকল কাঠগড়ায়। বিন্দি জানে ঘোষিত রায়ে কী ঘটবে ওর ভাগ্যে। মানসিকভাবে প্রস্তুতি\nনিয়েই এসেছিলো বিন্দি। তাই ভাবান্তরনেরও কোনো প্রশ্ন ছিলো না ওর কাছে। প্রধান বিচারপতিসহ\nঅন্যান্য বিচারপতিরা বেশ কিছু সময় ধরে বিন্দিকে পর্যবেক্ষণ করলেন। এক পর্যায়ে প্রধান\nবিচারপতি বিন্দিকে প্রশ্ন করলেন- কিছুক্ষণের মধ্যেই আপনার মামলার রায় ঘোষিত হবে...\nআপনার কোনো প্রতিক্রিয়া? বিন্দি নিরুত্তাপ শুকনো কন্ঠে উত্তর দিলো- কিছু নেই স্যার।\nযে রায়ই আপনারা ঘোষনা করবেন আমি মেনে নেব। আর কোনো প্রশ্ন করলেন না প্রধান বিচারপতি।\nঅন্যান্য বিচারপতিবৃন্দও না। প্রধান বিচাপতি রায় ঘোষনা শুরু করলেন- বাংলাদেশের মাননীয়\nহাইকোর্ট একটি হত্যাকাণ্ড সংঘটনের জন্যে আসামিকে মৃত্যুদণ্ডের যে রায় প্রদান করেছিলেন\nসে রায়টিকেই আজ দেশের সর্বোচ্চ এই আদালত বহাল রাখল। অর্থাৎ আসামিকে মৃত্যুদ-ণ্ড দণ্ডিত\nকরা হলো। একই সাথে আই জি, প্রিজনকে ফঁসিতে ঝুলিয়ে মৃত্যুদণ্ড কার্যকর করবার নির্দেশ\nপ্রদান করা হলো। যতক্ষণ পর্যন্ত আসামির মৃত্যু নিশ্চিত না হবে ততক্ষণ পর্যন্ত আসামিকে\nফাঁসির রজ্জুতে ঝুলিয়ে রাখবার আদেশ প্রদান করা হলো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রায় ঘোষনা শেষে বিচারপতিবৃন্দ এজলাস কক্ষ থেকে এক এক করে নিষ্ক্রান্ত হলেন। সাধারনতঃ\nএ্যাপিলেট ডিভিশনের রায় খুবই সংক্ষিপ্ত আকারে ঘোষনা করা হয়ে থাকে। আসামিকেও কোনো প্রশ্ন\nকরা হয় না। অথচ আজকে কেন যে ওকে প্রশ্ন করা হলো এবং কেন যে রায়টি কিছুটা দীর্ঘায়িত\nআকারে ঘোষনা করা হলো-বুঝতে পারল না বিন্দি।&nbsp;&nbsp;\n</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিন্দির মা এজলাসে ছিলো। রায় ঘোষনা শেষ হবার সঙ্গে সঙ্গে এজলাস থেকে বেরিয়ে বাইরের\nদরোজার পাশে দাঁড়াল। পরপরই পুলিশ কর্ডন করে বিন্দিকে এজলাসের বাইরে নিয়ে আসা মাত্রই\nদরোজার পাশ থেকে এসে ওর মা ওকে জড়িয়ে ধরে নীরবে অশ্রুপাত শুরু করল। কোনো কথা বলল না।\nবিন্দি মায়ের একটি হাত নিজের হাতের মুঠায় নিয়ে মায়ের মুখের দিকে তাকিয়ে শুধু একটি কথা\nবলল- আমি মনে প্রাণে মৃত্যুদণ্ডই কামনা করেছিলাম মা। আর কিছু না বলে পুলিশকে উদ্দেশ্য\nকরে বলল- আমাকে নিয়ে চলুন। পুলিশ ওকে নিয়ে প্রিজন ভ্যনে ওঠাল। ভ্যানটি চলে গেলো কেন্দ্রিয়\nকারগারের দিকে। কিছুক্ষণের মধ্যেই জনাকীর্ণ আদালত কক্ষ সারিবদ্ধ চেয়ারে আবৃত বিরান\nভুমিতে রূপান্তরিত হলো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এই মামলাটিতে নিম্ন আদালত বিন্দির বিরুদ্ধে মৃত্যুদণ্ডের যে রায়টি দিয়েছিলো উচ্চ\nআদালত সে রায়টিকেই বহাল রাখে। উচ্চ আদালতের রয়ের বিরুদ্ধে বিন্দি সর্বোচ্চ আদালতে\nআপিল করতে চায়নি। কিন্তু একমাত্র মায়ের জীবিত থাকার বিয়ষটি বিবেচনা করেই আপিলটি করেছিলো\nবিন্দি। আপিল করবার পরেও বিন্দি জানত পূর্বের রায়কেই বহাল রাখবে আপিল বিভাগ। কিন্তু\nতখন মা আর কিছু বলতে পারবে না। এবং এটি মাথায় রেখেই বিন্দি আপিল করবার ক্ষেত্রে সম্মতি\nজানিয়েছিলো। দেশের সর্বোচ্চ আদালত ওর মৃত্যুদণ্ডের সাজাটিকে বহাল রেখে ওর মনষ্কামনা\nপূর্ণ করে দিলেন। ভেতরে ভেতরে অনেকটা স্বস্তি অনুভব করল বিন্দি। বিন্দির জীবনের একটি\nমাত্র অধ্যায় আর অবশিষ্ট থাকল- ফাঁসিতে ঝুলে মৃত্যুকে বরন করে নেয়া।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>চার</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যখন ও ষষ্ঠ শ্রেণির ছাত্রী তখন একদিন স্কুল থেকে বাড়ি ফিরবার পথে একটি প্রাইভেট\nকার ওকে ধাক্কা দিয়ে মূল সড়কের পাশে ফেলে রেখে দ্রুত অদৃশ্য হয়ে যায়। মেয়েটি রাস্তার\nপাশে পড়ে যাবার পরপরই ওকে ঘিরে পথচারী এবং স্থানীয় লোকজনের ভীড় ক্রমেই বাড়তে থাকে।\nভীড় বেড়ে যাবার কারণে সেখানকার শোরগোলের মাত্রাটিও বেড়ে যেতে থাকে স্বাভাবিক নিয়মেই-\nস্বাভাবিক নিয়ম বলছি এ কারণে যে, আমাদের সামাজিক পারস্পেক্টিভে এটি একটি নিয়মেই পরিনত\nহয়েছে। এই প্রেক্ষিতের কারণেই ভীড় বেশি হলে চ্যাচামেচি, হাঙ্গামা, উচ্চ বাচ্য- এ সবের\nমাত্রাটিও যে বেড়ে যাবে- এটিতে কোনও সন্দেহ নেই- যা আমরা সবাই জানি এবং বুঝি। এবং এটি\nনা জানার অথবা না বোঝার কোনো বিষয়ও নয়। এখন যদি আমরা সবকিছু বুঝেও না বোঝার ভান করে\nথাকি নিয়ত তাহলে আমরা নিজেরাই নিজেদেরকে প্রতারনা করবার পর্যায়ভুক্ত হব। তাই বলে আমরা\nএমন কিছুও করতে পারি না যাতে বোঝা যেতে পারে- আমরা মোটেও সে ধরণের কিছু করছি না।&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এত কিছু বলা হলো শুধু একটি কারণে যে- আমাদের সমাজে সময়ে সময়ে ঘটে যাওয়া কিছু\nঘটনা আমাদের নৈমিত্তিক জীবন প্রবাহের চরিত্রের সঙ্গে মিশে গিয়ে একেবারে একাকার হয়ে\nগেছে। এই যে কোনও একটি ঘটনা কখনও ঘটে গেলেই ঘটনাস্থলে সাধারণ মানুষের ভীড় বেড়ে যাওয়া,\nহাঙ্গামা, চ্যাচামেচি, চিৎকার ইত্যাদির মাধ্যমে ঘটনাস্থলের পরিবেশটিকে একেবারেই নারকীয়\nপরিবেশে রূপান্তরিত করে ফেলা- এটি যেন আমাদের সামাজিক চরিত্রের একটি মজ্জাগত রূপের\nআকারে প্রতিষ্ঠিতি পেয়ে গেছে আপনা আপনিই। কিছু সময় আগে ঘটে যাওয়া দুর্ঘটনাটি সে প্রতিষ্ঠিতির\nখুবই ছেট্টো আকৃতির একটি গৌণ দৃষ্টান্ত মাত্র। দুর্ঘটনা কবলিত মেয়েটিকে উদ্ধার করে\nতাৎক্ষণিকভাবে প্রয়োজনীয় চিকিৎসার ব্যবস্থা করবার উদ্যোগ গ্রহন না করে শুধু বিশৃঙ্খরা\nসৃষ্টিতেই যেন মেতে উঠেছে সবাই। ফলতঃ যা হচ্ছে তা মূলতঃ মেয়েটির যন্ত্রণা বৃদ্ধি। &nbsp;&nbsp;&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এই হাঙ্গামা, চ্যাচামেচির মধ্যেই কে একজন প্রচণ্ড ভীড় ঠেলে মেয়েটির মাথার কাছে\nগিয়ে বসল এবং ওর মাথাটিকে নিজের ডান বাহুর ওপর নিয়ে মেয়েটির মুখের দিকে তাকাল। মেয়েটি\nতখনও জ্ঞান হারায়নি, মোটমুটি স্বাভাবিক রয়েছে। লোকটিকে দেখে মেয়েটি বলে উঠলো-স্যার,\nআপনি এসেছেন! বোঝা গেলো মেয়েটি খুব বেশি অহত হয়নি এবং সবাই বুঝল মেয়েটি লোকটিকে চেনে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হ্যাঁ, এসেছি তো। দেখছো না তোমার মাথা আমার হাতের ওপর। চলো আমি তোমাকে তোমার\nবাড়িতে পৌঁছে দেবো।- এই বলে ভীড়ের মাঝে থাকা একজনকে উদ্দেশ্য করে বলল- একটি রিকশা\nডেকে দিন তো প্লিজ। আমি ওর স্কুলের শিক্ষক। আমি ওকে ওর বাসায় নিয়ে যাচ্ছি।- শিক্ষকটির\nকথা সবাই বিশ্বাস করল এবং আশ্বস্ত হলো এই ভেবে যে- যাক নিশ্চিন্ত হওয়া গেলো। একজন শিক্ষক\nতার স্কুলের আহত ছাত্রীকে ওর নিজের বাড়িতে পৌঁছে দেবে- এতে আর কারও কোনো সন্দেহের\nঅবকাশ থাকবার প্রশ্নই ওঠে না। ইতিমধ্যে একটি রিকশা এসে দাঁড়াল ওদেরকে নিয়ে যাবার জন্যে।\nশিক্ষকটি মেয়েটিকে আগে রিকশায় তুলে দিয়ে নিজে গিয়ে ওর পাশে বসল। রিকশাটি গন্তব্যের\nদিকে যাত্রা শুরু করল। কিছুক্ষণের মধ্যেই ঘটনাস্থলটি ভীড়শুন্য হয়ে গেলো। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>পাঁচ</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শিক্ষকটি অবিবাহিত। তরুণ। শহরের দক্ষিণ প্রান্তে একটি আধা পাকা ঘর ভাড়া নিয়ে\nএকাই সে ঘরে বসবাস করেন। ঘরটির সাথে এ্যাটাচ্ড একটি বাথরুম রয়েছে। একজন মধ্যবয়সী চুক্তির\nকাজের মহিলা সকালে এবং রাত্রে খাবার রান্না করে দিয়ে যায়। সকালে ওই ঘরের বারান্দায়\nশিক্ষকটি তার স্কুলের বিভিন্ন শ্রেণির কয়েকজন ছাত্রীকে পড়ান। ছাত্রীদের মধ্যে শিক্ষকটির\nজনপ্রিয়তাও যথেষ্ট। বয়স খুব বেশি হলে বাইশ থেকে তেইশের মধ্যে। লোকটি এ শহরের স্থায়ী\nঅধিবাসী নন। বাইরের একটি সরকারিবালিকা বিদ্যালয় থেকে বদলী হয়ে এক বছর আগে এ শহরের এই\nবালিকা বিদ্যালয়টিতে যোগদান করেন। এক বছরের মধ্যেই ছাত্রীদের কাছে ঈর্ষনীয়ভাবে জনপ্রিয়\nহয়ে ওঠেন তিনি। ছাত্রীটি দ্বিধাহীন এবং নিশ্চিন্ত মনে ওর স্যারের পাশে রিকশায় বসে বাড়ির\nদিকে যাত্রা করে। আজ বৃহষ্পতিবার হবার কারণে দুপুরের আগেই ওদের স্কুল ছুটি হয়ে গেছে।\nশহরের রাস্তায় যানবাহনের যথেষ্ট ভিড় আর সে ভিড়ের মধ্যে থেকে মাঝে মাঝে কোনো গাড়ির হাইড্রলিক\nহর্নের শব্দ যেন আকস্মিক আঁৎকে ওঠার মতো পরিবেশ সৃষ্টি করেই চলেছে। ফুটপাথ দিয়ে হেঁটে\nচলা পথচারীরাও বুঝি মাঝে মাঝে আঁৎকে উঠছে হঠাৎ করে ওদের পাশ দিয়ে দিয়ে তীব্র গতিতে\nচলে যাওয়া সেই হাইড্রলিক হর্নের উৎকট শব্দে। এসবে মেয়েটি খুবই বিরক্তি বোধ করছিলো।\nআর এ বিরক্তির কারণেই পথের দিকে না তাকিয়ে ও দৃষ্টি নিবদ্ধ করেছিলো অপার আকাশের দিকে।\nআকাশটি মেঘ মুক্ত। আকাশ জুড়ে ছোট ছোট পাখির দল উত্তর থেকে দক্ষিন দিকে ওদের ভাষায় কথা\nবলতে বলতে উড়ে চলছিলো। আবার আর একটি পাখির দল ঠিক একইভাবে দক্ষিণ থেকে উত্তরের দিকে\nএকইভাবে আকাশ পাড়ি দিচ্ছিলো। এরই মধ্যে প্রকাণ্ড দুটি সোনা মাখা ডানার চিল একে অপরের\nসাথে বিষম ঝগড়া করে একটি আর একটি চিলের পিঠের ওপর উঠে বসতে চাইছিলো। কিন্তু পারছিলো\nনা। তবে চেষ্টাটি অব্যাহত ছিলো। চিল দুটির এমন ঝগড়া বিবাদ দেখে আনন্দে আপ্লুত হয়ে মেয়েটি\nপাশে বসা ওর স্যারকে বলেছিলো- দেখুন স্যার, আকাশে দুটি চিল কেমন ঝগড়া করছে, মারামারি\nকরছে! কিন্তু কেউ কাউকে হারাতে পারছে না।- শিক্ষকটি আকাশের দিকে কিছু সময় তাকিয়ে থেকে\nচিল দু’টির আঁচরণ দেখে দৃষ্টি সরিয়ে নিয়ে মেয়েটিকে বলেছিলেন- ওরা দুজন মারামারি বা ঝগড়া\nকরছে না। একটি আর একটির ওপর উঠে বসতে চাইছে।- স্যারের এ কথা শুনে মেয়েটি স্যারকে প্রশ্ন\nকরল- কেন স্যার, ওরা দুজন তো ঝগড়া না করেও উড়ে চলতে পারে।- উত্তরে স্যার বললেন- সে\nকারণটি তুমি এখনই বুঝতে পারবে না। যখন তোমার বয়স আরও বেশি হবে তখন বুঝতে পারবে। এখন\nচলো আমরা বাসার কাছাকাছি পৌঁছে গেছি।- এতক্ষণ মেয়েটি আকাশের দিকে চিল দুটির ঝগড়াই\nউপভোগ করছিলো। রিকশাটি কোথায় এসে পৌঁছেছে বুঝতে পারেনি। শিক্ষকের কথায় আকাশ থেকে দৃষ্টি\nনামিয়ে পথের দিকে তাকিয়ে কিছুটা আশ্চর্য হয়েই প্রশ্ন করল মেয়েটি ওর স্যারকে- এটা তো\nআমাদের বাড়ির রাস্তা নয় স্যার, আমাকে কোথায় নিয়ে এলেন?- মেয়েটির কথার উত্তরে স্যারের\nজবাব- হ্যাঁ, এটা তোমাদের বাড়ির রাস্তা নয়। এখানেই আমার বাড়ি। আমার বাড়িতে গিয়ে ওষুধ\nখেয়ে একটু বিশ্রাম করে নেবে- আঘাত তো খুব বেশি লাগেনি, একটু বিশ্রাম নিলেই তুমি একদম\nসুস্থ্য হয়ে উঠবে। তারপর তোমাকে আমি তোমার বাড়িতে পৌঁছে দিয়ে আসব। আর বাড়িতে আমারও\nএকটু কাজ রয়েছে, তুমি বিশ্রাম নিতে নিতে সে কাজটুকুও আমি সেরে নেব।- স্যারের কথা শুনে\nমেয়েটি একটু চিন্তান্বিত হলো। চিন্তান্বিত হয়ে কতকটা সংকোচের সাথেই স্যারকে বললো- স্যার\nএতক্ষণে বাবা হয়তো আমাকে খুঁজতে শুরু করে দিয়েছেন। আপনি আমাকে আমার বাড়িতেই পৌঁছে\nদিয়ে আসুন স্যার।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হ্যাঁ, তুমি বিশ্রাম নিতে নিতে আমার হাতের কাজটুকুও শেষ হয়ে যাবে। এইটুকু সময়ের\nজন্যে তোমার বাবা মা অস্থির হবেন না। চলো।- মেয়েটিও আর কিছু বললো না। রিকশা থেকে নেমে\nস্যারের সঙ্গে হাঁটতে শুরু করল। একটু পরেই ওরা পৌঁছে গেলো স্যারের বাসায়। বাসায় পৌঁছেই\nস্যার ওর ঘরটি খুলে মেয়েটিকে একটি চেয়ারে বসতে বলে ঘরের জানালা দুটি খুলে দিয়ে ওকে\nবললেন- তুমি বসো, আমি তোমার জন্যে জেল আর ওষূধ নিয়ে আসছি।- স্যার বেরিয়ে গেলেন ঘর থেকে।\nবাড়িতে কাউকে না দেখে মেয়েটি যেন কিছুটা আতঙ্কিত হয়ে পড়ল। টেবিলে রাখা দু-একটি বই নিয়ে নাড়াচাড়া\nকরল আর কি যেন ভাবতে থাকল। এভাবে কিছু সময় কেটে যাবার পর স্যার ওষূধ নিয়ে ফিরে এলেন।\nমেয়েটিকে বললেন- এই নাও, বাম হাতের যেখানে আঘাত পেয়েছো সেখানে এই জেলের খানিকটা লাগিয়ে\nদাও। দু-মিনিটের মধ্যেই ব্যাথা কমে যাবে। আর এই পাতাটি থেকে একটি ট্যাবলেট খেয়ে নাও পাঁচ\nমিনিটের মধ্যেই একেবারে সুস্থ্য হয়ে উঠবে।- স্যার টেবিলে রক্ষিত পানির জাগ থেকে এক\nগ্লাস পানি গ্লাসে ঢেলে ওর হাতে দিলেন এবং পাতা থেকে একটি ট্যাবলেট নিয়ে ওর হাতে দিয়ে\nবললেন- খেয়ে নাও।- মেয়েটি আর কিছু না বলে ট্যাবলেটটি খেয়ে নিলো। এরপর মেয়েটি জেলের\nটিউব থেকে ডান হাতের অঙ্গুলের ডগায় সামান্য একটু জেল নিয়ে বাম হাতের কনুইতে ধীরে ধীরে\nঘষতে লাগলো। এবার স্যার বললেন- তুমি বিশ্রাম করো, এর মধ্যে আমি আমার কাজটুকু সেরে নিই।-\nবলে স্যার ঘর থেকে বেরিয়ে গেলেন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ট্যাবলেটটি খাবার পর ধীরে ধীরে মেয়েটির চোখে ঘুম নামতে শুরু করল। ও যেন কেমন\nনিস্তেজ হয়ে যেতে থাকল। এভাবে সামান্য সময় কেটে যাবার পর মেয়েটি আর চেয়ারে বসে থাকতে\nপারল না। চেয়ারের পাশেই স্যারের বিছানায় গিয়ে শুয়ে পড়ল। সামান্য সময়ের মধ্যেই ঘুমিয়ে\nগেলো মেয়েটি। ঠিক এ রকমের একটি পরিবেশের জন্যেই বাইরে গিয়ে অপেক্ষা করছিলেন ওর শিক্ষকটি।\nশিক্ষকটি যখন ফিরে এলেন তখন দেখলেন অঘোর ঘুমে আচ্ছন্ন মেয়েটি। বালিশে মাথা রেখে ডান\nকাত হয়ে নিশ্চিন্তে ঘুমুচ্ছে মেয়েটি। শিক্ষকটি ওর কাছে গেলেন। ওর চোখ মুখের দিকে তাকিয়ে\nনিশ্চিত হলেন- মেয়েটি গভীর ঘুমে নিমজ্জিত। অনেকক্ষণ মেয়েটির মুখের দিকে তাকিয়ে থাকলেন\nশিক্ষকটি। ঘুমন্ত অবস্থায় মেয়েটি যে এত সুন্দর হতে পারে স্বাভাবিক অবস্থায় বুঝতে পারেননি\nতিনি। উত্তেজিত হয়ে পড়লেন ভীষনভাবে। খুব দ্রুত মেয়েটিকে চিৎ করে শোয়ালেন এবং বিছানায়\nউঠে ওর পাজামার ফিতে খুলে ফেললেন। তারপর যা হবার তাই ঘটতে শুরু করল মেয়েটির ওপর। পাগলের\nমতো মেয়েটিকে নিষ্পেষিত করতে করতে শুরু করলেনে শিক্ষকটি। শেষের দিকে প্রচণ্ড যন্ত্রনায়\nমেয়েটির ঘুম ভেঙ্গে গেলো। চোখ খুলেই দেখল ওর ওপর ওর স্যার। মেয়েটি আকুল কান্নায় ভেঙ্গে\nপড়ে শুধু বললো- স্যার আমার খুব কষ্ট হচ্ছে। আমাকে ছেড়ে দিন।- দাঁত দিয়ে নীচের ঠোঁটটি\nকামড়ে ধরে নিজের দুহাত দিয়ে নিজের মুখটি ঢাকলো মেয়েটি। কিছু সময় পর ওর দেহের ওপর থেকে\nনেমে এলো ওর স্যার- যিনি কিনা ক্লাসের সব ছাত্রীকে অবিরত আদর্শবতী হবার উপদেশ বিতরণ\nকরে থাকেন!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটির ওপর থেকে নেমে চেয়ারে বসে কতকটা নির্দেশ দেবার ভঙ্গিতেই বললেন শিক্ষকটি-\nশোনো, যা হবার তা-তো হয়ে গেছে। এখন এসব নিয়ে ভেবে আর কোনো লাভ নেই। যে ঘটনাটি ঘটল এ\nসম্পর্কিত একটি কথাও তুমি কাউকে বলবে না। আমি সবকিছুর ছবিই মোবাইলে তুলে নিয়েছি। ঘটনাটি\nতুমি প্রকাশ করলে এই ছবিগুলি আমি ফেসবুকসহ সব Social Media- তে প্রকাশ করে দেবো- যাতে তোমার, তোমার পরিবারের\nচরম ক্ষতি হয়ে যাবে।- উত্তরে বিন্দি বলেছিলো- আর কী ক্ষতি আপনি আমার করবেন স্যার? যে ক্ষতি\nকরবার তা তো আপনি করেই দিয়েছেন। এর চাইতে বড় কোনো ক্ষতি কোনো মেয়ের জীবনে থাকতে পারে\nকি?- এ প্রশ্নের উত্তর না দিয়ে শিক্ষকটি বললেন- তবে তোমার বাবা মা যদি রাজী থাকেন তাহলে\nআমি তোমাকে বিয়ে করবো।- এ কথাগুলি বলে বাথরুম থেকে কয়েক টুকরো টিস্যু এনে মেয়েটির হাতে\nদিয়ে বললেন- আমি বাইরে যাচ্ছি, এই টিস্যুগুলি দিয়ে সব মুছে নাও। বাইরে থেকে এসেই আমি\nতোমাকে নিয়ে তোমাদের বাড়িতে যাবো। আর আমি একটু আগে তোমাকে যা যা বলেছি সে সব কথার একটিরও\nযেন নড়চড় না হয়। হলে যা ঘটবার তোমার কপালেই ঘটবে। বুঝতে পারলে তো আমি কী বললাম?- মেয়েটি\nকোনো কথাই বলল না। শিক্ষকটি ঘর থেকে বেরিয়ে গেলেন। একই সাথে নির্দ্ধারিত হয়ে গেলো বিন্দির\nভাগ্য। চিরদিনের মতো নষ্ট হয়ে গেলো বিন্দি। অনেকটা সময় ধরে কি যেন ভাবতেই থাকলো বিন্দি।\nদৃষ্টি শুন্য আকাশের দিকে স্থির। জানালা দিয়ে যেটুকু আকাশ দেখা যায় সে টুকুর দিকে তাকিয়ে\nঅবিরাম ভেবে চলল বিন্দি। এক সময় স্বাভাবিক হবার চেষ্টা করল। কারণ ও এতক্ষণ ভেবে ভেবে\nসিদ্ধান্ত নিয়েই নিয়েছে- ঘটনাটির কথা ও কাউকেই বলবে না। বান্ধবীদেরকে তো নয়ই এমন কি\nবাবা মা’কেও না। তবে ওই শিক্ষককে ও কখনই ক্ষমা করতে পারবে না। প্রতিশোধ ও নেবেই। চরম\nপ্রতিশোধ- যে প্রতিশোধের জ্বলন্ত আগুনে শিক্ষক নামের ওই জানোয়ারটি জ্বলে জ্বলে ছাই\nহয়ে যাবে। বিন্দির জীবন তো শেষ হয়ে গেছে কিন্তু ওই শিক্ষকের জীবনও আর বাঁচবে না- এটি\nবিন্দির আত্ম-শপথ, চুড়ান্ত অঙ্গিকার। যে অঙ্গিকার, যে শপথ থেকে এক বিন্দুও সরে আসবার\nঅবকাশ নেই বিন্দির কাছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ফিরে এলেন শিক্ষকটি। এসেই বিন্দিকে বললেন- তুমি কি তৈরি? চলো।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হ্যাঁ স্যার, চলুন। আমি কাউকেই কিছু বলবো না। আপনি নিশ্চিন্ত থাকতে পারেন।- বিন্দির\nএ কথা শুনবার পর শিক্ষকটি কেমন যেন একটি দ্বিধা দ্বন্দে পড়ে গেলেন। ভাবলেন- এত দ্রুত\nএত স্বাভাবিক হলো কি করে মেয়েটি। অন্য কোনো দূরভিসন্ধি নেই তো। তাড়া দিলো বিন্দি- কই\nস্যার চলুন, দাঁড়িয়ে পড়লেন যে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হ্যাঁ, চলো।- দুজনই বেরিয়ে গেলো ঘর থেকে। কিছুক্ষণের মধ্যেই ওরা পৌঁছে গেলো\nবিন্দির বাড়িতে। বিন্দিকে ওর বাড়িতে পৌঁছে দিয়ে শিক্ষকটি চলে গেলেন ওর নিজের কাজে।\nযাবার আগে বিন্দি শিক্ষকটিকে বললো- আমি কাউকেই কিছু বলব না স্যার। এই কথাটি আমি অবশ্যই\nরাখব। আপনি নিশ্চিন্ত থাকতে পারেন।- বলেই বিন্দি বাড়ির ভেতর প্রবেশ করল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>ছয়</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ইতিমধ্যেই কেটে গেছে বারোটি বছর। এই বারো বছরে যমুনা দিয়ে অনেক পানি গড়িয়ে গেছে। বিন্দি স্কুল থেকে শুরু করে বিশ্ববিদ্যালয়ের সীমানা পেরিয়ে এসেছে। ও ভালো রেজাল্ট নিয়ে অনার্সসহ রাষ্ট্রবিজ্ঞানে মাস্টার্স ডিগ্রি অর্জন করেছে। বাবা পদোন্নতি পেয়ে শিক্ষা সচিবের কার্যালেয়ের প্রশাসনিক কর্মকর্তা পদে যোগদান করেছেন। সংসারের মলিন আবরনটি সরে গিয়ে উজ্বল ধবধবে সফেদ আকার ধারণ করেছে। বাবা মায়ের অন্তরালে একটি মৃদু উষ্ণ সুখের আবেশ তৈরি হয়েছে- যা ওদের কথা বার্তায় এখন স্পষ্ট হয়ে ওঠে। এরই সূত্র ধরেই বোধকরি বাবা মা কন্যার বিয়ে দেবার জন্যে উপযুক্ত পাত্রের অনুসন্ধান করছেন। কিন্তু বাবা মা ওকে সে বিষয়টি অবহিত করলেও বিন্দি অস্বীকৃতি জানিয়েছে। বিয়ে করতে চায়নি ও। মা ওকে বিষয়টি ভেবে দেখবার জন্যে কয়েকবার বললেও বিন্দি একই কথা বলেছে। এরপর বাবা মা-ও আর ওর সিদ্ধান্তের বাইরে কিছু বলেনি আর ওর সিদ্ধান্তের বিরোধিতাও করেনি। ষষ্ঠ শ্রেণিতে অধ্যয়নকালীন ওর জীবনে যে ঘটনাটি ঘটে গেছে সেটি ও কখনই ভুলতে পারেনি। স্কুল জীবন থেকে শুরু করে বিশ্ববিদ্যালয়ে পড়াশুনা করবার সময়েও ও সব সময়ের জন্যেই চরম বিষণ্ন থেকেছে। স্কুল জীবনের বান্ধবীদের সঙ্গে স্বাভাবিক আঁচরণ করলেও কোনো বান্ধবী ওকে কোনো প্রশ্ন না করলে ও কোনো কথা বলেনি। বিশ্ববিদ্যালয়েও তাই। বাড়িতে বাবা মায়ের সাথে যেটুকু কথা না বললেই নয় শুধু সেটুকুই বলেছে। আর সব সময় থেকেছে পড়ার টেবিলে। মা বিষয়টি বুঝতে পেরেছিলেন। জিজ্ঞাসাও করেছিলেন ওকে- কিরে বিন্দি তুই এখন এত চুপচাপ থাকিস কেন? আগে তো এমন কখনও ছিলি না। কোনো সমস্যা হয়েছে।- উত্তরে বিন্দি বলেছে- মা পড়াশুনার ভীষন চাপ। আমাতে ভালো রেজাল্ট করতে হবে। শুধু এটুকুই তোমরা মাথায় রেখো।- আর কিছু ও বলেনি। মা-ও এ নিয়ে আর কোনো প্রশ্ন করেনি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কলেজ জীবনেই বাবার অনুমতি নিয়ে কার ড্রাইভিংটি শিখে নিয়েছে। একটি বিশেষ জিদ ওর\nভেতর সব সময়ের জন্যে ক্রিয়াশীল থেকেছে যে, গাড়ি দুর্ঘটনার কারণেই ওর জীবনের সর্বোচ্চ\nসর্বনাশটি ঘটেছে। এটি না ঘটলে ওর জীবনটি হয়ত সুস্থ্য আর সুন্দর হতে পরত। ও যখন মাষ্টার্স\nডিগ্রি অর্জন করে তখন বাবার কাছে একটি ছোট কার কিনে দেবার আকুতি জানিয়েছিল। তবে এখুনি\nনা। ওর যখন কোনো ভালো চাকুরি হবে তখনই বাবা যেন ওকে একটি কার কিনে দেয়। বাবা ওর চাওয়াটি\nশুনে খুশিই হয়েছিলেন। বলেছিলেন- তুই আমার একটি মাত্র সন্তান। আর তোর কোনো চাওয়াকে আমি\nঅপূর্ণ রাখব- ভাবলি কি করে?- বিন্দি বাবার সম্মতি প্রাপ্তিতে খুশি হয়েছিলো। ওর ইচ্ছে\nও নিজের গাড়িতে চড়ে ওর অফিসে যাবে এবং অফিস থেকে ফিরে আসবে। ষষ্ঠ শ্রেণিতে থাকাকালীন\nবাবা শিক্ষা মন্ত্রনালয়ের সচিবের অধীনে উচ্চমান অফিস সহকারির পদে কর্মরত ছিলেন। তখন\nওর আর্থিক সচ্ছলতা আজকের মতো ছিলো না। তাই বিন্দিকে পায়ে হেঁটে অথবা কখনও কখনও রিকশায়\nচড়ে স্কুলে যাওয়া আসা করতে হতো। আর এখন ওর বাবা শিক্ষা মন্ত্রনালয়েরই এ্যাডিমিনিন্সট্রেটিভ\nঅফিসার- একটি সম্মানজনক পদে অধিষ্ঠিত। এখন ওর অনেক সচ্ছলতা। তাই একমাত্র মেয়েকে একটি\nছোট্ট কার কিনে দেয়া ওর পক্ষে মোটেই কোনো সমস্যা হিসেবে মনে হয়নি ওর কাছে। সে কারণেই\nকন্যার এটুকু চাওয়াকে অগ্রাহ্য করতে চায়নি পিতা। মা দুর্ঘটনার করণ দেখিয়ে মৃদু আপত্তি\nজানালেও বাবার সম্মতিটিই টিকে গেছে শেষ পর্যন্ত। এরপর বিন্দি মায়ের গলা জড়িয়ে ধরে বলেছে-\nআচ্ছা মা তোমার মেয়ে গাড়িতে করে অফিসে যাবে, অফিস থেকে বাড়িতে ফিরে আসবে- তোমার ভালো\nলাগবে না?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভালো তো লাগবেই। কিন্তু এই ভালো লাগা কোনো দুর্ঘটনার কবলে পড়ে যদি চুরমার হয়ে\nযায়- আমার আশঙ্কাটি সেখানেই।- মায়ের কথা শুনে বিন্দি মাকে সান্তনা দিয়ে বলেছে- মা,\nপুরুষদের চাইতে মেয়েরা অনেক সতর্কতার সাথে গাড়ি চালায় এবং খুব ভালোভাবেই চালায়। তোমার\nদুশ্চিন্তার কোনো কারণই নেই। তুমি দেখে নিও।- আর কিছু বলেনি বিন্দি। সোজা নিজের শোবার\nঘরে চলে গেছে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মাস্টার্স ডিগ্রিটি অর্জনের ছ-মাসের মাথায় ওদের জেলার বাইরের একটি উপজেলার\nসরকারি কলেজে রাষ্ট্রবিজ্ঞান বিভাগের প্রভাষক পদে ওর একটি চাকরি হয়েছে। বাবা মা ভীষণ\nখুশি হয়েছেন। বাবা ওর মন্ত্রনালয়ের কর্মকর্তা, কর্মচারীদের নির্দিষ্ট ফাণ্ড থেকে কিছু\nটাকা ঋণ গ্রহণ করে মেয়ের জন্যে একটি ছোটো আকারের কার কিনেছেন। সেই কারটি ড্রাইভ করেই\nবিন্দি প্রথম গিয়েছে সেই কলেজে ওর পদে যোগদান করতে। কলেজের প্রিন্সিপাল থেকে শুরু করে\nসকল শিক্ষক শিক্ষিকা ওকে সাদরে বরণ করে নিয়েছে। বরন করবার পালা শেষে অধ্যক্ষের কক্ষেই\nকিছু লাইট ফুডের Arrange করেছিলেন অধ্যক্ষ নিজেই।\nসবাই মিলে বসে ছিলেন অধ্যক্ষের টেবিলের চারপাশ জুড়ে। সবাই যখন খেতে শুরু করেছে ঠিক\nতখুনি একজন শিক্ষক এসে প্রবেশ করলেন অধ্যক্ষের কক্ষে। প্রবেশ করেই একটি চেয়ারে বসলেন।\nশিক্ষকটি বিন্দিকে লক্ষ করেননি। কিন্তু বিন্দি ওকে লক্ষ করেছিলো। প্রথম ওকে এখানে দেখেই\nচমকে উঠেছিলো বিন্দি। তবে সামান্য সময়ের জন্যে। তারপর সামলে নিয়েছিলো নিজেকে। এই লোকটি\nসেই শিক্ষক যে ওকে ষষ্ঠ শ্রেণিতে অধ্যয়নকালীন শিক্ষকটির নিজের ঘরে ওকে ঘুমের ওষুধ খাইয়ে\nজোর করে ধর্ষণ করেছিলো। খুবই স্বাভাবিকভাবে নিজের চেয়ার থেকে উঠে গিয়ে প্রশ্ন করেছিলো\nওই শিক্ষকটিকে- স্যার, আপনি এই কলেজে? কবে জয়েন করেছেন?- প্রশ্নটি করেই শিক্ষকটির মুখের\nদিকে তাকিয়ে থাকল বিন্দি। শিক্ষকটিও ওকে চিনে ফেলে কিছুটা বিব্রত হয়ে উত্তর দিয়েছিলো-\nএই তো এক মাস আগে। স্কুলের চাকরিটি ছেড়ে দিয়ে এই কলেজে জয়েন করেছি। তা তুমি কবে?- ওর\nপ্রশ্নের উত্তরে বলেছিলো বিন্দি এই তো স্যার আজকেই। ঠিক আছে স্যার চলুন এবার সবাই মিলে\nখেয়ে নিই।- একেবারেই স্বাভাবিক বিন্দি। অতীতে ঘটে যাওয়া ওই ঘটনাটির কোনো চিহ্ন মাত্রই\nনেই ওর আঁচরণে। বিন্দির এ আঁচরণে শিক্ষকটিও সম্ভবতঃ কিছুটা আশ্বস্ত হলো এই ভেবে যে,\nযাক বিন্দি যে কথাটি ওকে দিয়েছিলো সেটি পালন করেছে পুরো মাত্রায় শতভাগ। খাবার পালা\nশেষ হলে অধ্যক্ষ সব শিক্ষক শিক্ষিকার সাথে বিন্দির পরিচয় করিয়ে দিলেন। পরিচয় পর্ব শেষে\nযে যার ক্লাসে শিক্ষকরা চলে গেলেন। শুধু বিন্দি অধ্যক্ষের অনুমতি নিয়ে আজকে আর ক্লাসে\nগেল না। গাড়িটি স্টার্ট করে যাত্রা করল বাড়ির দিকে। সারা রাস্তায় গাড়ি চালাতে চালাতে\nশুধু একটি বিষয়ই চিন্তা করল- যাক এতদিনে হাতের মুঠোর ভেতর পাওয়া গেছে শিক্ষক নামের\nওই জানোয়ারটিকে। এ সুযোগটি কিছুতেই মিস্ করতে পারবে না বিন্দি। ওর নিজের অঙ্গিকার পূরণ\nকরতে হবে এবার। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>সাত</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আরও অতিবাহিত হয়েছে সাত বছর। এই সাত বছরের মধ্যে ওই শিক্ষকের সাথে বিন্দির সম্পর্ক\nঅনেকটাই স্বাভাবিক হয়ে এসেছে। দুজনের কেউই আর পরস্পর মুখোমুখি হলেও কোনো সঙ্কোচ অথবা\nবিব্রত বোধ করে না। বিন্দি পদোন্নতি পেয়ে প্রভাষক থেকে সহকারি অধ্যাপক হিসেবে ওই কলেজেই\nপদায়িত হয়েছেন। কারণ রাষ্ট্রবিজ্ঞান বিভাগের সহকারি অধ্যাপকের পদটি শুন্য হয়ে পড়েছিলো\nঅনেকদিন আগেই। সে কারণে বিন্দি যথারীতি সংশ্লিষ্ট পদে যোগদান করেছে। ওই শিক্ষকটিরও\nপদোন্নতি হবার কথা ছিলো এবং তিনি পদোন্নতির তালিকাতেও ছিলেন। কিন্তু ওর মাস্টার্সের\nসনদ পত্রের জটিলতার কারণে সাময়িকভাবে পদোন্নতিটি স্থগিত হয়ে গেছে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ওদের দুজনের মধ্যে সম্পর্ক স্বাভাবিক হবার পর একদিন ওই শিক্ষকটি বিন্দিকে ওর\nগাড়িতে করে শিক্ষকটির কাক্সিক্ষত গন্তব্য স্থানে পৌঁছে দেবার অনুরোধ করলে বিন্দি ওকে\nগাড়িতে তুলে নেয়। গাড়িতে বসেই শিক্ষকটি বিন্দির সঙ্গে কথা বলে- আমি তোমাকে একটি কথা\nবলতে চাই।- এ কথার উত্তরে বিন্দিও স্পষ্ট করে বলে- হ্যাঁ স্যার বলুন, কী বলবেন?- কিন্তু\nভেতরে ভেতরে বিন্দি কঠিন থেকে কঠিনতর হতে থাকে- যা শিক্ষকটির ধারণা করবার কথা নয়। বিন্দির\nআশ্বাস পেয়ে শিক্ষকটি সরাসরি বিন্দির কাছে একটি প্রস্তাব রাখে- আমি এখনও বিয়ে করিনি।\nঅবিবাহিতই রয়ে গেছি। তোমার যদি কোনো আপত্তি না থাকে তাহলে আমি তোমাকে বিয়ে করতে চাই।-\nএ কথা শুনবার পর বিন্দি অত্যন্ত স্বাভাবিকভাবে এবং ঠাণ্ডা মাথায়- আমার বিয়ে নিয়ে আমি\nএখনও ভাববার সুযোগই পাইনি। তাই এখন এ প্রসঙ্গটি নিয়ে কথা না বলাই ভালো। চলুন আপনি কোথায়\nযেন নামবেন বলেছিলেন?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হ্যাঁ, সামনের বাম দিকে পার্ক করলেই হবে।- বিন্দি গাড়িটি রাস্তার বাম দিকে থামিয়ে\nদিলো। শিক্ষকটি গাড়ি থেকে নেমে গেলেন। বিন্দি সরাসরি ওর বাড়ির দিকে যাত্রা শুরু করল।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>আট</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ওই শিক্ষকটির সাথে বিন্দির সর্বশেষ কথাগুলি হবার এক সপ্তাহ পর একদিন ক্লাস শেষে\nক্লাস থেকে বেরিয়ে আসবার সময় বিন্দি লক্ষ করল-সংশ্লিষ্ট শিক্ষকটি কলেজ ক্যাম্পাস থেকে\nবেরিয়ে মূল সড়ক দিয়ে হাঁটতে শুরু করেছেন। আর সময় নষ্ট করল না বিন্দি। গাড়ির স্টিয়ারিংয়ে\nবসে গাড়িটি স্টার্ট করে কলেজ ক্যাম্পাস থেকে বেরিয়ে এসে ওই শিক্ষকটিকে অনুসরণ করতে\nশুরু করল লো স্পিডে গাড়ি চালিয়ে। শিক্ষকটি যখন একটি মোড় ক্রস করে বাম দিকের ফাঁকা রাস্তা\nদিয়ে হাঁটতে শুরু করলেন ঠিক তখুনি গাড়ির স্পিড যতদূর সম্ভব বাড়িয়ে দিয়ে সোজাসুজি শিক্ষকটির\nওপর দিয়ে চালিয়ে দিলো। একটু সামনে গিয়ে পেছন ফিরে দেখল বিন্দি শিক্ষকটির মাথা চূর্ণ\nবিচূর্ণ হয়ে ঘিলুগুলি সব সড়কে ছিটকে পড়েছে। বিন্দি নিশ্চিত হলো শিক্ষকটি আর নেই। না\nফেরার দেশে চলে গেছেন। আর দাঁড়াল না বিন্দি গাড়ি নিয়ে সরাসরি গিয়ে প্রবেশ করল সদর থানার\nও সির কক্ষে। ও.সি’কে সব ঘটনা আদ্যেপান্ত খুলে বলল। একই সাথে ওকে এ্যারেস্ট করবার জন্যেও ও.সি’কে অনুরোধ জানাল। ও.সি\nনিয়ম অনুযায়ি ওকে কাস্টোডিতে নিয়ে ওর সকল বর্ণনা জবানবন্দি হিসেবে একটি নির্ধারিত ফরমে\nলিপিবদ্ধ করে ওকে সেই ফরমে স্বাক্ষর করতে বললেন। বিন্দি নিশ্চিন্তে স্বাক্ষর করল। শুরু\nহলো বিন্দির বিরুদ্ধে হত্যা মামলা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এর মধ্যে অতিক্রান্ত হয়েছে আরও চার বছর। এই চার বছরের মধ্যে দুবছরের মাথায় ওর\nবাবার মৃত্যু হয়েছে। মৃত্যুর আগে ওর বাবা ওর মাকে বলে গিয়েছিলেন- সর্বোচ্চ আদালতে\nবিন্দির মামলার চূড়ান্ত রায় যাই হোক রায় ঘোষণার পর তুমি শিক্ষা মন্ত্রনালয়ের সচিব এনায়েতুর\nরহমানের সঙ্গে অত্যন্ত গোপনে তাঁর বাসায় দেখা করবে। আমি ওঁকে সবকিছু বলেছি, তুমি শুধু\nদেখা করবে। আর উনি যে পরামর্শ দেবেন সেই পরমর্শ অনুযায়ী তুমি ব্যবস্থা নেবে।- এর বাইরে\nআর কোনো কথা বলেনি বিন্দির বাবা বিন্দির মাকে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চার বছর পর ওই হত্যা মামলার রায় দেশের সর্বোচ্চ আদালত থেকে ঘোষণা করা হলো। এই\nরায় ঘোষনার পর এখন শুধু মৃত্যুর জন্যে অপেক্ষা করবার পালা। মৃত্যুদণ্ডটি যতটা না কঠিন\nতার চাইতেও শতগুণ বেশি কঠিন নিশ্চিত মৃত্যু ক্ষণটির জন্যে অনিদ্রায় অর্ধাহারে প্রহরের\nপর প্রহর গুণে চলা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>নয়</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সর্বোচ্চ আদালতের রায় ঘোষিত হবার দশ দিন পর মাত্র একদিন কেন্দ্রিয় কারাগারে\nএসেছিল বিন্দির মা কন্যার সঙ্গে দেখা করবার জন্যে। আধা ঘণ্টা ধরে বিন্দির মা বিন্দির\nসঙ্গে একান্তে কথা বলেছিলো। কথা বলা শেষে ফিরে গিয়েছিলো মা ওর নিজের বাড়িতে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আজ ১৭ মার্চ। বিন্দির মৃত্যুদণ্ড কার্যকরের শেষ দিন। রাত বারোটার আগেই বিন্দির\nমৃত্যুদণ্ড কার্যকর করতে হবে। আইন অনুযায়ী মামলার পূর্ণাঙ্গ রায়ের কপি প্রকাশিত হবার\nপর ২১ দিনের আগে নয় এবং ২৮ দিনের পরে নয়- এর মধ্যেই রায় কার্যকর করতে হবে। সে হিসেবে\n২৮ দিনের সর্বশেষ দিনটি আজকের রাত্রি বারোটা পর্যন্ত। জেল কর্তৃপক্ষ সেভাবেই আজ রাত\n১১টা ৫৯ মিনিটে রায় কার্যকরের সময় নির্ধারণ করেছে- যা সময় মতো আসামিকে জানিয়েও দেয়া\nহয়েছে। আসামিও মানসিক দিক থেকে চূড়ান্ত প্রস্তুতিও নিয়ে রেখেছে। আজকের রাত্রিটিই বিন্দির\nজীবনের শেষ রাত্রি। তবে বিন্দি সন্তুষ্ট একটি মাত্র কারণে- যে ব্যক্তিটি বিন্দির জীবনের\nঅঙ্কুরটিকেই ধ্বংস করে দিয়েছিলো বিন্দিও তার জীবনটিকে পৃথিবীর চিত্রপট থেকে মুছে দিতে\nসক্ষম হয়েছে। এটিই বিন্দির জীবনের সবচাইতে বড় প্রাপ্তি। আর কোনো কিছুরই প্রয়োজন নেই\nবিন্দির। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এখন কারাগারের দেয়াল ঘড়িতে কাঁটায় কাঁটায় রাত দশটা বেজে তিরিশ মিনিট। কণ্ডেম\nসেল থেকে বের করে আনা হলো বিন্দিকে। মহিলা রক্ষীদের তত্ত্বাবধানে একটি প্রশস্ত বাথরুমে\nওকে গোসল করানো হলো। গোসল শেষে ওকে বাথরুম থেকে বের করে এনে ওকে দুরাকাত নফল নামাজ\nআদায় করতে বলা হলো। বিন্দি নামাজ আদায় করল। এরপর জেলখানা মসজিদের ঈমাম বিন্দিকে তওবা\nপাঠ করালেন। এসব আনুষ্ঠানিকতা শেষ করতে অনেকটা সময় পেরিয়ে গেলো। ফাঁসি কার্যকর করবার\nনির্দিষ্ট সময় কাছাকাছি এসে পড়ল। ওর দুহাত পেছন থেকে শক্ত করে বাঁধা হলো এবং বাঁধা\nঅবস্থায় ওকে ফাঁসির মঞ্চে নিয়ে আসা হলো চোখ দুটি কালো কাপড়ে ঢেকে দিয়ে। রাত্রি ১১টা\nবেজে চল্লিশ মিনিট। বিন্দিকে ফাঁসির মঞ্চে তোলা হলো। মঞ্চে তুলবার পর ওর পা দুটিও খুব\nশক্ত করে বেঁধে দেয়া হলো। মাথায় লম্বা কালো টুপি পরিয়ে মাথা মুখ ঢেকে দেয়া হলো। নিয়ম\nঅনুযায়ী মঞ্চের সামনে সারিবদ্ধভাবে দাঁড়িয়েছেন আই জি প্রিজন, ঢাকার জেলা প্রশাসক, কারাগারের\nজেলার, সিভিল সার্জন, দুজন ম্যাজিষ্ট্রেট, মসজিদের ঈমামসহ অন্যান্য গুরুত্বপূর্ণ ব্যক্তিরা।\nজল্লাদ বিন্দির গলায় ফাঁসির রজ্জু পরিয়ে দিলো। এখন শুধু ফাঁসির রজ্জুর অপর প্রান্তটি\nযে লিভারটির সঙ্গে যুক্ত- জল্লাদ কর্তৃক সেটিকে টেনে দেয়ার অপেক্ষা। জেলারের হাতে রক্ষিত\nরুমালটি মাটিতে ফেলে দেবার সঙ্গে সঙ্গে লিভারটি টেনে দেবে জল্লাদ। আর তখনই বিন্দির\nদেহটি পড়ে যাবে প্রায় দশ থেকে পনের ফুট গভীর একটি পাকা কুয়োর ভেতর। পড়ে গিয়েই ফাঁসির\nরজ্জুতে ঝুলতে থাকবে বিন্দির দেহ- যতক্ষণ না ওর মৃত্যু নিশ্চিত হয়। জেলার বার বার ঘড়ি\nদেখছেন আর অপেক্ষা করছেন নির্দিষ্ট সময়টির জন্যে। আর ঠিক সে মুহূর্তেই আই জি প্রিজনের\nমোবাইল ফোনটি বেজে উঠল। আই জি প্রিজন ফোনটি কানে ধরলেন। সামান্য কথা বলবার পর ফোনটির\nসুইচ অফ করে দিয়ে আই জি প্রিজন সবাইকে উদ্দেশ্য করে বললেন- মাননীয় স্বরাষ্ট্র মন্ত্রী\nমহোদয় এখুনি এখানে এসে পৌঁছুবেন। ততক্ষণ আমাদেরকে অপেক্ষা করতে হবে। আপনারা সবাই চেয়ারে\nবসুন।- কেউ কোনো কথা না বলে চেয়ারে বসে পড়লেন। এর মধ্যেই কারাগারের মূল ফটকটি খুলে\nদেয়া হলো। দুটি সাদা রংয়ের গাড়ি এসে কারাগারে প্রবেশ করল। গাড়ি দুটি থেকে স্বরাষ্ট্র\nমন্ত্রীসহ চার জন নেমে সোজা ফাঁসির মঞ্চে চলে এলেন। মন্ত্রী মহোদয় আসবার সঙ্গে সঙ্গে\nসবাই চেয়ার থেকে উঠে দাঁড়ালেন। দাঁড়ানো অবস্থাতেই মন্ত্রী মহোদয় একটি লম্বা সাদা খাম\nআই জি প্রিজনের হাতে দিয়ে বললেন- চিঠিটি সবাইকে পড়ে শোনান। - আই জি প্রিজন চিঠিটি পাঠ\nকরতে শুরু করলেন- </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"align\\":\\"center\\"} -->\n<p style=\\"text-align:center\\">‘রাষ্ট্রপতির আদেশ’-<br> মামলা নম্বর-১৫৬/৪৬-০৩/৯৭ <br> তারিখ- ১৫-০৩-২০০১ খ্রি. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>‘সংশ্লিষ্ট মামলাটির সার্বিক Case Historz-\nপাঠ এবং পর্যালোচনা করে, অপরাধ ঘটানোর বিষয় ও কার্যকারণ বিবেচনা এবং আসামির ওপর যে\nধরনের অপরাধ ঘটানো হয়েছে সে অপরাধের ধরণ এবং চরিত্র উদ্ঘাটনের পাশাপাশি ঘটনার কারণ\nনিঁখুতভাবে অনুসন্ধান এবং চুলচেরা বিশ্লেষণ করে সংবিধানের Article-৪৯-এর বিধান অনুযায়ী বাংলাদেশের রাষ্ট্রপতিকে\nপ্রদত্ত ক্ষমতা বলে এই মামলার আসামি- লতিকা আইবেক বিন্দির অপরাধকে সম্পূর্ণরূপে মওকুফ\nএবং ক্ষমা করে দিয়ে উক্ত মামলার সার্বিক দায় থেকে লতিকা আইবেক বিন্দিকে অব্যাহতি প্রদান\nপূর্বক নিঃশর্ত মুক্তি প্রদান করা হলো। এই আদেশ অবিলম্বে কার্যকর হবে।’</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>স্বাক্ষর-</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"align\\":\\"right\\"} -->\n<p style=\\"text-align:right\\">রাষ্ট্রপতি,<br>গণপ্রজাতন্ত্রী বাংলাদেশ।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>চিঠিটি পাঠ করা শেষ হলে আই জি প্রিজন বিন্দিকে ফাঁসির মঞ্চ থেকে নামিয়ে আনবার\nনির্দেশ দিলেন জল্লাদকে। জল্লাদ বিন্দির হাত, পা এবং চোখের বাঁধন খুলে দিয়ে এবং মাথার\nকালো টুপি খুলে ফেলে বিন্দিকে সবার সামনে নিয়ে এলো। বিন্দি সবার সামনে এসে দাঁড়িয়ে\nসবাইকে সালাম প্রদান করল। সবাই সালাম গ্রহণ করলেন। প্রথমেই বিন্দিকে লক্ষ করে কথা বললেন\nস্বরাষ্ট্র মন্ত্রী- আপনাকে অভিনন্দন। মহামান্য রাষ্ট্রপতি আপনার অপরাধকে ক্ষমা করে\nআপনাকে নিঃশর্ত মুক্তি প্রদান করেছেন। এখন আপনি সম্পূর্ণ মুক্ত।- আর কিছু বললেন না\nমাননীয় স্বরাষ্ট্র মন্ত্রী। এবার কথা বললেন আই জি প্রিজন- আপনি মুক্ত। তবে আজকের বাকী\nরাতটুকু আপনাকে এখানেই থাকতে হবে। এটি আইন এবং নিয়ম। রাত্রিতে কোনো আসামিকে মুক্তি\nদেবার বিধান নেই।- বলে জেলারকে কয়েকটি নির্দেশনা দিলেন। যার মধ্যে মুখ্যটি হলো বিন্দিকে\nকনডেম সেলের পরিবর্তে অন্য একটি কক্ষে বিছানাপত্র দিয়ে ওর শোবার ব্যবস্থা করণ। এরপর\nজেলার ওকে একটি চেয়ারে বসতে বলে সবাইকে নিয়ে নিজের অফিস কক্ষে নিয়ে গেলেন।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"><em>দশ</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>অবশিষ্ট রাতটুকু বিন্দির চোখে আর ঘুম এলা না। একদিকে আনন্দের উত্তেজনা আর একদিকে\nসমাজের চোখে ওর একটি ভিন্ন প্রতিচিত্র ফুটে ওঠা। তার পরেও ওর সান্তনা- ও এমন একটি কাজ\nকরেছে যে কাজটি সমাজে বসবাসকারী মানুষজনের মূল্যবোধের অভ্যন্তরে আলোড়ন তুলবার জন্যে\nএতটুকু হলেও বিশেষ একটি শক্তির মাত্রা সৃষ্টি করতে সক্ষম হবে। সেই শক্তির মাধ্যমে মানুষের\nমূল্যবোধ উর্ধ্বায়িত হতে পারবে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ভোরের আজান শেষ হয়েছে। ধীরে ধীরে পূর্ব দিগন্ত রক্তিমাভা ধারণ করতে শুরু করেছে।\nকারাগারের সব কয়েদি এবং হাজতিকে কারাগারের মাঠে লাইন আপ করে দাঁড় করানো হয়েছে। বিন্দির\nকক্ষের দরোজা খুলে দেয়া হয়েছে। বিন্দি কক্ষের বারান্দায় এসে দাঁড়িয়েছে। ওর মুক্তির\nযাবতীয় কাগজপত্রে গত রাত্রেই ওর স্বাক্ষর নিয়েছেন জেলার সাহেব। আজকে ওর করণীয় কোনো\nআনুষ্ঠানিকতা অবশিষ্ট নেই। বারান্দা থেকে নীচে নামবার জন্যে পা বাড়িয়েছে বিন্দি এমন\nসময় একজন সেন্ট্রি এসে বিন্দিকে জেলার সাহেবের অফিস কক্ষে যাবার জন্যে অনুরোধ জানাল।\nবললো- জেলার সাহেবই আমাকে পাঠিয়েছেন আপনাকে নিয়ে যাবার জন্যে। আমার সঙ্গে আসুন, আমিই\nনিয়ে যাচ্ছি আপনাকে। আপনার মা-ও এসেছেন।- আর কিছু না বলে দুজনই হাঁটতে শুরু করল জেলারের\nঅফিসের দিকে। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিন্দি জেলারের অফিস কক্ষে প্রবেশ করতেই মা মেয়ে দুজন দুজনকে জড়িয়ে ধরে আকুল\nকান্নায় ভেঙ্গে পড়েছে। কেউ কাউকে কোনো কথাই বলতে পারেনি। শুধুই কেঁদেছে। মা কেঁদেছেন\nমেয়েকে ফিরে পাবার আনন্দে আর মেয়ে কেঁদেছে মায়ের বুকে মাথা গুঁজবার ঠাঁই পাবার সুখে।\nএভাবে কেটেছে কিছুটা সময়। আবেগে আপ্লুত হয়ে উঠেছে মা আর মেয়ে। আবেগ কিছুটা থিতিয়ে এলে\nজেলার বিন্দিকে ডেকে কাছে নিয়ে বলেছেন- এবার তোমার মায়ের হাতটি শক্ত করে ধরে বাড়ি\nফিরে যাও। তুমি এখন সম্পূর্ণ মুক্ত। তুমি প্রতিবাদ এবং প্রতিরোধের একটি জীবন্ত দৃষ্টান্ত\nস্থাপন করলে মা। দেশের মানুষ তোমাকে মনে রাখবে। কখনই ভুলবে না।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জেলারকে সালাম জানিয়ে মায়ের হাত ধরে কারাগারের সামনের খোলা আকাশের নীচে এসে দাঁড়াল ওরা দুজন। দীর্ঘ চার বছরের কারাবাস শেষে আজ প্রথম মুক্ত আলো হাওয়ায় একেবারে স্বাধীনভাবে প্রাণপূর্ণ একটি শ্বাস বুক ভরে গ্রহণ করলো বিন্দি। তারপর তাকালো আকাশের দিকে। তাকিয়ে থাকলো অনেকক্ষণ। এক সময় দৃষ্টি নামিয়ে মায়ের চোখে চোখ রেখে বলল- মা, আমার ওপর যে অত্যাচার করা হয়েছে, যে অপরাধ করা হয়েছে সে অত্যাচার আর অপরাধের যথাযথ জবাব দিতে গিয়ে সমাজের চোখে আমিও একটি অপরাধ করেছি। কিন্ত আমার কৃত সে অপরাধটি আমার ওপর সংঘটিত আর দশটি সে ধরনের অপরাধের পথকে রুদ্ধ করে দিয়েছে- এটি আমি বিশ্বাস করি এবং এটিই আমার শ্রেষ্ঠ প্রাপ্তি। চলো।- একটি সুপ্রভাতের সূচনা করে মায়ের হাত ধরে বাড়ির দিকে পা বাড়াল বিন্দি।&nbsp; </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>©  সরদার মোহম্মদ রাজ্জাক</p>\n<!-- /wp:paragraph -->', 'এক\nতখনও ভোর হয়নি। তখনও বাসন্তিকা বর্ণ-শোভায় শোভিত শাড়ীতে দুলে ওঠা ফাল্গুনের মেঘহীন\nআকাশের পূর্ব নীলিমা জুড়ে রক্তরাগে মোড়ানো রক্তিম সূর্যের পূর্বরাগের পাখনা মেলা সোনামাখা\nবিজড়ন দিগন্তের সীমানা ছু...', '', 13, NULL, 'publish', 2353, 0, '2019-02-25 18:16:28', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (42, 2513, 35, 'আই হেড নো টাইম টু হেট', 'আই-হেড-নো-টাইম-টু-হেট', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\">মূল: এমিলি ডিকিনসন <br>বাংলাকরণ: আমিনা শেলী</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হেলা করা হলো না আমার<br>কবরের সন্ধান নিকটেই ছিল<br>জীবনটা খুব বেশি বড় ছিল না যে<br>গুছিয়ে নেব সব দ্বেষ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>প্রেম করা হলো না আমার<br>যাপনও হয় না জানি লেনদেন বিনা<br>প্রেমেতে পরিশ্রম হয়েছে যেটুকু<br>তা-ই তো জেনেছি অশেষ।</p>\n<!-- /wp:paragraph -->', 'মূল: এমিলি ডিকিনসন\nবাংলাকরণ: আমিনা শেলী\nহেলা করা হলো না আমার\nকবরের সন্ধান নিকটেই ছিল\nজীবনটা খুব বেশি বড় ছিল না যে\nগুছিয়ে নেব সব দ্বেষ\nপ্রেম করা হলো না আমার\nযাপনও হয় না জানি লেনদেন বিনা\nপ্রেমেতে পরিশ্র...', '', 4, 5, 'publish', 2707, 0, '2019-02-26 10:55:40', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (43, 2528, 14, 'একটি শিরোনামহীন প্রেমের গল্প', 'একটি-শিরোনামহীন-প্রেমের', '<!-- wp:paragraph -->\n<p>একটা দুঃস্বপ্নে ঘুম ভেঙ্গে গেল আজ। একটা সাপ আমার পিছু নিয়েছে। আমাকে তাড়া করে বেড়াচ্ছে অনবরত। আমি যেখানেই যাচ্ছি পিছু ছাড়ছে না কিছুতেই। আমি দৌড়ালে সাপও দৌড়াচ্ছে। বার বার ছোবল দিতে গিয়েও থেমে যাচ্ছে। ছোবল দেওয়ার চেষ্টা করছে। আমি দুরে সরে যাচ্ছি। সাপটি উড়তে শুরু করল মুহুর্তেই। উড়ে উড়ে আমার কপালে ছোবল দিতে চাইছে। আমি প্রানপনে দৌড়াচ্ছি। আর পারছি না। আমার শরীর কাঁপছে। আমার গলা শুকিয়ে গেছে। আমি পানি পানি করে চিৎকার করছি। তৃষ্ণায় খাক কোথাও পানি নেই। আমার কম্পন আরও বেড়েই চলেছে। সাপটাকে আর দেখা যাচ্ছে না। কিন্তু আমি চিৎকার করছি। তীব্র চিৎকারে আকাশ বাতাশ কাঁপিয়ে তুলেছি। আমার ঘুম ভেঙ্গেছে। আমি তখনও চিৎকার করছি। এরকম স্বপ্ন আমি প্রায়ই দেখি! সত্যি সত্যিই আমার গলা শুকিয়ে কাঠ। বিছানা ছেড়ে উঠে বসি আমি। এক গ্লাস পানি খেতে খেতে চারিদিকটা ভালভাবে তাকিয়ে দেখি। সাপটি খুঁজতে থাকি। কোথাও কিছু পাইনা। আমার বুকের মধ্যে কেঁপে কেঁপে ওঠে। আমার মনে হচ্ছে সাপটি এ রুমের মধ্যেই আছে। আমার গা ছমছমে ভাব কমেনা কিছুতেই। ঠিক এরকম সময়েই তোমার কথা মনে পড়ে। তোমার হাসি। তোমার কথা বলা। তোমার চাহনি আমার হৃদয়পটে ভেসে উঠতেই আমি অন্যমনস্ক হয়ে যায়। ইদানিং যে কোন স্বপ্নের পরেই তোমার কথা মনে পড়ে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>রাতের নীল আকাশে যখন একফালি চাঁদ উকি দেয়, যখন আকাশ ফুড়ে স্নিগ্ধময় জোৎস্নায় ভরে যায় চারপাশ তখন আমার হৃদয়ের মাঝে ঝড় ওঠে। বুকের ভেতরে অজানা অস্থিরতা কাজ করে। আমার শরীরটা কেমন কেঁপে কেঁপে ওঠে। আমি জানালার গ্রীল ধরে আকাশপানে তাকিয়ে থাকি। তীব্র অস্থিরতা আমার মন থেকে শরীরে ছড়িয়ে পড়ে। রবার্ট ফ্রস্টের কবিতার লাইন ভেসে ওঠে হৃদয়পটে। চারলাইন আবৃত্তি করি, </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The woods are lovely dark and deep<br>\nBut I have promise to keep<br>\nAnd miles to go before I sleep <br>\nAnd miles to go before I sleep. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আকাশের বুকে তখনও অগনিত তারার মেলা। ঝিঁকিমিকি আলো আধারের খেলা। দুয়েকটা জ্বোনাকির উড়ে চলা। আমার মনটা তখনও অস্থির। আমি তোমার কথা মনে করতে চাইছি না তবুও মনে পড়ছে। অস্থিরতা কমাতে সিগারেট ধরালাম। ব্যাপারটি লক্ষ করেছি ধোয়া ছাড়ার সময়েই। আকাশ পানে তাকিয়ে ধোয়া ছাড়তে খারাপ লাগছিল না খুব। ছেড়েছি বার কয়েক। ধোয়া ছাড়ছি আর খুক খুক করে কাশছি। পুড়ে যাচ্ছে হাতের সিগারেট। দ্রুত ছোট হয়ে আসছে সিগারেটের আয়ু। সেই সাথে ছোট হয়ে আসছে আমার চিন্তার আয়ু। হাতের সিগারেট আমাকে আকড়ে ধরেছে। আমি সিগারেটের প্যাকেটটা আকড়ে ধরেছি। প্যাকেটের গায়ে লেখা আছে ধুমপান ক্যান্সারের কারণ। আগে লেখা থাকতো ধুমপানে স্ট্রোক হয়। সকল ধুমপায়ীরা জানে এর কুফল। তবুও ধুমপান চলে ননস্টপ হারে। কারণ নেশা। একবার নেশা হয়ে গেলে ছাড়া কঠিন। তবে এর থেকেও আর জটিল নেশা জগতে আছে। &nbsp;জটিল নেশা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>জগতের সবচেয়ে মোহময় নেশা হল ভালবাসার নেশা। প্রেমের নেশা। আমিও সেই নেশাই আসক্ত। আমি জানি তোমাকে ভালবাসা আমার যতখানি সম্ভব তার চেয়েও বেশি তোমাকে হারানোর ভয়। তোমাকে নিয়ে মনের মধ্যে যত উঁচু পাহাড়ই গড়ি না কেন তেমার এক ফোঁটা চোখের জলেই তা নিমিষে ধ্বসে যেতে পারে। তোমাকে ভালবাসা আমার কাছে গভীর ঘুমে আচ্ছন্ন থেকে সুন্দর স্বপ্ন দেখার মতন। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সেদিন রাস্তার মোড়ে অনেক্ষন পুস্পর অপেক্ষা করছিলাম। পুস্প সেই মেয়েটি যাকে দেখে আমার হৃদয়ে ভালবাসা নামক একটা ফুল গাছের জন্ম হয়েছে। এই চারা গাছটিকে আমি রোজ যত্ন করি। পানি দিই। হৃদয়ের জমিনে বেড়ে উঠার তপস্যা করি। ধ্যান করি। পুঁজা করি। এখনই হয়তো সে কলেজ থেকে ফিরবে। কারও জন্য কোথাও দাড়িয়ে থাকা আমার অভ্যাসের বিপরীত। তবুও দাড়িয়ে রইলাম। আমার খুব ইচ্ছে করছিল আজ একটু পুস্পকে দেখি। পুস্প প্রস্ফুটিত পুস্পের মতই সুন্দর। তার&nbsp; সুবাসে মোহিত হতে হয় নিমিষেই। সে পবিত্র। সে স্নিগ্ধ। সে পরীর মতন। সে স্বপ্নের মতন।&nbsp; অনেক্ষন দাড়িয়ে থাকার পর খেয়াল হল আজ সরকারি ছুটি। কলেজ বন্ধ। এতক্ষন তার অপেক্ষা করে কি বোকামিই টা না করেছি! পুস্পের কথা ভাবতে ভাবতে সময় অপচয় করতেও ভাল লাগে। বোকামীগুলোও মধুর হয়ে যায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মনে মনে কত ভেবেছি পুস্পর হাত ধরে বলব, পুস্প আমি তোমার ভরা রোদ্দুরের ছায়া হতে চাই। তোমার জীবনের সৌরভ হতে চাই। হতে চাই নীলকণ্ঠ পাখি। এক আকাশে উড়ে বেড়াতে চাই ডানা মেলে। ডানা ঝাপটাতে ঝাপটাতে মেঘ ছুতে চাই দুজনে মিলে। তুমি বৃষ্টি চাইলে আমি আকাশের গা থেকে একমুঠো মেঘ পেড়ে দেব তোমায়। তা থেকে বৃষ্টি নামবে একদিন। তুমি নাচবে বৃষ্টির তালে তাল মিলিয়ে। আমি তোমার দিকে অপলক দৃষ্টিতে চেয়ে থাকবো। তোমার চোখে জল জমলে আমার কপালের ঘাম জড়ানো রুমাল দিয়েই তোমার চোখের জল মুছিয়ে দেব। বিকেল হলে পশ্চিম বারান্দার এক কোনে দাড়িয়ে লাল সুর্যেকে বিদায় জানাবো দুজনে মিলে। তুমি হাত নাড়বে লাল সুর্যকে। আমি তোমার হাতের সাথে তাল মিলাবো। তোমার কপালে একটা লাল টিপ পরিয়ে দিয়ে বলব সুর্যটা তোমার কপালে লাগিয়ে দিলাম, আমার হৃদয় রাজ্য আলোকিত কর হে প্রেয়সী। আমাকে ধন্য কর। চলো সোনালী দিনে স্বপ্নের মত সুন্দর সংসার গড়ি আমরা! আমার মুখে লেগে থাকা একচিলতে হাসির কারণ কি হবে তুমি?&nbsp; কতবার ভেবেছি তোমার চোখে চোখ রেখে ছুড়ে দেব মনের সমস্ত কথা। তোমাকে জড়িয়ে ধরে জীবনানন্দ দাশের মত করে বলব, চল বুনো হাঁস হই দুজনে। কিন্তু সাহসে কুলোইনি কোনদিন। জড়িয়ে ধরা তো দুরের কথা আমি আজও বলতে পারিনি, পুস্প চলো বুনো হাঁস হয় দুজনে। স্বচ্ছ সুন্দর পুকুর জলে ভেসে বেড়ায় মনের সুখে! কখনও বলতে পারিনি আমি, আমি কি তোমার তুমি হতে পারি? </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>গতরাত চোখের দুটি পাতা এক করতে পারিনি কিছুতেই। বুকের ভেতর কেমন জানি হাহাকার। ব্যাথা অনুভব করছি। মনে পড়ছে সেই প্রথম দিনটির কথা। সেদিন আমি পুস্পকে প্রথম দেখেছিলাম। সেদিন আকাশে ছিলো কালো মেঘ। প্রবল বৃষ্টিতে ভেসে যাচ্ছে পৃথিবী। নীল শাড়িতে তুমি এলে। আকাশের সব নীল ঝরে ঝরে পড়েছে তোমার শাড়িতে। কপালে কালো টিপ। মেঘ থেকে নিয়ে যেন জড়ো করে কপালে পরেছো। মাথার উপর গোলাপ ফুলের নকশা আঁকা ছাতা। বাতাশ ডানা ঝাপটাতে শুরু করলে তোমার ছাতাটা গেল উল্টে। তোমার শরীরের অর্ধেকটা ভিজে যাচ্ছে। আমার শান্ত হৃদয় অশান্ত হল। আমি তোমার চেখের দিকে তাকালাম। বর্ষায় ফুলে ওঠা নদীর মতই আমার হৃদয়েও মায়ার জন্ম হল। মায়াবিনী আমাকে মুগ্ধ করে চলেছে। আহ কি অপুর্ব চোখ। কাজলের রেখা থাকায় আরও সুন্দর লাগছিল চোখদুটিকে। স্নিগ্ধতা ছড়াচ্ছিল। আমার বুকের ভেতর তখন কাল বৈশাখি ঝড়। আমার বুকের ভেতর তখন সমুদ্রের জোয়ার। বড় বড় ঢেউ আছড়ে পড়ছে হৃদয়ে তীরে। ভাল লাগছে ভীষন। বার বার&nbsp; ছাতাটা উল্টে যাচ্ছে। মেয়েটি হাত ঝাকিয়ে ছাতা ঠিক করে চলেছে। আমার ঠোঁটের কোনে তখন ফুঁটে উঠেছে হাসি। আমি হাসছি। আমার হৃদয়ের ব্যালকুনিতে তখন উঁকি দিয়েছে ভালবাসা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটির মাথায় একটা কদম ফুল গোঁজা থাকলে মন্দ হত না। ভাবছি আর আপন মনে মেয়েটির সৌন্দর্য্য কল্পনা করছি। কি এক ভাল লাগা থেকে হেসেই চলেছি। হঠাতই মেয়েটির চোখে আগুন। বিস্ফারিত নেত্রে আমার দিকে তাকিয়ে বলে ওঠে, ভারি অসভ্য তো আপনি! মেয়েটির কথায় সম্বিত ফিরে এলো। লক্ষ্য করলাম মেয়েটি প্রায় অর্ধেক ভিজে গেছে। ভেজা অংশটুকু গাঢ় নীল আাকার ধারণ করেছে। আরও চমৎকার লাগছে তাকে। আমাকে বলে উঠল, কারও পৌষমাস কারও সর্বনাশ! এমন হ্যাংলার মত হাসার কি আছে বলুন তো! মেয়েটির কোন কথায় আমার কানে ঢুকছে না। খারাপও লাগছে না। আমার মুখে তখনও হাসির রেশ। মেয়েটি মহাবিরক্ত। আমি হেসেই চলেছি। ছাতা মাথায় মেয়েটি হন হন করে আমার সামনে দিয়ে চলে গেল। টুনটুনীর মত তখনও মনটা আনন্দে নেচে নেচে বেড়াচ্ছিল। প্রচুর ভালবেসে ফেলেছিলাম সেদিন থেকেই।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যেদিন ভালবাসার সুর্যদয় হল আমার মনের আাকাশে সেদিন থেকেই ঠিক করে রেখেছিলাম এই আলোতেই যেন সারাজীবন আলোকিত হতে পারি। কিন্তু ভুলেই গিয়েছিলাম সুর্যও অস্ত যায় একটি নির্দ্দিষ্ট সময় শেষে। মনে মনে রোজ চাইতাম পুস্পের সাথে আমার বন্ধুত্বটা হয়ে যাক অন্তত। পুস্প তার ভাললাগা মন্দ লাগাগুলো আমার সাথে ভাগাভাগি করুক। আমার সাথে কথা বলতে শুরু করুক।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দিন যত গড়াতে লাগল আমার স্বপ্নগুলো যেন আরও বিস্তৃতিলাভ করল। রোজ সংসার গড়ার স্বপ্নে বিভোর হতে শুরু করলাম। একটা মধুর সংসার হবে আমাদের। সংসারে আমি আর পুস্প। রাগ অভিমান ভালবাসা সবকিছু নিয়েই আমরা গড়ব একটা সংসার। সেই সংসারের নিখুত কারিগর হবে পুস্প। আমি ভুল করব বারবার। ও কারনে অকারনে আমাকে চোখ রাঙ্গাবে। আমি হাসব। অবাক হব। ও বাজার থেকে আমাকে ভিম আনতে বললে আমি ডিম আনব ভুল করে। সে কাঁচা ডিম ভেঙ্গেই বাসন কোসন মাজতে শুরু করবে। থালাবাটি দিয়ে বেরুবে ডিমের দুর্গন্ধ। আমি জিজ্ঞেস করব কিসের গন্ধ? ও হেসে বলবে তোমার আনা ভিমের গন্ধ। আমি অবাক হব। রাগ করব। বলব ভিম আনতে বললে কখোন তুমি ডিম আনতেই বলেছো! এই নিয়ে শুরু হবে তর্ক। রোজ রোজ সংসারের স্বপ্ন আমাকে অনেক বেশি দুর্বল করে তুলল ওর প্রতি। ওকে নানান প্রশ্ন করতে ইচ্ছে করে। একবার জানতে ইচ্ছে হয়েছিল, বাজার থেকে পঁচা মাছ আনলে পুস্প কি সেটি কুটতে বসে যাবে নাকি ছুড়ে ফেলবে মেঝেতে? নাকি চোখ রাঙ্গিয়ে ঝগড়া করবে আমার সাথে আর রান্না করবে!&nbsp; জানা হয়নি। জানতে পারিনি তবে খুব সখ ছিল দেখার।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>হয়তো পুস্পকে এই জীবনে পাওয়া যাবে না কিছুতেই। তবুও ওকে প্রচন্ড ভালবাসি। আমি জানি এসমস্ত কথা লেখার কোন প্রয়োজন নেই। কেউ হয়তো পড়বেও না। তবুও লিখছি। কারণ আমার দিন ক্রমাগত ছোট হয়ে আসছে। আমার পৃথিবী ছোট হয়ে আসছে। আমার শরীরের যন্ত্রণা বেড়েই চলেছে ক্রমাগত।&nbsp; মনে হচ্ছে আমি আর বাঁচব না। হয়তো অনার্সটাও কমপ্লিট হবে না। তার আগেও হয়তো চলে যেতে হবে জীবনের সমস্ত হিসাব বাকি রেখে। হয়তো পুস্প নামের মেয়েটি কখনো জানতেও পারবে না এক অভাগা তাকে গোপনে অনেক ভালবাসতো। তাকে নিয়ে রচনা করত হাজারো প্রেমের কাব্য। রাত জাগানিয়া পাখিদের মত থাকতো রাতের পর রাত নির্ঘুম। শুধু তার কথা ভাবতো। তাকে নিয়ে হাজার রকম স্বপ্ন দেখত। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>আজ আমার চোখের এক ফোঁটা জলকে সাক্ষি রেখে বলতে চাই পুস্প যে পৃথিবীর বুকে প্রস্ফুটিত তুমি স্নিগ্ধতা নিয়ে এসেছিলে সেই স্নিগ্ধতা গায়ে মাখতে পারলাম না। তবু ভালবাসি তোমাকে। ক্যান্সার নামক মরণ ব্যাধি বাসা বেধেছে আমার রক্তে। সেই ক্যানসার ক্রমাগত ছড়িয়ে পড়ছে সারা শরীরে। তীব্র যন্ত্রণায় ছটফট করছি হাসপাতালের বিছানায়। চোখে ক্রমাগত অন্ধকার দেখছি। শরীরের ভেতরের ঘা গুলো শরীর ফুঁড়ে বেরিয়ে আসতে চাইছে । বেঁচে থাকার মনোবল হারাচ্ছি ক্রমাগত। আমার শেষ ইচ্ছে ছিল তোমার মুখখানি দেখেই চোখদুটো চিরকালের মত বুঁজব। আমার চারপাশে শুধু অন্ধকার। যন্ত্রণা আমাকে শুকিয়ে দিয়েছে। আমার ওজনও অবিশ্বাস্য ভাবে কমে গেছে। চোখের নিচে কালো দাগ পড়েছে। রোজ সকালে যে ছেলেটি তোমার কলেজ যাওয়ার পথে দাড়িয়ে থাকত খুব গোপনে তার আর দাড়িয়ে থাকার শক্তি নেই। আমি আর দাড়াতে পারিনা। আমার পৃথিবী এখন শুন্য। এই শুন্য পৃথিবীতে তুমি আমার কষ্টের সাথী হবে এটা আমি চাই না, তাই তোমাকে কিছু না বলেই নিরবে সরে গেলাম দুরে। অনেক দুরে! সংসারী হও! সুখি হও জীবনে! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>শুধু এতটুকু পড়েই কুড়িয়ে পাওয়া ডায়েরির পাতাটা বন্ধ করে থো মেরে বসে রইলাম কিছুক্ষন। আমি স্তব্ধ। আমি যেন নিরব ও নির্বেকার। ফেঁটে যাওয়া বেলুনের মত চুপসে আছি। কোন কাজেই মন বসল না কিছুতেই।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কিছুক্ষণ থো মেরে বসে থেকে আবারও ডায়েরির পাতা খুললাম। দেখতে চাইলাম ছেলেটির কোন তথ্য পাওয়া যায় কিনা। নতুন করে আবার পাতা উল্টিয়ে দেখলাম সমস্ত তারিখগুলো কালো কলমে ঘষে ঘষে কেটে রেখে দেওয়া। নামটিও বোঝা যাচ্ছে না কিছুতেই। আমি ক্রমাগত পাতা উল্টাচ্ছি। ছেলেটির ঠিকানা খোঁজার নেশা আমাকে পেয়ে বসেছে। আমার বুকের মধ্যে হাহাকার। অজানা ব্যথায় মুষড়ে আছি। মেয়েটি কি কখনোই জানতে পারবে না ছেলেটিকে? ছেলেরটির শেষ সময়ে পুস্পকে আমি তার পাশে দেখতে চাই! ছেলেটির নাম ধাম জানিনা। লেখা নেই। জানিনা ছেলেটি কোন হাসপাতালে ভর্তি! ছেলেটি বেঁচে আছে নাকি মরে গেছে আমাকে জানতেই হবে! লক্ষ করলাম, আমি চোখের কোনে একবিন্দু জল জমেছে। আমার বুকে তখন আশ্বিনের মেঘ। ছেলেটিকে আমার পেতেই হবে। পুস্পকেও খুঁজে বের করে ছেলেটির শেষ ইচ্ছে পুরণ করতে হবে। পুস্পকে সামনে পেয়ে ছেলেটির অভিব্যক্তি দেখার আগ্রহে বিভোর হয়ে আছি। আমি ক্রমাগত ডায়েরির পাতা উল্টিয়ে দেখতে থাকি। আমার চোখদুটো কেন জানি ঝাপসা হয়ে আসে! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© মাহির তাজওয়ার</p>\n<!-- /wp:paragraph -->', 'একটা দুঃস্বপ্নে ঘুম ভেঙ্গে গেল আজ। একটা সাপ আমার পিছু নিয়েছে। আমাকে তাড়া করে বেড়াচ্ছে অনবরত। আমি যেখানেই যাচ্ছি পিছু ছাড়ছে না কিছুতেই। আমি দৌড়ালে সাপও দৌড়াচ্ছে। বার বার ছোবল দিতে গিয়েও থেমে যাচ...', '', 9, NULL, 'publish', 2170, 0, '2019-02-28 14:03:53', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (44, 2543, 36, 'আরও ভয়াবহ বাতাস', 'আরও-ভয়াবহ-বাতাস', '<!-- wp:paragraph {\\"backgroundColor\\":\\"very-light-gray\\"} -->\n<p class=\\"has-background has-very-light-gray-background-color\\"> মূল: মার্গারিটা এংগল <br>বাংলাকরণ: আহসান হাবীব ফরায়েজী</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সাংবাদিকের মতে এটা কিউবার মিসাইল সংকট<br>শিক্ষকের মতে, পৃথিবীর সমাপ্তি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>একটু আলোর সন্ধানে-<br>বিদ্যালয়ে আমাদেরকে শেখানো হলো- <br>কিউবার অভিশপ্ত আকাশকে দেখতে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাঁশির ক্ষুদ্র ক্ষুদ্র আওয়াজেও যেন<br>বিষাক্ত বারুদের সন্নিকট গন্ধ শুনতে পাচ্ছিলাম। <br>টেবিলের নিচেও অগ্নিশীখা ভয়ংকর। <br>রেডিয়েশন, টক্সিক থেকে বাঁচাতে কি <br>এগুলো উত্তম কখনো!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বাতাস যেন এক অভিশপ্ত শয়তান শহরে <br>তবুও বাচ্চার মুখচাপা হাসি; <br>তারা বুঝতেই পারে না মৃত্যু সম্মুখে দাড়িয়ে।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তারা কখনোই গুলি ছুয়ে দেখেনি<br>কিংবা কখনো শকুন <br>অথবা খচ্চরের চোয়ালের হাড়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>যখন আমি নড়বড়ে টেবিলের নিচে<br>আমার হৃদস্পন্দন বহুগুণ<br>অবশেষে তামাটে গণ্ধে সেটিও উড়ে গেলো।</p>\n<!-- /wp:paragraph -->', 'মূল: মার্গারিটা এংগল\nবাংলাকরণ: আহসান হাবীব ফরায়েজী\nসাংবাদিকের মতে এটা কিউবার মিসাইল সংকট\nশিক্ষকের মতে, পৃথিবীর সমাপ্তি।\nএকটু আলোর সন্ধানে-\nবিদ্যালয়ে আমাদেরকে শেখানো হলো-\nকিউবার অভিশপ্ত আকাশকে দেখতে।\n...', '', 4, 5, 'publish', 2410, 0, '2019-03-02 12:44:10', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (45, 2553, 13, 'ভাব দরিয়া', 'ভাব-দরিয়া', '<!-- wp:paragraph -->\n<p>লাল হয়ে শরীরে জ্বালা ধরে যায়<br>কিছু আকাঙ্খার প্রাপ্তির জন্য,<br>মাছ যেমন জলে বাঁচে আরামে<br>সান্নিধ্য পাবার তৃষ্ণায় গণ্য।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কাম দেব নড়াচড়া করে মাথায়<br>সর্পের ভয়ে স্পর্শ করে না,<br>সবুর ধরে ম্যাওয়ার আশায়<br>অন্যথা মরণ বীণ যন্ত্রণা!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>উষ্ঠ্যদেশে নিষ্ঠা রেখে জমিন সোজা<br>তাতেই ভাব দরিয়া রসে ভরা,<br>জোয়ার ভাটার প্রতীক্ষা করে করে<br>জীব দেহ্ শুকায় হবে খড়া! </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© মজনু মিয়া </p>\n<!-- /wp:paragraph -->', 'লাল হয়ে শরীরে জ্বালা ধরে যায়\nকিছু আকাঙ্খার প্রাপ্তির জন্য,\nমাছ যেমন জলে বাঁচে আরামে\nসান্নিধ্য পাবার তৃষ্ণায় গণ্য।\nকাম দেব নড়াচড়া করে মাথায়\nসর্পের ভয়ে স্পর্শ করে না,\nসবুর ধরে ম্যাওয়ার আশায়\nঅন্...', '', 4, NULL, 'publish', 2735, 0, '2019-03-03 12:24:06', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (46, 2558, 37, 'পরাজিত সৈনিকের অতৃপ্ত চাহনী', 'পরাজিত-সৈনিকের-অতৃপ্ত-চা', '<!-- wp:paragraph -->\n<p>সবুজ, শ্যামল, নিবিড় ছায়াঘেরা গ্রামটির নাম বন্দরভিটা। এর পাশ\nদিয়ে বয়ে গেছে মাথাভাঙ্গার শাখানদী। গ্রাম্য পরিবেশের মতো এখানে কৃষকেরা মাঠে কাজ করে,\nব্যবসায়ীরা ব্যবসা করে এবং গৃহিনীরা গৃহকর্মে ব্যস্থ থাকে। গ্রামের বুক চিরে বয়ে গেছে\nপাকা রাস্তা। এর দুই পাশে বিভিন্ন গাছের সমারহ। নিত্যদিনের মানুষগুলো কাজের সন্ধানে\nএকটি নির্দিষ্ট স্থানে অপেক্ষা করে, সেখান থেকে প্রয়োজন অনুযায়ী লোক সকল শ্রমিক খুঁজে\nনেয়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সতের মে দিনটি কেমন ভিন্ন প্রকৃতির। চারপাশে কাকের ডাকাডাকি, গুড়ি\nগুড়ি বৃষ্টি হচ্ছে। ভারি কান্নায় পরিবেশের সদস্যরা স্তব্ধ হয়ে আছে। পাখির কলকাকলি নেই,\nতবে মানুষের কান্নার ধ্বনিতে ভিড় জমে আছে। চির বিদায়ের পালকী দেখে বুঝতে আর বাকি রহিল\nনা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সাইফকে বাবা-মা খুব ভালবাসে। ওকে নিয়ে অনেক স্বপ্ন। স্বপ্ন বুননের\nপ্রথম ধাপে ছেলেকে গ্রামের প্রাথমিক বিদ্যালয়ে ভর্তি করে দিলেন। বিদ্যালয়ে নিয়মিত পড়াশোনা\nকরে ভালো ফলাফল করে। শিক্ষকবৃন্দ ও সহপাঠিদের সাথে সাইফের ভালো সম্পর্ক গড়ে ওঠে। এছাড়া\nগ্রামের সকলে ওকে খুব ভালোবাসে। প্রাথমিক শিক্ষা শেষে মাধ্যমিক শিক্ষার জন্য স্থানীয়\nবিদ্যালয়ে ভর্তি হয়। বাবা-মায়ের ভালবাসায় লালিত-পালিত ছেলেটি লাউয়ের ডোগার মতো বেড়ে\nওঠে। বাবা কৃষি খামারে কাজ করে ফিরে এসে ছেলের মুখের দিকে তাকালে সকল ক্লান্তি ভুলে\nযায়।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিদ্যালয়ের বিভিন্ন প্রতিযোগিতায় ভালো করতে থাকে সাইফ। পড়াশোর\nপাশাপাশি সে অন্য জগতের সন্ধান খুঁজে বেড়াই। পারিপার্শ্বিক পরিবেশ তাকে ধ্বংসের মুখে\nঠেলে দেওয়ার চক্রান্ত করলেও মনুষ্যত্ব তাকে ফিরিয়ে আনে। লেখাপড়ায় মনোযোগ দিতে কিছু\nবিলম্বের জন্য এস. এস. সি পরীক্ষায় ভালো ফলাফল করতে পারেনা। তবুও উচ্চশিক্ষার জন্য\nকলেজে ভর্তি সুযোগ হয়। এভাবে লেখাপড়া চলতে থাকে। কলেজে ভর্তির পর সাইফের ভালো ছেলেদের\nসাথে বন্ধুত্ব গড়ে ওঠে। পড়াশোর ব্যস্ত সময় আতিবাহিত হয় ওদের। এইচ. এস. সি পরীক্ষায়\nভালো ফলাফল করে। এখন সাইফ এবং ওর বন্ধুরা স্থির করে বিশ্ববিদ্যালয়ে ভর্তি হয়ে মা-বাবার\nমুখে হাসি ফোটাবে। উদ্যাম ও পরিশ্রম একত্রে চলতে থাকে। বিশ্ববিদ্যালয়ে হিসাব বিজ্ঞানে\nলেখাপড়ার সুযোগ পাই। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বিশ্ববিদ্যালয়ের জীবন খুব আনন্দের কথাটি শুধু শোনা যেত। এখন সাইফ\nসেই জীবনের একজন সদস্য। সাইফ এ পর্যন্ত যা চেয়েছে তাই পাওয়ার জন্য সর্বোচ্চ চেষ্টা\nকরে সফল হয়েছে। যা পাওয়ার আশা কম তার নিকট যেতেও ভয় পাই। অডিটোরিয়ামে অনুষ্ঠান দেখতে\nএসেছে সাইফ। একুশে ফেব্রুয়ারি রচনা প্রতিযোগিতায় ও প্রথম হয়েছে। এখানে পুরস্কার বিতরনি\nও আলোচনা সভা হবে। অনুষ্ঠান শুরু হয়েছে এরই মাঝে এক মেয়ের সাথে সাইফের পরিচয় হয়। সাইফ\nমেয়েদের দেখলে খুব ভয় পাই । কারণ এস. এস. সি পরীক্ষায় পূর্বে সমস্যায় পড়েছিল। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটি খুব আগ্রহ নিয়ে সাইফের সাথে কথা বলছে। পূর্বে সাইফ সম্পর্কে\nওর একটা ভালো ধারণা ছিল। কথা প্রসঙ্গে মনের গভীরে মেয়েদের যে কথাটি সুপ্ত থাকে তা প্রকাশ\nকরে। কথাটি সাইফের ভালো লাগলেও এড়িয়ে যাওয়ার চেষ্টা করে। দীর্ঘ আলাপ শেষে সাইফ বলে,\n“আমি যা চাই তা আমাকে পেতেই হবে, আর যা আমি পাবো না তার দিকে চাইনা”। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>মেয়েটি বলে আমাকে নিয়ে তুমি কখনো হতাস হবেনা। আমি শুধু তোমার,\nতোমাকে ছেড়ে কোনদিন চলে যাব না। এভাবে কিছুদিন অতিবাহিত হয়। চাঁদ ও সূর্যের উদয় ও অস্তের\nখেলায় মানুষের মনেরও পরিবর্তন হয়। মেয়েটির মুখের হাসি এখন আর সাইফের না, তা এখন প্রবাসী\nকোন এক ছেলের। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>কেউ কথা রাখেনি, জীবনের রঙ্গিন স্বপ্নগুলো এখন সাইফের গোলক ধাঁধার\nমতো। বাবা মা স্বপ্ন দেখে ছেলেকে নিয়ে, ছেলে স্বপ্ন দেখে কোনো এক প্রতারক মেয়েকে নিয়ে।\nঘুম, খাওয়া এবং গোসলের অনিয়ম ঘটতে থাকে। নেশায় জড়িয়ে পড়ে সাইফ। এভাবে বিশ্ববিদ্যালয়ে\nলেখাপড়ার বারটা বেজে যায়। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পরাজিত সৈনিকের মত সাইফ বাড়িতে ফিরে আসে। মা-বাবা ওর চেহারা দেখে\nকেঁদে ওঠে সাইফ স্থির দৃষ্টিতে তাকিয়ে আছে। ডা. বলেছে- ওর ব্লাড ক্যান্সার হয়েছে। বৃদ্ধ\nবাবা-মা কি সাইফের পাশে দাঁড়াতে পারবে? এখন সাইফকে ওদের পাশে দাঁড়ানোর কথা। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সব কিছু ভুলে সাইফ তার আপন জগতে ফিরে গেছে। সাইফ কি মা-বাবার হৃদয়ের\nবৃক্ষ থেকে ঝরে গেছে? না এই সমাজের চক্রান্তে হেরে গেছে? সাইফ মৃত্যুর পূর্বে বালিশের\nনিচে একুটি চিরকুট রেখে গেছে, তাতে লেখা ছিল- “আমি চলে যাচ্ছি, তবে একটি কথা এই পৃথিবীর\nসকল বন্ধুদের বলে যেতে চাই। ছাত্রজীবনে যেন অন্তরের প্রয়োজন মেটাতে বাবা মায়ের হাসি\nআনন্দ কেড়ে না নেয়। আমি চাই আমার মতো যেন আর একটা ছেলে মেয়েও ঝরে না পড়ে”।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ঘনকালো মেঘ পশ্চিম আকাশে গর্জে ওঠে। এক পশলা বৃষ্টিতে পেরিবেশ সজীব হয়ে ওঠে। সাইফের লেখা চিরকুটটি উপন্যাসের কভার পৃষ্ঠায় স্থান করে নেয়। পূর্ব আকাশে নতুন সূর্য ওঠে। সূর্যের আলোর মতো সাইফের চিরকুটের লেখাটি তরুণ প্রজন্মের মাঝে ছড়িয়ে পড়ে। মাথাভাঙ্গা নদী তার যৌবন হারিয়ে সাইফের সাথে গভীর মিতালি গড়ে তোলে...  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© শাহীন আলম </p>\n<!-- /wp:paragraph -->', 'সবুজ, শ্যামল, নিবিড় ছায়াঘেরা গ্রামটির নাম বন্দরভিটা। এর পাশ\nদিয়ে বয়ে গেছে মাথাভাঙ্গার শাখানদী। গ্রাম্য পরিবেশের মতো এখানে কৃষকেরা মাঠে কাজ করে,\nব্যবসায়ীরা ব্যবসা করে এবং গৃহিনীরা গৃহকর্মে ব্যস্থ ...', '', 9, NULL, 'publish', 1925, 0, '2019-03-03 13:27:30', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (47, 2564, 38, 'বোধিবৃক্ষ', 'বোধিবৃক্ষ', '<!-- wp:paragraph -->\n<p>প্রেম অপ্রেমের দোলাচলে বোধিবৃক্ষের মৃদুমন্দ হাওয়া</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>দেখা যায় না যায় না ছোঁয়া। হাওয়া দোলা দেয় , বৌদ্ধপূর্ণিমার রাতে<br>মুখরিত আলোয় মাখামাখি জোছনা নাচে, শিরশিরিয়ে নেমে যায় পদচারণা।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>সিসার কলকের মতো লম্বা টানের মিষ্টি ধোঁয়া সুড়সুড়ি জমা করে <br>বাম অলিন্দে। সোনার কাছাকাছি; একটা তামাটে হাসি চোখে ঝিলিক দিলে<br>সূর্য ডুবে যায়। অন্ধকার হয়ে গেলে: <br>আমরা ওলকচুর পাতা বিছিয়ে বিশাল আকাশে জায়গা খুঁজি<br>একটু জায়গা মিললেই ফুলে ফলে ভরে যেতো বন<br>হাড়িতে জিইয়ে রাখা মন মিঠাপানিতে <br>দে দোল দে দোল…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© তিথি আফরোজ</p>\n<!-- /wp:paragraph -->', 'প্রেম অপ্রেমের দোলাচলে বোধিবৃক্ষের মৃদুমন্দ হাওয়া\nদেখা যায় না যায় না ছোঁয়া। হাওয়া দোলা দেয় , বৌদ্ধপূর্ণিমার রাতে\nমুখরিত আলোয় মাখামাখি জোছনা নাচে, শিরশিরিয়ে নেমে যায় পদচারণা।\nসিসার কলকের মতো ল...', '', 4, NULL, 'publish', 2151, 0, '2019-03-05 12:02:03', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (48, 2571, 39, 'ভুলে গেছি রোজ', 'ভুলে-গেছি-রোজ', '<!-- wp:paragraph -->\n<p>সময় বড় কম।<br>আমরা সারাদিন ছুটোছুটি, ব্যস্ততার মধ্যে <br>আজ ভুলতে বসেছি কত মুখ আছে আমাদের<br>এক চব্বিশ ঘন্টার।<br>আসলে সেই চোখ আমরা হারিয়ে ফেলেছি যেটা দিয়ে দেখব আলতো পায়ে নববধূর মতো সলজ্জ সন্ধ্যে নামছে শহরের উপকন্ঠে।<br>আমাদের কানে আজ আর পৌঁছয় না সেই দৃশ্যের শব্দ যেখানে সিল্যুয়েট রহস্যময়ী মাথায় আঁচল টেনে<br>প্রদীপ জ্বালায় বিগ্রহহীন বিরহী সিঁদুর মাখা দেব দেউলে।<br>কতদিন কালপুরুষ দেখা হয় না অবাক শিশুর চোখ দিয়ে।<br>মডিউলার কিচেনে বড্ড চড়া, বড্ড বেমানান গনগনে কয়লার আঁচ, তাই ফুটন্ত ভাতের গন্ধ নিতেও এখন আর থমকে দাঁড়ানো হয় না।<br>আসলে আজও রোজই দৃশ্যের জন্ম হয়, শুধু আমরাই তা ভুলে গেছি। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© অহি বন্দ্যোপাধ্যায়  </p>\n<!-- /wp:paragraph -->', 'সময় বড় কম।\nআমরা সারাদিন ছুটোছুটি, ব্যস্ততার মধ্যে\nআজ ভুলতে বসেছি কত মুখ আছে আমাদের\nএক চব্বিশ ঘন্টার।\nআসলে সেই চোখ আমরা হারিয়ে ফেলেছি যেটা দিয়ে দেখব আলতো পায়ে নববধূর মতো সলজ্জ সন্ধ্যে নামছে শহরের ...', '', 4, NULL, 'publish', 2803, 0, '2019-03-07 10:58:30', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (49, 2575, 40, '﻿ফিরে এসো', 'ফিরে-এসো', '<!-- wp:paragraph -->\n<p>বললে, ফিরবে না&nbsp;<br>আর এই শহরে</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>এ শহর-<br>যেন দানবের বহর।<br>এখানে সত্য নেই, <br>আছে মিথ্যের দল<br>যাদের দাপট চলে সেই। <br>ভালোবাসা এখানে <br>নোংরা করে ওলি গলি,<br>আর চার দেয়ালে?<br>শুধু নাটক চলে \'চোরাবালি\'।<br>বললে, ফিরবে না<br>আর এই শহরে?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> এ শহর-<br> যেন সহজ সুখের দোসর।<br> ব্যস্ত রাজপথগুলো <br> শুধু খোঁজে নিয়তি,<br> পদপিষ্ট জীবনে মোদের <br> নেয় না শোষক বিরতি।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বলি-<br>এমনই তো হয় শহর, <br>ক্ষমা-ক্ষতির এক বিষের নহর। <br>তবুও লোহিত প্রাণ,&nbsp; <br>বাঁধে সুরে জয়গান। </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তবুও লোহিত প্রাণ, <br>বাঁচে সঞ্চিয়া কিছু শান। <br>তাই এসো ফিরে-&nbsp;<br>তবে আর এই শহুরে নৃত্যে নয়, <br>অধীর কোন সবুজ বৃত্তে। <br>যেখানে স্বপ্নরা কখনো হবে না<br>আর ধুসর গোধূলি,<br>খরচে নিতে পারো <br>কিছু সিকি আর আধুলি।।</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>©  সহন রুদ্র</p>\n<!-- /wp:paragraph -->', 'বললে, ফিরবে না\nআর এই শহরে\nএ শহর-\nযেন দানবের বহর।\nএখানে সত্য নেই,\nআছে মিথ্যের দল\nযাদের দাপট চলে সেই।\nভালোবাসা এখানে\nনোংরা করে ওলি গলি,\nআর চার দেয়ালে?\nশুধু নাটক চলে \'চোরাবালি\'।\nবললে, ফিরবে না\nআর এই শহর...', '', 4, NULL, 'publish', 2748, 0, '2019-03-09 10:20:03', '2026-09-12 18:23:43', '2026-09-12 18:23:43'),
  (50, 2584, 15, 'কাঠ কয়লার মৈথুন', 'কাঠ-কয়লার-মৈথুন', '<!-- wp:paragraph -->\n<p>মেঠো\nশালিকেরা ছুটছে গন্তব্যহীন..</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>পথভিখারি আমার ছায়া<br>এখন সৈনাস সেবায়<br>স্পর্শে কৌতুহল চোখ<br>খুব সহজেই অন্ধকারে অদৃশ্য</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>তুমি বলেছিলে <br>জীবন এমনই হয়</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>বেনামি চিঠির শরীরে<br>পোড়া কাঠের গন্ধ <br>খুব সহজেই যে চোখ <br>দূশ্যমান হতো<br>পুড়ে পুড়ে সে চোখ<br>কাঠ কয়লার সাথে মৌথুনে ব্যাস্ত…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>© শাহরিয়ার জাহাঙ্গীর </p>\n<!-- /wp:paragraph -->', 'মেঠো\nশালিকেরা ছুটছে গন্তব্যহীন..\nপথভিখারি আমার ছায়া\nএখন সৈনাস সেবায়\nস্পর্শে কৌতুহল চোখ\nখুব সহজেই অন্ধকারে অদৃশ্য\nতুমি বলেছিলে\nজীবন এমনই হয়\nবেনামি চিঠির শরীরে\nপোড়া কাঠের গন্ধ\nখুব সহজেই যে চোখ\nদূশ্য...', '', 4, NULL, 'publish', 3010, 0, '2019-03-10 13:27:05', '2026-09-12 18:23:43', '2026-09-12 18:23:43');
